\begin{minted}[fontsize=\scriptsize,xleftmargin=1em,linenos=true,highlightlines={12-13,16,19,23}]{yaml}
apiVersion: batch/v1
kind: Job
metadata:
  name: "quantum-job"
spec:
  template:
    metadata:
      name: "quantum-pod"
    spec:
      containers:
        - name: "quantum-task"
          image: registry.com/user/job-dependencies:v1
          command: ["python", "/app/main.py"]
          resources:
            limits:
              nvidia.com/gpu: '1' # requires GPU usage
          volumeMounts:
          - name: source-code-volume
            mountPath: /app
      volumes:
        - name: source-code-volume
          configMap:
            name: task-files #{"main.py": "code"}
      restartPolicy: Never
\end{minted}
\caption{Quantum job specification}
\label{listing:job}
\end{listing}












\section{Evaluation}
