\section{Methodology Overview and Notation}
\label{app:method_overview}

This section provides a consolidated overview of the LD-FPG framework's workflow, key mathematical notation used throughout the paper, and supplementary details regarding data processing, model architectures, and training procedures.

\subsection{Notation}
\label{app:notation_details}
We define the following notation used throughout the main text and appendix:
\begin{itemize}
    \item $k$: Number of nearest neighbors used for graph construction.
    \item $\tilde X^{(t)} \in \R^{N \times 3}$: Raw (unaligned) Molecular Dynamics coordinates for frame $t$.
    \item $\Theta$: Encoder neural network function; $\Theta^*$ denotes frozen, pre-trained encoder parameters.
    \item $K$: Order of Chebyshev polynomials in the ChebNet encoder.
    \item $d_c$: Dimensionality of the conditioner tensor $C$.
    \item $H, W$: Output dimensions (height and width respectively) for pooling layers, where $d_p = H \cdot W$.
    \item $N_{\text{layers}}$: Number of layers in a Multi-Layer Perceptron (MLP).
    \item $\mathcal{L}_{\text{diffusion}}$: Loss function for training the Denoising Diffusion Probabilistic Model (DDPM).
    \item $N$: Total heavy atoms per structure.
    \item $V = \{1, ..., N\}$: Atom nodes.
    \item $G=(V, E)$: Graph representation.
    \item $\Ibb \subset V$: Backbone atom indices; $\Nbb = |\Ibb|$.
    \item $\Isc \subset V$: Sidechain atom indices; $\Nsc = |\Isc|$. ($V = \Ibb \cup \Isc$).
    \item $z_{\mathrm{res},j} \in \R^{d_p}$: Local pooled context vector summarizing the deformation of residue $R_j$ (this corresponds to $\mathbf{h}_{R_j}^{(b)}$ as used in Appendix~\ref{app:residue_pooling_details}).
    \item $\Xtrue \in \R^{N \times 3}$: Ground truth aligned coordinates. $\Xtrue^{(b, i)}$ for atom $i$, sample $b$.
    \item $\Xpred \in \R^{N \times 3}$: Predicted coordinates.
    \item $\Xref \in \R^{N \times 3}$: Reference structure coordinates (e.g., first frame).
    \item $d_z$: Encoder latent embedding dimensionality.
    \item $\Zlatent \in \R^{N \times d_z}$: Latent atom embeddings from encoder: $Z = \text{Encoder}(\Xtrue, E)$.
    \item $\Zref \in \R^{N \times d_z}$: Reference structure latent embeddings: $Z_{\text{ref}} = \text{Encoder}(\Xref, E_{\text{ref}})$.
    \item $C \in \R^{N \times d_c}$: General conditioning tensor (typically $C=\Zref$). $C_{ex}$ is batch-expanded.
    \item $d_p$: Pooled context vector dimension.
    \item $\mathcal{P}$: Generic pooling operator.
    \item $\mathcal{R} = \{R_1, ..., R_{N_{\text{res}}}\}$: Partition of atoms into residues.
    \item $f: V \to \{1, ..., N_{\text{res}}\}$: Atom-to-residue mapping.
    \item $\phi, \psi, \chi_k$: Dihedral angles; $\alpha \in \mathcal{A}$ is a generic type.
    \item $M_{\alpha}(j)$: Mask for valid angle $\alpha$ in residue $j$.
    \item $P(\alpha_{\text{pred}}), P(\alpha_{\text{true}})$: Empirical angle distributions.
    \item $D(\cdot \| \cdot)$: Divergence function (KL, JS).
    \item $w_{\text{base}}, \lambda_{\text{mse}}, \lambda_{\text{div}}$: Loss weights.
    \item $f_{\text{dih}}$: Probability of applying dihedral-based loss terms during stochastic fine-tuning.
    \item $\| \mathbf{v} \|^2$: Squared Euclidean norm.
    \item $T$: Diffusion timesteps.
    \item $\beta_t, \alpha_t, \bar{\alpha}_t$: Diffusion schedule parameters.
    \item $\mathbf{h}_0$: Initial pooled latent embedding for diffusion.
    \item $\mathbf{h}_t$: Noisy latent at step $t$.
    \item $\epsilon \sim \mathcal{N}(0, I)$: Standard Gaussian noise.
    \item $\epsilon_\theta(\mathbf{h}_t, t)$: Denoising network predicting noise $\epsilon$.
\end{itemize}

\subsection{Overall Training and Generation Workflow}
\label{app:workflow_details}
The LD-FPG framework follows a multi-phase training and generation procedure, outlined in Algorithm~\ref{alg:main_workflow_appendix}.

\begin{algorithm}[htbp] 
\caption{Overall Training and Generation Workflow (LD-FPG)}
\label{alg:main_workflow_appendix}
\begin{algorithmic}[1] 
\State \textbf{Input:} Aligned coordinates file (\texttt{my\_protein.json}), Topology file (\texttt{condensed\_residues.json}), Reference PDB (\texttt{heavy\_chain.pdb}).
\State \textbf{Parameters:} Encoder config ($d_z, K, \dots$), Decoder config (Pooling Type, $H, W, N_{layers}, \dots$), Optional fine-tuning weights ($\lambda_{mse}, \lambda_{div}$), Diffusion config ($T, \beta_{start}, \beta_{end}, \epsilon_\theta$ type).

\Statex \textbf{// --- Preprocessing (Details in Appendix~\ref{app:input_processing_details}) ---}
\State Load aligned coordinates $\{\Xtrue^{(f)}\}_{f=1}^{N_{\text{frames}}}$ from \texttt{my\_protein.json}.
\State Load topology (atom indices $\Ibb, \Isc$, residue map $f$, dihedral defs.) from \texttt{condensed\_residues.json}.
\State Build graph dataset $GraphDataset = \{\text{BuildGraph}(\Xtrue^{(f)}, k=4) \}_{f=1}^{N_{\text{frames}}}$.

\Statex \textbf{// --- Phase 1: Encoder Pre-training (Optional) (Details in Appendix~\ref{app:encoder_config_details_ext} ---}
\State Initialize $\text{Encoder}_{\theta}$ (ChebNet model).
\State Train $\text{Encoder}_{\theta}$ on $GraphDataset$ using coordinate reconstruction loss $\Lhno$ (Eq. in Appendix~\ref{app:loss_function_formulations}).
\State Save best encoder parameters $\theta^*$.

\Statex \textbf{// --- Phase 2: Decoder Training (Details in Appendix~\ref{app:decoder_architectures_summary}) ---}
\State Load pre-trained $\text{Encoder}_{\theta^*}$ and freeze weights.
\State Generate latent embeddings $Z^{(f)} = \text{Encoder}_{\theta^*}(\Xtrue^{(f)})$ for all frames $f$.
\State Create Decoder Input Dataset $D_{dec} = \{(Z^{(f)}, \Xtrue^{(f)}) \mid f=1..N_{\text{frames}}\}$.
\State Define conditioner $C = \Zref = \text{Encoder}_{\theta^*}(\Xtrue^{(1)})$ (Details in Appendix~\ref{app:conditioning_tuning_details_ext}). 

\State \textbf{Select Decoder Variation:}
\If{PoolingType is Blind}
    \State Initialize $\text{Decoder}_{\phi} \gets \text{BlindPoolingDecoder}(\dots)$.
    \State Train $\text{Decoder}_{\phi}$ on $D_{dec}$ using coordinate loss $\Ldec = \Lcoord$.
    \State \textit{Optional Fine-tuning:} Continue training with $\Ldec = w_{\text{base}}\Lcoord + \lambda_{mse}\Lmseh + \lambda_{div}\Ldivh$ (stochastically, see Appendix~\ref{app:loss_function_formulations}).
    \State Save best decoder parameters $\phi^*$.
\ElsIf{PoolingType is Sequential}
    \State Initialize $\text{BBDecoder}_{\phi_{bb}}, \text{SCDecoder}_{\phi_{sc}}(\dots)$.
    \State Train $\text{BBDecoder}_{\phi_{bb}}$ on $D_{dec}$ using $\Lbb = \Lcoord^{\text{bb}}$. Freeze $\phi_{bb}^*$.
    \State Train $\text{SCDecoder}_{\phi_{sc}}$ on $D_{dec}$ using $\Lsc = \Lcoord^{\text{full}}$ (requires frozen $\text{BBDecoder}_{\phi_{bb}^*}$).
    \State Save best parameters $\phi_{bb}^*$, $\phi_{sc}^*$.
\ElsIf{PoolingType is Residue-Based}
    \State Initialize $\text{Decoder}_{\phi} \gets \text{ResidueBasedDecoder}(\dots)$.
    \State Train $\text{Decoder}_{\phi}$ on $D_{dec}$ using coordinate loss $\Ldec = \Lcoord$.
    \State Save best decoder parameters $\phi^*$.
\EndIf
\Statex \textbf{// --- Phase 3: Latent Diffusion Training (Details in Appendix~\ref{app:diffusion_model_methodology}) ---}
\State Load best $\text{Encoder}_{\theta^*}$ and $\text{Decoder}_{\phi^*}$ (or relevant pooling part).
\State Generate pooled latent embeddings $\mathbf{h}_0^{(f)} = \text{Pool}(Z^{(f)})$ for all $f$, using the specific pooling mechanism of the chosen decoder.
\State Create $DiffusionInputDataset = \{\mathbf{h}_0^{(f)}\}$.
\State Initialize $\epsilon_\theta$ (Denoising model).
\State Train $\epsilon_\theta$ on $DiffusionInputDataset$ using $\mathcal{L}_{\text{diffusion}}$ (Eq. \ref{eq:diffusion_loss_main}).
\State Save best diffusion model parameters $\theta_{diff}^*$.

\Statex \textbf{// --- Output Generation (Sampling) ---}
\State Load best models: $\text{Encoder}_{\theta^*}$, $\text{Decoder}_{\phi^*}$ (or $\text{BBDecoder}_{\phi_{bb}^*}, \text{SCDecoder}_{\phi_{sc}^*}$), $\epsilon_{\theta_{diff}}^*$.
\State Sample novel pooled latent(s) $\mathbf{h}_0^{\text{gen}}$ using $\epsilon_{\theta_{diff}}^*$ (Algorithm in Appendix~\ref{app:diffusion_model_methodology}).
\State \textbf{Decode generated latent(s):} (Feed $\mathbf{h}_0^{\text{gen}}$ into appropriate decoder stage)
\State $\Xpred^{\text{gen}} \gets \text{Decoder}_{\phi^*}(\dots, \text{context}=\mathbf{h}_0^{\text{gen}}, C)$ 
\State \textbf{Output:} Generated coordinates $\{\Xpred^{\text{gen}}\}$
\end{algorithmic}
\end{algorithm}
