\section{Decoder Architectures and Pooling Strategies}
\label{app:decoder_architectures_summary}

This section provides a detailed description of the three primary pooling strategies employed within the decoder architectures: Blind pooling, sequential pooling, and residue-based pooling. For each strategy, we delineate how atom-wise latent embeddings $Z \in \R^{B \times N \times d_z}$ (where $B$ is batch size, $N$ is the number of heavy atoms, and $d_z$ is the latent dimension per atom) and a conditioner $C \in \R^{N \times d_c}$ (typically the latent representation of the reference structure, $\Zref$) are processed to generate the input for the final coordinate prediction MLP. Specific hyperparameter configurations for representative models are detailed in the Extended Technical Appendix (Section~\ref{app:extended_technical}).

\subsection{Blind Pooling Strategy}
\label{app:blind_pooling_details}

The blind pooling strategy aims to capture a global context from all atom embeddings for the entire protein structure.
Let $Z^{(b)} \in \R^{N \times d_z}$ be the latent atom embeddings for a single sample $b$ in a batch.
\begin{enumerate}
    \item \textbf{Global Pooling:} The atom embeddings $Z^{(b)}$ are treated as an image-like tensor and processed by a 2D adaptive average pooling layer, $\mathcal{P}_{\text{global}}$ (typically \texttt{nn.AdaptiveAvgPool2d} with output size $H \times W$). This operation pools across all $N$ atoms for each sample in the batch:
    $$ \mathbf{h}_{\text{global}}^{(b)} = \mathcal{P}_{\text{global}}(Z^{(b)}) \in \R^{d_p} $$
    where $d_p = H \cdot W$ is the dimension of the pooled global context vector. For a batch, this results in $\mathbf{H}_{\text{global}} \in \R^{B \times d_p}$.

    \item \textbf{Context Expansion:} This global context vector $\mathbf{h}_{\text{global}}^{(b)}$ is then expanded (tiled) to match the number of atoms $N$, resulting in $\mathbf{H}_{\text{global\_ex}}^{(b)} \in \R^{N \times d_p}$, where each row $i$ (for atom $i$) is identical to $\mathbf{h}_{\text{global}}^{(b)}$. For a batch, this is $\mathbf{H}_{\text{global\_ex}} \in \R^{B \times N \times d_p}$.

    \item \textbf{Conditioner Expansion:} The conditioner $C \in \R^{N \times d_c}$ is expanded for the batch to $C_{ex} \in \R^{B \times N \times d_c}$.

    \item \textbf{MLP Input Formulation:} For each atom $i$ in sample $b$, the input to the final MLP, $\text{MLP}_{\text{blind}}$, is formed by concatenating its corresponding expanded global context and its conditioner vector:
    $$ M_{\text{in}}^{(b,i)} = \text{concat}(\mathbf{h}_{\text{global}}^{(b)}, C^{(b,i)}) \in \R^{d_p + d_c} $$
    Note that $\mathbf{h}_{\text{global}}^{(b)}$ is the same for all atoms $i$ within sample $b$.

    \item \textbf{Coordinate Prediction:} A shared $\text{MLP}_{\text{blind}}$ processes $M_{\text{in}}^{(b,i)}$ for each atom to predict its 3D coordinates:
    $$ \Xpred^{(b,i)} = \text{MLP}_{\text{blind}}(M_{\text{in}}^{(b,i)}) \in \R^3 $$
    This results in the full predicted structure $\Xpred \in \R^{B \times N \times 3}$.
\end{enumerate}

\subsection{Sequential Pooling Strategy}
\label{app:sequential_pooling_details}
The sequential pooling strategy decodes the protein structure in two stages: first the backbone atoms ($\Ibb$), then the sidechain atoms ($\Isc$), using information from the preceding stage.

\subsubsection{Backbone Decoder Stage}
Let $Z^{(b)} \in \R^{N \times d_z}$ be the full latent atom embeddings and $C^{(b)} \in \R^{N \times d_c}$ be the full conditioner for sample $b$.
\begin{enumerate}
    \item \textbf{Backbone Embedding Selection:} Latent embeddings $Z_{\text{bb}}^{(b)} \in \R^{\Nbb \times d_z}$ and conditioner vectors $C_{\text{bb}}^{(b)} \in \R^{\Nbb \times d_c}$ corresponding to backbone atoms $\Ibb$ are selected.

    \item \textbf{Backbone Pooling:} $Z_{\text{bb}}^{(b)}$ is pooled using a 2D adaptive average pooling layer $\mathcal{P}_{\text{bb}}$ (e.g., \texttt{BlindPooling2D} from the implementation, with output size $H_{bb} \times W_{bb}$) to obtain a backbone-specific context vector:
    $$ \mathbf{h}_{\text{bb}}^{(b)} = \mathcal{P}_{\text{bb}}(Z_{\text{bb}}^{(b)}) \in \R^{d_{p,bb}} $$
    where $d_{p,bb} = H_{bb} \cdot W_{bb}$. For a batch, this is $\mathbf{H}_{\text{bb}} \in \R^{B \times d_{p,bb}}$.

    \item \textbf{Context and Conditioner Expansion:} $\mathbf{h}_{\text{bb}}^{(b)}$ is expanded to $\mathbf{H}_{\text{bb\_ex}}^{(b)} \in \R^{\Nbb \times d_{p,bb}}$. $C_{\text{bb}}^{(b)}$ is used directly.

    \item \textbf{MLP Input for Backbone Atoms:} For each backbone atom $j \in \Ibb$ in sample $b$, the input to the backbone MLP, $\text{MLP}_{\text{bb}}$, is:
    $$ M_{\text{in, bb}}^{(b,j)} = \text{concat}(\mathbf{h}_{\text{bb}}^{(b)}, C_{\text{bb}}^{(b,j)}) \in \R^{d_{p,bb} + d_c} $$

    \item \textbf{Backbone Coordinate Prediction:} A shared $\text{MLP}_{\text{bb}}$ predicts backbone coordinates:
    $$ {\Xpred}_{\text{bb}}^{(b,j)} = \text{MLP}_{\text{bb}}(M_{\text{in, bb}}^{(b,j)}) \in \R^3 $$
    This yields the predicted backbone structure $X_{pred_{\text{bb}}} \in \R^{B \times \Nbb \times 3}$.
\end{enumerate}
\subsubsection{Sidechain Decoder Stage}
\label{app:sequential_sidechain_decoder_details} % Added a more specific label
This stage predicts sidechain atom coordinates ${\Xpred}_{\text{sc}}$ using the full latent embeddings $Z^{(b)} \in \R^{N \times d_z}$, the conditioner $C^{(b)} \in \R^{N \times d_c}$, and the predicted backbone coordinates ${\Xpred}_{\text{bb}}^{(b)} \in \R^{B \times \Nbb \times 3}$ from the Backbone Decoder Stage.

\begin{enumerate}
    \item \textbf{Sidechain Embedding Selection:} Latent embeddings $Z_{\text{sc}}^{(b)} \in \R^{\Nsc \times d_z}$ corresponding to sidechain atoms $\Isc$ are selected from the full latent embeddings $Z^{(b)}$.

    \item \textbf{Sidechain Pooling:} The selected sidechain embeddings $Z_{\text{sc}}^{(b)}$ are pooled using a 2D adaptive average pooling layer $\mathcal{P}_{\text{sc}}$ (e.g., \texttt{BlindPooling2D} with output size $H_{sc} \times W_{sc}$) to obtain a sidechain-specific context vector for each sample in the batch:
    $$ \mathbf{h}_{\text{sc}}^{(b)} = \mathcal{P}_{\text{sc}}(Z_{\text{sc}}^{(b)}) \in \R^{d_{p,sc}} $$
    where $d_{p,sc} = H_{sc} \cdot W_{sc}$. For a batch, this results in $\mathbf{H}_{\text{sc}} \in \R^{B \times d_{p,sc}}$.

    \item \textbf{Feature Construction for Sidechain MLP Input:}
    The input to the sidechain MLP, $\text{MLP}_{\text{sc}}$, is a global vector $M_{\text{in, sc}}^{(b)}$ constructed per sample $b$. The construction varies based on the \texttt{arch\_type}:
    \begin{itemize}
        \item Let $X_{\text{pred, bb\_flat}}^{(b)} \in \R^{\Nbb \cdot 3}$ be the flattened predicted backbone coordinates for sample $b$.
        \item Let $C_{\text{sc}}^{(b)} \in \R^{\Nsc \times d_c}$ be the sidechain portion of the reference conditioner. If $d_c = d_z$, this is $Z_{\text{ref, sc}}^{(b)}$.
        This is flattened to $C_{\text{sc\_flat}}^{(b)} \in \R^{\Nsc \cdot d_c}$.
    \end{itemize}

    \textbf{Arch-Type 0:}
    The input consists of the flattened predicted backbone coordinates and the pooled sidechain context from the current frame's embeddings.
    $$ M_{\text{in, sc}}^{(b)}[\text{Arch 0}] = \text{concat}(X_{\text{pred, bb\_flat}}^{(b)}, \mathbf{h}_{\text{sc}}^{(b)}) $$
    The dimension of $M_{\text{in, sc}}^{(b)}[\text{Arch 0}]$ is $(\Nbb \cdot 3) + d_{p,sc}$.

    \textbf{Arch-Type 1:}
    This architecture adds a reduced representation of the sidechain portion of the reference conditioner.
    \begin{itemize}
        \item The flattened sidechain conditioner $C_{\text{sc\_flat}}^{(b)}$ is passed through a linear reduction layer:
        $$ C_{\text{sc\_reduced}}^{(b)} = \text{Linear}_{\text{sc\_reduce}}(C_{\text{sc\_flat}}^{(b)}) \in \R^{d'_{c,sc}} $$
        (e.g., $d'_{c,sc}=128$ in the implementation).
    \end{itemize}
    The MLP input is then:
    $$ M_{\text{in, sc}}^{(b)}[\text{Arch 1}] = \text{concat}(X_{\text{pred, bb\_flat}}^{(b)}, \mathbf{h}_{\text{sc}}^{(b)}, C_{\text{sc\_reduced}}^{(b)}) $$
    The dimension of $M_{\text{in, sc}}^{(b)}[\text{Arch 1}]$ is $(\Nbb \cdot 3) + d_{p,sc} + d'_{c,sc}$.

    \textbf{Arch-Type 2:}
    This architecture uses a reduced representation of both the predicted backbone coordinates and the sidechain portion of the reference conditioner.
    \begin{itemize}
        \item The flattened predicted backbone coordinates $X_{\text{pred, bb\_flat}}^{(b)}$ are passed through a linear reduction layer:
        $$ X_{\text{pred, bb\_reduced}}^{(b)} = \text{Linear}_{\text{bb\_reduce}}(X_{\text{pred, bb\_flat}}^{(b)}) \in \R^{d'_{\text{bb}}} $$
        (e.g., $d'_{\text{bb}}=128$ in the implementation).
        \item The sidechain conditioner is reduced as in Arch-Type 1 to $C_{\text{sc\_reduced}}^{(b)} \in \R^{d'_{c,sc}}$.
    \end{itemize}
    The MLP input is then:
    $$ M_{\text{in, sc}}^{(b)}[\text{Arch 2}] = \text{concat}(X_{\text{pred, bb\_reduced}}^{(b)}, \mathbf{h}_{\text{sc}}^{(b)}, C_{\text{sc\_reduced}}^{(b)}) $$
    The dimension of $M_{\text{in, sc}}^{(b)}[\text{Arch 2}]$ is $d'_{\text{bb}} + d_{p,sc} + d'_{c,sc}$.

    \item \textbf{Sidechain Coordinate Prediction:} The sidechain MLP, $\text{MLP}_{\text{sc}}$, processes the constructed input vector $M_{\text{in, sc}}^{(b)}$ (corresponding to the chosen \texttt{arch\_type}) to predict all sidechain coordinates for sample $b$ simultaneously:
    $$ X_{\text{pred, sc\_flat}}^{(b)} = \text{MLP}_{\text{sc}}(M_{\text{in, sc}}^{(b)}) \in \R^{\Nsc \cdot 3} $$
    This flattened output is then reshaped to $X_{\text{pred, sc}}^{(b)} \in \R^{\Nsc \times 3}$.

    \item \textbf{Full Structure Assembly:} The final predicted structure $\Xpred^{(b)} \in \R^{N \times 3}$ for sample $b$ is assembled by combining the predicted backbone coordinates $X_{\text{pred, bb}}^{(b)}$ and the predicted sidechain coordinates $X_{\text{pred, sc}}^{(b)}$.
\end{enumerate}

\subsection{Residue-based Pooling Strategy}
\label{app:residue_pooling_details}
The Residue-based Pooling strategy generates a context vector specific to each residue and uses this local context for predicting the coordinates of atoms within that residue.
Let $Z^{(b)} \in \R^{N \times d_z}$ be the latent atom embeddings for sample $b$. Let $V_j$ be the set of atom indices belonging to residue $R_j$, and $f: V \to \{1, ..., N_{\text{res}}\}$ be the mapping from a global atom index to its residue index.
\begin{enumerate}
    \item \textbf{Per-Residue Pooling:} For each residue $R_j$ in sample $b$:
        \begin{itemize}
            \item Select atom embeddings for residue $R_j$: $Z_{R_j}^{(b)} \in \R^{|V_j| \times d_z}$.
            \item Pool these embeddings using a 2D adaptive average pooling layer $\mathcal{P}_{\text{res}}$ (e.g., \texttt{nn.AdaptiveAvgPool2d} with output $H \times W$):
            $$ \mathbf{h}_{R_j}^{(b)} = \mathcal{P}_{\text{res}}(Z_{R_j}^{(b)}) \in \R^{d_p} $$
            where $d_p = H \cdot W$.
        \end{itemize}
    This results in a set of $N_{\text{res}}$ pooled vectors for sample $b$, which can be represented as $\mathbf{H}_{\text{res}}^{(b)} \in \R^{N_{\text{res}} \times d_p}$. For a batch, this is $\mathbf{H}_{\text{res}} \in \R^{B \times N_{\text{res}} \times d_p}$.

    \item \textbf{Atom-Specific Context Assembly:} For each atom $i$ in sample $b$, its specific context vector is the pooled vector of its parent residue $R_{f(i)}$:
    $$ \mathbf{h}_{\text{atom\_context}}^{(b,i)} = \mathbf{h}_{R_{f(i)}}^{(b)} \in \R^{d_p} $$
    This can be gathered for all atoms to form $\mathbf{H}_{\text{atom\_context}}^{(b)} \in \R^{N \times d_p}$.

    \item \textbf{Conditioner Expansion:} The conditioner $C \in \R^{N \times d_c}$ is expanded for the batch to $C_{ex} \in \R^{B \times N \times d_c}$.

    \item \textbf{MLP Input Formulation:} For each atom $i$ in sample $b$, the input to the final MLP, $\text{MLP}_{\text{res}}$, is formed by concatenating its residue's pooled context and its specific conditioner vector:
    $$ M_{\text{in, res}}^{(b,i)} = \text{concat}(\mathbf{h}_{\text{atom\_context}}^{(b,i)}, C^{(b,i)}) \in \R^{d_p + d_c} $$

    \item \textbf{Coordinate Prediction:} A shared $\text{MLP}_{\text{res}}$ processes $M_{\text{in, res}}^{(b,i)}$ for each atom to predict its 3D coordinates:
    $$ \Xpred^{(b,i)} = \text{MLP}_{\text{res}}(M_{\text{in, res}}^{(b,i)}) \in \R^3 $$
    This results in the full predicted structure $\Xpred \in \R^{B \times N \times 3}$.
\end{enumerate}
This strategy allows the model to learn representations that are localized at the residue level, potentially capturing residue-specific conformational preferences more directly.


