\section{Latent Diffusion Model Details}
\label{app:diffusion_model_methodology}

This section details the Denoising Diffusion Probabilistic Model (DDPM)~\citep{ho2020denoising} utilized in our framework. The DDPM operates on the pooled latent embeddings $\mathbf{h}_0 \in \R^{d_p}$ (where $d_p$ is the dimension of the pooled latent space, dependent on the pooling strategy) obtained from the encoder and pooling stages. Specific architectures and hyperparameters for the denoising network $\epsilon_\theta$ are discussed in the Extended Technical Appendix (Section~\ref{app:extended_technical}).

\subsection{DDPM Formulation}
The DDPM consists of a predefined forward noising process and a learned reverse denoising process.

\noindent\textbf{Forward Process (Noising):}
The forward process gradually adds Gaussian noise to an initial latent embedding $\mathbf{h}_0$ over $T$ discrete timesteps. At each timestep $t$, the transition is defined by:
$$ q(\mathbf{h}_t | \mathbf{h}_{t-1}) = \mathcal{N}(\mathbf{h}_t; \sqrt{1-\beta_t} \mathbf{h}_{t-1}, \beta_t \mathbf{I}) $$
where $\{\beta_t\}_{t=1}^T$ is a predefined variance schedule (e.g., linear, cosine) that controls the noise level at each step. A useful property of this process is that we can sample $\mathbf{h}_t$ at any arbitrary timestep $t$ directly from $\mathbf{h}_0$:
$$ q(\mathbf{h}_t | \mathbf{h}_0) = \mathcal{N}(\mathbf{h}_t; \sqrt{\bar{\alpha}_t} \mathbf{h}_0, (1 - \bar{\alpha}_t) \mathbf{I}) $$
where $\alpha_t = 1 - \beta_t$ and $\bar{\alpha}_t = \prod_{s=1}^t \alpha_s$. As $t \to T$, if the schedule is chosen appropriately, $\mathbf{h}_T$ approaches an isotropic Gaussian distribution $\mathcal{N}(0, \mathbf{I})$.

\noindent\textbf{Reverse Process (Denoising):}
The reverse process aims to learn the transition $q(\mathbf{h}_{t-1} | \mathbf{h}_t)$, which is intractable directly. Instead, a neural network, $\epsilon_\theta(\mathbf{h}_t, t)$, is trained to predict the noise component $\epsilon$ that was added to $\mathbf{h}_0$ to produce $\mathbf{h}_t = \sqrt{\bar{\alpha}_t}\mathbf{h}_0 + \sqrt{1-\bar{\alpha}_t}\epsilon$, where $\epsilon \sim \mathcal{N}(0, \mathbf{I})$. The network is optimized by minimizing the simplified DDPM loss function (as shown in Eq.~\ref{eq:diffusion_loss_main} in the main text):
$$ \mathcal{L}_{\text{diffusion}}(\theta) = \mathbb{E}_{t, \mathbf{h}_0, \epsilon} \left[ \| \epsilon - \epsilon_\theta(\sqrt{\bar{\alpha}_t}\mathbf{h}_0 + \sqrt{1-\bar{\alpha}_t}\epsilon, t) \|^2 \right] $$
where $t$ is sampled uniformly from $\{1, ..., T\}$.

\subsection{Sampling New Latent Embeddings}
Once the denoising network $\epsilon_\theta$ is trained, new latent embeddings $\mathbf{h}_0^{\text{gen}}$ can be generated by starting with a sample from the prior distribution, $\mathbf{h}_T \sim \mathcal{N}(0, \mathbf{I})$, and iteratively applying the reverse denoising step:
$$ \mathbf{h}_{t-1} = \frac{1}{\sqrt{\alpha_t}} \left( \mathbf{h}_t - \frac{\beta_t}{\sqrt{1-\bar{\alpha}_t}} \epsilon_\theta(\mathbf{h}_t, t) \right) + \sigma_t \mathbf{z} $$
where $\mathbf{z} \sim \mathcal{N}(0, \mathbf{I})$ for $t > 1$, and $\mathbf{z} = 0$ for $t=1$. The variance $\sigma_t^2$ is typically set to $\beta_t$ or $\tilde{\beta}_t = \frac{1-\bar{\alpha}_{t-1}}{1-\bar{\alpha}_t}\beta_t$. The full sampling procedure is outlined in Algorithm~\ref{alg:app_sampling_diffusion_revised}.

\begin{algorithm}[htbp!]
\caption{Reverse Diffusion Sampling for Latent Embeddings}
\label{alg:app_sampling_diffusion_revised}
\begin{algorithmic}[1]
\State \textbf{Input:} Trained denoising model $\epsilon_\theta$, number of generation samples $B_{\text{gen}}$, dimension of pooled latent $d_p$, diffusion timesteps $T$, schedule parameters (e.g., $\beta_1, ..., \beta_T$).
\State Calculate $\alpha_t = 1-\beta_t$ and $\bar{\alpha}_t = \prod_{s=1}^t \alpha_s$ for all $t$.
\State Set $\sigma_t^2 = \beta_t$ (or alternative like $\tilde{\beta}_t$).
\State Sample initial noise $\mathbf{h}_T \sim \mathcal{N}(0, \mathbf{I})$ of shape $(B_{\text{gen}}, d_p)$.
\For{$t = T, ..., 1$}
    \State Sample $\mathbf{z} \sim \mathcal{N}(0, \mathbf{I})$ of shape $(B_{\text{gen}}, d_p)$ if $t > 1$, else $\mathbf{z} = \mathbf{0}$.
    \State Predict noise: $\epsilon_{\text{pred}} \leftarrow \epsilon_\theta(\mathbf{h}_t, t)$
    \State Calculate conditional mean: $\mu_\theta(\mathbf{h}_t, t) = \frac{1}{\sqrt{\alpha_t}} \left( \mathbf{h}_t - \frac{\beta_t}{\sqrt{1-\bar{\alpha}_t}} \epsilon_{\text{pred}} \right)$
    \State Update latent sample: $\mathbf{h}_{t-1} \leftarrow \mu_\theta(\mathbf{h}_t, t) + \sigma_t \mathbf{z}$
\EndFor
\State \textbf{Output:} Generated latent embeddings $\mathbf{h}_0^{\text{gen}} = \mathbf{h}_{0}$
\end{algorithmic}
\end{algorithm}
