In a constrained Markov game, an initial state $s_1$ is drawn from the initial distribution $\rho$, i.e., $s_1 \sim \rho\in\Delta(\mc S)$.
At each timestep $t$, the players select a joint action $a_t\sim \pi_t(\cdot\lvert s_t)$ based on policy $\pi\in\Pi_M$ and each player receives a reward $r_t^i(s_t,a_t)$ and a set of  constraints $\{g_t^{i,j}(s_t,a_t)\}_{j\in[J]}$. Then, the state $s_t$ transitions to a new state $s_{t+1} \sim P_t(\cdot\lvert s_t, a_t)$. %Over the episodes, each agent $i$ collects its stage rewards and constraints. 
The expected cumulative reward over the horizon $H$ of player $i$ is defined as:\looseness-1
\[
V^{r^i}(\pi) := \mathbb{E}_{s_1 \sim \rho, a_t \sim \pi_t(\cdot | s_t), s_{t+1} \sim P_t(\cdot | s_t, a_t)} \left[ \sum_{t=1}^{H} r^i_t(s_t, a_t) \right],
\]
and its expected cumulative constraint value  over the horizon $H$ is defined as:
\begin{align*}
    V^{g^{i,j}}(\pi) := \mathbb{E}_{s_1 \sim \rho, a_t \sim \pi_t(\cdot | s_t), s_{t+1} \sim P_t(\cdot | s_t, a_t)} \left[ \sum_{t=1}^{H} g^{i,j}_t(s_t, a_t) \right],\, \forall j\in[J].
\end{align*}

The transition dynamics $P$ and policy $\pi\in\Pi_M$ induce a distribution over state-action pairs, the so-called state-action occupancy measure, given by:
\begin{align*}
    d_1^\pi(s_1,a_1) &= \rho(s_1)\pi_1(a_1\lvert s_1), \,
    \forall (s_1,a_1)\in\mc S\times\mc A   ,\\
    d_t^\pi(s_t,a_t) &= \!\!\!\!\!\!\!\! \!\!\!\!\sum_{(s_{t-1},a_{t-1})\in\mc S\times \mc A}\!\!\!\!\!\!\!\!\!\!\!\!d_{t-1}^\pi(s_{t-1},a_{t-1}) P_{t-1}(s_t\lvert s_{t-1},a_{t-1})\pi_t(a_t\lvert s_t),\,\forall (s_t,a_t)\in\mc S\times\mc A, t=2,\dots,H.
\end{align*}
%
The reward function and constraint functions can then equivalently be expressed as:
\begin{equation}\label{eq:reward_constraint_via_occupancy}
  \begin{split}
    &V^{r^i}(\pi) = \sum_{t=1}^H \sum_{(s_t,a_t)\in\mc S\times \mc A} d_t^\pi(s_t,a_t) r_t^i(s_t,a_t),\\
    &V^{g^{i,j}}(\pi) = \sum_{t=1}^H \sum_{(s_t,a_t)\in\mc S\times \mc A} d_t^\pi(s_t,a_t) g_t^{i,j}(s_t,a_t), \,\forall j\in[J].
  \end{split}
\end{equation}
In a constrained Markov game, each player $i$ is subject to constraints of the form:
\begin{align}\label{eq:i-feasible_set}
    V^{g^{i,j}}(\pi)\geq c^{i,j},\,\forall j\in[J].
\end{align}
A policy $\pi$ is said to be $i$-feasible if Inequality \eqref{eq:i-feasible_set} above holds for every $j\in[J]$. We denote the set of $i$-feasible policies by:
\begin{align}
    \mc C_\pi^i:=\{\pi\in\Pi_M\mid V^{g^{i,j}}(\pi)\geq c^{i,j},\, \forall j\in[J]\}.\label{eq:i-feasible}
\end{align}
Furthermore, a policy $\pi$ is called feasible if it is $i$-feasible for all $i\in\mc N$. We denote the set of feasible policies by:
\begin{align}
    \mc C_\pi:=\{\pi\in\Pi_M\mid V^{g^{i,j}}(\pi)\geq c^{i,j},\, \forall j\in[J],\forall i\in\mc N\}.\label{eq:feasible_set}
\end{align}
Observe that $\mc C_\pi=\bigcap_{i\in\mc N}\mc C_\pi^i$. For Markov games with \emph{common coupling constraints}, we note that $\mc C_\pi^i$ reduces to $\mc C_\pi$ for all $i\in\mc N$ since each player has the same set of constraints.

\section{Equivalent notions of constrained correlated equilibrium}\label{sec:equinotion}

An important solution concept in Markov games is the correlated equilibrium. The constrained correlated equilibrium generalizes this notion to \emph{constrained Markov games}. Such an equilibrium is defined as a policy that is robust against a given set of players' modifications, in the sense that for each player $i$, deviating to a new policy under a set of modifications will either be not profitable or result in an infeasible policy. In the following, we define possible sets of modifications $\Phi^i$, distinguishing between non-Markovian and Markovian, as well as between stochastic and deterministic modifications.

\begin{itemize}
    \item For player $i$, the set of \emph{non-Markovian stochastic} modifications is given by:\looseness-1
\begin{align*}
    \Phi_{NM}^i:=\{\phi^i := \{\phi_t^i\}_{t=1}^{H},\text{ where } \phi_t^i: (\mc S \times \mc A)^{t-1} \times \mc S \times \mAi \to \Delta(\mAi),\,\forall t\in[H]\}.
\end{align*}
    \item For player $i$, the set of \emph{Markovian stochastic} modifications is given by:
\begin{align*}
    \Phi_{M}^i:=\{\phi^i := \{\phi_t^i\}_{t=1}^{H},\text{ where }\phi_t^i: \mc S \times \mAi \to \Delta(\mAi),\,\forall t\in[H]\}.
\end{align*}
\end{itemize}
%
In the above two definitions, if $\Delta(\mc A^i)$ is replaced by $\mc A^i$, then we refer to these sets as \emph{non-Markovian deterministic} denoted by $\Phi_{NM,det}^i$ and \emph{Markovian deterministic} modifications denoted by $\Phi_{M,det}^i$, respectively. Note that $\Phi_M^i\subseteq\Phi_{NM}^i$, $\Phi_{NM,det}^i\subseteq\Phi_{NM}^i$, and 
$\Phi_{M,det}^i\subseteq\Phi_{M}^i$. Given $\phi^i\in\Phi^i_{NM}$, a modified policy $\phi^i\circ\pi:=\{\phi_t^i\circ\pi_t\}_{t=1}^H$ is a policy modified by $\phi^i$, where $(\hat a_t^i,a_t^{-i})\sim\pi_t$  and then $\phi_t^i$ modifies $\hat a_t^i$ to another $a_t^i$ at random. Formally, for all $t\in[H]$, all $a_t\in\mc A$, and all $s_t\in\mc S$, it is given by:\looseness-1
    \begin{align*}
        (\phi_t^i\circ\pi_t)(a_t\lvert s_{1:t}, a_{1:t-1}) =\sum_{a_t^i\in\mc A^i} \phi_t^i( a_t^i\lvert s_{1:t}, a_{1:t-1}, \hat a_t^i)\pi_t((\hat a_t^i,a_t^{-i})\lvert s_t). 
    \end{align*}


