\begin{definition}[Constrained correlated equilibrium] \label{def:con_CE}
    A Markovian policy $\pi\in\Pi_M$ is a constrained correlated equilibrium if $\pi$ is feasible, namely, $\pi\in\mc C_\pi$, and if for any player $i \in \mc N$ the following holds:
    \begin{align}\label{eq_notionCE}
       V^{r^i}(\pi) \ge \max_{\text{$\phi^i\in\Phi_{NM}^i$ is $i$-feasible}}V^{r^i}(\phi^i \circ \pi).
    \end{align}
    In the maximization above, $\phi^i$ is said to be $i$-feasible if the modified policy $\phi^i\circ\pi $ is $i$-feasible, namely, $\phi^i\circ\pi$ satisfies Inequality \eqref{eq:i-feasible_set} for every $j\in[J]$.
\end{definition}
%In a constrained correlated equilibrium, $\pi$ is a feasible policy such that no player can improve its value function by employing any stochastic modification $\phi^i$ that results in a feasible modified policy $\phi^i\circ\pi$.

In unconstrained Markov games, it is known that replacing non-Markovian stochastic modifications $\Phi_{NM}^i$ with non-Markovian deterministic modifications $\Phi_{NM,det}^i$ results in an equivalent definition of correlated equilibria \cite[Theorem~1.1]{chen2022finding}. We further strengthen this statement by showing that replacing $\Phi_{NM}^i$ with \emph{Markovian deterministic} modifications $\Phi_{M,det}^i$ is sufficient for the characterization of correlated equilibria. We provide a proof in Appendix \ref{app:proof_cor_equinotion}.\looseness-1

\begin{proposition}\label{cor_specialcase}
In unconstrained Markov games, policy $\pi\in\Pi_M$ is a correlated equilibrium if for any player $i\in\mc N$ the following holds:
  \begin{align*}
        &V^{r^i}(\pi)\geq\max_{\phi^i\in\Phi^i_{M,det}}V^{r^i}(\phi^i\circ\pi).
    \end{align*}
\end{proposition}
In the presence of constraints, \cite[Theorem~1.2]{chen2022finding} shows that restricting to deterministic modifications will result in a strictly weaker notion of constrained correlated equibriua. This motivates the question of whether we can limit the class of modifications in Definition \ref{def:con_CE} to get equivalent notions of constrained correlated equilibria. Our result below addresses this.\looseness-1
\begin{theorem}\label{cor:equinotion}
    The following statements are equivalent:
    \begin{enumerate}
        \item Policy $\pi\in\Pi_M$ is a constrained correlated equilibrium as per Definition \ref{def:con_CE}.
        \item Policy $\pi\in\Pi_M$ is feasible and for any player $i \in \mc N$ the following holds:
    \begin{align*}
       V^{r^i}(\pi) \ge \max_{\text{$\phi^i\in\Phi_{M}^i$ is $i$-feasible}} V^{r^i}(\phi^i \circ \pi).
    \end{align*}
        \item Policy $\pi\in\Pi_M$ is feasible and for any player $i\in\mc N$ the following holds:
  \begin{align*}
        &V^{r^i}(\pi)\geq\max_{\text{$\alpha\in \Delta(K^i)$ is $i$-feasible}} \sum_{k=1}^{K^i} \alpha_k V^{r^i}(\phi^i(k)\circ\pi),
    \end{align*}

    where $K^i:=|\Phi_{M,det}^i|$ and $\phi^i(k)\in\Phi_{M,det}^i$, $\forall k\in[K^i]$. We say that \( \alpha\in\Delta(K^i) \) is $i$-\textit{feasible} if  $\alpha\in\{\alpha\mid\sum_{k=1}^{K^i} \alpha_k V^{g^{i,j}}(\phi^i(k)\circ\pi) \geq c^{i,j},\,\forall j \in [J]\}$.
    \end{enumerate}
\end{theorem}

We provide a proof in Appendix~\ref{app:proof_cor_equinotion} and briefly summarize the results here. The equivalences above imply that in Inequality~\eqref{eq_notionCE} of Definition~\ref{def:con_CE}, we can equivalently consider either Markovian modifications \( \Phi^i_{M} \) or convex combinations of Markovian deterministic modifications \( \Phi^i_{M,\mathrm{det}} \). The former simplifies the verification of constrained correlated equilibria, while the latter plays a crucial role in our existence proof in the next section.

\begin{remark}
For learning (constrained) correlated equilibria $\pi\in\Pi_M$, Proposition \ref{cor_specialcase} and Theorem \ref{cor:equinotion} imply that it suffices to consider regret notions with respect to $\Phi^i_{M}$, contradicting the conjecture in \cite{cai2024near} that such modifications yield a weaker equilibrium notion.\looseness-1 
\end{remark}

