\subsection{Preliminary results}\label{sec:prelim_results}

%The proof of Theorem~\ref{thm_main} relies on constructing a point-to-set map \( f: \mathcal{C}_d \to 2^{\mathcal{C}_d} \), where \( \mathcal{C}_d \) denotes the set of feasible state-action occupancy measures, as defined in Equation~\eqref{eq:c_d}. 
For a given state-action occupancy measure \( d \in \mathcal{C}_d \), we define the corresponding feasible Markovian policy \( \pi \) via the point-to-set mapping \( \Gamma(d):\mc C_d\rightarrow 2^{\mc C_\pi} \) as follows: for every timestep $t\in[H]$, state \( s \in \mathcal{S} \) and action $a\in\mc A$,
\begin{align*}
    \pi_t(a| s) = 
  \begin{cases}
    \frac{d_t(s, a)}{\sum_a d_t(s, a)}, & \text{if } \sum_a d_t(s, a) \neq 0, \\
    \text{arbitrary distribution}, & \text{otherwise.}
  \end{cases}
\end{align*}

The next lemma below establishes properties of the set $\mc C_d$ and mapping $\Gamma(d)$.

\begin{lemma}\label{lem:mapping1}
The following holds:
\begin{enumerate}
    \item The set \( \mathcal{C}_d \) is compact and convex. 
    \item The mapping \( \Gamma(d) \) is upper semi-compact in $d\in\mc C_d$.
\end{enumerate}
\end{lemma}

\begin{proof}
Property 1 follows from \cite{altman2021constrained}. For Property 2, for each $d\in\mc C_d$, $\Gamma(d)$ by construction is a union over $t\in[H]$ and $s\in\mc S$ consisting of either singletons or $\Delta(\mc A)$, which is compact. Upper semi-continuity in $d\in\mc C_d$ follows from \cite[Proposition~3.4]{altman2000constrained}. \looseness-1
\end{proof}


Given player $i$ and policy $\pi\in\mc C_\pi$, recall that by Theorem \ref{cor:equinotion} finding the best feasible modification $\phi^i\in\Phi_{M}^i$ is equivalent to finding a feasible $\alpha\in\Delta(K^i)$ which can equivalently be formulated as the following linear program:

\paragraph{Linear Program {(\( LP^i(\pi)\)})} Find $\alpha\in\Delta(K^i)$, where $\Phi^i_{M,det}=\{\phi^i(k)\}_{k=1}^{K^i}$, such that: 
\begin{align*}
\max_{\alpha}\ &\sum_{k=1}^{K^i}\alpha_k V^{r^i}(\phi^i(k)\circ\pi) \\
\text{s.t. } &\sum_{k=1}^{K^i}\alpha_k V^{g^j}(\phi^i(k)\circ\pi)\ge c^j,\,\forall j\in[J],\tag{$LP^i(\pi)$} \label{lp}\\
&\sum_{k=1}^{K^i}\alpha_k=1,\\
&\alpha_k\ge 0,\,\forall k\in [K^i].
\end{align*}

Let \( \Omega^i(\pi) \) be the set of optimal solutions of \ref{lp}, and let \( \Psi^i(\pi) \) denote the optimal value of \ref{lp}. These mappings $\Omega^i(\pi)$ and $\Psi^i(\pi)$ satisfy the following properties:

\begin{lemma}\label{lem:mapping2}
Let Assumption \ref{ass:weakened_Slater} hold. Then, the following holds:
\begin{enumerate}
     %\item Given player \( i \) and policy $\pi$, let \( \phi^i \) be the optimal modification returned by solving \eqref{eq:problem_agent_i}, then $V^{r^i}(\phi^i\circ\pi)=\Psi^i(\pi)$.
    \item The optimal set \( \Omega^i(\pi) \) is convex and upper semi-compact in \( \pi\in\mc C_\pi \) for any \( i \in \mc N \).
    \item The optimal value \( \Psi^i(\pi) \) is continuous in \( \pi\in\mc C_\pi \) for any \( i \in \mc N \). 
\end{enumerate}
\end{lemma}

%The first property shows that the optimal value of the optimization problem in \eqref{eq:problem_agent_i} is equal to the optimal value of $LP^i(\pi)$  for a given player \(i\) and policy \(\pi\). 
We provide a proof in Appendix \ref{app:lem:mapping2}. The two properties demonstrate compactness and (upper semi-)continuity of the mappings $\Omega^i(\pi)$ and $\Psi^i(\pi)$. %These properties are crucial for the proof of the main theorem, where we show that the point-to-set mapping \(f\) satisfies the conditions of Kakutani's fixed-point theorem.\looseness-1
To connect the solution set $\Omega^i(\pi)$ of \ref{lp} to the set of feasible state-action occupnacy measures $\mc C_d$, we define a linear transformation which maps any $\pi\in\mc C_\pi$ to $d\in\mc C_d$:\looseness-1
\begin{align*}
    A^i(\pi) := \bigcup_{\alpha \in \Omega^i(\pi)} \left\{\sum_{k\in[K^i]} \alpha_k d_t^{\phi^i(k)\circ\pi}(s,a)\right\}_{t\in[H],\,(s,a)\in\mc S\times\mc A}.
\end{align*}


The following lemma, for which we provide a proof in Appendix \ref{app:lem:mapping3}, shows that $A^i(\pi)$ defines a valid mapping to $\mc C_d$ and is upper semi-compact.

\begin{lemma}\label{lem:mapping3}
For any player $i\in\mc N$ and policy $\pi\in\mathcal{C}_\pi$, the point-to-set mapping~$A^i(\pi):\mc C_\pi\rightarrow 2^{\mc C_d}$ is upper semi-compact. % mapping from $\mathcal{C}_\pi$ to a convex and compact set in $2^{\mathcal{C}_d}$, and upper semi-continuous for any $\pi\in\mathcal{C}_\pi$.
\end{lemma}

