\begin{proof}[Proof of Theorem \ref{thm_main}]
Consider the point-to-set map $f:\mathcal{C}_d \to 2^{\mathcal{C}_d}$ given by:
\begin{align*}
   f(d):= \bigcup_{i\in\mc N} f^i(\Gamma(d)),
\end{align*}
where for each player $f^i:\mathcal{C}_\pi \to 2^{\mathcal{C}_d}$ is a point-to-set map defined as:
\begin{align*}
f^i(\pi) &:=\left( 1 -  \frac{\Psi^i(\pi)- V^{{r}^{i}}(\pi)}{2H}\right) d^\pi+ \frac{\Psi^i(\pi)- V^{{r}^{i}}(\pi)}{2H} A^i(\pi).
\end{align*}

\noindent First, we will show that for all $i\in\mc N$ the point-to-set map $f^i$ is a valid mapping into $2^{\mathcal{C}_d}$ and then that $f^i$ is upper semi-compact. 
\\
\\
\noindent \textbf{$f^i$ is a valid mapping:}  By assumption $\pi\in\mc C_\pi$ and thus by definition $d^\pi\in\mc C_d$. By Lemma \ref{lem:mapping3}, it holds that $A^i(\pi)\subseteq\mc C_d$. Furthermore, it follows that for all $\pi\in\mathcal{C}_{\pi}$:
\begin{align*}
    \Psi^i(\pi)- V^{{r}^{i}}(\pi) = \max_{\alpha\in\Delta(K^i) \text{ is  feasible}} \sum_{k=1}^{K^i} \alpha_k V^{r^i}(\phi^i(k)\circ\pi)-V^{{r}^{i}}(\pi)\ge 0.
\end{align*}
The above term can be upper-bounded by: $\Psi^i(\pi)- V^{{r}^{i}}(\pi)\le \Psi^i(\pi) \le H$. Therefore:
\begin{align*}
    1\ge 1 -  \frac{\Psi^i(\pi)- V^{{r}^{i}}(\pi)}{2H} \ge 1-\frac{H}{2H}=\frac{1}{2}.
\end{align*}


%Since any element $d^i$ of $A(i,\pi)$ lies in the feasible state-action occupancy measure set $\mathcal{C}_d$ for any $i\in[N]$ by Proposition \ref{pro_pre},
By convexity of $\mc C_d$, shown in Lemma \ref{lem:mapping1}, the convex combination of $d^\pi$ and $d^i\in A^i(\pi)$ belongs to $\mathcal{C}_d$. Therefore, $f^i$ is a valid mapping into $2^{\mathcal{C}_d}$.
\\
\\
\noindent \textbf{$f^i$ is upper semi-compact:} By Lemmas \ref{lem:mapping2} and \ref{lem:mapping3}, $\Psi^i(\pi)$ is a continuous real-valued function and $A^i(\pi)$ is upper semi-compact in $\pi\in\mathcal{C}_\pi$. Furthermore, $V^{{r}^{i}}(\pi)$ and $d^\pi$ are continuous functions since both can be represented as polynomial functions of $\pi$. Since for every $\pi\in\mc C_\pi$, $f^i(\pi)$ is a compact set it follows that $f^i$ is upper semi-compact for all $\pi\in\mc C_\pi$.


Next, we will show that the point-to-set map $f:\mathcal{C}_d \to 2^{\mathcal{C}_d}$ 
is a valid mapping into $2^{\mathcal{C}_d}$ and that $f$ is upper semi-compact. 
\\
\\
\noindent \textbf{$f$ is valid mapping and upper semi-compact:} The mapping $f$ is a valid mapping into $2^{\mathcal{C}_d}$ since $\Gamma$ maps $\mathcal{C}_d$ to $2^{\mc C_\pi}$ and $f^i$ maps $\mathcal{C}_\pi$ to $2^{\mathcal{C}_d}$. As $\Gamma(d)$ is upper semi-compact for all $d\in \mathcal{C}_d$ by Lemma \ref{lem:mapping1}, and the composition of two upper semi-compact functions remains upper semi-compact \cite[Theorem 5.10]{anisiu1981point}, it follows that $f^i(\Gamma(d))$ is upper semi-compact for all $d\in \mathcal{C}_d$ and $i\in\mc N$. Furthermore, $f(d)$ is upper semi-compact for all $d\in \mathcal{C}_d$ as it is the union of $N$ upper semi-compact functions \cite[Theorem 5.4]{anisiu1981point}.

In the last step, we will show that for the mapping $f$, a fixed point $d^*\in f(d^*)$ exists and that any corresponding policy $\pi^*\in\Gamma(d^*)$ is a constrained correlated equilibrium.
\\
\\
\noindent \textbf{Existence of a constrained correlated equilibrium:} Since by Lemma \ref{lem:mapping1}, $\mathcal{C}_d$ is a compact and convex set and $f(d)$ is upper semi-compact, Kakutani’s fixed point theorem guarantees the existence of a fixed point $d^*$ of $f$ such that
\begin{align}
d^*\in f(d^*). \label{eq_fix}
\end{align}
%
Consider any policy $\pi\in\Gamma(d^*)$. By Equation \eqref{eq_fix}, for any $i\in\mc N$, we have that:
\begin{align}
    d^\pi\in\left( 1 -  \frac{\Psi^i(\pi)- V^{{r}^{i}}
    (\pi)}{2H}\right) d^\pi+ \frac{\Psi^i(\pi)- V^{{r}^{i}}(\pi)}{2H} A^i(\pi).\label{eq_fix_d}
\end{align}

To prove $\pi$ is a constrained correlated equilibrium, by Theorem \ref{cor:equinotion}, we have to show that for any player $i$ and any feasible $\alpha$, the following holds:
  \begin{align*}
        &V^{r^i}(\pi)\geq\max_{\text{$\alpha\in \Delta(K^i)$ is feasible}} \sum_{k=1}^{K^i} \alpha_k V^{r^i}(\phi^i(k)\circ\pi),
    \end{align*}
This is equivalent to showing that $\Psi^i(\pi)\le V^{{r}^{i}}(\pi)$, since $\Psi^i(\pi)$ is the optimal solution returned by solving \ref{lp}. We prove this by contradiction. Assume that there exists a player $i\in\mc N$ and a feasible $\alpha \in\Delta(K^i)$ such that:
    \begin{align*}
          \sum_{k=1}^{K^i} \alpha_k V^{r^i}(\phi^i(k)\circ\pi)> V^{r^i}(\pi).
    \end{align*}
Combining the above inequality with Equation \eqref{eq_fix_d}, we have $d^\pi\in A^i(\pi)$ and by construction of $A^i(\pi)$ it follows that: $V^{r^i}(\pi) = \Psi^i(\pi)$, which is a contradiction. We conclude that any policy $\pi\in\Gamma(d^*)$ is a constrained correlated equilibrium.\looseness-1
\end{proof}

Considering \emph{common} rather than \emph{playerwise} coupling constraints is crucial in our analysis to establish the existence of a constrained correlated equilibrium under a significantly weakened Slater-type condition. Moreover, we believe that leveraging a similar analysis, our existence result for \emph{common} coupling constraints can easily be extended in two directions: Markov games with (i) infinite-horizon and (ii) countable state space and compact action sets. The first direction requires generalizing Theorem~\ref{cor:equinotion} to the infinite-horizon, and the second direction requires generalizing the arguments related to upper-semi continuity  (Lemmas \ref{lem:mapping1}, \ref{lem:mapping2}, and \ref{lem:mapping3}) to countable state spaces and compact action sets.\looseness-1


