\subsection{Equivalence between \texorpdfstring{$\Phi^i_{NM}$}{Phi(NM)} and \texorpdfstring{$\Phi^i_{M}$}{Phi(M)}}\label{app:equ_NM_M}
The aim of this section is to show that the set of state-action occupancy measures induced by non-Markovian stochastic modifications $\Phi^i_{{NM}}$ is equivalent to the set of state-action occupancy measures induced by Markovian stochastic modifications $\Phi^i_{{M}}$.

To this end, in Section \ref{app:thm:MCE}, we construct an MDP tailored to player~$i$ under policy $\pi$. This enables meaningful comparisons between non-Markovian stochastic modifications and their Markovian stochastic counterparts. Then, in Appendix \ref{sub_supportinglemmas}, we prove that this MDP is well-posed (Lemma \ref{lemma:validdis}) and show two key properties: (i)  in the constructed MDP, there exists a Markovian stochastic modification $\bar\phi^i\in\Phi^i_{M}$, which induces the same marginal state-action occupancy as the non-Markovian stochastic modification $\phi^i\in\Phi^i_{NM}$ (Lemma~\ref{pro:d=d}) and (ii) there is a one-to-one mapping from the state-action occupancy measure of the constructed MDP to the state-action occupancy measure of the original Markov game \ref{eq:constrained_MG} (Lemma \ref{lemma:eq_occ_ori}). Finally, leveraging the above results, in Section \ref{app:equi_in_MG_NM_M} we prove the aim of this section (Lemma \ref{thm:MCE}).


\subsubsection{Construction of the first MDP}\label{app:thm:MCE}
For any player \( i \in \mathcal{N} \) and any policy \( \pi\in\Pi_M \), we construct a finite-horizon MDP defined by the tuple:
\begin{align}\label{eq:MDP1}
\left\{\{\tilde{\mathcal{S}}_t\cup\{b\}\}_{t\in[H]}, \mathcal{A}^i, H, \tilde{P}^\pi, \tilde{\rho}\right\}.\tag{MDP(1)}
\end{align}
The state space at timestep $t$ is given by \(\tilde{\mathcal{S}_t}\cup\{b\}\), where \( \tilde{\mathcal{S}}_t :=(\mathcal{S} \times \mathcal{A})^{t-1} \times (\mathcal{S} \times \mathcal{A}^i) \) and \( b \) is an auxiliary state. Each element of \( \tilde{\mathcal{S}}_t \) takes the form \( \tilde{s}_t = (s_{1:t-1}, a_{1:t-1}, s_t, a_t^i) \), where \( (s_{1:t-1}, a_{1:t-1}) \in (\mathcal{S} \times \mathcal{A})^{t-1} \) and \( (s_t, a_t^i) \in \mathcal{S} \times \mathcal{A}^i \). The time horizon \( H \) is the same as in the original Markov game \ref{eq:constrained_MG}. The action space \( \mathcal{A}^i \) corresponds to player \( i \)'s action set in the original Markov game \ref{eq:constrained_MG}. The transition kernel is denoted by \( \tilde{P}^\pi := \{\tilde{P}_t^\pi\}_{t \in [H-1]} \), where each \( \tilde{P}_t^\pi : \tilde{\mathcal{S}_t} \times \mathcal{A}^i \to [0,1] \) is defined as follows:
\begin{align}\label{eq:Tilde_P}
    &\tilde{P}_t^\pi \left( (s'_{1:t},a'_{1:t},s_{t+1},a_{t+1}^i) \mid (s_{1:t-1},a_{1:t-1},s_t,a_t^i),\hat{a}_t^i \right) \nonumber\\
    &\quad= \frac{1}{|\mathcal{A}^i|} P_t(s_{t+1} \mid s_t, (\hat a_t^i,a_t^{-i})) \pi_t((a_t^i,a_t^{-i}) \mid s_t) 
    \mathds{1}_{a_t' = (\hat a_t^i,a_t^{-i}),(s'_{1:t},a'_{1:t-1}) = (s_{1:t},a_{1:t-1})},\\
    &\tilde{P}_t^\pi \left( b \mid (s_{1:t-1},a_{1:t-1},s_t,a_t^i),\hat{a}_t^i \right) = 1 - \sum_{a_t^{-i}}\pi_t((a_t^i,a_t^{-i}) \mid s_t).\nonumber
\end{align}
We define \( b \) to be an absorbing state, such that the transition kernel satisfies:
\begin{align*}
    \tilde{P}_t^\pi \left( b \mid b \right) = 1.
\end{align*}

\noindent Furthermore, we define the initial distribution for all $\til s_1\in\til{\mc S}_1\cup\{b\}$ as:
\begin{align}\label{eq:modified_init_distr}
    \tilde{\rho}(\ts_1)=\begin{cases}
        \frac{\rho(s_1)}{|\mathcal{A}^i|}, \,&\text{if }\ts_1=(s_1,a_1^i)\in\tilde{\mc S}_1,\\
        0, \,&\text{otherwise}.
    \end{cases}
\end{align}
It is straightforward to verify that $\tilde{\rho} \in \Delta(\tilde{\mathcal{S}}_1\cup\{b\})$. 






\subsubsection{Properties of the first MDP}
\label{sub_supportinglemmas}

In the lemma below, we show that that the transition kernel $\tilde{P}_t^\pi$ of \ref{eq:MDP1} defines a valid probability distribution over the state space $\tilde{\mathcal{S}}_{t+1} \cup \{b\}$ for all $t \in [H-1]$, ensuring that \ref{eq:MDP1} is well-posed. 

\begin{lemma}\label{lemma:validdis}
Suppose $\til P^\pi$ is defined as in Equation \eqref{eq:Tilde_P}. Then, $\til P^\pi_t$ is a valid probability distribution in $\Delta(\tilde{\mathcal{S}}_{t+1}\cup\{b\})$ for all $t\in[H-1]$.  
\end{lemma}
\begin{proof}
 For any given timestep $t\in[H-1]$, state $\tilde{s}_t=\left(s_{1:t-1},a_{1:t-1},s_t,a_t^i\right)\in\tilde{S}_t$, and action $\hat{a}_t^i\in\mathcal{A}_i$, it holds that:
     \begin{align*}
     &\sum_{\ts_{t+1}\in\til{\mc S}_{t+1}\cup\{b\}}\tilde{P}_t^\pi\left(\tilde{s}_{t+1}|\left(s_{1:t-1},a_{1:t-1},s_t,a_t^i\right),\hat{a}_t^i\right)\\
    =&\sum_{s'_{1:t},a'_{1:t}}\sum_{s_{t+1},a_{t+1}^i}\tilde{P}_t^\pi\left(\left(s'_{1:t},a'_{1:t},s_{t+1},a_{t+1}^i\right)|\left(s_{1:t-1},a_{1:t-1},s_t,a_t^i\right),\hat{a}_t^i\right)\\
    &+\tilde{P}_t^\pi\left(b|\left(s_{1:t-1},a_{1:t-1},s_t,a_t^i\right),\hat{a}_t^i\right)\\ =&\sum_{s'_{1:t},a'_{1:t}}\sum_{s_{t+1},a_{t+1}^i}\frac{1}{|\mathcal{A}^i|}P_t(s_{t+1}|s_t,(\hat a_t^i, a_t^{-i}))\pi_t((a_t^i,a_t^{-i})|s_t)\mathds{1}_{a_t' = (\hat a_t^i,a_t^{-i}),(s'_{1:t},a'_{1:t-1}) = (s_{1:t},a_{1:t-1})}\\
    &+1-\sum_{a_t^{-i}}\pi_t((a_t^i,a_t^{-i})|s_t)\\
    =&\sum_{a_{t+1}^i}\frac{1}{|\mathcal{A}^i|}\sum_{a_t^{-i}}\sum_{s_{t+1}}P_t(s_{t+1}|s_t,(\hat a_t^i,a_t^{-i}))\pi_t((a_t^i,a_t^{-i})|s_t)+1-\sum_{a_t^{-i}}\pi_t((a_t^i,a_t^{-i})|s_t)\\
    =&\sum_{a_t^{-i}}\pi_t((a_t^i,a_t^{-i})|s_t)+1-\sum_{a_t^{-i}}\pi_t((a_t^i,a_t^{-i})|s_t)\\
    =&1.
\end{align*}
Furthermore, for the auxiliary state $b$ and timestep $t\in[H-1]$, it holds that:
\begin{align*}
    &\sum_{\til s\in\til{\mc S}_{t+1}\cup\{b\}}\tilde{P}_t^\pi\left(\tilde{s}\mid b\right)=\til P_t^\pi(b \mid b) = 1.
\end{align*}
We conclude that $\tilde{P}_t^\pi$ is a valid probability distribution in $\Delta(\tilde{\mathcal{S}}_{t+1}\cup\{b\})$.
\end{proof}

We note that any non-Markovian stochastic modification $\phi^i\in\Phi^i_{NM}$, where \( \phi^i := \{\phi_t^i\}_{t=1}^H \) with \( \phi_t^i: (\mathcal{S} \times \mathcal{A})^{t-1} \times \mathcal{S} \times \mathcal{A}^i \to \Delta(\mathcal{A}^i) \), constitutes a valid policy in \ref{eq:MDP1}. Specifically, given any \( \tilde{s}_t \in \tilde{\mathcal{S}}_t \) action \(\hat{a}_t^i\) is selected according to \( \hat{a}_t^i \sim \phi_t^i(\cdot \mid \tilde{s}_t) \). Furthermore, for any given non-Markovian modification \( \phi^i \in \Phi_{{NM}}^i \), we construct a corresponding Markovian modification \( \bar\phi^i \in \Phi_{{M}}^i \), where each \( \bar\phi_t^i: \mathcal{S} \times \mathcal{A}^i \to \Delta(\mathcal{A}^i) \) is defined as follows:
\begin{align}
    \bar\phi_t^i(\hat a_{t}^i \mid s_t, a_t^i) = \begin{cases}
       \frac{\sum\limits_{s_{1:t-1}, a_{1:t-1}} \tilde{d}_t^{\phi^i}((s_{1:t-1}, a_{1:t-1}, s_t, a_t^i), \hat a_t^i)}{\sum\limits_{\hat a_t^i} \sum\limits_{s_{1:t-1}, a_{1:t-1}} \tilde{d}_t^{\phi^i}((s_{1:t-1}, a_{1:t-1}, s_t, a_t^i), \hat a_t^i)}, & \text{if the denominator}>0, \\
       \text{any distribution in } \Delta(\mathcal{A}^i), & \text{otherwise}.
    \end{cases} \label{eq:defphi}
\end{align}
We note that $\bar\phi^i$ is also a valid policy in \ref{eq:MDP1}. Namely, for any state \( \tilde{s}_t = (s_{1:t-1}, a_{1:t-1}, s_t, a_t^i) \) in \(\tilde{\mathcal{S}}_t \), we can define the policy as:
\begin{align*}
    \bar{\phi}^i_t(\hat{a}_t^i \mid \tilde{s}_t) := \bar{\phi}^i_t(\hat{a}_t^i \mid s_t, a_t^i).
\end{align*}

In the next lemma, we show that the original modification $\phi^i\in\Phi^i_{NM}$ and the corresponding Markovian modification $\bar\phi^i\in\Phi^i_{M}$ constructed in \eqref{eq:defphi} induce the same marginal state-action occupancy measure over \( (s_t, a_t^i) \) and $\hat{a}_t^i$ for every timestep \( t \) in \ref{eq:MDP1}.

\begin{lemma}\label{pro:d=d}
For all \( h \in [H] \), \( (s_h, a_h^i) \in \mathcal{S} \times \mathcal{A}^i \), and \( \ha_h^i \in \mathcal{A}_i \), the following equality holds:
\begin{align}
    \sum_{s_{1:h-1},a_{1:h-1}} \!\!\!\tilde{d}_h^{\phi^i}((s_{1:h-1},a_{1:h-1},s_h,a_h^i),\hat{a}_h^i) 
    = \!\!\!\sum_{s_{1:h-1},a_{1:h-1}} \!\!\!\tilde{d}_h^{\bar{\phi}^i}((s_{1:h-1},a_{1:h-1},s_h,a_h^i),\hat{a}_h^i),
    \label{eq_ind} 
\end{align}
where \( \tilde{d}_h^{\phi^i} \) and \( \tilde{d}_h^{\bar\phi^i} \)  denote the state-action occupancy measures at timestep \( h \) of \ref{eq:MDP1}, induced by the modifications \( \phi^i \) and \( \bar\phi^i \), respectively.
\end{lemma}
\begin{proof}
We prove the above lemma by induction.

\noindent \textbf{Base case:} 
For $h=1$ note that: 
\begin{align}\label{eq:intermediate_helper}
\sum_{\hat{a}_1^i} \tilde{d}_1^{\phi^i}((s_1, a_1^i), \hat{a}_1^i) = \sum_{\hat{a}_1^i} \tilde{\rho}(s_1, a_1^i) \phi_1^i(\hat{a}_1^i | s_1, a_1^i) = \tilde{\rho}(s_1, a_1^i).
\end{align}

\noindent Then, if \(\tilde{\rho}(s_1, a_1^i) \neq 0\), we can express \( \tilde{d}_1^{\bar{\phi}^i}((s_1, a_1^i), \hat{a}_1^i) \) as follows:
\begin{align*}
    \tilde{d}_1^{\bar{\phi}^i}((s_1, a_1^i), \hat{a}_1^i) &= \tilde{\rho}(s_1, a_1^i) \bar{\phi}_1^i(\hat{a}^i | s_1, a_1^i) \\
    &= \tilde{\rho}(s_1, a_1^i) \frac{\tilde{d}_1^{\phi^i}((s_1, a_1^i), \hat{a}_1^i)}{\sum_{\hat{a}_1^i} \tilde{d}_1^{\phi^i}((s_1, a_1^i), \hat{a}_1^i)} \\
    &\overset{\eqref{eq:intermediate_helper}}{=} \tilde{d}_1^{\phi^i}((s_1, a_1^i), \hat{a}_1^i).
\end{align*}
If \(\tilde{\rho}(s_1, a_1^i) = 0\), then we obtain 
\[
\tilde{d}_1^{\bar{\phi}^i}((s_1, a_1^i), \hat{a}_1^i) = \tilde{d}_1^{\phi^i}((s_1, a_1^i), \hat{a}_1^i) = 0.
\]

\noindent \textbf{Induction step:}
Assume that Equation \eqref{eq_ind} holds for all \( (s_h, a_h^i) \in \mathcal{S}_h \times \mathcal{A}^i \), all \( \ha_h^i \in \mathcal{A}_i \), and all \( h \in [t-1] \). We now show that it also holds for \(t \). For $\tilde{d}_t^{\phi^i}$, we have
\begin{align}
    &\sum_{\ha_t^i}\sum_{s_{1:t-1},a_{1:t-1}}\tilde{d}_t^{\phi^i}((s_{1:t-1},a_{1:t-1},s_t,a_t^i),\ha_t^i)\nonumber\\
    =&\sum_{\ha_t^i}\sum_{s'_{1:t-1},a'_{1:t-1}}\sum_{s_{1:t-2},a_{1:t-2}}\sum_{s_{t-1},a_{t-1}^i}\sum_{\ha_{t-1}^i} \tilde{d}_{t-1}^{\phi^i}((s_{1:t-2},a_{1:t-2},s_{t-1},a_{t-1}^i),\ha_{t-1}^i)\nonumber\\
    &\times\tilde{P}_{t-1}^\pi((s'_{1:t-1},a'_{1:t-1},s_t,a_t^i)|(s_{1:t-2},a_{1:t-2},s_{t-1},a_{t-1}^i),\ha_{t-1}^i) \phi^i_t(\ha_t^i|(s'_{1:t-1},a'_{1:t-1},s_t,a_t^i))\nonumber\\
    \overset{(i)}{=}&\sum_{s'_{1:t-1},a'_{1:t-1}}\sum_{s_{1:t-2},a_{1:t-2}}\sum_{s_{t-1},a_{t-1}^i}\sum_{\ha_{t-1}^i} \tilde{d}_{t-1}^{\phi^i}((s_{1:t-2},a_{1:t-2},s_{t-1},a_{t-1}^i),\ha_{t-1}^i)\nonumber\\
    &\times\tilde{P}_{t-1}^\pi((s'_{1:t-1},a'_{1:t-1},s_t,a_t^i)|(s_{1:t-2},a_{1:t-2},s_{t-1},a_{t-1}^i),\ha_{t-1}^i)\nonumber\\
    \overset{(ii)}{=}&\frac{1}{|\mathcal{A}^i|}\sum_{s_{t-1}}\sum_{(\ha_{t-1}^i,a_{t-1}^{-i})}\sum_{a_{t-1}^{i}}P_{t-1}(s_t|s_{t-1},(\ha_{t-1}^i,a_{t-1}^{-i}))\pi_{t-1}((a_{t-1}^i,a_{t-1}^{-i}) | s_{t-1}) \nonumber \\
   & \times \sum_{s_{1:t-2},a_{1:t-2}} \tilde{d}_{t-1}^{\phi^i}((s_{1:t-2},a_{1:t-2},s_{t-1},a_{t-1}^i),\ha_{t-1}^i).\label{eq:sumd}
\end{align}
In step \((i)\), we apply that \(\sum_{\ha_t^i} \phi^i_t(\ha_t^i | (s'_{1:t-1}, a'_{1:t-1}, s_t, a_t^i)) = 1\) and in step \((ii)\), we use the definition of \(\tilde{P}^\pi_{t-1}\). For $\tilde{d}_t^{\bar\phi^i}$, we write
\begin{align}
    &\sum_{s_{1:t-1},a_{1:t-1}}\tilde{d}_t^{\bar\phi^i}((s_{1:t-1},a_{1:t-1},s_t,a_t^i),\ha_t^i)\nonumber\\
    =&\bar{\phi}_t^i(\ha_t^i|s_t,a_t^i)\sum_{s'_{1:t-1},a'_{1:t-1}}\sum_{s_{1:t-2},a_{1:t-2}}\sum_{s_{t-1},a_{t-1}^i}\sum_{\ha_{t-1}^i} \tilde{d}_{t-1}^{\bar\phi^i}((s_{1:t-2},a_{1:t-2},s_{t-1},a_{t-1}^i),\ha_{t-1}^i) \nonumber\\
    &\times\tilde{P}_{t-1}^\pi((s'_{1:t-1},a'_{1:t-1},s_t,a_t^i)|(s_{1:t-2},a_{1:t-2},s_{t-1},a_{t-1}^i),\ha_{t-1}^i)\nonumber\\
    \overset{(i)}{=}&\frac{\bar{\phi}_t^i(\ha_t^i|s_t,a_t^i)}{|\mathcal{A}^i|}\sum_{s_{t-1}}\sum_{(\ha_{t-1}^i,a_{t-1}^{-i})}\sum_{a_{t-1}^{i}}P_{t-1}(s_t|s_{t-1},(\ha_{t-1}^i,a_{t-1}^{-i}))\pi_{t-1}((a_{t-1}^i,a_{t-1}^{-i}) | s_{t-1}) \nonumber \\
    & \times \sum_{s_{1:t-2},a_{1:t-2}} \tilde{d}_{t-1}^{\bar\phi^i}((s_{1:t-2},a_{1:t-2},s_{t-1},a_{t-1}^i),\ha_{t-1}^i)\nonumber\\
    \overset{(ii)}{=}&\frac{\bar{\phi}_t^i(\ha_t^i|s_t,a_t^i)}{|\mathcal{A}^i|}\sum_{s_{t-1}}\sum_{(a_{t-1}^{-i},\ha_{t-1}^i)}\sum_{a_{t-1}^{i}}P_{t-1}(s_t|s_{t-1},(\ha_{t-1}^i,a_{t-1}^{-i}))\pi_{t-1}((a_{t-1}^i,a_{t-1}^{-i}) | s_{t-1}) \nonumber \\
    & \times \sum_{s_{1:t-2},a_{1:t-2}} \tilde{d}_{t-1}^{\phi^i}((s_{1:t-2},a_{1:t-2},s_{t-1},a_{t-1}^i),\ha_{t-1}^i)\nonumber\\
    \overset{(iii)}{=}&{\bar{\phi}_t^i(\ha_t^i|s_t,a_t^i)}\left(\sum_{\ha_t^i}\sum_{s_{1:t-1},a_{1:t-1}}\tilde{d}_t^{\phi^i}((s_{1:t-1},a_{1:t-1},s_t,a_t^i),\ha_t^i)\right).\label{eq:step1}
\end{align}
\noindent In step \((i)\), we use the definition of \(\tilde{P}^\pi_{t-1}\) and in step \((ii)\), we apply the following equation, which holds by induction:
\begin{align*}
    \sum_{s_{1:t-2},a_{1:t-2}} \!\!\!\!\tilde{d}_{t-1}^{\bar\phi^i}((s_{1:t-2},a_{1:t-2},s_{t-1},a_{t-1}^i),\ha_{t-1}^i) =\!\!\!\! \sum_{s_{1:t-2},a_{1:t-2}}\!\! \!\!\tilde{d}_{t-1}^{\phi^i}((s_{1:t-2},a_{1:t-2},s_{t-1},a_{t-1}^i),\ha_{t-1}^i).
\end{align*}
In step \((iii)\), we plug in Equation \eqref{eq:sumd}. If Equation \eqref{eq:sumd} is non-zero, we can substitute the definition of \(\bar \phi^i\) from Equation \eqref{eq:defphi} into Equation \eqref{eq:step1}. This results in:
\begin{align*}
    \sum_{s_{1:t-1},a_{1:t-1}} \tilde{d}_t^{\bar\phi^i} \left( (s_{1:t-1},a_{1:t-1},s_t,a_t^i), \ha_t^i \right) = \sum_{s_{1:t-1},a_{1:t-1}} \tilde{d}_t^{\phi^i} \left( (s_{1:t-1},a_{1:t-1},s_t,a_t^i), \ha_t^i \right).
\end{align*}
Otherwise, if Equation \eqref{eq:sumd} is zero, by Equation \eqref{eq:step1} we have the following:
\begin{align*}
    \sum_{s_{1:t-1},a_{1:t-1}} \tilde{d}_t^{\bar\phi^i} \left( (s_{1:t-1},a_{1:t-1},s_t,a_t^i), \ha_t^i \right) = 0.
\end{align*}
Meanwhile, if Equation \eqref{eq:sumd} is zero, we obtain 
\begin{align*}
    \sum_{s_{1:t-1},a_{1:t-1}} \tilde{d}_t^{\phi^i} \left( (s_{1:t-1},a_{1:t-1},s_t,a_t^i), \ha_t^i \right)=0,
\end{align*}
which holds as each state-action distribution is non-negative. Therefore, we conclude that:
\begin{align*}
    \sum_{s_{1:t-1},a_{1:t-1}} \tilde{d}_t^{\bar\phi^i} \left( (s_{1:t-1},a_{1:t-1},s_t,a_t^i), \ha_t^i \right) = \sum_{s_{1:t-1},a_{1:t-1}} \tilde{d}_t^{\phi^i} \left( (s_{1:t-1},a_{1:t-1},s_t,a_t^i), \ha_t^i \right).
\end{align*}
\end{proof}

In the lemma below, we demonstrate a one-to-one mapping between the state-action occupancy measure of policy $\phi^i$ in \ref{eq:MDP1} and that of the modified policy $\phi^i\circ\pi$ in the Markov game \ref{eq:constrained_MG}.

\begin{lemma}\label{lemma:eq_occ_ori}
    For any player $i\in\mc N$, Markovian policy $\pi\in\Pi_M$, and non-Markovian stochastic modification \( \phi^i \in\Phi_{NM}^i \), the state-action occupancy measure of the modified policy $\phi^i\circ\pi$ equals:\looseness-1
\begin{align}
    \!\!\!\!\!\!d_h^{\phi^i\circ \pi}({s}_h, (\hat{a}_h^i, a_h^{-i})) = |\mathcal{A}^i|^h\sum_{a_h^i}\sum_{s_{1:h-1},a_{1:h-1}}\!\!\!\!\!\!\!\tilde{d}_h^{\phi^i}((s_{1:h-1},a_{1:h-1},s_h,a_h^i),\hat a_h^i) \pi_h((a_h^i,a_h^{-i})|s_h), \label{eq_occ_ori}
\end{align}
for all $(s_h, (\ha_h^i,a_h^{-i})) \in \mathcal{S} \times \mathcal{A}$ and $h\in[H]$, where ${d}_h^{\phi^i\circ\pi}$ denotes the state-action occupancy measure at timestep $h$ of Markov game \ref{eq:constrained_MG} and $\tilde{d}_h^{\phi^i}$ denotes the state-action occupancy measure at timestep $h$ of \ref{eq:MDP1}.

\begin{remark}
    The lemma above also holds for any Markovian stochastic modification $\bar\phi^i\in\Phi_{M}^i$ since $\Phi_{M}^i$ is a subset of $\Phi_{NM}^i$ and $\bar\phi^i$ constitutes a valid policy in \ref{eq:MDP1}.
\end{remark}


%If $\bar\phi^i:\mc S\times \mc A^i\rightarrow\Delta(\mc A^i)$ is a stationary Markovian stochastic modification then Equation \eqref{eq_occ_ori} holds with $d_t^{\phi^i\circ\pi}$ replaced by $d^{\bar\phi^i\circ\pi}$.
\end{lemma}
\begin{proof} 
We prove the above lemma by induction.

\noindent \textbf{Base case:} For $h=1$, we have that for any $(s_1,(\hat{a}_1^i,a_1^{-i}))\in \mc S\times\mc A$ the following holds:
\begin{align*}
    &|\mathcal{A}^i| \sum_{a_1^{i}} \tilde{d}_1^{\phi^i}((s_1,a_1^i),\hat a^i)\pi_1((a_1^i,a_1^{-i}) \mid s_1)\\
    \overset{(i)}{=}& |\mathcal{A}^i| \sum_{a_1^{i}}\tilde{\rho}(s_1,a_1^i) \phi^i_1(\ha^i_1|s_1,a_1^i)\pi_1((a_1^i,a_1^{-i}) \mid s_1)\\
    \overset{(ii)}{=}&\sum_{a_1^{i}} \rho(s_1)\phi_1^i(\ha^i_1|s_1,a_1^i )\pi_1((a_1^i,a_1^{-i}) \mid s_1)\\
    =& d_1^{\phi^i\circ \pi}({s}_1, (a_1^{-i},\hat a_1^i)),
\end{align*}
where in step $(i)$ we express \( \tilde{d}_1^{\phi^i} \) by the dynamics of \ref{eq:MDP1}. In step \((ii)\) we plug in the definition of \(\tilde{\rho}\) given in Equation \eqref{eq:modified_init_distr}. % and use that by construction of the loop-free finite-horizon MDP defined in Equation \eqref{eq:loop-free_MDP} it holds that $\phi^i(\hat{a}_1^i \mid \til s_1)=\phi_1^i(\hat{a}_1^i \mid \til s_1)$.
\\
\\
\noindent \textbf{Induction step:} Assume that Equation \eqref{eq_occ_ori} holds for all \( (s_h, (a_h^{-i},\ha_h^i)) \in \mathcal{S} \times \mathcal{A} \) and all \( h \in [t-1] \), then we show that Equation \eqref{eq_occ_ori} also holds for $t$. We can rewrite \(\tilde{d}_t^{\phi^i}\) as:
\begin{align*}
    &\tilde{d}_t^{\phi^i}((s_{1:t-1},a_{1:t-1},s_t,a_t^i),\hat a_t^i)\\
    \overset{(i)}{=}&\sum_{\bar s_{1:t-2},\bar a_{1:t-2}}\sum_{ \bar s_{t-1}}\sum_{\bar a_{t-1}^i}\sum_{\hat a_{t-1}^i}\tilde{d}_{t-1}^{\phi^i}((\bar s_{1:t-2},\bar a_{1:t-2},\bar s_{t-1},\bar a_{t-1}^i),\hat a_{t-1}^i)\\
    &\times\tilde{P}_{t-1}^\pi(s_{1:t-1},a_{1:t-1},s_t,a_t^i|(\bar s_{1:t-2},\bar a_{1:t-2},\bar s_{t-1},\bar a_{t-1}^i),\hat{a}_{t-1}^i)\phi^i_t(\ha_t^i|s_{1:t-1},a_{1:t-1},s_t,a_t^i)\\
    \overset{(ii)}{=}&|\mathcal{A}^i|^{-1}\sum_{\bar s_{1:t-2},\bar a_{1:t-2}}\sum_{ \bar s_{t-1}}\sum_{\bar a_{t-1}^i}\sum_{\hat a_{t-1}^i}\tilde{d}_{t-1}^{\phi^i}((\bar s_{1:t-2},\bar a_{1:t-2},\bar s_{t-1},\bar a_{t-1}^i),\hat a_{t-1}^i)\pi_{t-1}((\bar a_{t-1}^i,\bar a_{t-1}^{-i}) \mid \bar s_{t-1})\\
    &\times P_{t-1}(s_t|\bar s_{t-1},(\ha_{t-1}^i,\bar a_{t-1}^{-i}))\mathds{1}_{a_{t-1} = (\hat a_{t-1}^i,\bar a_{t-1}^{-i}),(s_{1:t-1},a_{1:t-2}) = (\bar s_{1:t-1},\bar a_{1:t-2})}\phi^i_t(\ha_t^i|s_{1:t-1},a_{1:t-1},s_t,a_t^i)\\
    \overset{(iii)}{=}&|\mathcal{A}^i|^{-1}\sum_{\bar a_{t-1}^i}\tilde{d}_{t-1}^{\phi^i}(( s_{1:t-2}, a_{1:t-2}, s_{t-1},\bar a_{t-1}^i), a_{t-1}^i)\pi_{t-1}(( \bar a_{t-1}^i,a_{t-1}^{-i}) \mid  s_{t-1})P_{t-1}(s_t| s_{t-1},a_{t-1})\\
    &\times\phi^i_t(\ha_t^i|s_{1:t-1},a_{1:t-1},s_t,a_t^i).
\end{align*}
In step \((i)\), we express the state-action distribution using the transition dynamics, in step \((ii)\), we apply the definition of \(\tilde{P}^\pi_{t-1}\), and in step \((iii)\), we sum only over the indicator function with non-zero value. Using the above equation, we obtain:
\begin{align*}
    &|\mathcal{A}^i|^t\sum_{a_t^i}\sum_{s_{1:t-1},a_{1:t-1}}\tilde{d}_t^{\phi^i}((s_{1:t-1},a_{1:t-1},s_t,a_t^i),\hat a_t^i) \pi_t((a_t^i,a_t^{-i})|s_t)\\
    =&|\mathcal{A}^i|^{t-1}\sum_{a_t^i}\sum_{s_{1:t-1},a_{1:t-1}}\sum_{\bar a_{t-1}^i}\tilde{d}_{t-1}^{\phi^i}(( s_{1:t-2}, a_{1:t-2}, s_{t-1},\bar a_{t-1}^i), a_{t-1}^i) \pi_{t-1}(( \bar a_{t-1}^i,a_{t-1}^{-i}) \mid  s_{t-1})\\
    &\times  P_{t-1}(s_t| s_{t-1},a_{t-1}) \phi^i_t(\ha_t^i|s_{1:t-1},a_{1:t-1},s_t,a_t^i)\pi_t((a_t^i,a_t^{-i})|s_t)\\
    \overset{(i)}{=}& \sum_{a_t^i}\sum_{s_{1:t-1},a_{1:t-1}}d_{t-1}^{\phi^i\circ \pi}(s_{1:t-1},a_{1:t-1})P_{t-1}(s_t| s_{t-1},a_{t-1})\phi^i_t(\ha_t^i|s_{1:t-1},a_{1:t-1},s_t,a_t^i)\pi_t((a_t^i,a_t^{-i})|s_t)\\
    =& \sum_{s_{1:t-1},a_{1:t-1}}d_{t-1}^{\phi^i\circ \pi}(s_{1:t-1},a_{1:t-1})P_{t-1}(s_t| s_{t-1},a_{t-1})\sum_{a_t^i} \phi^i_t(\ha_t^i|s_{1:t-1},a_{1:t-1},s_t,a_t^i)\pi_t((a_t^i,a_t^{-i})|s_t)\\    
    =&\sum_{s_{1:t-1},a_{1:t-1}} d_t^{\phi^i\circ \pi}(s_{1:t-1},a_{1:t-1},{s}_t, (\hat{a}_t^i,a_t^{-i}))\\
    =&d_t^{\phi^i\circ \pi}({s}_t, (\hat{a}_t^i,a_t^{-i})),
\end{align*}
where in step \((i)\), we apply Equation \eqref{eq_occ_ori} which holds by induction:
\begin{align*}
   & |\mathcal{A}^i|^{t-1}\sum_{\bar a_{t-1}^i}\sum_{s_{1:t-2},a_{1:t-2}}\tilde{d}_{t-1}^{\phi^i}((s_{1:t-2},a_{1:t-2},s_{t-1},\bar a_{t-1}^i), a_{t-1}^i) \pi_{t-1}((\bar a_{t-1}^i,a_{t-1}^{-i})|s_{t-1}) \\
    =&  d_{t-1}^{\phi^i\circ \pi}({s}_{t-1}, ({a}_{t-1}^i,a_{t-1}^{-i}))\\
    =&\sum_{s_{1:t-2},a_{1:t-2}}  d_{t-1}^{\phi^i\circ \pi}(s_{1:t-1},a_{1:t-1}).
\end{align*}
\end{proof}


\subsubsection{State-action occupancy measure of \texorpdfstring{$\Phi^i_{NM}$}{Phi(NM)} and \texorpdfstring{$\Phi^i_M$}{Phi(M)}}\label{app:equi_in_MG_NM_M}

In this section, we utilize the results established in Appendix~\ref{sub_supportinglemmas} to prove that the set of modifications $\Phi^i_{\mathrm{NM}}$ and $\Phi^i_{\mathrm{M}}$ induce the same state-action occupancy measure over the Markov game \ref{eq:constrained_MG}.

% In Lemma~\ref{pro:d=d}, we show that the original modification $\phi^i\in\Phi^i_{NM}$ and a Markovian modification $\bar\phi^i\in\Phi^i_{M}$ we construct below induce the same marginal state-action occupancy measure over \( (s_t, a_t) \) for every timestep \( t \) in \ref{eq:MDP1}. Combining this result with Lemma~\ref{lemma:eq_occ_ori}, which establishes a one-to-one correspondence between the state-action occupancy measures of \ref{eq:MDP1} and those of the original constrained Markov game \ref{eq:constrained_MG}, we conclude in Lemma~\ref{thm:MCE} that \( \phi^i \circ \pi \) and \( \bar\phi^i \circ \pi \) yield the same state-action occupancy measures over \( (s_t, a_t) \) for every \( t \) in the original constrained Markov game \ref{eq:constrained_MG}.
\begin{lemma}
\label{thm:MCE}
Given player $i\in\mc N$ and policy $\pi\in\Pi_M$, for any non-Markovian modification $\phi^i\in\Phi_{NM}^i$, there exists a corresponding  Markovian modification $\bar\phi^i\in\Phi_{M}^i$ such that: 
\begin{align*}
    d_t^{\phi^i \circ \pi}(s_t,a_t) = d_t^{\bar{\phi}^i \circ \pi}(s_t,a_t), \quad\forall(s_t,a_t)\in\mS\times\mA, \forall t\in[H].
\end{align*}
\end{lemma}

\begin{proof}\label{proof:MCE} Given player $i$ and policy $\pi$, any non-Markovian stochastic modification $\phi^i\in\Phi_{NM}^i$ in the original Markov game \ref{eq:constrained_MG} constitutes a valid policy in \ref{eq:MDP1}, since each \( \phi_t^i \) maps from \( \tilde{\mathcal{S}}_t \) to \( \Delta(\mathcal{A}^i) \).

In Lemma \ref{lemma:eq_occ_ori}, we established the following equality between the distribution over the state-action space in the original Markov game \ref{eq:constrained_MG} and \ref{eq:MDP1}: for all $(s_t, (\ha_t^i,a_t^{-i})) \in \mathcal{S} \times \mathcal{A}$ and all $t\in[H]$ it holds that:
\begin{align}
    d_t^{\phi^i\circ \pi}({s}_t, (\hat{a}_t^i, a_t^{-i})) = |\mathcal{A}^i|^t\sum_{a_t^i}\sum_{s_{1:t-1},a_{1:t-1}}\!\!\!\!\!\tilde{d}_t^{\phi^i}((s_{1:t-1},a_{1:t-1},s_t,a_t^i),\hat a_t^i) \pi_t((a_t^i,a_t^{-i})|s_t). \label{eq_equaldis1}
\end{align}
Recall Equation \eqref{eq:defphi}, where, for any given modification $\phi^i$, we constructed $\bar\phi^i$ which corresponds to a Markovian stochastic modification in the original Markov game \ref{eq:constrained_MG}. Then, similarly by Lemma \ref{lemma:eq_occ_ori}, for all $(s_t, (\ha_t^i,a_t^{-i})) \in \mathcal{S} \times \mathcal{A}$ and all $t\in[H]$ it holds that:
\begin{align}
    d_t^{\bar\phi^i\circ \pi}({s}_t, (\hat{a}_t^i, a_t^{-i})) = |\mathcal{A}^i|^t\sum_{a_t^i}\sum_{s_{1:t-1},a_{1:t-1}}\!\!\!\!\!\tilde{d}_t^{\bar\phi^i}((s_{1:t-1},a_{1:t-1},s_t,a_t^i),\hat a_t^i) \pi_t((a_t^i,a_t^{-i})|s_t). \label{eq_equaldis2}
\end{align}
Furthermore, by Lemma \ref{pro:d=d}, the following equality holds for all \( t \in [H] \), \( (s_t, a_t^i) \in \mathcal{S} \times \mathcal{A}^i \), and \( \ha_t^i \in \mathcal{A}_i \):
\begin{align}
    \sum_{s_{1:t-1},a_{1:t-1}} \tilde{d}_t^{\phi^i}((s_{1:t-1},a_{1:t-1},s_t,a_t^i),\hat{a}_t^i) 
    = \sum_{s_{1:t-1},a_{1:t-1}} \tilde{d}_t^{\bar{\phi}^i}((s_{1:t-1},a_{1:t-1},s_h,a_t^i),\hat{a}_t^i).
    \label{eq_equaldis}
\end{align}
Combining Equations \eqref{eq_equaldis1}, \eqref{eq_equaldis2}, and \eqref{eq_equaldis}, it holds that:

\begin{align*}
 d_t^{\bar\phi^i\circ \pi}({s}_t, (\hat{a}_t^i,a_t^{-i}))=&|\mathcal{A}^i|^t\sum_{a_t^i}\sum_{s_{1:t-1},a_{1:t-1}}\tilde{d}_t^{\bar \phi^i}((s_{1:t-1},a_{1:t-1},s_t,a_t^i),\hat a_t^i) \pi_t((a_t^i,a_t^{-i})|s_t)\\  
    =&|\mathcal{A}^i|^t\sum_{a_t^i}\sum_{s_{1:t-1},a_{1:t-1}}\tilde{d}_t^{ \phi^i}((s_{1:t-1},a_{1:t-1},s_t,a_t^i),\hat a_t^i) \pi_t((a_t^i,a_t^{-i})|s_t)\\  
    =&d_t^{\phi^i\circ \pi}({s}_t, (\hat{a}_t^i,a_t^{-i})).
\end{align*}
\end{proof}
\subsection{Equivalence between \texorpdfstring{$\Phi^i_{M}$}{Phi(M)} and convex combination of  \texorpdfstring{$\Phi^i_{M,{det}}$}{Phi(M,det)}}\label{app:equ_M_MD} 

The aim of this section is to show that the set of state-action occupancy measures induced by Markovian stochastic modifications $\Phi^i_{\mathrm{M}}$ is equivalent to the convex hull of state-action occupancy measures induced by Markovian deterministic modifications $\Phi^i_{\mathrm{M,det}}$.

The proof parallels the arguments in Appendix~\ref{app:equ_NM_M}. In Appendix \ref{app:constuctsecondMDP}, we begin by constructing an MDP tailored to player~$i$ under policy $\pi$, enabling direct comparisons between Markovian stochastic and Markovian deterministic modifications. We show that this MDP is well-defined (Lemma~\ref{lemma:MDP2_validdis}) and admits a one-to-one correspondence between its state-action occupancy measure and that of the original Markov game (Lemma~\ref{lemma:MDP2_eq_occ_ori}). Finally, in Section~\ref{app:equi_in_MG_M_M,det} we prove the aim of this section by leveraging the classical result of MDPs, namely that stochastic Markov policies are equivalent to convex combinations of deterministic ones in terms of occupancy measures (Lemma~\ref{prop:deterministic_modification}).



\subsubsection{Construction and properties of the second MDP}\label{app:constuctsecondMDP}
Similarly to \ref{eq:MDP1}, for any player \( i \in \mathcal{N} \) and any policy \( \pi\in\Pi_M \), we construct a finite-horizon MDP defined by the tuple:
\begin{align}\label{eq:MDP2}
\left\{\bar{\mc S}\cup\{b\}, \mathcal{A}^i, H, \bar{P}^\pi, \bar{\rho}\right\}.\tag{MDP(2)}
\end{align}
%
The state space is given by $\bar{\mc S}\cup\{b\}$, where $\bar{\mc S}:= \mathcal{S} \times \mathcal{A}^i$ and \( b \) is an auxiliary state. Each element of $\bar{\mc S}$ takes the form \( \bar s=(s,a^i) \). The time horizon \( H \) is the same as in the original Markov game \ref{eq:constrained_MG}. The action space \( \mathcal{A}^i \) corresponds to player \( i \)'s action set in the original Markov game \ref{eq:constrained_MG}. The transition kernel is denoted by \( \bar{P}^\pi := \{\bar{P}_t^\pi\}_{t \in [H-1]} \), where each \( \bar{P}_t^\pi : \bar{\mathcal{S}} \times \mathcal{A}^i \to [0,1] \) is defined as follows:
\begin{align}\label{eq:MDP2_Tilde_P}
    &\bar{P}_t^\pi \left( (s_{t+1},a_{t+1}^i) \mid (s_t,a_t^i),\hat{a}_t^i \right) 
    = \frac{1}{|\mathcal{A}^i|} \sum_{a_t^{-i}}P_t(s_{t+1} \mid s_t, (\hat a_t^i,a_t^{-i})) \pi_t((a_t^i,a_t^{-i}) \mid s_t),\\
    &\bar{P}_t^\pi \left( b \mid (s_t,a_t^i),\hat{a}_t^i \right) = 1 - \sum_{a_t^{-i}}\pi_t((a_t^i,a_t^{-i}) \mid s_t).\nonumber
\end{align}
We define \( b \) to be an absorbing state, such that the transition kernel satisfies:
\begin{align*}
    \bar{P}_t^\pi \left( b \mid b \right) = 1.
\end{align*}

\noindent Furthermore, we define the initial distribution for all $\bar s_1\in\bar{\mc S}\cup\{b\}$ as:
\begin{align*}
    \bar{\rho}(\bar s_1)=\begin{cases}
        \frac{\rho(s_1)}{|\mathcal{A}^i|}, \,&\text{if }\bar s_1=(s_1,a_1^i)\in\bar{\mc S}_1,\\
        0, \,&\text{otherwise}.
    \end{cases}
\end{align*}
It is straightforward to verify that $\bar{\rho} \in \Delta(\bar{\mathcal{S}}\cup\{b\})$. Lemma~\ref{lemma:MDP2_validdis} ensures that \ref{eq:MDP2} is well-posed. 

\begin{lemma}\label{lemma:MDP2_validdis}
Suppose $\bar P^\pi$ is defined as in Equation \eqref{eq:MDP2_Tilde_P}. Then, $\bar P^\pi_t$ is a valid probability distribution in $\Delta(\bar{\mathcal{S}}\cup \{b\})$ for all $t\in[H-1]$.  
\end{lemma}
%
The proof follows from the same arguments as in the proof of Lemma \ref{lemma:validdis}. 

We note that any Markovian stochastic modification $\bar\phi^i\in\Phi^i_{M}$, i.e., \(\bar \phi^i := \{\bar\phi_t^i\}_{t=1}^H \) with \( \bar\phi_t^i: \mathcal{S} \times \mathcal{A}^i \to \Delta(\mathcal{A}^i) \), constitutes a valid policy in \ref{eq:MDP2}. In the following lemma, we demonstrate a one-to-one mapping between the state-action occupancy measure of the modified policy $\bar\phi^i\circ\pi$ in the original Markov game \ref{eq:constrained_MG} and that of the \ref{eq:MDP2}.


\begin{lemma}\label{lemma:MDP2_eq_occ_ori}
    For any player $i\in\mc N$, Markovian policy $\pi\in\Pi_M$, and Markovian stochastic modification \( \bar\phi^i \in\Phi_{M}^i \), the state-action occupancy measure of the modified policy $\bar\phi^i\circ\pi$ equals:\looseness-1
\begin{align*}
    \!\!\!\!\!\!d_h^{\bar\phi^i\circ \pi}({s}_h, (\hat{a}_h^i, a_h^{-i})) = |\mathcal{A}^i|^h\sum_{a_h^i}\bar d_h^{\bar\phi^i}((s_h,a_h^i),\hat a_h^i) \pi_h((a_h^i,a_h^{-i})|s_h), 
\end{align*}
for all $(s_h, (\ha_h^i,a_h^{-i})) \in \mathcal{S} \times \mathcal{A}$ and $h\in[H]$, where $\bar d_h^{\bar\phi^i}(\til s, a^i)$ denotes the state-action occupancy measure at timestep $h$ of \ref{eq:MDP2}.
\end{lemma}

The proof follows from the same arguments as in the proof of Lemma \ref{lemma:eq_occ_ori}. 

\subsubsection{State-action occupancy measure of \texorpdfstring{$\Phi^i_{M}$}{phi(M)} and \texorpdfstring{$\Phi^i_{M,det}$}{phi(M,det)}}\label{app:equi_in_MG_M_M,det}


Here, we utilize the results of the previous section to establish a connection between any Markovian stochastic modification $\bar\phi^i\in\Phi_{M}^i$ and the set of deterministic modifications $\Phi_{M,det}^i$ at the level of state-action occupancy of the Markov game \ref{eq:constrained_MG}.

\begin{lemma}\label{prop:deterministic_modification}
 Given player $i$ and policy $\pi\in\Pi_M$, for any Markovian modification $\bar\phi^i\in\Phi^i_{M}$, there exists a vector $\alpha\in\Delta(K^i)$ such that:
    \begin{align*}
        d_t^{\bar\phi^i\circ \pi}(s_t,a_t)=\sum_{k=1}^{K^i}\alpha_k  d_t^{\bar\phi^i(k)\circ\pi}(s_t,a_t),\,\forall(s_t,a_t)\in\mc S\times\mc A,\forall t\in[H],
    \end{align*}
    where $\bar\phi^i(k)\in\Phi_{M,det}^i$, $k\in[K^i]$. The converse of this statement also holds.%$\Phi_{det}^i=\{\phi^i_k\}_{k=1}^{|\Phi_{det}^i|}$.
\end{lemma}


\begin{proof}\label{proof:connection_deterministic_stochastic}
Given player \( i \) and policy \( \pi \in \Pi_M \), consider any modification \( \bar\phi^i\in\Phi_{M}^i \). Such a modification of the Markov game \ref{eq:constrained_MG} defines a valid policy for \ref{eq:MDP2}.

In the MDP setting, we leverage that Markovian stochastic policies and convex combinations of Markovian deterministic policies are equivalent in terms of the state-action occupancy measures they induce (see \cite[Theorem~5.2]{feinberg1996measurability}). Namely, there exists a vector $\alpha\in\Delta(K^i)$ such that:
\begin{align}\label{eq:connection_stochastic_deterministic}
    \bar d_t^{\bar\phi^i}((s_t, a_t^i), \hat a_t^i)
    = \sum_{k=1}^{K^i} \alpha_k \, \bar d_t^{\bar \phi^i(k)}(( s_t, a_t^i), \hat a_t^i),
\end{align}
for all \( (s_t, a_t^i) \in \bar{\mc S} \), all \( \hat a_t^i \in \mc A^i \), and all $t\in[H]$, where each \( \bar\phi^i(k) \in \Phi^i_{M,det} \) is a Markovian deterministic policy of \ref{eq:MDP2}. Note that since Equation \eqref{eq:connection_stochastic_deterministic} holds with equality, the reverse statement is also true. Namely, given a vector $\alpha\in\Delta(K^i)$, there exists a $\bar\phi^i\in\Phi_{M}^i$ such that Equation \eqref{eq:connection_stochastic_deterministic} holds.

Then, by Lemma~\ref{lemma:MDP2_eq_occ_ori}, the corresponding state-action occupancy measure of the modified policy \( \bar\phi^i \circ \pi \) which includes \( \bar\phi^i(k) \circ \pi \) in the original Markov game \ref{eq:constrained_MG} is given by:
\begin{align*}
    d_t^{\bar\phi^i \circ \pi}(s_t, (\hat a_t^i, a_t^{-i}))
    = |\mathcal{A}^i|^t \sum_{a_t^i} \sum_{s_{1:t-1}, a_{1:t-1}}
    \bar d_t^{\bar \phi^i}((s_t, a_t^i), \hat a_t^i) \,
    \pi_t((a_t^i, a_t^{-i}) \mid s_t).
\end{align*}
%
for all $s_t\in\mc S$, all $(\hat a_t^i, a_t^{-i})\in\mc A$, and all $t\in[H]$. Combining the above two expressions, we conclude the proof.
\end{proof}




\subsection{Main proofs of Section \ref{sec:equinotion}}\label{sub_maintheorem}

Leveraging the results in Section \ref{app:equ_NM_M} and \ref{app:equ_M_MD}, we first provide the main proof of Proposition \ref{cor_specialcase} and then we provide the main proof of Theorem \ref{cor:equinotion}.
\\
\\
Now, we are ready to prove Proposition \ref{cor_specialcase}.
\begin{proof}[Proof for Proposition \ref{cor_specialcase}]
Given player $i$ and policy $\pi\in\Pi_M$, we note that any Markovian stochastic modification $\bar\phi^i\in\Phi^i_{M}$ constitutes a valid policy in \ref{eq:MDP2}. For this MDP, we define a reward function $\bar r^{i,\pi}$ as follows: for $t\in[H]$,
\begin{align*}
    &\bar{r}_t^{i,\pi}(\bar{s}_t, \hat a_t^i) =  |\mathcal{A}^i|^t \sum_{a_t^{-i}} r_t^i(s_t, (\hat a_t^i,a_t^{-i})) \pi_t((a_t^i,a_t^{-i}) \mid s_t),\,\, \forall \bar{s}_t = (s_t, a_t^i) \in \bar{\mathcal{S}},
\end{align*}
and $\bar{r}_t^{i,\pi}(b)=0$. The expected cumulative reward $V^{\bar r^{i,\pi}}(\bar\phi^i)$ of \ref{eq:MDP2} is given by:
\begin{align*}
    &V^{\bar{r}^{i,\pi}}(\bar\phi^i)\\
    \overset{(i)}{=}& \sum_{t=1}^{H} \sum_{s_t,a_t^i} \sum_{\ha_t^i} \bar{d}_t^{\bar\phi^i}((s_t,a_t^i),\ha_t^i) \bar{r}_t^{i,\pi}((s_t,a_t^i),\ha_t^i) \\
    \overset{(ii)}{=}& \sum_{t=1}^{H} |\mathcal{A}^i|^t \sum_{s_t,a_t^i} \sum_{\ha_t^i} \bar{d}_t^{\bar\phi^i}((s_t,a_t^i),\ha_t^i) \left(\sum_{a_t^{-i}} r_t^i(s_t, ( \hat a_t^i, a_t^{-i})) \pi_t((a_t^i,a_t^{-i}) \mid s_t) \right)\\
     {=} & \sum_{t=1}^{H} \sum_{s_t}\sum_{(\ha_t^i,a_t^{-i})}r_t^i(s_t, ( \hat a_t^i, a_t^{-i}))\left(|\mathcal{A}^i|^t\sum_{a_t^i}\bar{d}_t^{\bar\phi^i}((s_t,a_t^i),\hat a_t^i) \pi_t((a_t^i,a_t^{-i})|s_t)\right)\\
    \overset{(iii)}{=} &\sum_{t=1}^{H} \sum_{s_t}\sum_{(\ha_t^i,a_t^{-i})}r_t^i(s_t, ( \hat a_t^i,a_t^{-i}))\left( d_t^{\bar\phi^i\circ \pi}({s}_t, (\hat{a}_t^i, a_t^{-i}))\right)\\
    =&  V^{r^i}(\bar\phi^i \circ \pi),
\end{align*}
where \( (i) \) holds since the reward $\bar{r}_t^{i,\pi}(b)$ is zero for all $t\in[H]$. Furthermore, in step \( (ii) \), we substitute the definition of \( \bar{r}_t^{i,\pi} \) and in step \( (iii) \), we apply Lemma \ref{lemma:MDP2_eq_occ_ori}.
The above equation implies that: 
\begin{align}\label{eq:optimality_game_MDP}
    \max_{\bar\phi^i\in\Phi^i_{M}}V^{r^i}(\bar\phi^i\circ\pi)=\max_{\bar\phi^i\in\Phi^i_{M}}V^{\bar{r}^{i,\pi}}(\bar\phi^i).
\end{align}
Furthermore, in MDPs there always exists an optimal Markovian deterministic policy which maximizes the expected cumulative reward \cite{altman2021constrained} such that: 
\begin{align}\label{eq:optimailty_MDP}
\max_{\bar\phi^i\in\Phi^i_{M}}V^{\bar{r}^{i,\pi}}(\bar\phi^i)=\max_{\bar\phi^i(k)\in\Phi^i_{M,det}}V^{\bar{r}^{i,\pi}}(\bar\phi^i(k)).
\end{align}
Combining Equations \eqref{eq:optimality_game_MDP} and \eqref{eq:optimailty_MDP}, we conclude the proof.
\end{proof}

Next, we provide the main proof of Theorem \ref{cor:equinotion}.

\begin{proof}[Proof of Theorem \ref{cor:equinotion}]
\begin{itemize}
    \item \textbf{Equivalence between the first and second statement:} By Lemma \ref{thm:MCE}, for any $\phi^i\in\Phi^i_{NM}$ there exists a $\bar\phi^i\in\Phi_{M}$ such that: 
\begin{align*}
    d_t^{\phi^i \circ \pi}(s_t,a_t) = d_t^{\bar{\phi}^i \circ \pi}(s_t,a_t), \quad\forall(s_t,a_t)\in\mS_t\times\mA, \forall t\in[H].
\end{align*}
 Since the reward $V^{r^i}(\phi^i \circ \pi)$ and the constraint functions $V^{g^{i,j}}(\phi^i \circ \pi)$ are linear functions of the state-action occupancy measure as seen in Equation \eqref{eq:reward_constraint_via_occupancy}, we have:\looseness-1
    \begin{align*}
        &V^{r^i}(\phi^i \circ \pi) =  V^{r^i}(\bar\phi^i(k) \circ \pi) \,\, \text{and} \,\, V^{g^{i,j}}(\phi^i \circ \pi) = V^{g^{i,j}}(\bar\phi^i(k) \circ \pi), \, \forall j\in[J].
    \end{align*}
    This implies the equivalence between the first and the second statement in Theorem~\ref{cor:equinotion}.\looseness-1
    \item \textbf{Equivalence between the first and third statement:} By Lemma \ref{prop:deterministic_modification}, for any $\bar\phi^i\in\Phi^i_{M}$, there exists a vector $\alpha\in\Delta(K^i)$ such that:
    \begin{align*}
        d_t^{\bar\phi^i\circ \pi}(s_t,a_t)=\sum_{k=1}^{K^i}\alpha_k  d_t^{\bar\phi^i(k)\circ\pi}(s_t,a_t),\,\forall(s_t,a_t)\in\mc S\times\mc A,\forall t\in[H],
    \end{align*}
    where $\bar\phi^i(k)\in\Phi_{M,det}^i$. By the same linearity arguments as above, we conclude the equivalence between the first and third statements in Theorem \ref{cor:equinotion}.
\end{itemize}
\end{proof}



\section{Verification of examples}
In the following, we provide detailed mathematical justifications for Examples \ref{example1} and \ref{example2}. Since we focus on the normal-form game setting (i.e., with the time horizon $H = 1$ and one state), we omit the time index $t$ and the state $s$ for simplicity in this section.
\subsection{Verification of Example \ref{example1}}\label{app:example1}
\begin{proof}  
Consider a 2-player normal-form game, where each player’s action space is \(\mA^1 = \mA^2 = \{1,2\}\). Denote by $P1$ and $P2$ the first and the second player, respectively. The reward and the playerwise coupling constraint functions of each player are given by:  
