%\begin{lemma}\label{lem:help2}
%    \citep[Corollary~II.3.4]{dantzig1967continuity} Assume ${\lim}\sup_{n\rightarrow\infty} rank(\xi_{n,I},\psi_n)\leq rank(\xi_I,\psi)$. Then, either $\lim_{n\rightarrow\infty} H(\xi_n,\psi_n)=H(\xi,\psi)$ or $H(\xi_n,\psi_n)$ is empty infinitely often.
%\end{lemma}

\begin{proof}
\begin{enumerate}
    \item Denote by $I=\{m\in[J+K^i])\ \lvert\ \xi_m(\alpha)=0,\, \forall \alpha\in H(\xi,\psi)\}$ the set of those inequality constraints \eqref{eq:LP_1} and \eqref{eq:LP_3} that are actually equality constraints for all feasible points. Note that this set depends only on the limiting $LP^i$. In the following, we will show that:
    \begin{align}\label{eq:rank_condition}
        {\lim}\sup_{n\rightarrow\infty} rank(\xi_{n,I},\psi_n)\leq rank(\xi_I,\psi).
    \end{align}
    Suppose for now that Inequality \eqref{eq:rank_condition} holds, then, by \citep[Corollary~II.3.4]{dantzig1967continuity} it follows that either $\lim_{n\rightarrow\infty} H(\xi_n,\psi_n)=H(\xi,\psi)$ or $H(\xi_n,\psi_n)$ is empty infinitely often. By Assumption \ref{ass:feasible_policies} the set $H(\xi_n,\psi_n)$ is non-empty for all $n$ and therefore, by \citep[Corollary~II.3.4]{dantzig1967continuity} it follows that $\lim_{n\rightarrow\infty} H(\xi_n,\psi_n)=H(\xi,\psi)$. Thus, the conditions of \citep[Theorem~I.2.2]{dantzig1967continuity} are satisfied and applying it we obtain that $\lim\inf_{n\rightarrow\infty} M(\pi_n\mid H(\xi_n,\psi_n))\subseteq M(\pi\mid  H(\xi,\psi))$. This concludes the proof of the first point.

    We are now left with showing that Inequality \eqref{eq:rank_condition} indeed holds.

\noindent \textbf{Consider $rank(\psi)$ and $rank(\psi_n)$:}  Since $\psi_n=\psi =\sum_{k=1}^{K^i}\alpha_k-1$, therefore  $$rank(\psi)=rank(\psi_n)=1.$$

\noindent \textbf{Consider $rank(\xi_I)$ and $rank(\xi_{n,I})$:} Consider $\xi:\R^{K^i}\rightarrow\R^{J + K^i}$ with:
\begin{align*}
    & \xi_j(\alpha)=c^j - \sum_{k=1}^{K^i}\alpha_k V^{g^j}(\phi^i(k)\circ\pi)\leq 0,\,\forall j\in[J],\\
    & \xi_k(\alpha)= -\alpha_k\leq 0, \, \forall k\in\{J+1,\dots,J+K^i\}.
\end{align*}
%Recall the definition of $I=\{m\in[J+K^i])\ \lvert\ \xi_m(\alpha)=0,\, \forall \alpha\in H(\xi,\psi)\}$. 

\textbf{Case I (Assumption \ref{ass:strictly_feasible_policy} holds)} Under Assumption \ref{ass:strictly_feasible_policy} there exists a strictly feasible solution $\alpha$ which implies that $\xi_j(\alpha)<0$ for all $j\in[J]$, and $\psi(\alpha)=0$.

Next, pick any solution $\alpha'$ such that $\alpha'_k>0$ for all $k\in[K^i]$. Then, let $\alpha^{''}=(1-\varepsilon)\alpha+\varepsilon\alpha'$. For $\alpha^{''}$ it holds that $\psi(\alpha^{''})=0$ since $\psi$ is affine, and $\alpha^{''}_k>0$  for all $k\in[K^i]$. Furthermore, by choosing $\varepsilon$ sufficiently small, it holds that $\sum_{k=1}^{K^i}\alpha^{''}_k V^{g^j}(\phi^i(k)\circ\pi)>c^j$ and therefore $\xi_k(\alpha)<0$ for all $k\in\{J+1,\dots,J+K^i\}$.

This implies that $\xi_{m}(\alpha^{''})<0$ for all $m\in[J+K^i]$ and therefore $I$ is empty. We conclude that:
\begin{align*}
    rank(\xi_{n,I},\psi_n)\overset{(i)}{=}rank(\psi_n)\overset{(ii)}{\leq} rank(\psi)\overset{(iii)}{=}rank(\phi_I,\psi), \,\forall n,
\end{align*}

where in $(i)$ and $(iii)$ we use that $I=\emptyset$, and in $(ii)$ we use that $\psi$ has full rank. Thus, Inequality \eqref{eq:rank_condition} is satisfied.
\\
\\
\textbf{Case II (Assumptions \ref{ass:alt} hold)} By second condition of Assumption \ref{ass:alt}, there exists a $\alpha\in\Delta(K^i)$ such that $\alpha\in H(\xi,\psi)$, and satisfies $\alpha_k>0$ for all $k\in[K^i]$. We conclude that $\xi_{m}(\alpha)< 0$ for all $m=J+1,\dots, J+K^i$ and thus $\{J+1,\dots, J+K^i\}\notin I$.


Without loss of generality, we assume that $rank(\{\xi_j\}_{j\in[J]})=J$ since otherwise the redundant constraints can be removed. Note that removing redundant constraints from \ref{lp} does not affect $LP^i_n$ since $I=\{m\in[J+K^i]\ \lvert\ \xi_m(\alpha)=0,\, \forall \alpha\in H(\xi,\psi)\}$ depends only on the limiting \ref{lp}. Furthermore, without loss of generality, we assume that $J=1$ and drop the index $j$ from our notation. For all feasible solutions, we assume that the constraint holds with equality such that $\sum_{k=1}^{K^i}\alpha_k V^{g}(\phi^i(k)\circ\pi)=c$ for all $\alpha\in H(\xi,\psi)$. This implies that $\xi(\alpha)=0$ for all $\alpha\in H(\xi,\psi)$. Suppose that $(\xi_I,\psi)$ has full rank, i.e.,  $rank(\xi_I,\psi)=2$, then the following holds:
\begin{align*}
    rank(\xi_{n,I},\psi_n)\leq rank(\xi_I,\psi), \,\forall n
\end{align*}
\noindent since $rank(\xi_{n,I},\psi_n)\leq 2$. Thus, Inequality \eqref{eq:rank_condition} is satisfied.
\\
\\
Next, we show that $rank(\xi_I,\psi)=2$. Any linear mapping such as $(\xi_I,\psi):\R^{K^i}\rightarrow\R^{2}$ can be represented as $\alpha^T M - (1,c)^T$ where $M\in\R^{2\times K^i}$ and is defined as follows:
\begin{align*}
    M:=\begin{bmatrix}
        1,1,\dots,1\\
V^g(\phi^i(1)\circ\pi),V^g(\phi^i(2)\circ\pi),\dots,V^g(\phi^i(K^i)\circ\pi)
    \end{bmatrix}
\end{align*}
Therefore, by the first condition of Assumption \ref{ass:alt}, we have $rank(M)=2$.

Both Case I and Case II satisfy Inequality \eqref{eq:rank_condition}, which concludes the proof of the first point.
%the assumption of Lemma \ref{lem:help2}. Furthermore, by Assumption \ref{ass:feasible_policies} the $H(\xi_n,\psi_n)\neq\emptyset$ for all $n$. Thus, by Lemma \ref{lem:help2} it follows that $\lim_{n\rightarrow\infty} H(\xi_n,\psi_n)=H(\xi,\psi)$. Applying Lemma \ref{lem:help1} we obtain that $\lim\inf_{n\rightarrow\infty} M(\pi_n\mid H(\xi_n,\psi_n))\subseteq M(\pi\mid  H(\xi,\psi))$ which concludes the proof of the first point.

\item The proof follows from the first point and the same arguments as in \cite[Theorem~3.6 (ii)]{altman1991sensitivity}.

\item The proof follows from the first point and the same arguments as in \cite[Theorem~3.6 (iv)]{altman1991sensitivity}.

\end{enumerate}
\end{proof}

