    \begin{align}
        d_t^i(s,a) := \sum_{k=1}^{K^i} \alpha_k d_t^{\phi^i(k)\circ\pi}(s,a), \,\forall(s,a)\in\mc S\times \mc A, \,\forall t\in[H],\label{eq:help1}
    \end{align}
    where $\alpha\in\Omega^i(\pi)$. For all $\pi'\in\Gamma(d^i)$, we have that:
\begin{align*}
        V^{g^j}(\pi') 
         =& \sum_{t=1}^{H}\sum_{s_t,a_t}d_t^{i}(s_t,a_t) g_t^j(s_t,a_t) \\
        \overset{(i)}{=}& \sum_{t=1}^{H}\sum_{s_t,a_t}\sum_{k=1}^{K^i}  \alpha_k d_t^{\phi^i(k)\circ\pi}(s_t,a_t) g_t^j(s_t,a_t) \\
