\section{Preliminaries}
\label{sec:prelims}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In this section, we review and slightly extend a range of results of differing nature. In \cref{subsec:orientations}, we revisit the theory of semiadditive orientations developed in \cite{BCSY-Fourier}. In \cref{subsec:integrals-p-complete}, we recall a theorem of Li \cite{Li-2025-cardinalities} about computations of semiadditive integrals in $p$-complete 1-semiadditive stable categories. Finally, in \cref{subsec:higher-cats}, we extend the induced character formula of \cite{Ponto-Shulman-2014-induced-character, Carmeli-Cnossen-Ramzi-Yanovski-2022-characters} to $\chrHeight$-categories, using iterated characters.

    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{Semiadditive orientations}
    \label{subsec:orientations}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        Following the terminology of \cite{BCSY-Fourier}:

        \begin{definition}
            Let $\In \coloneqq \tau_{\ge 0} \Sigma^{\chrHeight} I_{\QQ / \ZZ}$ be the truncated and shifted $p$-typical Brown--Comenetz dual of the sphere.
        \end{definition}
        $\In$ is a higher analog of the group $\In[0] = \mu_{\infty}$ of roots of unity. Its $n$-th homotopy group corresponds to higher roots of unity (at all primes) as in \cite{CSY-cyclotomic}. In particular, it defines a notion of height $\chrHeight$ Pontryagin duality:

        \begin{definition}
            Let $M$ be a connective spectrum. Its height $\chrHeight$ Pontryagin dual is defined to be 
            \begin{equation*}
                \ndual{M} \coloneqq \tau_{\ge 0}\hom(M, \In).
            \end{equation*}    
        \end{definition}

        \begin{remark}
            Note the the homotopy groups of the $\chrHeight$-th Pontryagin dual of $M$ are the Pontryagin dual of the homotopy groups of $M$.
            \begin{equation*}
                \pi_i \ndual{M} \simeq \widehat{\pi}_{\chrHeight-i}(M) \coloneqq \Hom_{\Ab}(\pi_{\chrHeight-i}(M), \QQ/\ZZ).
            \end{equation*}
            for $0 \le i \le \chrHeight$.
        \end{remark}

        \begin{definition}
            Let $\cC$ be an $\infty$-semiadditive, presentably symmetric monoidal category and let $R \in \CAlg(\cnSp)$. An $(R,\chrHeight)$-pre-orientation of $\cC$ is a map of connective spectra
            \begin{equation*}
                \omega \colon \ndual{R} \to \ounit_{\cC}\units.
            \end{equation*}
        \end{definition}

        \begin{definition}
            An $R$-module $M$ is $[0,\chrHeight]$-finite if it is connective, $\chrHeight$-truncated and all its homotopy groups are finite. We denote by $\Mod_R^{[0,\chrHeight]\hyphen\mrm{fin}}$ the full subcategory of $[0,\chrHeight]$-finite $R$-modules.
        \end{definition}

        \begin{proposition}[{\cite[Proposition~3.10]{BCSY-Fourier}}]
            The space of $(R,\chrHeight)$-pre-orientations of $\cC$ is isomorphic to the space of natural transformations 
            \begin{equation*}
                \ounit_{\cC}[-] \To \ounit_{\cC}^{\ndual{(-)}} \qin \Fun(\Mod_R^{[0,\chrHeight]\hyphen\mrm{fin}}, \CAlg(\cC)).
            \end{equation*}
        \end{proposition}
        For a pre-orientation $\omega$, we denote the corresponding natural transformation by $\mscr{F}_{\omega}$ and call it the associated Fourier transform.

        \begin{definition}\label{def:orientation}
            A pre-orientation $\omega$ is an orientation if the associated Fourier transform is a natural isomorphism. If the space of $(R,\chrHeight)$-orientations of $\cC$ is non-empty we say the $\cC$ is $(R,\chrHeight)$-orientable.
        \end{definition}

        For any $R$, $\ndual{R} \simeq \ndual{(\tau_{\le \chrHeight} R)}$. Therefore an $(R,\chrHeight)$-orientation is equivalent to a $(\tau_{\le \chrHeight} R, \chrHeight)$-orientation.

        \begin{example}
            A $(\ZZ/N, 0)$-orientation of $\Vect$ is a choice of a primitive $N$-th root of unity in $\field$. $\Vect$ is $(\SS,0)$-orientable if and only if $\field$ is cyclotomically-closed.
        \end{example}

        \begin{example}
            Let $\cC$ be $\infty$-semiadditive. A $(\ZZ/p^r,\chrHeight)$-orientation of $\cC$ is equivalent to a primitive $p^r$-th root of unity of height $\chrHeight$, as in \cite{CSY-cyclotomic}.
        \end{example}

        \begin{example}[{\cite[Proposition~7.27, Corollary~4.21]{BCSY-Fourier}}]
            At the prime $p=2$, for any $R\in\CAlg(\SpTn)$, the category $\Mod_R(\SpTn)$ is $(\Fq{2},\chrHeight)$-orientable. In particular, $\SpTn$, $\SpKn = \Mod_{\SSKn}(\SpTn)$, $\ModEn = \Mod_{\En}(\SpTn)$ are $(\Fq{2},\chrHeight)$-orientable.
        \end{example}

        We interpret the $(\SS, \chrHeight)$-orientability of $\cC$  as expressing that the unit $\ounit_{\cC}$ is spherically cyclotomically closed. Similarly, $(\SS_{(p)}, \chrHeight)$-orientability is interpreted as admitting all $p$-typical spherical roots of unity. 

        \begin{example}[{\cite[Theorem~7.8]{BCSY-Fourier}}]
            $\ModEn$ is $(\SS_{(p)},\chrHeight)$-orientable.
        \end{example}   

        Orientation also behaves well under categorification:
        \begin{theorem}[{\cite[Corollary~5.16]{BCSY-Fourier}}]
            Assume $R$ is $\chrHeight$-truncated. Then $\cC$ is $(R,\chrHeight)$-orientable if and only if $\Mod_{\cC}$ is $(R, \chrHeight+1)$-orientable.
        \end{theorem}

        \begin{definition}\label{def:Vectn}
            Let $\field$ be a field of characteristic 0. 
            Define $\Vectn[1] \coloneqq \Vect \in \CAlg(\PrL)$ and $\Vectnp \coloneqq \Mod_{\Vectn} \in \CAlg(\PrL)$.

            To be more formal, we choose a sequence of inaccessible cardinals $\kappa_1 \subseteq \kappa_2 \subseteq \cdots$, and consider $\Vectn[1]$ as lying in $\CAlg(\PrL_{\kappa_1})$. We then define $\Vectnp \coloneqq \Mod_{\Vectn}(\PrL_{\kappa_{\chrHeight}}) \in \CAlg(\PrL_{\kappa_{\chrHeight+1}})$. We will usually omit this careful description and always assume we work in $\PrL_{\kappa_{\chrHeight}}$ for large enough $\chrHeight$.
        \end{definition}

        \begin{corollary}
            $\Vectnp$ is $(\Fq{2},\chrHeight)$-orientable.
        \end{corollary}

        \begin{definition}\label{def:cyc-closure}
            An $\chrHeight$-cyclotomic-closure of $\ounit_{\cC}$ is an algebra $\ounit_{\cC}\cyc \in \CAlg(\cC)$ such that:
            \begin{enumerate}
                \item $\Mod_{\ounit_{\cC}\cyc}(\cC)$ is $(\SS,\chrHeight)$-orientable.
                \item $\ounit_{\cC} \to \ounit_{\cC}\cyc$ is a pro-Galois extension in the sense of Rognes \cite{Rognes-2008-Galois}.
                \item It is the minimal such extension: For any pro-Galois extension $\ounit_{\cC} \to R$ such that $\Mod_R(\cC)$ is $(\SS,\chrHeight)$-orientable, there exists a map $\ounit_{\cC}\cyc \to R$.
            \end{enumerate}
        \end{definition}
        We do not discuss the existence of cyclotomic closures in this paper but instead assume it, and specifically the existence of $\cVectn = (\Vectn)\cyc$. The existence of these cyclotomic closures will be addressed in a forthcoming paper by the first author.

