    \subsection{Semiadditive integrals in $p$-complete categories}
    \label{subsec:integrals-p-complete}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

        We use a result of Li, which shows that in $p$-complete 1-semiadditive stable categories, integrals over finite classifying spaces of groups can be expressed as linear combinations of integrals over their $p$-subgroups. To establish an analogous statement for free loops spaces, we must appeal to specific arguments from the proof. We therefore briefly recall the key steps below:

        For a group $G$ we denote by $\mrm{A}(G)$ its Burnside ring, i.e.\ the group completion of the semi-ring generated by isomorphism classes of finite $G$-sets. 

        \begin{theorem}[{\cite[Theorem~3.1]{Yoshida-1983-Burnisde-ring}, \cite[Theorem~5.2.5]{Li-2025-cardinalities}}]\label{lem:p-completed-Burnside-generators}
            Let $G$ be a finite group. Let $\{P_1,\dots, P_r\}$ be the set of its $p$-Sylow subgroups. Then in the $p$-completed Burnside ring $\Ap$
            \begin{equation*}
                1 = \sum_{i_1 < \cdots < i_k} (-1)^{k-1} \frac{\left|P_{i_1} \cap \cdots \cap P_{i_k}\right|}{|G|} [ G / (P_{i_1} \cap \cdots \cap P_{i_k})].
            \end{equation*}
        \end{theorem}

        Assume that $\cC$ is a $p$-complete stable symmetric monoidal category. Then $\pi_0(\ounit_{\cC}^{\BG})$ is a module over $\pi_0(\SS_p^{\BG})$. The Segal conjecture (\cite{Lewis-May-McClure-1982-Segal,Carlsson-1984-Segal,Adams-Gunawardena-Miller-1992-Segal}), says that $\pi_0(\SS_p^{\BG}) \simeq \ApIG$, where $I_G \subseteq \mrm{A}(G)$ is the augmentation ideal. In particular, $\pi_0(\ounit_{\cC}^{\BG})$ is an $\Ap$-module.

        \begin{corollary}[{\cite[Theorem 5.2.5]{Li-2025-cardinalities}}]\label{cor:integral-of-BG-is-linear-combination-along-p-subgroups}
            Let $\cC$ be a $p$-complete, $1$-semiadditive, symmetric monoidal stable category. Let $G$ be a finite group and $\{P_1,\dots, P_r\}$ be the set of its $p$-Sylow subgroups. Then, for  $f\in \ounit_{\cC}^{\BG}$,
            \begin{equation*}
                \int_{\BG} f = \sum_{i_1 < \cdots < i_k} (-1)^{k-1} \frac{\left|P_{i_1} \cap \cdots \cap P_{i_k}\right|}{|G|}\int_{\B(P_{i_1} \cap \cdots \cap P_{i_k})} f.
            \end{equation*} 
        \end{corollary}

        \begin{proof}
            Using the $\Ap$-module structure, by \cref{lem:p-completed-Burnside-generators}, it is enough to verify that for a $p$-subgroup $P$ of $G$,
            \begin{equation}\label{eqn:G/P-is-restriction}
                \int_{\BG} ([G/P] \cdot f)= \int_{\BP} f \tag{$\star$}.
            \end{equation}
            This can be done by translating all the operations to the language of spans of spaces.
            We denote by $\Span(\cC; L, R)$ the span category of $\cC$, with left morphisms in $L \subseteq \cC^{[1]}$ and right morphisms in $R\subseteq \cC^{[1]}$ (see \cite[Definition~5.7]{Barwick-2017-spectral-Mackey-functors}). In particular, we will denote by $\Span(\spc; \mfin, \mrm{all})$ the category whose objects are spaces and its morphisms are spans where the wrong way maps have $m$-finite fibers.
            As $\SS_p^{\BG}$ is $0$-semiadditive (i.e.\ a commutative monoid) it promotes to a functor
            \begin{equation*}
                (\SS_p^{\BG})^{(-)} \colon \Span(\spc, \mfin[0], \textrm{all}){\op} \to \pCompSp.
            \end{equation*}
            The action of $[G / P]$ on $\SS_p^{\BG}$ is represented by the span
            \begin{equation*}
                \begin{tikzcd}
                    & {\BP} \\
                    {\BG} & {} & {\BG.}
                    \arrow[from=1-2, to=2-1]
                    \arrow[from=1-2, to=2-3]
                \end{tikzcd}
            \end{equation*}
            Recall that the integral over $\BG$ is defined by evaluating $\ounit_{\cC}^{(-)} \colon \Span(\spcpi[1])\op\to \cC$ against the span
            \begin{equation*}
                \begin{tikzcd}
                    & \BG \\
                    \pt && \BG.
                    \arrow[from=1-2, to=2-1]
                    \arrow[equals, from=1-2, to=2-3]
                \end{tikzcd}
            \end{equation*}
            Thus, the left hand side of \labelcref{eqn:G/P-is-restriction} is represented by the composition of spans
            \begin{equation*}
                \begin{tikzcd}
                    & {\BG} && {\BP} \\
                    \pt && {\BG} & {} & {\BG}
                    \arrow[from=1-2, to=2-1]
                    \arrow[equals, from=1-2, to=2-3]
                    \arrow[from=1-4, to=2-3]
                    \arrow[from=1-4, to=2-5]
                \end{tikzcd} \simeq
                \begin{tikzcd}
                    & {\BP} \\
                    \pt & {} & {\BG,}
                    \arrow[from=1-2, to=2-1]
                    \arrow[from=1-2, to=2-3]
                \end{tikzcd}
            \end{equation*}
            which in turn represents the integral $\int_{\BP}$ of the restriction to $\BP$.
        \end{proof}

        % In particular, power operations in $p$-typical categories are determined by the restiction to $p$-subgroups:
        % \begin{corollary}\label{cor:power-operations-p-typical}
        %     Let $\cC$ be symmetric monoidal, 1-semiadditive stable category. Let $G \to \Sm$ be a homomorphism and $\hchar \colon \B\Sm \to \ounit_{\cC}\units$ a pointed map. Then
        %     \begin{equation*}
        %         \beta^{\degree}_{G,\hchar} = \sum_{i_1 < \cdots < i_k} (-1)^{k-1}\frac{|P_{i_1} \cap \cdots \cap P_{i_k}|}{|G|} \beta^{\degree}_{P_{i_1} \cap \cdots \cap P_{i_k}, \hchar},
        %     \end{equation*}
        %     where $\{P_1,\dots,P_r\}$ is the set of $p$-Sylow subgroups of $G$.
        % \end{corollary}

        \begin{remark}\label{rmrk:Burnside-ring-of-1-types}
            Note that the Burnside ring is the Grothendieck group of the monoid of finite $G$-sets up to isomorphisms, and therefore it depends on $\BG$ rather than on $G$. The space of finite $G$-sets is equivalent to the space of $0$-finite maps of spaces $A \to \BG$. We therefore extend the notion of the Burnside ring of a finite group, to that of a 1-finite space. For a 1-finite space $X$ we define its Burnside ring $\mrm{A}(X)$ as the Grothendieck group of isomorphism classes of 0-finite maps to $X$. If $X = \BG$, then $\mrm{A}(\BG) = \mrm{A}(G)$ is the usual Burnside ring, and if $X = \bigsqcup_i \BG_i$, then $\mrm{A}(X) \simeq \bigsqcap_{i} \mrm{A}(G_i)$.
        \end{remark}

        \begin{corollary}\label{cor:integral-of-LBG-is-linear-combination-along-p-subgroups}
            Let $\cC$ be a $p$-complete, $1$-semiadditive, symmetric monoidal stable category. Let $G$ be a finite group and $\{P_1,\dots, P_r\}$ be the set of its $p$-Sylow subgroups. Then, for $t \ge 0$ and $f\in \ounit_{\cC}^{\Lp^t\BG}$,
            \begin{equation*}
                \int_{\Lp^t\BG} f = \sum_{i_1 < \cdots < i_k} (-1)^{k-1} \frac{\left|P_{i_1} \cap \cdots \cap P_{i_k}\right|}{|G|}\int_{\L^t\B(P_{i_1} \cap \cdots \cap P_{i_k})} f.
            \end{equation*} 
        \end{corollary}

        \begin{proof}
            Using the notations of \cref{rmrk:Burnside-ring-of-1-types}, the $t$-fold free loops space functor defines a ring map
            \begin{equation*}
                \begin{split}
                    \L^t \colon \mrm{A}(G) = \mrm{A}(\BG) & \to \mrm{A}(\L\BG) \simeq \bigsqcap_{[g] \in G / \mrm{conj}} \mrm{A}(\cent_G(g)) \\
                    [A \to \BG] & \mapsto [\L^t A \to \L^t\BG].
                \end{split}
            \end{equation*}
            The $p$-typical free loops space of a $p$-complete space, is the $p$-completion of the free loops space, and therefore satisfies
            \begin{equation*}
                (\L \BG)_p^\wedge \simeq \Lp (\BG)_p^\wedge.
            \end{equation*}
            Thus, after $p$-completion, the above map can be identified with the $t$-fold $p$-typical free loops space
            \begin{equation*}
                \Lp^t \colon \Ap \to \Ap[\Lp^t \BG].
            \end{equation*}
            Therefore, in the $\Ap[\Lp^t\BG]$-algebra $\pi_0(\SS_p^{\Lp^t \BG})$,
            \begin{equation*}
                1 = \Lp^t(1) = \sum_{i_1 < \cdots < i_k} (-1)^{k-1} \frac{\left|P_{i_1} \cap \cdots \cap P_{i_k}\right|}{|G|}[\Lp^t \B(P_{i_1} \cap \cdots \cap P_{i_k}) \to \Lp^t \BG].
            \end{equation*}
            The proof now follows, as in the proof of \cref{cor:integral-of-BG-is-linear-combination-along-p-subgroups}.
        \end{proof}


