    \subsection{Higher categories and iterated characters}
    \label{subsec:higher-cats}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

        We begin by recalling the theory of higher categories and the monoidal trace. We then use the 1-categorical induced character formula to derive an iterated version suited to the higher categorical setting. 

        Let $\cC$ be a symmetric monoidal $\chrHeight$-category. An object $V \in \cC$ is 1-dualizable (or just dualizable) if there exists $V\dual \in \cC$ along with evaluation and coevaluation maps
        \begin{equation*}
            \ev \colon V \otimes V\dual \to \ounit_{\cC}, \qquad \coev \colon \ounit_{\cC} \to V\dual \otimes V
        \end{equation*}
        satisfying the zig-zag identities, i.e.\ the maps
        \begin{equation*}
            V \xto{\id \otimes \coev} V \otimes V\dual \otimes V \xto{\ev \otimes \id} V, \qquad V\dual \xto{\coev \otimes \id} V\dual \otimes V \otimes V\dual \xto{\id \otimes \ev} V
        \end{equation*}
        are isomorphisms.

        \begin{definition}
            We denote the $(\chrHeight-1)$-category spanned by dualizable objects with (higher) morphisms which are left adjoint in $\cC$ by $\cC\ndbl[1]$.
            For $t > 1$ we define the $(\chrHeight-t)$-category
            \begin{equation*}
                \cC\tdbl \coloneqq (\cC\ndbl[(t-1)])\ndbl[1].
            \end{equation*}
            An object $V \in \cC\tdbl$ is called $t$-dualizable. Objects in $\cC\ndbl$ are called fully-dualizable.
        \end{definition}

        % \begin{remark}
        %     In our notations, an object is 2-dualizable if and only if both the evaluation and coevaluation maps are left-adjointable. This differs from the standard notion of 2-dualizability, which requires full adjointability, that is, that $\ev$ and $\coev$ both admit infinite chains of left and right adjoints. Both definitions yield the same notion of full adjointability.
        % \end{remark}

        \begin{definition}
            Given an $\chrHeight$-category $\cC$, we define its loops as
            \begin{equation*}
                \laxloops \cC \coloneqq \ounit_{\cC} \simeq \End_{\cC}(\ounit_{\cC}) \qin \Mon(\Catn[\chrHeight-1]).
            \end{equation*}
            When $\cC$ is symmetric monoidal, $\laxloops \cC$ is symmetric monoidal and the tensor product of $\ounit_{\cC}$ identifies with the composition of $\End_{\cC}(\ounit_{\cC})$.
        \end{definition}
        \begin{corollary}
            A morphism $f \colon \ounit_{\cC} \to \ounit_{\cC}$ is right $t$-adjointable\footnote{If and only if $f$ is left $t$-adjointable, and in this case it is ambidextrous.} in $\cC$ if and only if it is $t$-dualizable in $\laxloops \cC$.
        \end{corollary}
        In particular
        \begin{equation*}
            (\laxloops(\cC\tdbl))\core \simeq ((\laxloops \cC)\tdbl)\core.
        \end{equation*}

        \begin{definition}[{\cite[Definition 2.9]{Hoyois-Scherozke-Sibilla-2017-traces}, \cite[Definition~2.24]{Carmeli-Cnossen-Ramzi-Yanovski-2022-characters}}]
            Let $\cC$ be a symmetric monoidal $n$-category. There exists a symmetric monoidal functor\footnote{In the above references they actually construct the functor from a larger category (denoted by $\End(\cC)$ in \cite{Hoyois-Scherozke-Sibilla-2017-traces} and by $\cC^{\mrm{trl}}$ in \cite{Carmeli-Cnossen-Ramzi-Yanovski-2022-characters}) consisting of (not necessarily invertible) endomorphisms of dualizable objects and left adjoint morphisms with lax commuting squares between them. We restrict their construction to the simpler category consisting only of isomorphisms $\cC\ndbl[1]$.}
            \begin{equation*}
                \tr \colon \cC\ndblA[\TT]{1} \to \laxloops \cC
            \end{equation*}
            sending $f \colon V \to V$ to its trace
            \begin{equation*}
                \tr(f \mid V) \colon \ounit_{\cC} \xto{\coev} V \otimes V\dual \xto{f \otimes \id} V \otimes V\dual \isoto V\dual \otimes V \xto{\ev} \ounit_{\cC}.
            \end{equation*}
            The dimension of $V$ is defined to be
            \begin{equation*}
                \dim(V) \coloneqq \tr(\id_V \mid V).
            \end{equation*}
        \end{definition}

        \begin{lemma}[{\cite[Lemma~3.2.1]{Keidar-Ragimov-2025-twisted-graded}}]\label{lem:trace-is-T-invariant}
            The trace map 
            \begin{equation*}
                \tr \colon (\cC\dblspace)^{\TT} \to (\laxloops \cC)\core \simeq \Omega \cC\core
            \end{equation*}
            is $\TT$-invariant. Its $\TT$-fixed points induce the dimension map, remembering the $\TT$-action
            \begin{equation*}
                \dim \simeq \tr^{h\TT} \colon \cC\core \to (\Omega \cC\core)^{\B\TT}.
            \end{equation*}
        \end{lemma}

