        \begin{corollary}\label{cor:tr-of-k-dualizable}
            Assume that $V \in \cC$ is $t$-dualizable and $f \in \Aut(V)$. Then $\tr(f \mid V)$ is $(t-1)$-dualizable.
        \end{corollary}
