        % \end{proof}

        \begin{definition}
            Let $\cC$ be a symmetric monoidal $\chrHeight$-category. Let $A$ be a space and $V \in \cC\tdblA$ be an $A$-local system of $t$-dualizable objects. Define its $t$-fold character as the composition
            \begin{equation*}
                \chi^t_V \colon \L^t A \simeq A^{\TT^t} \xto{V^{\TT^t}} \cC\tdblA[\TT^t] \xto{\tr^t} \laxloops^t \cC.
            \end{equation*}
        \end{definition}

        \begin{remark}
            Let $V \in \cC\tdblA$ and let $(\gamma_1,\dots,\gamma_t) \colon \TT^t \to A$ be $t$ commuting loops based at $a \in A$. The character of $V$ at $(\gamma_1,\dots,\gamma_t)$ is the $t$-fold trace of the induced automorphisms 
            \begin{equation*}
                \tr^t(\gamma_1, \dots, \gamma_t \mid V_a).
            \end{equation*}
            Note in particular that the $t$-fold character is a $t$-fold iteration of the 1-character functor.
        \end{remark}

        \begin{corollary}\label{cor:characters-are-T-invariant}
            Let $\cC$ be a symmetric monoidal $\chrHeight$-category, $A \in \spc$ and $V\in \cC\tdblA$. Then the $t$-fold character of $V$
            \begin{equation*}
                \chi^t_V \colon \L^t A \to \laxloops^t \cC                
            \end{equation*}
            is $\TT^t$-invariant.
        \end{corollary}

        \begin{proof}
            The $t$-fold character map is the composition
            \begin{equation*}
                \chi^t_V \colon \L^t A = A^{\TT^t} \xto{V^{\TT^t}} \cC\tdblA[\TT^t] \xto{\tr^t} \laxloops^t \cC.
            \end{equation*}
            The first map is $\TT^t$-equivariant by definition and the second by \cref{cor:tr^k-is-T^k-invariant}.            
        \end{proof}

        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \subsubsection*{Induced character formula}
        Recall the 1-categorical induced character formula as developed in \cite{Ponto-Shulman-2014-induced-character, Carmeli-Cnossen-Ramzi-Yanovski-2022-characters}:

        \begin{theorem}[{\cite[Theorem~5.20]{Carmeli-Cnossen-Ramzi-Yanovski-2022-characters}}]\label{thm:induced-character-formula}
            Let $\cC \in \CAlg(\PrL)$ and let $V \in \cC^A$ be a local system of dualizable objects. For a map of spaces $f \colon A \to B$ such that $f^* \colon \cC[B] \to \cC[A]$ is right adjointable, the induced character $\chi_{f_! V}$ is given by the composition
            \begin{equation*}
                \ounit_{\cC}[\L B] \xto{\tr(f^*)} \ounit_{\cC}[\L A] \xto{\chi_V} \ounit_{\cC}.
            \end{equation*}
            In particular, if $\cC$ is $m$-semiadditive and $f$ is a map of $m$-finite spaces, then
            \begin{equation*}
                \chi_{f_! V} = \int_{\L f} \chi_V.
            \end{equation*}
        \end{theorem}
        \begin{proof}
            The first part is exactly \cite[Theorem~5.20]{Carmeli-Cnossen-Ramzi-Yanovski-2022-characters}. The second is by observing that in the $m$-semiadditive case,
            \begin{equation*}
                \tr (f^*) \colon \ounit_{\cC}[\L B] \to \ounit_{\cC}[\L A]
            \end{equation*}
            is equivalent to the composition
            \begin{equation*}
                (\L f)^* \colon \ounit_{\cC}[\L B] \isoto \ounit_{\cC}^{\L B} \xto{(\L f)^*} \ounit_{\cC}^{\L A} \isogets \ounit_{\cC}[\L A].
            \end{equation*}
            The above composition then agrees with the definition of the semiadditive integral.
        \end{proof}

        We iterate this theorem to give a higher analogue, assuming that the category satisfies some $\chrHeight$-presentability condition.

        \begin{definition}
            Let $\cC$ be an $\chrHeight$-category.
            \begin{enumerate}
                \item We say that $\cC$ is $\chrHeight$-presentable if $\laxloops^i \cC$ is presentable for $0 \le i < \chrHeight$ (\cite{stefanich-2020-presentable}).
                \item We say that $\cC$ is $(\chrHeight,m)$-semiadditive if $\laxloops^i \cC$ is $m$-semiadditive for $0 \le i < \chrHeight$.
            \end{enumerate}
        \end{definition}


        \begin{corollary}\label{cor:induced-k-character-formula}
            Let $\cC$ be a symmetric monoidal $\chrHeight$-presentable category.
            Let $V \in \cC\tdblA$ be a local system of $t$-dualizable objects. Then for a map of spaces $f \colon A \to B$ such that $f^* \colon \cC[B] \to \cC[A]$ is $t$-adjointable, the induced iterated character $\chi^t_{f_! V}$ is given by the composition
            \begin{equation*}
                \laxloops^{t}\cC[\L^t B] \xto{\tr^t(f^*)} \laxloops^{t}\cC[\L^t A] \xto{\chi^t_V} \laxloops^{t} \cC.
            \end{equation*}
            In particular, if $\cC$ is $(\chrHeight,m)$-semiadditive and $f$ is a map of $m$-finite spaces, then
            \begin{equation*}
                \chi^t_{f_! V} \simeq \int_{\L^t f} \chi^t_{V}.
            \end{equation*}
        \end{corollary}



