\section{Characters and alternating powers in the higher categorical settings}
\label{sec:categorical}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

    In \cref{subsec:semiadditive-characters} we introduce alternating powers and power operations in the context of higher semiadditive categories. In the higher categorical framework, one can use the iterated induced character formula \cref{cor:induced-k-character-formula} to compute their iterated dimension.

    In \cite[Lemma~3.3.10]{Keidar-Ragimov-2025-twisted-graded}, independently proven in \cite[Lemma~4.7]{Ramzi-2023-seperability} (see also \cref{lem:character-of-Tm}), we provide a formula for the character of a permutation representation. By this formula, to compute the iterated character, under the assumption that the $\TT$-action on the dimension is trivial, it suffices to extend the character computation from permutation representations $\Tm V \in \cC^{\B\Sm}$ to $\Tm (\BG)^*V \in \cC^{\B(G \wr \Sm)}$. We perform this extension in \cref{subsec:higher-cats-and-alternating}, where we compute the character of $\Tm W \in \cC^{\B(G \wr \Sm)}$ in terms of the character of $W$, for any $W \in \cC\dblA[\BG]$.

    In \cref{subsec:categorical-alternating}, we briefly examine the categorical case $\Mod_{\cVectn}$. In this setting, we derive a formula for the alternating power of the unit. We also provide generating functions that compute iterated dimensions of characters induced from functionals on stable stems in low heights, yielding results analogous to \cite[\textsection~5.2]{Keidar-Ragimov-2025-twisted-graded}.


    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{Semiadditive characters and alternating powers}
    \label{subsec:semiadditive-characters}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

        \begin{definition}
            Let $\cC$ be a symmetric monoidal category and let $H \in\Grp(\spc)$ be an $\EE_1$-group. 
            A character of $H$ in $\cC$ is a map of $\EE_1$-groups
            \begin{equation*}
                \hchar \colon H \to \ounit_{\cC}\units.
            \end{equation*}
            Equivalently a character is a map of pointed connected spaces $\BH\to \B\ounit_{\cC}\units \simeq \B\Aut(\ounit_{\cC})$ and thus gives an $H$-action on $\ounit_{\cC}$. We denote the unit with this action by $\ounit_{\cC}[\hchar]\in\cC^{\BH}$.
        \end{definition}

        \begin{definition}
            Let $H \in \Grp(\spc)$ and $\hchar \colon H \to \ounit_{\cC}\units$ be a character. Define the inverse character $\overline{\hchar} \colon H \to \ounit_{\cC}\units$ as the composition
            \begin{equation*}
                \overline{\hchar} \colon H \xto{\hchar} \ounit_{\cC}\units \xto{(-)^{-1}} \ounit_{\cC}\units.
            \end{equation*}
        \end{definition}

        \begin{definition}
            Let $\cC\in\CAlg(\PrL)$, $H\in\Grp(\spc)$ and $\hchar \colon H \to \ounit_{\cC}\units$ a character. For $V\in\cC^{\BH}$ we define its $\hchar$-isotypic component by
            \begin{equation*}
                V_{\hchar} \coloneqq (V\otimes \ounit_{\cC}[\overline{\hchar}])^{h H}.
            \end{equation*}
        \end{definition}

        \begin{definition}\label{def:alt-power}
            Let $\cC\in\CAlg(\PrL)$, $H$ a group with a homomorphism $H \to \Sm$ and a character $\hchar \colon H \to \ounit_{\cC}\units$. 
            For $V\in \cC$ define its $\hchar$-twisted $\degree$-th alternating power $\alt_{H,\hchar} V \coloneqq (\Tm V)_{\hchar}$ as the $\hchar$-isotypic component of $\Tm V\in \cC^{\BH}$. That is:
            \begin{equation*}
                \alt_{H, \hchar} V = (\Tm V \otimes \ounit_{\cC}[\overline{\hchar}])^{h H}.
            \end{equation*}
        \end{definition}

        \begin{notation}
            Our main interest will be in the case $H = \Sm$ with the identity morphism. In this case we drop $H$ from the notation
            \begin{equation*}
                \alt_{\hchar} V = (\Tm V \otimes \ounit_{\cC}[\overline{\hchar}])^{h\Sm}.
            \end{equation*}
        \end{notation}

        \begin{example}
            For any $\cC$ there exists a trivial character $\hchar \equiv 1$. Its corresponding alternating powers are identified with the symmetric powers.
        \end{example}

        \begin{example}
        \label{exm:classical-characters}
            Let $\field$ be a field of characteristic different than 2. Then $\Sm$ has exactly two characters in $\Vect$: the trivial and the sign characters. The corresponding alternating powers are the symmetric powers and the classical alternating powers respectively.
        \end{example}

        Both the trivial and the sign representations factor through $\ZZ/2$. More generally, if $H$ is a finite group, then any character of $H$ in $\Vect$ factors through $\mu_{\infty}(\field)$ --- the group of roots of unity in $\field$. We extend this idea to the higher semiadditive setting, replacing roots of unity with their higher analogue, as captured by semiadditive orientations (\cref{subsec:orientations}).


        \begin{definition}\label{def:characters-from-orientation}
            Let $H$ be a group, $R$ a connective ring spectrum and $\cC$ an $(R,\chrHeight)$-oriented category. 
            A character is said to be $(R,\chrHeight)$-orientation-induced if it factors through the orientation map $\ndual{R} \to \ounit_{\cC}\units$.
        \end{definition}


