        \subsubsection*{Twisted power operations}
        Let $\hchar \colon \BH \to \B\ounit_{\cC}\units$ be a character. The $\hchar$-twisted alternating power functor
        \begin{equation*}
            \alt_{\hchar} \colon \cC \to \cC
        \end{equation*}
        can be thought of as a (twisted) power operation in $\Mod_{\cC}$. Under semiadditivity assumptions, it introduces operations on the ring $\K(\cC\dbl)$. 

        % $\Mod_{\cC}$ is $\infty$-semiadditive and the semiadditive integral is identified with the colimit in the corresponding functor categories.
        The character $\hchar$ can also be viewed as a map of pointed spaces
        \begin{equation*}
            \hchar \colon \BH \to \cC\units.
        \end{equation*}
        Observing that $\cC$ is the unit object in $\Mod_{\cC}$ motivates the following definition:

        \begin{definition}\label{cons:power-operation}
            Let $\cC$ be 1-semiadditive, symmetric monoidal category. Let $H$ be a finite group with a homomorphism $H \to \Sm$ and let $\hchar \colon \BH \to \ounit_{\cC}\units$ be a pointed map.
            Define the $\hchar$-twisted power operation as the composition
            \begin{equation*}
                \beta_{H,\hchar}^{\degree} \colon \underlying \ounit_{\cC} \xto{(-)^{\degree}} (\underlying \ounit_{\cC})^{\BH} \xto{-\cdot \overline{\hchar}} (\underlying \ounit_{\cC})^{\BH} \xto{\int_{\BH}} \underlying \ounit_{\cC}.
            \end{equation*}
        \end{definition}

        \begin{notation}
            In the case where $H = \Sm$ with the identity morphism we drop the group from the notation
            \begin{equation*}
                \beta_{\hchar}^{\degree} \colon \underlying \ounit_{\cC} \xto{(-)^{\degree}} (\underlying \ounit_{\cC})^{\B\Sm} \xto{-\cdot \overline{\hchar}} (\underlying \ounit_{\cC})^{\B\Sm} \xto{\int_{\B\Sm}} \underlying \ounit_{\cC}.
            \end{equation*}
        \end{notation}

        \begin{example}
            When $\hchar \colon \B\Sm \to \ounit_{\cC}\units$ is the trivial map, the $\hchar$-twisted power operation is the usual semiadditive power operation (see e.g.\ \cite[Definition~4.1.1]{CSY-teleambi}).
        \end{example}

        \begin{example}
            Let $\field$ be a field of characteristic 0 and $\cC = \Mod_{\K(\field)}$. Let 
            \begin{equation*}
                \hchar \colon \B\Sm \xto{\sgn} \Sigma\field\units \to \Mod_{\field}\units \to \K(\field)\units.
            \end{equation*}
            Then the $\hchar$-twisted power operation $\beta^{\degree}_{\hchar} \colon \K(\field) \to \K(\field)$ is the $\degree$-th $\lambda$-operation $\lambda_{\degree}$.
        \end{example}

