        \begin{remark}\label{rmrk:decategorification-of-alternating-powers}
            The category $\Mod_\cC$ is $\infty$-semiadditive and the semiadditive integral over a map $A \to \FunL_{\cC}(X,Y)$ is computed as the colimit over $A$ in the functor category. 
            We therefore deduce the following equality for any finite group $H$ and $V \in \cC^A$:
            \begin{equation*}
                \int^{\Mod_{\cC}}_{\BH} V= \colim_{\BH} V = V_{hH} \qin \cC.
            \end{equation*}
            In particular, for any character $\hchar \colon \BH \to \B\ounit_{\cC}\units$ the $\hchar$-twisted power operation in $\Mod_{\cC}$ is the $\hchar$-twisted alternating power in $\cC$:
            \begin{equation*}
                \beta^{\degree}_{H,\hchar}(-) = \int_{\B\Sm}^{\Mod_\cC} (-)^{\degree} \cdot \overline{\hchar} =\alt_{H, \hchar} (-).
            \end{equation*}
        \end{remark}


