        \subsubsection*{Induced character formula for alternating powers}

        In the context of $\chrHeight$-presentable $(\chrHeight,1)$-semiadditive categories, one can use the iterated induced character formula to compute the diemsnions of alternating powers.

        \begin{lemma}
            Let $\cC$ be a symmetric monoidal $\chrHeight$-presentable, $(\chrHeight,1)$-semiadditive category.
            Let $H$ be a finite group, $H \to \Sm$ a homomorphism, $V \in \cC\tdbl$ and $\hchar \colon \Sm \to \ounit_{\cC}\units$ a character. Then 
            \begin{equation*}
                \dim^t(\alt_{H,\hchar}) = \int_{\L^t \BH} \chi^t_{\Tm V \otimes \ounit_{\cC}[\overline{\hchar}]} = \int_{\L^t \BH} \chi^t_{\Tm V} \cdot \chi^t_{\ounit_{\cC}[\overline{\hchar}]} \qin \laxloops^{t} \cC.
            \end{equation*}
        \end{lemma}

        \begin{proof}
            This follows by \cref{cor:induced-k-character-formula}, as $\alt_{H,\hchar} V$ is the induced representation of $\Tm V \otimes \ounit_{\cC}[\overline{\hchar}]$ under the map $\BH \to \pt$.
        \end{proof}

        \begin{definition}\label{def:transgression}
            Let $A\in\spc$, $X\in \cnSp$ and $\hchar \colon A\to X$ be a map of spaces. We define the transgression of $\hchar$ as
            \begin{equation*}
                \tg(\hchar) \colon \L A \xto{\L\hchar} \L X\simeq  X \times \Omega X \xto{\eta +\id} \Omega X
            \end{equation*}
            where $\eta \colon X \to \Omega X$ is the Hopf map. 
        \end{definition}

        \begin{remark}
            The name comes from group cohomology. When $A=\BH$ for a group $H$ and $X=\Sigma^n M$ for an abelian group $M$, the map above is the transgression map in group cohomology (\cite{Dijkgraff-Witten-1990-transgression}). 
        \end{remark}

        \begin{lemma}\label{lem:tg-of-const}
            Let $x \colon A \to X$ be a constant map choosing $x\in X$. Then its transgression is the constant map
            \begin{equation*}
                \tg(x) \equiv \eta x \qin \Omega X.
            \end{equation*}
        \end{lemma}
        \begin{proof}
            Under the identification $\L X \simeq X \oplus \Omega X$, $\L x \colon \L A \to X \oplus \Omega X$ is the constant map on $(x,0)$.
        \end{proof}

