        \begin{proposition}\label{prop:transgersion-is-charcter-of-character}
            Let $\cC$ be a symmetric monoidal $\chrHeight$-presentable category.
            Let $H$ be a finite group and $\hchar \colon H \to \ounit_{\cC}\units$ a character. Then for $1 \le t \le \chrHeight$
            \begin{equation*}
                \chi^t_{\ounit_{\cC}[\hchar]}=\tg^t(\hchar) \qin (\laxloops^t \cC)^{\L^t \BH}.
            \end{equation*}
        \end{proposition}

        \begin{proof}
            It is enough to show that, for a 1-finite space $A$ and $\hchar \colon A \to \cC\units$, we have
            \begin{equation*}
                \chi_{\hchar} \simeq \tg(\hchar).
            \end{equation*}

            In this case the character map $\chi_{\hchar} \colon \L A \to \Omega \cC\core$ factors as 
            \begin{equation*}
                \Map(\TT, A) \xto{\hchar \circ -} \Map(\TT, \cC\units) \xto{\tr} \ounit_{\cC} \units \to \Omega \cC\core.
            \end{equation*}
            By \cite[Lemma~3.2.7]{Keidar-Ragimov-2025-twisted-graded}, under the identification $\Map(\TT, \cC\units) \simeq \cC\units \oplus \ounit_{\cC}\units$ the map $\tr$ becomes $\eta + \id$. Therefore 
            \begin{equation*}
                \chi_{\hchar} = \tg(\hchar).
            \end{equation*}            
