        \begin{remark}
            Note that when $\cC$ is $(R,\chrHeight)$-oriented, then $\laxloops \cC$ is $(R,\chrHeight-1)$-oriented. If $\hchar$ factors through $\ndual{R}$, then its transgression factors as
            \begin{equation*}
                \tg(\hchar) \colon \L\BH \to \L\ndual{R} \xto{\eta + \id} \Omega \ndual{R} \simeq \ndual[\chrHeight-1]{R}.
            \end{equation*}
            That is, transgression sends orientation-induced characters to orientation-induced maps.
        \end{remark}

        \begin{corollary}\label{cor:k-character-of-alternating}
            Let $\cC$ be a symmetric monoidal $\chrHeight$-presentable, $(\chrHeight,1)$-semiadditive category. Then for $V \in \cC\tdbl$, a homomorphism $H \to \Sm$, and a character $\hchar \colon H \to \ounit_{\cC}\units$,
            \begin{equation*}
                \dim^t (\alt_{H, \hchar} V) \simeq \int_{\L^t \BH} \chi^t_{\Tm V} \cdot \tg^t(\overline{\hchar}) \qin \laxloops^{t} \cC.
            \end{equation*}
        \end{corollary}




    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{Wreath products and premutation representations}
    \label{subsec:higher-cats-and-alternating}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        Our goal in this subsection is to express the character of $\Tm W \in \cC^{\B(G \wr \Sm)}$ for any $W \in \cC\dblA[\BG]$ in terms of the character of $W$ itself.
        We begin by recalling the structure of stabilizers in wreath products. Using this, we deduce the general result from the special case $G = e$, which was treated in \cite{Keidar-Ragimov-2025-twisted-graded}.        

        \begin{notation}\label{not:not1}
            Let $G$ be a group. We denote elements of $G^{\degree}$ by $\underline{g} = (g_1, \dots, g_{\degree})$. 
            Recall that the wreath product $G \wr \Sm$ is the semidirect product $G^{\degree} \rtimes \Sm$. We denote its elements by $(\underline{g}; \sigma)$ where $\underline{g} \in G^{\degree}$ and $\sigma \in \Sm$.
        \end{notation}

        \begin{notation}\label{not:not2}
            For $\underline{g}\in G^{\degree}$, we say that $x\in \underline{g}$ if there exists $i$ for which $g_i = x$. We define its multiplicity as the number of indices equal to $x$
            \begin{equation*}
                \mul_{\underline{g}}(x) \coloneqq |\{i \mid g_i = x\}|.
            \end{equation*}
        \end{notation}

        \begin{notation}\label{not:sigma}
            For $\sigma\in \Sm$. We denote by
            \begin{enumerate}
                \item $\Nk$ --- The number of $k$ cycles in the decomposition to disjoint cycles of $\sigma$.
                \item $\numcyc = \sum_k \Nk$ --- the number of cycles in the decomposition of $\sigma$ to disjoint cycles.
            \end{enumerate}
        \end{notation}

        \begin{definition}\label{def:root-of-central-element}
            Let $G$ a be group, $z \in \Z(G)$ and $k \in \NN$. We define the group
            \begin{equation*}
                G\kz{z} \coloneqq G \langle x \mid x^k = z, \ gx = xg\  \forall g \in G \rangle.
            \end{equation*}
            It is an extension of $\Ck$ by $G$
            \begin{equation*}
                1 \to G \to G\kz{z} \to \Ck \to 1.
            \end{equation*}
            In particular, $G\kz{e} = G \times \Ck$.
        \end{definition}

        % \begin{remark}\label{rmrk:adding-roots-to-abelian-group}
        %     By definition, if $G$ is a finite abelian group then so is $G\kz{z}$ for any $z \in G$ and $k \in \NN$.
        % \end{remark}

        \begin{lemma}\label{lem:decomposition-of-wreath}
            Let $G$ be a finite group. Then
            \begin{equation*}
                \begin{split}
                    \L\B(G \wr \Sm) 
                    & = \bigsqcup_{[\sigma] \in \Sm/\mathrm{conj}} \ 
                    \bigsqcap_{k=1}^\degree \ 
                    \bigsqcup_{[\underline{g}^k] \in \Sm[\Nk] \backslash G^{\Nk} / \mrm{conj}} \ 
                    \bigsqcap_{x \in \underline{g}^k} \B (\cent_G(x)\kz{x} \wr \Sm[\mul_{\underline{g^k}}(x)]) \\
                    & = \bigsqcup_{\sigma \in \Sm/\mathrm{conj}} \ 
                    \bigsqcup_{[\underline{g}^1], \dots, [\underline{g}^{\degree}]} \ 
                    \bigsqcap_{k=1}^\degree \
                    \bigsqcap_{x \in \underline{g}^k} \B (\cent_G(x)\kz{x} \wr \Sm[\mul_{\underline{g}^k}(x)]).
                \end{split}
            \end{equation*}
            In particular,
            \begin{equation*}
                \L\B\Sm  = \bigsqcup_{[\sigma] \in \Sm / \mrm{conj}} \ \bigsqcap_{k=1}^{\degree} \B(\ZZ/k \wr \Sm[\Nk]),
            \end{equation*}
            and the group $\bigsqcap_{k=1}^{\degree} (\ZZ/k \wr \Sm[\Nk])$ is the centralizer $\Csigma$. The groups $\ZZMod{k}$ are generated by the $k$-cycles and the groups $\Sn[\Nk]$ permutes the different $\Nk$ $k$-cycles.
        \end{lemma}

        \begin{proof}
            When $G = e$, this result is classical. For a proof in the general case, see \cite{Bernhardt-Niemeyer-Rober-Wollenhaupt-2022-wreath}. A deduction of the general case from the special case $G = e$ using the symmetric monoidal dimension in $\Span(\spcpi[1])$ can be found in \cref{app:conjugacy-of-wreath}. See also \cite{Barthel-Stapleton-2017-power-operations} for a discussion of the $\pi_0$-level version of this result.
        \end{proof}

        \begin{remark}\label{rmrk:conjugacy-classes-to-connected-components}
            Let $(\underline{h}; \sigma) \in G \wr \Sm$. We can explicitly describe the connected component corresponding to the conjugacy class of this element. Suppose that $\sigma$ decomposes into disjoint cycles as
            \begin{equation*}
                \sigma = (a^1_1, \dots, a^1_{m_1}) (a^2_1, \dots, a^2_{m_2}) \cdots (a^r_1, \dots, a^r_{m_r}).
            \end{equation*}
            Then the conjugacy class of $(\underline{h}; \sigma)$ corresponds to the connected component of $[\sigma], [\underline{g}^1], \dots, [\underline{g}^{\degree}]$, where
            \begin{equation*}
                \underline{g}^k = (\, \sqcap_{j} h_{a^i_j} \mid m_i = k\,).
            \end{equation*}
        \end{remark}


        \begin{definition}\label{def:stabilizer-action}
            Let $\cC$ be a symmetric monoidal category.
            Let $\sigma \in \Sm$ and $V \in \cC \dbl$. By abuse of notations, we denote by
            \begin{equation*}
                (\dim V)^{\numcyc} \coloneqq \bigsqcap_{k=1}^{\degree} \Tm[\Nk] \Res^{\TT}_{\ZZ/k} \dim(V) = \bigsqcap_{k=1}^{\degree} \dim(V)^{\Nk} \qin \ounit_{\cC}^{\B\Csigma}
            \end{equation*}
            the object with the corresponding $\Csigma$-action.
            It is the action of $\Csigma \simeq \bigsqcap_{k = 1}^{\degree} ((\ZZ / k)^{\Nk} \rtimes \Sm[\Nk])$ on $(\dim V)^{\numcyc} \in \ounit_{\cC}$, where the component $(\ZZ / k)_{\tau} \subseteq (\ZZ / k)^{\Nk}$ corresponding to a cycle $\tau \subseteq \sigma$ of length $k$, acts on the component $(\dim (V))_{\tau}$ by restriction along the natural map $\ZZ/k \into \TT$. $\Sm[\Nk]$ acts on $\bigsqcap_{\substack{\tau \subseteq \sigma, \\ |\tau| = k}} (\dim V)_{\tau}$ by permutation.
        \end{definition}

        \begin{remark}
            When $\cC$ is an $\chrHeight$-category, as we denote the product in $\ounit_{\cC} = \laxloops \cC$ by $\otimes$, we will denote this element by $(\dim V)\om[\numcyc] \in (\laxloops \cC)^{\B\Csigma}$.
        \end{remark}

        \begin{lemma}[{\cite[Lemma~4.7]{Ramzi-2025-endomorphisms-of-THH}, \cite[Lemma~3.3.10]{Keidar-Ragimov-2025-twisted-graded}}]\label{lem:character-of-Tm}
           Let $\cC$ be a symmetric monoidal category, $V\in \cC\dbl$, $[\sigma] \in \Sm / \mrm{conj}$. Then 
           \begin{equation*}
               \chi_{\Tm V}(\sigma) \simeq \dim(V)^{\numcyc} \qin \ounit_{\cC}^{\B \Csigma}.
           \end{equation*}
        \end{lemma}

        \begin{corollary}\label{cor:dim-of-alternating-depends-only-on-dim}
            Assume that $\cC$ is 1-semiadditive and presentable. Then for any $V \in \cC\dbl$ and a character $\hchar \colon \Sm \to \ounit_{\cC}\units$, the dimension $\dim(\alt_{\hchar} V)$ depends only on $\dim(V) \in \ounit_{\cC}^{\B\TT}$ and $\hchar$.
        \end{corollary}
        \begin{proof}
            By \cref{lem:character-of-Tm}, $\chi_{\Tm V}$ depends only on $\dim(V)$. The result now follows by \cref{cor:k-character-of-alternating}.
        \end{proof}

        % \begin{remark}\label{rmrk:dim-of-alternating-depends-cyclic-group}
        %     More precisely, the dimension $\dim(\alt_{\hchar} V)$ depends only on $\dim(V) \in (\laxloops \cC)^{\vee_k \B\Ck}$ --- the restriction of $\dim(V)$ to any finite subgroup $\Ck \subseteq \TT$.
        % \end{remark}

        The proof of \cref{lem:character-of-Tm} uses Baez's and Dolan's cobordism hypothesis \cite{Baez-Dolan-1995-cobordism} in dimension 1. Its proof sketched in \cite{Lurie-2008-cobordism} and proved (in dimension 1) in \cite{Harpaz-2012-cobordism}. To generalize this lemma to the case where $V$ admits a group action, we use the cobordism hypothesis with tangential structures, which was proved (assuming the cobordism hypothesis) in \cite[Theorem~2.4.18]{Lurie-2008-cobordism}. We use the slightly less general theorem, when the space is connected:
       \begin{theorem}[{The cobordism hypothesis for $G$-manifolds in dimension 1 \cite{Harpaz-2012-cobordism}, \cite[Theorem~2.4.26]{Lurie-2008-cobordism}}]\label{thm:cobordism-hyp-in-dim-1}
           Let $G$ be an $\EE_1$-group and $\chi \colon G \to O(1)$ a homomorphism of groups. Then for any symmetric monoidal category $\cC$, the evaluation at the point defines an isomorphism of spaces
           \begin{equation*}
               \Map^{\otimes}(\Bord_1^G, \cC) \simeq (\cC\dblspace)^{h G}.
           \end{equation*}
       \end{theorem}

       \begin{remark}\label{rmrk:G-cobordism}
           If $G$ is discrete and the map $G \to O(1)$ is trivial, we can explicitly describe the category $\Bord_1^G$ (see \cite[Notation~2.4.16, Definition~Sketch~2.4.17]{Lurie-2008-cobordism}). Its objects are commutative triangles
           \begin{equation*}
               \begin{tikzcd}
                    & \BG \\
                    \pt && {O(1),}
                    \arrow["e", from=1-2, to=2-3]
                    \arrow[from=2-1, to=1-2]
                    \arrow[from=2-1, to=2-3]
                \end{tikzcd}
           \end{equation*}
           i.e.\ framed points with a lift to $\BG$, and the morphisms are framed 1-dimensional manifolds with a lift to $\BG$, respecting the boundary. 
           Informally, we can think of $\Bord_1^G$ as consisting of framed points, and the morphisms are 1-dimensional manifolds where on each connected component $M$, we add a weight which is an element in $G$ if $M$ is a line or an element in $G$ up to conjugation if $M$ is a circle. The weight of the composition of bordisms will be the product of the weights.
       \end{remark}

        \begin{recollection}\label{recol:T-action-on-BG}
            Let $G$ be a discrete group. A $\TT$-action on the space $\BG$ is the same as a map of pointed spaces $\B \TT \to \B\Aut(\BG)$, which, as $\B\TT$ is simply connected and $\B\Aut(\BG)$ is 2-truncated, is the same as an element in $\pi_2(\B\Aut(\BG)) = \Z(G)$. That is, a $\TT$-action on $\BG$ is the data of a central element of $G$.
        \end{recollection}

        \begin{lemma}
            Let $G$ be a discrete group and $z\in \Z(G)$ corresponding to a $\TT$-action on $\BG$. Then, restricting the $\TT$-action to $\Ck\subseteq \TT$, we have
            \begin{equation*}
                (\BG)_{h \Ck} \simeq \B G\kz{z}.
            \end{equation*}
        \end{lemma}

        \begin{proof}
            This is proved in \cref{lem:cyclic-fixed-points-of-BG}. We remark that this result is not needed for the rest of the paper if one replaces $\BG\kz{z}$ with $(\BG)_{h\Ck}$ everywhere.
        \end{proof}

        \begin{remark}\label{rmrk:roots-of-centralizer-acts-on-character}
           Let $\cC$ be symmetric monoidal $\chrHeight$-category, $G$ a discrete group and $V \in \cC\dblA[\BG]$.
           For any $x \in G$, the character map restricted to $\B\cent_G(x)$
            \begin{equation*}
                \chi_V \colon \B\cent_G(x) \into \L\BG \to \ounit_{\cC},
            \end{equation*}
            is $\TT$-invariant by \cref{cor:characters-are-T-invariant}, and in particular $\Ck$-invariant for any $k \ge 1$. Therefore, it is equivalent to a map
            \begin{equation*}
                \B\cent_G(x)\kz{x} \simeq (\B\cent_G(x))_{h\Ck} \to \ounit_{\cC},
            \end{equation*}
            choosing $\chi_V(x)$. That is, $\chi_V(x)$ admits a natural action of $\cent_{G}(x)\kz{x}$.

            In the case where $G = e$, this is the $\Ck$-action on $\dim(V)$ restricted from the $\TT$-action.
        \end{remark}

        \begin{notation}
             Let $A$ be a space and $B\in \spc^A$ be an $A$-local system of spaces. 
             By embedding $\spc$ into the 2-category of spans $\Span_{1.5}(\spc)$\footnote{The notation $\Span_{1.5}$ indicates that the 2-arrows are maps between spans, to distinguish $\Span_2$ where the 2-arrows are spans of spans.}, sending morphisms to the right way maps, we get an $A$-local system with values in $\Span_{1.5}(\spc)$. We will abuse notation and call this local system $B$ as well. 
        \end{notation}

        \begin{lemma}\label{lem:colimt-of-character-in-spans}
            Let $B \in \spc^A$ and let 
            \begin{equation*}
                \chi^{\Span}_B \colon \L A \to \laxloops \Span_{1.5}(\spc) \simeq \spc
            \end{equation*}
            be the character of $B$ thought of as a $\Span_{1.5}(\spc)$-valued local system. Then 
            \begin{equation*}
                \colim_{\L A} \chi^{\Span}_B =\L(\colim_A B),
            \end{equation*}
            where both colimits are computed in $\spc$. 
        \end{lemma}

        \begin{proof}
            We observe that the colimit of $B$ in $\Span_{1.5}(\spc)$ is computed as the colimit of $B$ in $\spc$. As $\dim_{\Span_{1.5}(\spc)}(\colim_A B) = \L(\colim_A B)$, by the induced character formula
            \begin{equation*}
                \colim_{\L A} \chi_B = \int_{\L A} \chi_B \simeq \dim_{\Span_{1.5}(\spc)}(\colim_A B) = \L(\colim_A B).
            \end{equation*}
        \end{proof}


