        \begin{proposition}\label{lem:character-of-wreath-product}
            Let $\cC$ be symmetric monoidal category and $G$ be a finite group. Let $V\in \cC\dblA[\BG]$. Then the the character of the $G \wr \Sm$-representation $\Tm V$ is the map
            \begin{gather*}
                \chi_{\Tm V} 
                \colon \L\B(G \wr \Sm) 
                \simeq 
                    \bigsqcup_{[\sigma] \in \Sm / \mrm{conj}} \ 
                    \bigsqcup_{[\underline{g}^1],\dots,[\underline{g}^{\degree}]} \ 
                    \bigsqcap_{k=1}^{\degree} \ 
                    \bigsqcap_{x \in \underline{g}^k} \B(\cent_G(x)\kz{x} \wr \Sm[\mul_{\underline{g}^k}(x)])
                \to \ounit_{\cC} \\
                ((x)_{x \in \underline{g}^k})_{k=1}^{\degree} 
                \mapsto \bigsqcap_{k=1}^{\degree} \bigsqcap_{x \in \underline{g}^k} \Tm[\mul_{\underline{g}^k}(x)]\chi_V(x) 
                \simeq \bigsqcap_{k=1}^{\degree} \bigsqcap_{x \in \underline{g}^k} \chi_V(x)^{\mul_{\underline{g}^k}(x)}
            \end{gather*}
            where the $\cent_G(x)\kz{x}$-action is as described in \cref{rmrk:roots-of-centralizer-acts-on-character}
        \end{proposition}


        \begin{proof}
            First note that $\L\B(G \wr \Sm) \simeq \L((\BG^{\degree})_{h\Sm})$ and therefore, by \cref{lem:colimt-of-character-in-spans} 
            \begin{equation*}
                \L\B(G \wr \Sm) \simeq \colim_{\L\B\Sm} \chi^{\Span}_{\BG^{\degree}}.
            \end{equation*}
            By \cref{lem:character-of-Tm}, 
            \begin{equation*}
                \chi^{\Span}_{\BG^{\degree}}(\sigma) \simeq (\L \BG)^{\numcyc} \qin \spc^{\B \Csigma}.
            \end{equation*}
            The character map $\chi_{\Tm V} \colon \L\B(G \wr \Sm) \to \ounit_{\cC}$ can therefore be described as a system of $\Csigma$-invariant maps
            \begin{equation*}
                \chi_{\Tm V}(\sigma) \colon (\L\BG)^{\numcyc} \to \ounit_{\cC}.
            \end{equation*}
            It is enough to check that the map $\chi_{\Tm V}(\sigma)$ is the claimed map, and it is enough to verify it in the universal case $\Bord_1^G$ (\cref{thm:cobordism-hyp-in-dim-1,rmrk:G-cobordism}). In that case, it is straightforward using \cref{rmrk:conjugacy-classes-to-connected-components}.
        \end{proof}

        \begin{corollary}\label{cor:character-when-no-T-action}
            Let $\cC$ be a 1-semiadditive symmetric monoidal category, $G$ a finite group and  $V \in  \cC\dbl$. Assume that the $\TT$-action on $\dim(V)$ is trivial. Then the character of the $G \wr \Sm$-representation $\Tm (\BG)^* V$ is
            \begin{gather*}
                \chi_{\Tm (\BG)^* V}
                \colon \L\B(G \wr \Sm) 
                \simeq 
                    \bigsqcup_{[\sigma] \in \Sm / \mrm{conj}} \ 
                    \bigsqcup_{[\underline{g}^1],\dots,[\underline{g}^{\degree}]} \ 
                    \bigsqcap_{k=1}^{\degree} \ 
                    \bigsqcap_{x \in \underline{g}^k} \B(\cent_G(x)\kz{x} \wr \Sm[\mul_{\underline{g}^k}(x)])
                \to \ounit_{\cC} \\
                ((x)_{x \in \underline{g}^k})_{k=1}^{\degree} 
                \mapsto \bigsqcap_{k=1}^{\degree} \bigsqcap_{x \in \underline{g}^k} \Tm[\mul_{\underline{g}^k}(x)] (\B\cent_G(x)\kz{x})^*(\dim V)
                \simeq \bigsqcap_{k=1}^{\degree} \bigsqcap_{x \in \underline{g}^k} (\dim V)^{\mul_{\underline{g}^k}(x)}.
            \end{gather*}
            That is, the $\cent_G(x)\kz{x}$-action is trivial, and the action of $\Sm[\mul_{\underline{g}^k}(x)]$ is by permuting the corresponding elements. 
        \end{corollary}

        \begin{remark}
            Let
            \begin{equation*}
                p \colon \B(G \wr \Sm) \to \B\Sm
            \end{equation*}
            be the natural projection. Noting that $\Tm (\BG)^* V \simeq p^* \Tm V$ for $V \in \cC\dbl$, one can alternatively prove \cref{cor:character-when-no-T-action} using only \cref{lem:character-of-Tm}, via the composite
            \begin{equation*}
                \chi_{p^* \Tm V} \colon \L\B(G \wr \Sm) \xto{(\L p)^*} \L\B\Sm \xto{\chi_{\Tm V}} \ounit_{\cC}.
            \end{equation*}
            Although in this paper we consider only characters of representations of the form $\Tm(\BG)^* V$, we chose to present the computation in \cref{lem:character-of-wreath-product} as we find it conceptually satisfying.
        \end{remark}



        \begin{corollary}\label{cor:dim^k-of-alternating-depends-only-on-dim^k}
            Let $\cC$ be a symmetric monoidal $\chrHeight$-presentable, $(\chrHeight,1)$-semiadditive category. Let $V \in \cC\tdbl$, $H \to \Sm$ a homomorphism of finite groups and $\hchar \colon H \to \ounit_{\cC}\units$ a character. Assume that the $\TT$-action on $\dim^i(V)$ is trivial for every $0\le i \le t$. Then $\dim^t(\alt_{H,\hchar} V) \in (\laxloops^t \cC)^{\B\TT^t}$ depends only on $\dim^t(V) \in (\laxloops^t \cC)^{\B\TT^t}$.
        \end{corollary} 

