    \subsection{Characters induced from duals of stable stems}
    \label{subsec:categorical-alternating}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        We now specialize to the case $\cC = \Mod_{\cVectn}$ (\cref{def:cyc-closure}), which is a symmetric monoidal, $(\chrHeight+1)$-presentable, and $(\chrHeight+1,\infty)$-semiadditive category.

        We compute the iterated dimension of the alternating power of the unit:
        \begin{notation}
            Let $\Pi \field \in \sVect$ be the $(0|1)$-dimensional vector space, so that $\pi_0 (\sVect\units) = \{\field, \Pi\field\}$

            Let $f \colon A \to \sVect\units$ be an $A$-local system of invertible super vector spaces. Define
            \begin{itemize}
                \item $d_+(f)$ to be the number of connected components of $A$ on which $f$ is $\field$ with the trivial action;
                \item $d_-(f)$ to be the number of connected components of $A$ on which $f$ is $\Pi \field$ with the trivial action.
            \end{itemize}
        \end{notation}
        \begin{proposition}\label{cor:inductive-formula-Vectn}
            Let $H$ be a finite group with a homomorphism $H \to \Sm$. Let $\hchar \colon \B\Sm \to \B(\cVectn)\units$ be a character in $\Mod_{\cVectn}$. 
            Then the $(\chrHeight+1)$-fold dimension
            \begin{equation*}
                \dim^{\chrHeight+1}(\alt_{H,\hchar} \cVectn) = d_+(\tg^{\chrHeight}(\overline{\hchar})) - d_-(\tg^{\chrHeight}(\overline{\hchar})) \qin \field.
            \end{equation*}
        \end{proposition}

        \begin{proof}
            By \cref{cor:k-character-of-alternating}
            \begin{equation*}
                \begin{split}
                    \dim^{\chrHeight}(\alt_{H,\hchar} \cVectn) 
                    & \simeq \colim_{\L^{\chrHeight}\BH} \tg^{\chrHeight}(\overline{\hchar}) \\
                    & \simeq \bigoplus_{x \in \pi_0 \L^{\chrHeight}\BH} \tg^{\chrHeight}(\overline{\hchar})(x)^{h\Omega_x \L^{\chrHeight}\BH} \qin \sVect.
                \end{split}
            \end{equation*}
            For any $x\in \L^{\chrHeight} \BH$, $\tg^{\chrHeight}(\overline{\hchar})(x)$ lands in $\sVect\units$ and therefore is a one-dimensional vector space (up to $\Pi$). Its fixed-points is therefore one-dimensional if the action is trivial and trivial otherwise. The proof follows as $\dim(\Pi \field) = -1$.
        \end{proof}

        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \subsubsection*{Characters induced from duals of stable stems}

        \label{characters-from-dual-stable-stems}
        The $(\chrHeight+1)$-category $\Mod_{\cVectn}$ is $(\SS,\chrHeight)$-oriented. Recall that $(\SS,\chrHeight)$-orientation-induced characters of symmetric groups are maps of connected spaces $\B\Sm \to \B\In$. 
        \begin{equation*}
            \pi_0 \Map_*(\B\Sm, \B\In) \simeq \pi_0 \Map_{\cnSp}(\redSS[\B\Sm], \Sigma \In) \simeq \pi_0\Map_{\cnSp}(\Omega \redSS[\B\Sm], \In) \simeq \widehat{\pi}_{\chrHeight+1}(\redSS[\B\Sm]).
        \end{equation*}
        Therefore an orientation-induced characters are classified by $\widehat{\pi}_{\chrHeight+1}(\redSS[\B\Sm])$.
        The composition
        \begin{equation*}
            \redSS[\B\Sm] \to \redSS[\B\Sinfty] \simeq \redSS[\tau_{\ge 1}\SS] \xto{c} \tau_{\ge 1}\SS,
        \end{equation*}
        defines a map
        \begin{equation*}
            \widehat{\pi}_{\chrHeight+1}(\SS) = \widehat{\pi}_{\chrHeight+1}(\tau_{\ge 1}\SS) \to \widehat{\pi}_{\chrHeight+1}(\redSS[\B\Sm]).
        \end{equation*}
        That is, each functional $\pichar$ on $\pin$ defines a character of $\Sinfty$, which can be restricted to a character of $\Sm$. We denote the corresponding alternating powers by $\alt_{\pichar}$.

        These characters and their corresponding alternating powers were studied in \cite{Keidar-Ragimov-2025-twisted-graded}.
        There it was shown that for \emph{additive} $(\SS,\chrHeight)$-oriented categories in low heights, there exists a simple generating function computing the dimensions of the alternating powers (\cite[Proposition 5.2.8, Lemma 5.2.11, Lemma 5.2.12]{Keidar-Ragimov-2025-twisted-graded}), under some conditions.

        In $\Mod_{\cVectn}$ we can get similar results for the iterated dimension:
        Recall that for $\chrHeight \le 2$, $\widehat{\pi}_{\chrHeight+1}(\SS)$ is a cyclic group.
        \begin{proposition}\label{prop:generating-function}
            Let $0 \le \chrHeight \le 2$. Let $\pichar \in \widehat{\pi}_{\chrHeight+1}(\SS)$ be a generator and\footnote{Here $\Mod_{\cVectn[0] } = \catname{Vect}_{\field\cyc}$.}  $V \in (\Mod_{\cVectn})\ndbl[\chrHeight+1]$ such that the $\TT^i$-action on $\dim^i(V)$ is trivial for $1\le i \le \chrHeight+1$. Then
            \begin{equation*}
                (\sum_{\degree} \dim^{\chrHeight+1}(\Sym V) t^{\degree}) (\sum_{\degree} \dim^{\chrHeight+1}(\alt_{\pichar} V) (-t)^{\degree}) = 1.
            \end{equation*}
        \end{proposition}
        \begin{proof}
            For convenience, denote $\cC \coloneqq \Mod_{\cVectn}$, and $\ounit_{\cC} = \cVectn$.
            Consider the twisted graded category $\Gr^{\pichar}_{\ZZ} \cC$ as in \cite[Definition~2.3.25]{Keidar-Ragimov-2025-twisted-graded}. That is, it is the Thom construction along the map
            \begin{equation*}
                \ZZ \xonto{\pichar} \widehat{\pi}_{\chrHeight+1}(\SS) \to \Sigma^2 \In \to \Sigma^2 \ounit_{\cC}\units \to (\Mod_{\cC})\units.
            \end{equation*}
            In particular, it is a commutative algebra in $\Mod_{\cC}$, which as a monoidal category is isomorphic to $\FunDay(\ZZ, \cC)$, and thus admits a natural structure of an $(\chrHeight+1)$-category.

            In this category, consider the objects $V\shift{0} \oplus V\shift{1}$ i.e.\ the the graded object which is $V$ at places 0 and 1, and zero everywhere else. 
            By \cite[Lemma~5.2.5, Lemma~5.2.6]{Keidar-Ragimov-2025-twisted-graded}, the restricted action to finite subgroups of $\TT^i$ on $\dim^i(\ounit_{\cC}\shift{1})$ is trivial. Therefore so is the restricted action on
            \begin{equation*}
                \dim^i(V\shift{0} \oplus V\shift{1}) = \dim^i(V\shift{0}) + \dim^i(V\shift{0})\cdot \dim^i(\ounit_{\cC}\shift{1}) = \dim^i(V) \cdot (1 + \dim^{i}(\ounit_{\cC}\shift{1})).
            \end{equation*}

            By \cite[Lemma~5.2.3]{Keidar-Ragimov-2025-twisted-graded}
            \begin{equation*}
                \dim^{\chrHeight+1}(\ounit_{\cC}\shift{1}) = \eta^{\chrHeight+1} \cdot \pichar \qin \widehat{\pi}_{0}(\SS) = \mu_{\infty} \subseteq \field\cyc = \laxloops^{\chrHeight+1} \cC.
            \end{equation*}

            It is straightforward to verify that $\eta^{\chrHeight+1} \cdot \pichar = -1 \in \widehat{\pi}_{0}(\SS)$.
            Therefore,
            \begin{equation*}
                \dim^{\chrHeight+1}(V\shift{0} \oplus V\shift{1}) = \dim^{\chrHeight+1}(V) \cdot (1 + \dim^{\chrHeight+1}(\ounit_{\cC}\shift{1})) = 0 \qin \field\cyc.
            \end{equation*}
            By \cref{cor:dim^k-of-alternating-depends-only-on-dim^k}, \cref{rmrk:enough-cyclic-subgroups},
            \begin{equation*}
                \dim^{\chrHeight+1} \Sym(V\shift{0} \oplus V\shift{1}) = \dim^{\chrHeight+1} \Sym (0) = \begin{cases}
                    1, & \degree = 0 \\
                    0, & \degree > 0.
                \end{cases}
            \end{equation*}
            On the other hand
            \begin{equation*}
                \begin{split}
                    \Sym(V\shift{0} \oplus V\shift{1}) 
                    & = (\bigoplus_{i+j = \degree} \Ind_{\Sm[i] \times \Sm[j]}^{\Sm} V\shift{0}\om[i] \otimes V\shift{1}\om[j])_{h\Sm} \\
                    & \simeq \bigoplus_{i + j = \degree} (V\shift{0}\om[i])_{h\Sm[i]} \otimes (V\shift{1}\om[j])_{h\Sm[j]}.
                \end{split}
            \end{equation*}
            By definition,
            \begin{equation*}
                (V\shift{0}\om[i])_{h\Sm[i]} \simeq (\Sym[i] V)\shift{0}.
            \end{equation*}
            By \cite[Proposition~4.1.8, Remark~4.3.6]{Keidar-Ragimov-2025-twisted-graded}
            \begin{equation*}
                (V\shift{1}\om[j])_{h\Sm[j]} \simeq (\alt[j]_{\pichar} V)\shift{j} \simeq (\alt[j]_{\pichar} V)\shift{0} \otimes \ounit_{\cC}\shift{j}.
            \end{equation*}
            Thus,
            \begin{equation*}
                \begin{split}
                    \dim^{\chrHeight+1} \Sym(V\shift{0} \oplus V\shift{1}) 
                    & = \sum_{i+j = \degree} \dim^{\chrHeight+1} \Sym[i](V) \cdot \dim^{\chrHeight+1} \alt[j]_{\pichar} V \cdot (\dim^{\chrHeight+1} \ounit_{\cC}\shift{1})^j \\
                    & = \sum_{i+j = \degree} \dim^{\chrHeight+1} \Sym[i](V) \cdot (-1)^j\dim^{\chrHeight+1}\alt[j]_{\pichar} V,
                \end{split}
            \end{equation*}
            which is the requested formula.
        \end{proof}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Transchromatic characters as monoidal characters}
\label{subsec:chromatic-induction}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

    This section moves from the higher-categorical world to the chromatic one. Working in the category $\ModEn$, we extend the induced-character machinery using the transchromatic character of Hopkins--Kuhn--Ravenel and Stapleton. We isolate a family of functions that can be categorified, prove that their iterated characters coincide with the corresponding transchromatic characters, and derive an explicit formula for these characters. This formula, in turn, lets us compute the dimensions of twisted alternating powers.










    % In \cref{subsec:categorification-of-functions}, we study a family of functions to $\Enp$ that admit categorification in the chromatic setting, and develop character theory for them, relating it to transchromatic character theory. We use it to establish explicit formulas for dimensions and power operations, analogous to those in \cref{sec:categorical}. Finally, in \cref{subsec:minus-one}, we give an explicit computation in height~1.    

    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{Characters and categorification of functions}
    \label{subsec:categorification-of-functions}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        We begin by constructing a decategorification map from representations in $\ModEn$ to $\Enp$-valued functions, using the chromatic Nullstellensatz.
        Since the chromatic Nullstellensatz (\cite{Burklund-Schlank-Yuan-2022-Nullstellensatz}) will be used often throughout this subsection, we introduce the following terminology:

        \begin{notation}
            Let $R$ be a nonzero $\Tn$-local ring.
            We refer to maps $R \to \En(L)$ of $\Tn$-local commutative algebras, where $L$ is algebraically closed, as \emph{geometric points}.
        \end{notation}

        Recall that any object $V \in (\ModEn)\dbl$ defines a class in the $\Tnp$-localized $K$-theory spectrum
        \begin{equation*}
            \KTnp(\En) \coloneqq \LTnp \K((\ModEn)\dbl).
        \end{equation*}
        By the chromatic redshift for $\En$ \cite{Yuan-2024-redshift-En}, there exists a geometric point
        \begin{equation*}
            \phi \colon \KTnp(\En) \to \Enp(L),
        \end{equation*}
        for some algebraically closed field $L$.

        \begin{definition}\label{def:increasing-height}
             Let $A$ be a 1-finite space. We define the decategorification map as the composition
             \begin{equation*}
                 \de \colon ((\ModEn)\dblspace)^A \to \KTnp(\En)^{A} \xto{\phi^A} \Enp(L)^A.
             \end{equation*}
        \end{definition}

        \begin{remark}\label{rmrk:dim-categorifiable}
            Let $V \in (\ModEn)\dblA$. Then 
            \begin{equation*}
                \de(V) \colon A \to \Enp(L)
            \end{equation*}
            chooses $\dim(V_a) \in \ZZ \subseteq \pi_0 \Enp(L)$ at each $a \in A$ (where the dimension of $V_a$ is an integer by \cite[Proposition~10.11]{Mathew-2016-Galois}).
        \end{remark}

        \begin{definition}\label{exm:decategorifying-through-K}
            In particular, for a character $\hchar \colon \BH \to \B\En\units$ we define
            \begin{equation*}
                \de(\hchar) \coloneqq \de(\En{}[\hchar]) \in (\Enp(L)\units)^{\BH}.
            \end{equation*}
            Then $\de(\hchar) \colon \BH \to \Enp(L)\units$ is a pointed map.%, which we think of as a \quotes{decategorified character} of height $\chrHeight+1$.
        \end{definition}

        \begin{lemma}\label{lem:decategorification-of-orientation-induced-characters}
            If $\hchar$ is a $(\SS,\chrHeight)$-orientation-induced character, then $\de(\hchar)$ factors through the $(\tau_{\leq n} \SS,\chrHeight+1)$-orientation $\Sigma\In \to\Inplus \to \Enp(L)\units$.
        \end{lemma}
        \begin{proof}
            By \cite[Lemma 5.3.22]{Keidar-Ragimov-2025-twisted-graded}, the composition of the suspension of the orientation map with the decateogrification
            \begin{equation*}
                \Sigma \In \to \Sigma \En\units \to (\ModEn)\units \xto{\de} \Enp(L)\units
            \end{equation*}
            is a $(\tau_{\le \chrHeight} \SS, \chrHeight+1)$-orientation of $\Enp(L)$. That is, it is a connected cover of an orientation
            \begin{equation*}
                \Inplus \to \Enp(L)\units.
            \end{equation*}
            The claim now follows.
        \end{proof}

        The decategorification behaves well with respect to ($p$-typicla) semiadditive integrals.

        \begin{lemma}\label{lem:integral-of-decategorification-of-En}
            Let $A$ be a 1-finite space and $V \in (\ModEn)\dblA$. Then both semiadditive integrals
            \begin{equation*}
                \int^{\Enp(L)}_A \de(V) \in \pi_0 \Enp(L) \qand \int^{\En}_{\Lp A}\chi_V \in \pi_0 \En
            \end{equation*}
            land in $\ZZ_{(p)}$ and are equal.
        \end{lemma}
        \begin{proof}
            As $\Lp$ respects disjoint unions, we can assume $A = \BG$. Let $P \subseteq G$ be a $P$-subgroup so that $\Lp\BP = \L\BP$. By \cite[Lemma~5.3.10]{Keidar-Ragimov-2025-twisted-graded}
            \begin{equation*}
                \int^{\Enp(L)}_{\BP} \de(V) = \int^{\En}_{\Lp\BP} \chi_V \qin \ZZ.
            \end{equation*}
            The result now follows from \cref{cor:integral-of-BG-is-linear-combination-along-p-subgroups} and \cref{cor:integral-of-LBG-is-linear-combination-along-p-subgroups}.
        \end{proof}        

        By \cref{lem:integral-of-decategorification-of-En}, maps $f \colon A \to \Enp$ that admit a categorification, i.e.\ have a preimage $V_f \in (\ModEn)\dblA$ under the decategorification map, admit a character $\widetilde{\chi}_f \coloneqq \chi_{V_f} \in \En^{\L A}$ (which may depend on the choice of the preimage), satisfying
        \begin{equation*}
            \int^{\Enp}_A f = \int^{\En}_{\Lp A} \widetilde{\chi}_f.
        \end{equation*}
        Assuming $\widetilde{\chi}_f$ is also categorifiable, this process can be iterated.

        We define a family of categorifiable functions $A \to \Enp$ that includes the characters of permutation representations and is closed under the operation $\widetilde{\chi}$. In particular, this allows us to define iterated characters of permutation representations via categorification.

        \begin{definition}\ 
            \begin{enumerate}
                \item A function $f \colon \B(G \wr \Sm) \to \Enp$ is \emph{a permutation function of height $\chrHeight+1$} if there exists a $d \in \ZZ$ such that $f = \pm \Tm (\BG)^* d$. That is, 
                \begin{equation*}
                    f = \pm d^{\degree} \in \Enp^{\B(G \wr \Sm)}
                \end{equation*}
                where $\Sm$ acts on the coordinates and $G^{\degree}$ acts trivially. 
                \item A function 
                \begin{equation*}
                    f = \bigsqcup_i \bigsqcap_j f_{i,j} \colon  \bigsqcup_i \bigsqcap_j \B(G_{i,j} \wr \Sm[\degree_{i,j}]) \to \Enp
                \end{equation*}
                is a permutation function of height $\chrHeight+1$ if each $f_{i,j}$ is.
                \item Let $A$ be a 1-finite space. A function $f \colon A \to \Enp$ is called a \emph{twisted permutation function} of height $\chrHeight+1$ if it is of the form $f = f' \cdot \hchar$, where $f' \colon A \to \Enp$ is a permutation function, and
                \begin{equation*}
                    \hchar \colon A \to \B \In
                \end{equation*}
                is a map of spaces, regarded as a map to $\Enp$ via the orientation map $\Sigma \In \to \Enp\units$.
            \end{enumerate}
        \end{definition}

        We now note that all twisted permutation functions admit a preimage under $\de$:
        \begin{construction}\ 
            \begin{enumerate}
                \item\label{item:1} Let $f \colon \B(G \wr \Sm) \to \Enp$ be of the form $f = d^{\degree}$ for $d \in \ZZ$. Define 
                \begin{equation*}
                    V_f \coloneqq \begin{cases}
                        \Tm(\BG)^* \En^{\oplus d}, & d \ge 0 \\
                        \Tm(\BG)^* \Sigma \En^{\oplus (-d)}, & d < 0
                    \end{cases}
                    \qin (\ModEn)\dblA[\B(G\wr \Sm)].
                \end{equation*}
                \item\label{item:2} Let $f \colon \B(G\wr \Sm) \to \Enp$ be of the form $f = -f'$, where $f'$ is as above. Then define
                \begin{equation*}
                    V_f \coloneqq \Sigma V_{f'} \qin (\ModEn)\dblA[\B(G \wr \Sm)].
                \end{equation*}
                \item\label{item:5} Let 
                \begin{equation*}
                    f = \bigsqcup_i \bigsqcap_j f_{i,j} \colon \bigsqcup_i \bigsqcap_j \B(G_{i,j} \wr \Sm[\degree_{i,j}]) \to \Enp
                \end{equation*}
                be a permutation function. Define
                \begin{equation*}
                    V_f \coloneqq \bigoplus_i \bigotimes_j V_{f_{i,j}}.
                \end{equation*}
                \item\label{item:3} Let $\hchar \colon A \to \B\In$ be a map of spaces. In particular 
                \begin{equation*}
                    A \xto{\hchar} \B\In \to \B\En\units \to (\ModEn)\units
                \end{equation*}
                is a local system choosing $\En$ at each connected component. Denote this local system by $\En{}[\hchar] \in (\ModEn)\dblA$.
                \item\label{item:4} Let $f \colon A \to \Enp$ be a twisted permutation function. Then $f$ is of the form $f' \cdot \hchar$ where $f'$ is a permutation function and $\hchar \colon A \to \B\In$. Define
                \begin{equation*}
                    V_f \coloneqq V_{f'} \otimes \En{}[\hchar] \qin (\ModEn)\dblA.
                \end{equation*}

            \end{enumerate}            
        \end{construction}

        \begin{lemma}
            Let $f \colon A \to \Enp$ be a twisted permutation function. Then, after composition with the map $\Enp^A \to \Enp(L)^A$, $f$ is identified with $\de(V_f)$.
        \end{lemma}
        \begin{proof}
            It is enough to verify the claim for (\labelcref{item:1}), (\labelcref{item:2}) and (\labelcref{item:3}). (\labelcref{item:1}) and (\labelcref{item:2}) are clear. (\labelcref{item:3}) follows from \cref{lem:decategorification-of-orientation-induced-characters}.
        \end{proof}

        In particular, any twisted permutation function $f$ of height $\chrHeight+1$ admits a character $\widetilde{\chi}_f = \chi_{V_f}$. 

        \begin{lemma}
            Let $f$ be a twisted permutation function of height $\chrHeight+1$. Then $\widetilde{\chi}_f$ is a twisted permutation function of height $\chrHeight$.
        \end{lemma}
        \begin{proof}
            Let $f \colon A \to \Enp$ be a twisted permutation function. Therefore $f = f' \cdot \hchar$ where $f'$ is a permutation function and $\hchar \colon A \to \Sigma \In$. Thus $V_f = V_{f'} \otimes \En{}[\hchar]$, and therefore 
            \begin{equation*}
                \widetilde{\chi}_f = \chi_{V_{f'}} \cdot \chi_{\En{}[\hchar]}.
            \end{equation*}
            Since the $\TT$-action on $\dim(V_{f'})$ is trivial (see e.g.\ \cite[Corollary~3.2.5]{Keidar-Ragimov-2025-twisted-graded}), by \cref{cor:character-when-no-T-action}, 
            \begin{equation*}
                \chi_{V_{f'}} \colon \L A \to \En
            \end{equation*}
            is a permutation function of height $\chrHeight$. 
            By \cref{prop:transgersion-is-charcter-of-character} $\chi_{\En{}[\hchar]} = \tg(\hchar)$. The transgression $\tg(\hchar)$ is the composition
            \begin{equation*}
                \tg(\hchar) \colon \L A \xto{\L\hchar} \L\Sigma \In \simeq \Sigma \In \oplus \In \xto{\eta + 1} \In \to \En\units.
            \end{equation*}
            For each $a \in \pi_0 \L A$, the value of $\tg(\hchar)(a) \in \pi_0\En\units$ lies in the image of $\pi_0\In \to \pi_0\En\units$ and in particular is a $p$-power torsion. As
            \begin{equation*}
                \pi_0\En\units[p^{\infty}] = \Witt(\Fpbar)[\![u_1,\dots,u_{\chrHeight-1}]\!]\units[p^{\infty}] = \begin{cases}
                    \{1\}, & p \neq 2 \\
                    \{\pm 1\}, & p = 2
                \end{cases},
            \end{equation*}
            each connected component lands in $\{\pm 1\} \subseteq \En\units$. In particular, on each connected component, we may assume the transgression is of the form $\pm 1 \cdot \hchar'$, where $\hchar' \colon \B\Omega_a A \to \In$ is pointed, therefore factors through the connected cover map $\hchar' \colon \B\Omega_a A \to \B\In[\chrHeight-1]$. Thus $\tg(\hchar)$ is a twisted permutation function.
        \end{proof}

        \begin{definition}
            Let $f \colon A \to \Enp$ be a twisted permutation function. Define inductively for $0 \le t \le \chrHeight+1$ a twisted permutation function $\widetilde{\chi}^t_f \colon \L^t A \to \En[\chrHeight+1-t]$ as follows:
            \begin{align*}
                & \widetilde{\chi}^0_f \coloneqq f \colon A \to \Enp, \\
                & \widetilde{\chi}^t_f \coloneqq \widetilde{\chi}_{\tilde{\chi}^{t-1}_f} \colon \L^t A \to \En[\chrHeight+1-t].
            \end{align*}
        \end{definition}

        % \begin{corollary}\label{cor:iterated-characters-multiplicative}
        %     Let $f, g \colon A \to \Enp$ be twisted permutation functions. Then for any $0 \le t \le \chrHeight+1$
        %     \begin{equation*}
        %         % \widetilde{\chi}^t_{f + g} = \widetilde{\chi}^t_f + \widetilde{\chi}^t_g, \qquad
        %         % \widetilde{\chi}^t_{-f} = -\widetilde{\chi}^t_f, \qquad
        %         \widetilde{\chi}^t_{f\cdot g} = \widetilde{\chi}^t_f \cdot \widetilde{\chi}^t_g.
        %     \end{equation*}
        % \end{corollary}

        \begin{corollary}\label{cor:iterated-characters-integrals}
            Let $f \colon A \to \Enp$ be a twisted permutation function. Then for any map of $1$-finite spaces $B \to A$, and $0 \le t \le \chrHeight+1$
            \begin{equation*}
                \int^{\Enp}_B f = \int^{\En[\chrHeight+1-t]}_{\L_p^t B} \widetilde{\chi}^t_f.
            \end{equation*}
        \end{corollary}
        \begin{proof}
            This follows by induction from \cref{lem:integral-of-decategorification-of-En}.
        \end{proof}

        \begin{corollary}\label{cor:iterated-characters-transgression}
            Let $\hchar \colon A \to \Sigma \In \to \Enp\units$ be a map of spaces. Then $\widetilde{\chi}^t_{\hchar} = \tg^t(\hchar)$, i.e.\ it is the composition
            \begin{equation*}
                 \widetilde{\chi}^t_{\hchar} \colon \L^t A \xto{\tg^t \hchar} \In[\chrHeight+1-t] \to \En[\chrHeight+1-t]\units.
            \end{equation*}
        \end{corollary}


    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{Transchromatic character theory for twisted permutation functions}
    \label{subsec:HKR-and-characters}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

        The transchromatic character theory, developed by Hopkins--Kuhn--Ravenel, Stapleton and Lurie (\cite{Hopkins-Kuhn-Ravenel-2000-HKR,Stapleton-2013-HKR,Lurie-2019-Elliptic3}) provides for any $\pi$-finite space $A$ a character map 
        \begin{equation*}
            \chi^{t, \HKR}_{(-)} \colon \Enp(L)^A \to C^{\chrHeight+1}_{\chrHeight+1-t}(L)^{\Lp^{t} A},
        \end{equation*}
        where $\LKn[\chrHeight+1-t] \Enp(L) \to C^{\chrHeight+1}_{\chrHeight+1-t}(L)$ is the $\Kn[\chrHeight+1-t]$-local splitting algebra at height $\chrHeight+1-t$. By the chromatic Nullstellensatz, there exists a geometric point
        \begin{equation*}
            C^{\chrHeight+1}_{\chrHeight+1-t}(L) \to \En[\chrHeight+1-t](K_t).
        \end{equation*}
        We also denote the composition
        \begin{equation*}
            \Enp(L)^A \xrightarrow{\chi^{t, \HKR}_{(-)}} C^{\chrHeight+1}_{\chrHeight+1-t}(L)^{\Lp^{t} A} \to \En[\chrHeight+1-t](K_t)^{\Lp^{t} A}
        \end{equation*}
        again by $\chi^{t, \HKR}_{(-)}$.
        For $t = 1$ we write $\chi^{\HKR} = \chi^{1, \HKR}$.

        When $f$ admits a preimage $V_f$ under $\de$, we have defined
        \begin{equation*}
            \widetilde{\chi}_f \coloneqq \chi_{V_f} \in \En^{\L A}.
        \end{equation*}
        On the other hand, the transchromatic character provides a map
        \begin{equation*}
            \chi^{\HKR}_f \in \En(K_1)^{\Lp A}.
        \end{equation*}
        We expect that, after composing with a map $\En \to \En(K_1)$ and restricting along $\Lp A \to \L A$, the two notions agree. Although we do not prove this in full generality, we verify that it holds in the cases relevant to our applications.


