        % \end{proof}

        \begin{lemma}[{\cite[Lemma~5.3.20]{Keidar-Ragimov-2025-twisted-graded}}]\label{lem:HKR-vs-twice-HKR}
             Let $A$ be a $\pi$-finite space and $0 \le t \le s \le \chrHeight+1$. Then for any geometric point $C^{\chrHeight+1}_{\chrHeight+1-t} \to \Enp[\chrHeight+1-t](K_t)$ there exists a map of $\Kn[\chrHeight+1-s]$-local commutative algebras $C^{\chrHeight+1}_{\chrHeight+1-s} \to C^{\chrHeight+1-t}_{\chrHeight+1-s}(K_t)$ rendering the following diagram commutative
             \begin{equation*}
                \begin{tikzcd}
                    {\Enp^{A}} & {(C^{\chrHeight+1}_{\chrHeight+1-t})^{\Lp^{t}A}} & {\En[\chrHeight+1-t](K_t)^{\Lp^{t}A}} \\ \\
                    {(C^{\chrHeight+1}_{\chrHeight+1-s})^{\Lp^s A}} && {C^{\chrHeight+1-t}_{\chrHeight+1-s}(K_t)^{\Lp^{s}A}.}
                    \arrow["{\chi^{t,\HKR}}", from=1-1, to=1-2]
                    \arrow["{\chi^{s,\HKR}}", from=1-1, to=3-1]
                    \arrow[from=1-2, to=1-3]
                    \arrow["{\chi^{s-t,\HKR}}", from=1-3, to=3-3]
                    \arrow[from=3-1, to=3-3]
