        \begin{theorem}\label{thm:chi-tilde-t-is-HKR}
            Let $f \colon A \to \Enp$ be a twisted permutation function. Then for $0 \le t \le \chrHeight+1$, after composition with a geometric point 
            \begin{equation*}
                \En[\chrHeight+1-t] \to \En[\chrHeight+1-t](K_t) \to \En[\chrHeight+1-t](K'_t)
            \end{equation*}
            for some algebraically-closed field $K'_t$,
            \begin{equation*}
                \res{\widetilde{\chi}^{t}_f}{\Lp^{t} A} \simeq \chi^{t,\HKR}_f \qin \En[\chrHeight+1-t](K'_t)^{\Lp^{t} A}.
            \end{equation*}
        \end{theorem}
        \begin{proof}
            We prove this by induction on $t$. For $t = 0$ it is trivial. Assume 
            \begin{equation*}
                \res{\widetilde{\chi}^{t}_f}{\Lp^{t-1} \B A} \simeq \chi^{t,\HKR}_f \qin \En[\chrHeight+1-t](K'_{t})^{\Lp^{t} \B A}.
            \end{equation*}
            By \cref{lem:chi-tilde-1-is-HKR}, \cref{lem:decomposition-of-wreath}, there exists a geometric point $C^{\chrHeight+1-t}_{\chrHeight-t}(K'_{t}) \to \En[\chrHeight-t](K''_{t+1})$ such that
            \begin{equation*}
                \res{\widetilde{\chi}^{t+1}_f}{\Lp^{t} \B A} \simeq \chi^{\HKR}_{\chi^{t,\HKR}_f} \qin \En[\chrHeight-t](K''_{t+1})^{\Lp^{t+1} \B A}.
            \end{equation*}
            By \cref{lem:HKR-vs-twice-HKR}
            \begin{equation*}
                \chi^{\HKR}_{\chi^{t,\HKR}_f} \simeq \chi^{t+1, \HKR}_f.
            \end{equation*}
            By \cite[Lemma 7.14, Theorem 7.2(2)]{Burklund-Schlank-Yuan-2022-Nullstellensatz} there exists an algebraically-closed field $K'_{t+1}$ and geometric points $\En[\chrHeight-t](K''_{t+1}) \to \En[\chrHeight-t](K'_{t+1})$ and $\En[\chrHeight-t](K_{t+1}) \to \En[\chrHeight-t](K'_{t+1})$, proving the claim.
        \end{proof}


        \begin{remark}\label{rmrk:dim-alt-iterative}
            \cref{thm:chi-tilde-t-is-HKR} gives an alternative proof of the shifted semiadditivity of the transchromatic character (\cite[Remark 7.4.8, Remark~7.4.9]{Lurie-2019-Elliptic3}, \cite{Ben-Moshe-2024-shifted-semiadditive}) for twisted permutation functions, using the usual shifted semiadditivity of the monoidal dimension (\cref{cor:iterated-characters-integrals}).

            In particular, for $V\in (\ModEn)\dbl$, a character $\hchar \colon \B\Sm \to \B\En\units$ induced by spherical orientation and $0 \le t \le \chrHeight$
            \begin{equation*}
                \dim(\alt_{\hchar} V) =  \int^{C^{\chrHeight}_{\chrHeight+1-t}}_{\Lp^{t-1} \L\B\Sm}\chi^{t,\HKR}_{\chi_{\Tm V}} \cdot \tg^{t+1}(\overline{\hchar}) \qin \ZZ.
            \end{equation*}
        \end{remark}

        \begin{remark}
            \cref{thm:chi-tilde-t-is-HKR} along with the proof of \cref{lem:chi-tilde-1-is-HKR}, provide an algorithm for computing the dimension of $\alt_{\hchar} V$ for $V \in (\ModEn)\dbl$. First,
            \begin{equation*}
                \dim(\alt_{\hchar} V) = \int^{\En[0]}_{\Lp^{\chrHeight} \L \B\Sm} \widetilde{\chi}^{\chrHeight+1}_{d^{\degree}} \cdot \tg^{\chrHeight+1}(\overline{\hchar}).
            \end{equation*}
            This semiadditive integral is taken in a rational ring, therefore it is computed as
            \begin{equation*}
                \dim(\alt_{\hchar} V) = \sum_{x \in \pi_0 \Lp^{\chrHeight} \L \B\Sm} \frac{1}{|\Omega_x \Lp^{\chrHeight} \L \B\Sm|} \widetilde{\chi}^{\chrHeight+1}_{d^{\degree}} (x) \cdot \tg^{\chrHeight+1}(\overline{\hchar})(x).
            \end{equation*}
            The character $\widetilde{\chi}^{\chrHeight+1}_{d^{\degree}} $ can be computed using the character of the total power operation \cite{Barthel-Stapleton-2017-power-operations} which has a closed formula. More concretely, if we consider an element $x \in \pi_0(\Lp^{\chrHeight} \L\B\Sm)$ as a $\Zp^\chrHeight \times \ZZ$-set of size $\degree$. Then, $\chi^{\chrHeight+1}_{d^{\degree}}(x)$ is equal to $d$ raised to the number of orbits of this $\Zp^{\chrHeight} \times \ZZ$-set.

            We do not know of a general closed formula for computing the transgression. However, such a formula exists when $\hchar$ is induced by a $(\ZZ,\chrHeight)$-orientation, that is,
            \begin{equation*}
                \hchar \colon \B\Sm \to \B^{\chrHeight+1}\QQ/\ZZ
            \end{equation*}
            and therefore corresponds to a cohomology class $\hchar \in \H^{\chrHeight+1}(\Sm; \QQ/\ZZ)$.
            If $\hchar$ is represented by a cocycle
            \begin{equation*}
                \hchar:\Sm^{\chrHeight+1}\to \QQ/\ZZ
            \end{equation*}
            then, by \cite[Theorem~3]{Willerton-2008-transgression} its transgression on $(g_1,\cdots,g_{\chrHeight}) \in \Csigma^\chrHeight$ is given by the alternating sum:
            \begin{equation*}
                \tg(\hchar)(g_1,\dots,g_{\chrHeight})= \hchar(\sigma,g_1,g_2,\dots,g_{\chrHeight})-\hchar(g_1,\sigma,g_2,\dots,g_\chrHeight)+\dots+(-1)^{\chrHeight+1} \hchar(g_1,\dots,g_{\chrHeight} ,\sigma)
            \end{equation*}
            This formula can be iterated in order to compute $\tg^{\chrHeight+1}(\hchar)(x)$.
        \end{remark}


        \begin{corollary}\label{cor:power-op-iterative}
            Let $\hchar \colon \B\Sm \to \Sigma \In$ be a map of pointed spaces. Let $H \to \Sm$ be a homomorphism of finite groups and $d \in \ZZ \subseteq \pi_0 \En$. Then for $1\le t \le \chrHeight+1$:
            \begin{equation*}
                \beta^{\degree}_{H, \hchar}(d) = \begin{cases}
                    \int\limits^{C^{\chrHeight}_{\chrHeight+1-t}}_{\Lp^t \BH} \chi^{t-1,\HKR}_{\chi_{\Tm \En^{\oplus d}}} \cdot \tg^t(\overline{\hchar}), & d \ge 0 \\
                     & \\
                    \int\limits^{C^{\chrHeight}_{\chrHeight+1-t}}_{\Lp^t \BH} \chi^{t-1,\HKR}_{\chi_{\Tm \Sigma \En^{\oplus (-d)}}} \cdot \tg^t(\overline{\hchar}), & d < 0
                \end{cases}
            \end{equation*}
        \end{corollary}

        \begin{proof}
            Define the twisted permutation function
            \begin{equation*}
                f_d \coloneqq d^{\degree} \cdot \overline{\hchar} \colon \B\Sm \to \Enp.
            \end{equation*}
            Recall that
            \begin{equation*}
                \beta^{\degree}_{H,\hchar}(d) = \int^{\Enp}_{\BH} f_d.
            \end{equation*}
            The result now follows by unraveling the categorification 
            \begin{equation*}
                V_{f_d} = \begin{cases}
                    \En^{\oplus d} \otimes \En{}[\hchar], & d \ge 0 \\
                    \Sigma \En^{\oplus (-d)} \otimes \En{}[\hchar], & d < 0.
                \end{cases}
            \end{equation*}
        \end{proof}

        \begin{remark}
            In particular, if $P \subseteq \Sm$ is a $p$-subgroup and $\hchar \colon \B\Sm \to \Sigma \In$ is a pointed map of spaces, then for $d \in \ZZ$
            \begin{equation*}
                \beta^{\degree}_{P, \hchar}(d) = \begin{cases}
                    \dim(\alt_{P,\hchar} \En^{\oplus d}), & d \ge 0, \\
                    \dim(\alt_{P,\hchar} \Sigma \En^{\oplus (-d)}), & d < 0,
                \end{cases}
            \end{equation*}
            and the iterative formulas of \cref{cor:power-op-iterative} and \cref{rmrk:dim-alt-iterative} agree.
        \end{remark}

