\section{Computations in height 1}
\label{sec:computations}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

    In this section, we give a concrete computation in height~1, computing the dimensions of alternating powers in $\ModEn[1]$ and $\Mod_{\sVect}$ corresponding to characters induced from the $(\Fq{2},1)$-orientation.

    Recall that a primitive height 1 minus one, or equivalently an $(\Fq{2},1)$-orientation, is a non-degenerate map of connective spectra
    \begin{equation*}
        (-1)^{(1)} \colon \Sigma \ZZ/2 \simeq \ndual[1]{\Fq{2}} \to \ounit_{\cC}\units.
    \end{equation*}
    An $(\Fq{2},1)$-orientation-induced character of $\Sm$ is a map
    \begin{equation*}
        \hchar \colon \B\Sm \to \Sigma^2 \ZZ/2,
    \end{equation*}
    or equivalently a cohomology class $\hchar \in \H^2(\Sm; \ZZ/2)$.

    Given a height 1 minus one and a cohomology class $\hchar \in \H^2(\Sm; \ZZ/2)$ we have constructed the corresponding alternating power functor $\alt_{\hchar}$.
    Recall the following result of Schur:
    \begin{theorem}[\cite{Schur-1911-alternating-groups}]
        \begin{equation*}
            \H^2(\Sm; \QQ/\ZZ) = \begin{cases}
                0, & m \le 3 \\
                \ZZ/2, & m \ge 4
            \end{cases}, \qquad
            \H^2(\Sm; \ZZ/2) = \begin{cases}
                \ZZ/2, & m \le 3 \\
                (\ZZ/2)^2, & m \ge 4
            \end{cases},
        \end{equation*}
        and the map $\H^2(\Sm; \ZZ/2)\to \H^2(\Sm; \QQ/\ZZ)$ is surjective.
    \end{theorem}

    \begin{definition}\label{def:sgn^(1)}
        Let $\degree \ge 4$. Let $\sgn^{(1)} \colon \B\Sm \to \B^2\QQ/\ZZ$ be the unique non-trivial map.
        By Schur's theorem, we know it factors (non-uniquely) through a map, which we also denote
        \begin{equation*}
            \sgn^{(1)} \colon \B\Sm \to \B^2 \ZZ/2.
        \end{equation*}
    \end{definition}

    \begin{remark}
        As we are interested in the character $\B\Sm \to \B^2\Ct \to \En[1]\units$, which factors through $\B^2\QQ/\ZZ$, the choice of the decomposition through $\B^2\ZZ/2$ does not matter.
    \end{remark}

    % \begin{definition}
    %     :et $\cC$ be $(\Fq{2},1)$-oriented category. For a choice of $\sgn^{(1)} \colon \B\Sm \to \B^2 \ZZ/2$ we denote the corresponding alternating power functor by
    %     \begin{equation*}
    %         \alt_{(1)} \coloneqq \alt_{\sgn^{(1)}} \colon \cC \to \cC.
    %     \end{equation*}
    % \end{definition}

    Our goal is to calculate $\dim(\alt_{\sgn^{(1)}} V)$ for $V$ dualizable in the chromatic case. Note that as $\sgn^{(1)}$ factors through $\Sigma^2\ZZ/2$, we have $\overline{\sgn^{(1)}} \simeq \sgn^{(1)}$, and therefore
    \begin{equation*}
        \alt_{\sgn^{(1)}}V = (V\om \otimes \En[1][\sgn^{(1)}])^{h\Sm}.
    \end{equation*}


    In height 1, the algebra $\En[1][\B\ZZ/2]$ plays a role analogues to that of the regular representation: Recall (\cite[Proposition 4.5]{CSY-cyclotomic}) that there exists a $\B\ZZ/2$-equivariant idempotent $\varepsilon \in \En[1][\B \ZZ/2]$ such that $\En[1][\varepsilon^{-1}] \simeq \En[1]$. The complement is called a height 1 cyclotomic extension of $\En$ and is denoted
    \begin{equation*}
        \En[1][(-1)^{(1)}] \coloneqq \En[1][(1-\varepsilon)^{-1}].
    \end{equation*}
    By \cite[Proposition 5.2]{CSY-cyclotomic}, $\En[1][([(-1)^{(1)}]$ is an $e = (\ZZ/2)\units$-Galois extension of $\En[1]$. That is, $\En[1][(-1)^{(1)}] \simeq \En[1]$ as commutative algebras, but admits a non-trivial $\B\ZZ/2$-action. Restricting along $\sgn^{(1)} \colon \B\Sm \to \B^2 \ZZ/2$, we get a $\Sm$-equivariant decomposition
    \begin{equation*}
        \En[1][\B \ZZ/2] \simeq \En[1][\triv] \oplus \En[1][\sgn^{(1)}].
    \end{equation*}
    Therefore, in order to compute $\alt_{\sgn^{(1)}} V$ for $V\in \ModEn[1]$, we can replace $\En[1][\sgn^{(1)}]$ by $\En[1][\B \ZZ/2]$:
    \begin{equation*}
        (V\om \otimes \En[1][\B \ZZ/2])^{h\Sm} \simeq \Sym V \oplus \alt_{\sgn^{(1)}} V.
    \end{equation*}
    When $V = \En[1][X]$ is a free module,
    \begin{equation*}
        (V\om \otimes \En[1][\B \ZZ/2])^{h\Sm} \simeq (\En[1][X^\degree \times \B\ZZ/2])_{h\Sm} \simeq \En[1][(X^{\degree} \times \B\ZZ/2)_{h\Sm}].
    \end{equation*}
    As $\En[1][-] \colon \Span(\spcpi) \to \ModEn[1]$ is symmetric monoidal, when $X$ is $\pi$-finite, $\En[1][X]$ is dualizable and we can compute the dimension of the above module as the dimension of $(X^{\degree} \times \B\ZZ/2)_{h\Sm}$ in $\Span(\spcpi)$.

    \begin{definition}
        Let $\Sm^+$ be the $\ZZ/2$-central extension of $\Sm$ corresponding to $\sgn^{(1)}$, i.e.\footnote{Note again that the group $\Sm^+$ depends on the choice of factorization $\B\Sm \to \B^2\ZZ/2$. However, the computations are the same for both choices.}
        \begin{equation*}
            \B\Sm^+ = \fib(\B\Sm \xto{\sgn^{(1)}} \B^2 \ZZ/2).
        \end{equation*}
    \end{definition}

