    \begin{lemma}\label{lem:Sm+-orbits}
        Let $X$ be a space with $\Sm$-action. Then, restricting along $\Sm^+ \onto \Sm$,
        \begin{equation*}
            X_{h\Sm^+} \simeq (X \times \B\ZZ/2)_{h\Sm}.
        \end{equation*}
    \end{lemma}

    \begin{proof}
        Equipping $\B\ZZ/2$ with the transitive $\B\ZZ/2$-action, the space $X \times \B\ZZ/2$ admits a $(\Sm \times \B\ZZ/2)$-action and
        \begin{equation*}
            (X \times \B\ZZ/2)_{h(\Sm \times \B\ZZ/2)} \simeq X_{h\Sm}.
        \end{equation*}
        Moreover, the natural map
        \begin{equation*}
            X_{h\Sm} \to \B\Sm \times \B^2\ZZ/2,
        \end{equation*}
        induced as the orbits of $X \times \B\ZZ/ 2 \to \pt$, is trivial on the second coordinate.

        By unstraightening, we get a pullback square
        \begin{equation*}
            \begin{tikzcd}
                {(X \times \B \ZZ/2)_{h\Sm}} & {X_{h\Sm}} \\
                {\B\Sm} & {\B\Sm \times \B^2 \ZZ/2.}
                \arrow[from=1-2, to=2-2]
                \arrow[from=1-1, to=1-2]
                \arrow[from=1-1, to=2-1]
                \arrow["{(\id,\sgn^{(1)})}", from=2-1, to=2-2]
                \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-1, to=2-2]
            \end{tikzcd}
        \end{equation*}
        The map $(\id, \sgn^{(1)}) \colon \B\Sm \to \B\Sm \times \B^2 \ZZ/2$ factors through the diagonal $\Delta \colon \B\Sm \to \B\Sm \times \B\Sm$. Together with the product of pullbacks
        \begin{equation*}
            \begin{tikzcd}
                {X_{h\Sm}} & {X_{h\Sm}} \\
                {\B\Sm} & {\B\Sm}
                \arrow[from=1-2, to=2-2]
                \arrow["{\id}", from=1-1, to=1-2]
                \arrow[from=1-1, to=2-1]
                \arrow["{\id}", from=2-1, to=2-2]
                \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-1, to=2-2]
            \end{tikzcd}
            \qand
            \begin{tikzcd}
                {\B\Sm^+} & {\pt} \\
                {\B\Sm} & {\B^2 \ZZ/2,}
                \arrow[from=1-2, to=2-2]
                \arrow[from=1-1, to=1-2]
                \arrow[from=1-1, to=2-1]
                \arrow["{\sgn^{(1)}}"', from=2-1, to=2-2]
                \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-1, to=2-2]
            \end{tikzcd}
        \end{equation*}
        we get the pullback diagram
        \begin{equation*}
            \begin{tikzcd}
                {(X \times \B\ZZ/2)_{h\Sm}} & {X_{h\Sm} \times \B\Sm^+} & {X_{h\Sm}} \\
                {\B\Sm} & {\B\Sm \times \B\Sm} & {\B\Sm \times \B^2 \ZZ/2.}
                \arrow[from=1-1, to=1-2]
                \arrow[from=1-1, to=2-1]
                \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-1, to=2-2]
                \arrow[from=1-2, to=1-3]
                \arrow[from=1-2, to=2-2]
                \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-2, to=2-3]
                \arrow[from=1-3, to=2-3]
                \arrow["\Delta", from=2-1, to=2-2]
                \arrow["{\id \times \sgn^{(1)}}", from=2-2, to=2-3]
            \end{tikzcd}
        \end{equation*}
        The left hand side pullback square, is a pullback of a product of maps along the diagonal, and therefore is equivalent to the pullback square
        \begin{equation*}
            \begin{tikzcd}
                {(X \times \B\ZZ/2)_{h\Sm}} & {X_{h\Sm}} \\
                {\B\Sm^+} & {\B\Sm,}
                \arrow[from=1-2, to=2-2]
                \arrow[from=1-1, to=1-2]
                \arrow[from=1-1, to=2-1]
                \arrow[from=2-1, to=2-2]
                \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-1, to=2-2]
            \end{tikzcd}
        \end{equation*}
        and by unstraightening, $X_{h\Sm^+} \simeq (X \times \B\ZZ/2)_{h\Sm}$.
    \end{proof}

    \begin{remark}
        In particular, for $X = \pt$, we get the well-known formula for group extensions
        \begin{equation*}
            (\B\ZZ/2)_{h\Sm} \simeq \B\Sm^+.
        \end{equation*}
    \end{remark}

    \begin{lemma}\label{lem:E1-of-smash-of-wedge-of-circles}
        Let $d \ge 0$ and $X=(\bigvee_d S^1)^{\wedge m}$. Then
        \begin{align*}
            & \En[1][X_{h\Sm}] \simeq \Sym \En[1] \oplus \Sym(\Sigma \En[1]^{\oplus d}), \\
            & \En[1][X_{h\Sm^+}] \simeq \Sym \En[1] \oplus \alt_{\sgn^{(1)}} \En[1] \oplus \Sym(\Sigma \En[1]^{\oplus d})\oplus \alt_{\sgn^{(1)}}(\Sigma \En[1]^{\oplus d}).
        \end{align*}
    \end{lemma}

    \begin{proof}
        By \cref{lem:Sm+-orbits}
        \begin{equation*}
            \En[1][X_{h\Sm^+}] \simeq \En[1][(X \times \B\ZZ/2)_{h\Sm}] \simeq \En[1][X \times \B\ZZ/2]_{h\Sm}.
        \end{equation*}
        As before, this splits as
        \begin{equation*}
            \En[1][X_{h\Sm^+}] \simeq (\En[1][X] \otimes (\En[1] \oplus \En[1][\sgn^{(1)}]))_{h\Sm} \simeq (\En[1][X])_{h\Sm} \oplus (\En[1][X] \otimes \En[1][\sgn^{(1)}])_{h\Sm}.
        \end{equation*}
        Write $\redEn[1][-]$ for the reduced homology functor, that is
        \begin{equation*}
            \redEn[1][X]  = \cofib(\En[1][X] \to \En[1]).
        \end{equation*}
        The base point of $X$ is an equivariant section so that $\En[1][X] \simeq \redEn[1][X] \oplus \En[1]$ in $\Sp^{\B\Sm}$.
        The reduced homology functor is symmetric monoidal with respect to the smash product, therefore
        \begin{equation*}
            \En[1][X] \simeq \redEn[1][X] \oplus \En[1] \simeq \redEn[1][\bigvee_d S^1]\om \oplus \En[1] \simeq (\Sigma \En[1]^{\oplus d})\om \oplus \En[1].
        \end{equation*}
        Thus
        \begin{equation*}
            \En[1][X_{h\Sm}] \simeq \En[1][X]_{h\Sm} \simeq (\Sigma \En[1]^{\oplus d})\om_{h\Sm} \oplus (\En[1])_{h\Sm} = \Sym(\Sigma \En[1]^{\oplus d}) \oplus \Sym \En[1],
        \end{equation*}
        and
        \begin{equation*}
            \begin{split}
                ((\En[1][X] \otimes \En[1][\sgn^{(1)}])_{h\Sm}  
                & = ((\Sigma \En[1]^{\oplus d})\om \otimes \En[1][\sgn^{(1)}])_{h\Sm} \oplus (\En[1][\sgn^{(1)}])_{h\Sm} \\
                & = \alt_{\sgn^{(1)}} (\Sigma \En[1]^{\oplus d}) \oplus \alt_{\sgn^{(1)}} \En[1].
            \end{split}
        \end{equation*}
    \end{proof}

    \begin{remark}
        Note that the discussion so far applies to any $(\Fq{2},1)$-oriented category, such as $\SpKn[1]$ or $\Mod_{\Vect}$.
    \end{remark}

    \begin{theorem}\cite[Corollary 4.3.4, Corollary 4.7.5]{Lurie-2019-Elliptic3}\label{thm:intertia-groupoid}
        Let $G$ be a finite group and $X$ be a compact genuine $G$-space. Then  
        \begin{equation*}
            \dim(\En[1][X_{hG}]) = \dim((\En[1] \otimes \QQ)[(\bigsqcup_{g \in G^{(2)}} X^{\langle g \rangle})_{hG}],
        \end{equation*} 
        where $G^{(2)}$ is the subset of $2$-power torsion elements in $G$ and the $G$-action on $\bigsqcup_{g \in G^(2)} X^{h \langle g \rangle}$ is given by
        \begin{equation*}
            h.(g,x) = (hgh^{-1}, h.x).
        \end{equation*}
    \end{theorem}

    \begin{proof}
        Applying global sections to \cite[Corollary 4.3.4, Corollary 4.7.5]{Lurie-2019-Elliptic3} to $A=\En[1]$ with the Quillen $2$-divisible group, the finite group $G$, the colattice $\hat{\Lambda} = \ZZ_p$ and choosing $B$ as the splitting algebra, gives a base change formula 
        \begin{equation*}
            \En[1]^{X_{h G}} \otimes B \simeq B^{(\bigsqcup_{g \in G^{(2)}}X^{\langle g \rangle})_{hG}}.
        \end{equation*}
        By ambidexterity
        \begin{equation*}
            \En[1][X_{h G}] \otimes B \simeq B[(\bigsqcup_{g \in G^{(2)}}X^{\langle g \rangle})_{hG}].
        \end{equation*}
        Using the fact that the splitting algebra is faithfully flat over $\En[1] \otimes \QQ$ we get 
        \begin{equation*}
            \dim(B[(\bigsqcup_{g \in G^{(2)}}X^{\langle g \rangle})_{hG}]) = \dim ((\En[1] \otimes \QQ)[(\bigsqcup_{g \in G^{(2)}}X^{\langle g \rangle})_{hG}]).
        \end{equation*}
        Finally, the claim follows as the symmetric monoidal functor $B \otimes -$ preserves dimensions and since $\pi_0\En[1]$ is torsion-free.
    \end{proof}


    \begin{notation}
        We denote the image of $1 \in \ZZ/2$ under the central homomorphism $\ZZ/2 \to \Sm^+$  by $z \in \Z(\Sm^+)$. We denote the preimages of $\sigma \in \Sm$ under the map $\Sm^+ \to \Sm$ by $\overline{\sigma}$ and $z\overline{\sigma}$.
    \end{notation}

    \begin{proposition}\label{prop:dim-of-alternating-in-height-1-ge0}
        Let $V\in (\ModEn[1])\dbl$ with $\dim(V) = d \ge 0$. Then
        \begin{equation*}
            \dim \alt_{\sgn^{(1)}} V = \sum_{\substack{[\sigma] \in \Sm^{(2)} / \mrm{conj},\\ \overline{\sigma}\not\sim z\overline{\sigma} \in \Sm^+}} d^{\numcyc}.
        \end{equation*}
    \end{proposition}

    \begin{proof}
        Since the $\TT$-action on $\dim(V)$ is trivial (see e.g.\ \cite[Corollary~3.2.5]{Keidar-Ragimov-2025-twisted-graded}), by \cref{cor:dim-of-alternating-depends-only-on-dim} 
        \begin{equation*}
            \dim \alt_{\sgn^{(1)}} V = \dim \alt_{\sgn^{(1)}} \En[1]^{\oplus d}.
        \end{equation*}
        We may therefore assume $V = \En[1]^{\oplus d}$. Let $[d]$ be a set with $d$ elements, so that $[d]^{\degree}$ is a (Borel) $\Sm^+$-space. By \cref{lem:Sm+-orbits}
        \begin{equation*}
            \En[1][[d]^{\degree}_{h\Sm^+}] \simeq ((\En[1]^{\oplus d})\om \otimes \En[1][\B\ZZ/2])^{h\Sm} \simeq \Sym (\En[1]^{\oplus d}) \oplus \alt_{\sgn^{(1)}} (\En[1]^{\oplus d})
        \end{equation*}
        By \cref{thm:intertia-groupoid}
        \begin{equation*}
            \dim(\En[1][[d]^{\degree}_{h\Sm^+}]) 
            = \dim((\En[1] \otimes \QQ)[(\bigsqcup_{\overline{\sigma} \in (\Sm^+)^{(2)}}([d]^{\degree})^{\langle \overline{\sigma} \rangle})_{h\Sm^+}])
            = \sum_{[\overline{\sigma}]\in (\Sm^+)^{(2)} / \mrm{conj}} d^{\numcyc},
        \end{equation*}
        where in the last equality we used the fact that finite groups have no rational homology. 
        Similarly,
        \begin{equation*}
            \dim \Sym (\En[1]^{\oplus d}) = \dim(\En[1][[d]_{h\Sm}]) = \sum_{[\sigma] \in \Sm^{(2)}/\mrm{conj}} d^{\numcyc}.
        \end{equation*}
        Therefore
        \begin{equation*}
            \dim \alt_{\sgn^{(1)}} V = \sum_{\substack{[\sigma]\in \Sm^{(2)} / \mrm{conj} \\ \overline{\sigma} \not\sim z\overline{\sigma} \in \Sm^+}} d^{\numcyc}.
        \end{equation*}
    \end{proof}     

    \begin{proposition}\label{prop:dim-of-alternating-in-height-1-<0}
        Let $V\in (\ModEn[1])\dbl$ with $\dim(V) = d < 0$. Then
        \begin{equation*}
            \dim \alt_{\sgn^{(1)}} V = \sum_{\substack{[\sigma] \in \Sm^{(2)} / \mrm{conj},\\ \overline{\sigma}\not\sim z\overline{\sigma} \in \Sm^+}} (d^{\numcyc} + (-d)^{\numcyc} -1).
        \end{equation*}
    \end{proposition}

    \begin{proof}
        Again by \cref{cor:dim-of-alternating-depends-only-on-dim} 
        \begin{equation*}
            \dim \alt_{\sgn^{(1)}} V = \dim \alt_{\sgn^{(1)}} \Sigma \En[1]^{\oplus (-d)}.
        \end{equation*}
        We may therefore assume $V = \Sigma \En[1]^{\oplus (-d)}$.
        Consider the topological space $(\bigvee_{(-d)} S^1)$ and the corresponding genuine $\Sm^+$-space $X \coloneqq (\bigvee_{(-d)} S^1)^{\wedge \degree}$.
        By \cref{thm:intertia-groupoid} and \cref{lem:E1-of-smash-of-wedge-of-circles} we have 
        \begin{equation}\label{eq:1}
            \begin{split}
                \dim( (\En[1]\otimes \QQ)[(\bigsqcup_{\overline{\sigma} \in (\Sm^+)^{(2)}} X^{\langle \overline{\sigma} \rangle})_{h\Sm^+}] ) 
                % & = \dim(\En[1][X_{h\Sm^+}]) \\
                & = \dim \Sym \En[1] + \dim \alt_{\sgn^{(1)}} \En[1] \\
                & + \dim \Sym(\Sigma \En[1]^{\oplus (-d)}) + \dim \alt_{\sgn^{(1)}} (\Sigma \En[1]^{\oplus (-d)}),
            \end{split}
        \end{equation} 
        and 
        \begin{equation}\label{eq:2}
            \dim( (\En[1]\otimes \QQ)[(\bigsqcup_{\sigma \in \Sm^{(2)}} X^{\langle \overline{\sigma} \rangle})_{h\Sm}] ) 
            = \dim \Sym \En[1] + \dim \Sym(\Sigma \En[1]^{\oplus (-d)}).
        \end{equation} 
        By \cref{prop:dim-of-alternating-in-height-1-ge0},
        \begin{equation}\label{eq:3}
            \dim \alt_{\sgn^{(1)}} \En[1] = \sum_{\substack{[\overline{\sigma}] \in \Sm^{(2)} \\ \overline{\sigma} \not\sim z\overline{\sigma} \in \Sm^+}} 1.
        \end{equation}
        Note that non-equivariantly $X \simeq \bigvee_{[-d]^{\degree}}S^{\degree}$. For every non-trivial orbit of $\sigma$ in $[-d]^{\degree}$, $\langle \overline{\sigma}\rangle$ permutes the corresponding spheres and therefore the corresponding fixed points consist only of the base-point.
        If $\sigma$ fixes an element in $[-d]^{\degree}$, then the corresponding fixed points are $S^{\numcyc}$.

        Since finite groups have no rational homology, it follows that 
        \begin{equation}\label{eq:4}
            \begin{split}
                \dim( (\En[1]\otimes \QQ)[(\bigsqcup_{\overline{\sigma} \in (\Sm^+)^{(2)}} X^{\langle \overline{\sigma} \rangle})_{h\Sm^+}] ) 
                & = \sum_{[\overline{\sigma}] \in (\Sm^+)^{(2)} / \mrm{conj}} |[-d]^{\langle \sigma \rangle}| \dim(\En[1][S^{\numcyc}]) \\
                & = \sum_{[\overline{\sigma}] \in (\Sm^+)^{(2)} / \mrm{conj}} (-d)^{\numcyc} \cdot (1 + (-1)^{\numcyc}) \\
                & = \sum_{[\overline{\sigma}] \in (\Sm^+)^{(2)} / \mrm{conj}} ((-d)^{\numcyc} + d^{\numcyc}),
            \end{split}
        \end{equation}
        and similarly
        \begin{equation}\label{eq:5}
            \begin{split}
                \dim( (\En[1]\otimes \QQ)[(\bigsqcup_{\sigma \in \Sm^{(2)}} X^{\langle \overline{\sigma} \rangle})_{h\Sm}] ) 
                = \sum_{[\sigma] \in \Sm^{(2)} / \mrm{conj}} ((-d)^{\numcyc} + d^{\numcyc}),
            \end{split}
        \end{equation}
        Combining \cref{eq:1}, \cref{eq:2}, \cref{eq:3}, \cref{eq:4} and \cref{eq:5} we get
        \begin{equation*}
            \dim \alt_{\sgn^{(1)}} (\Sigma \En[1]^{\oplus (-d)}) = \sum_{\substack{[\sigma] \in \Sm^{(2)} / \mrm{conj} \\ \overline{\sigma} \not\sim z\overline{\sigma} \in \Sm^+}} (d^{\numcyc} + (-d)^{\numcyc} - 1).
        \end{equation*}
    \end{proof}     

    \begin{theorem}[{\cite{Schur-1911-alternating-groups}, see also \cite[Theorem~1.3]{Bessenrodt-1994-covering-of-symmetric-groups}}]\label{thm:conjugacy-in-Sm+}
        Let $\degree \geq 4$ and $\sigma\in\Sm$. Then $\overline{\sigma}$ and $z\overline{\sigma}$ are not conjugate if and only if one of the following holds:
        \begin{enumerate}
            \item The decomposition of $\sigma$ into disjoint cycles contains no even cycles, or
            \item the decomposition of $\sigma$ into disjoint cycles consist of cycles of different lengths, and there are odd number of cycles of even length.
        \end{enumerate}
        In particular, let $\degree = \sum b_i 2^i$ be the binary decomposition. $\sigma \in \Sm^{(2)}$ satisfies one of the above conditions if and only if
        \begin{enumerate}
            \item $\sigma = e$, or
            \item $|\{i > 0 \mid b_i = 1\}|$ is even and $\sigma$ consist of 1 cycle of length $2^i$ for each $i$ such that $b_i = 1$.
        \end{enumerate}
        Thus, for any $\degree$ there is at most one non-trivial element $\sigma \in \Sm^{(2)}$ such that $\overline{\sigma} \not\sim z\overline{\sigma}$.
    \end{theorem}

    \begin{remark}
        Note that $\lfloor \frac{\degree}{2} \rfloor = \sum_{i \ge 0} b_{i+1} 2^{i}$. Therefore there exists a non-trivial element in $\Sm^{(2)}$ such that its liftings to $\Sm^+$ are non-conjugate if and only if the binary decomposition of $\lfloor \frac{\degree}{2} \rfloor$ has an even number of 1-s.
    \end{remark}

    \begin{corollary}\label{cor:dim-height-1->=0}
        Let $V\in (\ModEn[1])\dbl$ with $\dim(V) = d \ge 0$ and $4 \le \degree = \sum_{i} b_i 2^i$ its binary decomposition. Then 
        \begin{enumerate}
            \item If $|\{i >0 \mid b_i = 1\}|$ is odd then
            \begin{equation*}
                \dim \alt_{\sgn^{(1)}} V = d^{\degree}.
            \end{equation*}
            \item If $|\{i >0 \mid b_i = 1\}|$ is even
            \begin{equation*}
                \dim \alt_{\sgn^{(1)}} V = d^{\degree} + d^{|\{i \ge 0 \mid b_i = 1\}|}.
            \end{equation*}
        \end{enumerate}
    \end{corollary}

    \begin{corollary}\label{cor:dim-height-1-<0}
        Let $V\in (\ModEn[1])\dbl$ with $\dim(V) = d < 0$ and $4 \le \degree = \sum_{i} b_i 2^i$ its binary decomposition. Then 
        \begin{enumerate}
            \item If $|\{i >0 \mid b_i = 1\}|$ is odd then
            \begin{equation*}
                \dim \alt_{\sgn^{(1)}} V = d^{\degree} + (-d)^{\degree} - 1.
            \end{equation*}
            \item If $|\{i >0 \mid b_i = 1\}|$ is even
            \begin{equation*}
                \dim \alt_{\sgn^{(1)}} V = d^{\degree} + (-d)^{\degree} + d^{|\{i \ge 0 \mid b_i = 1\}|} + (-d)^{|\{i \ge 0 \mid b_i = 1\}|} - 2.
            \end{equation*}
        \end{enumerate}
    \end{corollary}

    In the categorical case $\cC = \Mod_{\sVect}$, similar arguments show that

    \begin{proposition}\label{prop:categorical-height-1}
        Let $d\in \ZZ_{\ge 0}$. Then
        \begin{equation*}
            \dim^2(\alt_{\sgn^{(1)}} (\sVect^{\oplus d}))=\sum_{[\sigma]\in \mcal{O}(\degree) \cup \mcal{D}(\degree)} d^{\numcyc}
        \end{equation*}
        where
        \begin{enumerate}
            \item $\mcal{O}(\degree)$ is the set of conjugacy classes in $\Sm$ such that their decomposition into disjoint cycles contains no even cycles, and
            \item $\mathcal{D}(\degree)$ denotes the set of conjugacy classes in $\Sm$ such that their decomposition into disjoint cycles consist of cycles of different lengths, and there are odd number of cycles of even length.
        \end{enumerate}
    \end{proposition}

    \begin{remark}
        From these computations, one can deduce the values of $\sgn^{(1)}$-twisted power operations evaluated on integers (in $\En[2]$ in the chromatic case, or in $\cVectn[2]$ in the categorical case).
    \end{remark}


