\section{Conjugacy classes of wreath products via the monoidal dimension}
\label{app:conjugacy-of-wreath}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

    Our goal in this appendix is to obtain a formula for centralizers and conjugacy classes in the wreath product $G \wr \Sm$ in terms of those of $G$ and $\Sm$. We do so by working in the universal 1-semiadditive category $\Span(\spcpi[1])$, where we compute the dimension of the symmetric power of $\BG$ in two different ways.

    % \begin{Atheorem}[{\cite[Corollary 5.3]{Harpaz-2020-ambi}}]
    %     Any symmetric monoidal $1$-semiadditive category $\cC$ admits a symmetric monoidal, $1$-finite colimit-preserving functor
    %     \begin{equation*}
    %         \ounit_{\cC}[-] \colon \Span(\spcpi[1]) \to \cC.
    %     \end{equation*}
    % \end{Atheorem}


    First, recall that in $\Span(\spcpi[1])$
    \begin{equation*}
        \dim(\Sym(\BG)) \simeq \L\Sym \BG \simeq \L (\BG^{\degree})_{h\Sm} \simeq \L\B(G\wr\Sm) \simeq \bigsqcup_{[(\underline{g}, \sigma)] \in G \wr \Sm /\mrm{conj}} \B\cent_{(\underline{g},\sigma)}(G \wr \Sm).
    \end{equation*}

    Second, we use the induced character formula \cref{thm:induced-character-formula}
    \begin{equation*}
        \dim (\Sym (\BG)) \simeq \int_{\L\B\Sm} \chi_{\Tm(\BG)}.
    \end{equation*}

    \begin{Alemma}
        Let $\sigma\in \Sm$. Then, using the notations of \cref{not:sigma} 
        \begin{equation*}
            \Csigma\simeq  ( \Sm[{\Nk[1]}])\times ((\ZZ/2)^{\Nk[2]}\rtimes \Sm[{\Nk[2]}]) \times \cdots \times ((\ZZ/\degree)^{\Nk[\degree]}\rtimes \Sm[{\Nk[\degree]}]).
        \end{equation*}
        moreover each $\ZZ/k$ is generated by the corresponding cycle and $\Sm[\Nk]$ permutes the all cycles of length $k$.
    \end{Alemma}

    % In order to calculate the integrals we want to understand the action of the stabilizers on the the dimensions.

    \begin{Alemma}[{\cref{lem:character-of-Tm}}]
       Let $\cC\in \CAlg(\PrL)$ and $V\in \cC\dbl$. Then for any $\sigma \in \L\B\Sm$
       \begin{equation*}
            \chi_{\Tm V}(\sigma)=\dim(V)^{\numcyc} \qin \ounit_{\cC}^{\B\Csigma}
       \end{equation*}
       where $\dim(V)^{\numcyc}$ is equipped with the $\Csigma$-action of \cref{def:stabilizer-action}.
    \end{Alemma}

    In the case $\cC = \Span(\spcpi[1])$ and $V = \BG$:
    \begin{equation*}
        \begin{split}
            \L\B(G \wr \Sm) & = \dim(\Sym (\BG)) \\
            & \simeq \int_{\L\B\Sm} \chi_{\Tm\BG} \\
            & \simeq \bigsqcup_{[\sigma] \in \Sm/\mrm{conj}} \int_{\B\Csigma} \L\BG^{\numcyc} \\
            & \simeq \bigsqcup_{[\sigma] \in \Sm/\mrm{conj}} (\L\BG^{\numcyc})_{h \Csigma} \\
            & \simeq \bigsqcup_{[\sigma] \in \Sm/\mrm{conj}}\bigsqcap_{k=1}^\degree (\L\BG^{\Nk})_{h ((\ZZ/k)^{\Nk} \rtimes \Sm[\Nk])}.
        \end{split}
    \end{equation*}
    $((\ZZ/k)^{\Nk} \rtimes \Sm[\Nk])$-orbits can be computed by first taking $(\ZZ/k)^{\Nk}$-orbits and then computing orbits under the induced $\Sm[\Nk]$-action. Note that
    \begin{equation*}
        (\L\BG^{\Nk})_{h (\ZZ/k)^{\Nk}} \simeq ((\L\BG)_{h\ZZ/k})^{\Nk} \qin \spc^{\B\Sm[\Nk]}.
    \end{equation*}
    \begin{Acorollary}\label{cor:LB(G-wr-Sm)}
        Let $G$ be a finite group. Then
        \begin{equation*}
            \L\B(G \wr \Sm) \simeq \bigsqcup_{[\sigma] \in \Sm/\mrm{conj}} \bigsqcap_{k=1}^\degree (((\L\BG)_{h\ZZ/k})^{\Nk})_{h \Sm[\Nk]}.
        \end{equation*}
    \end{Acorollary}

    The $\ZZ/k$-action on $\L\BG$ is the restriction of the $\TT$-action on $\L\BG = \Map(\TT,\BG)$. Recall that a $\TT$-action on $\BG$ is the data of an element in the center $\Z(G)$ (\cref{recol:T-action-on-BG}).
    In particular a $\TT$-action on $\L\BG \simeq \bigsqcup_{[g] \in G / \mrm{conj}} \B\cent_g(G)$ is an element in $\Z(\cent_g(G))$ for every conjugacy class in $G$. 
    The $\TT$-action on $\L\BG$ is described by $g \in \Z(\cent_g(G))$ for any conjugacy class $[g]$ of $G$.

    \begin{Adefinition}[\cref{def:root-of-central-element}]
            Let $G$ a be group, $z \in \Z(G)$ and $k \in \NN$. We define the group
            \begin{equation*}
                G\kz{z} \coloneqq G \langle x \mid x^k = z, \ gx = xg\  \forall g \in G \rangle.
            \end{equation*}
        \end{Adefinition}

    \begin{Alemma}\label{lem:cyclic-fixed-points-of-BG}
        Let $G$ be a finite group and $z \in \Z(G)$ that induces a $\TT$-action on $\BG$.
        Then
        \begin{equation*}
            (\BG)_{h\ZZ/k} \simeq \B G\kz{z}.
        \end{equation*}
    \end{Alemma}

    \begin{proof}
        The case where $G$ is an abelian group is a reinterpretation of a classical fact. Indeed in this case we want to show that the following 
        \begin{equation*}
            \begin{tikzcd}
                {\BG\kz{z}} & \pt \\
                {\B\ZZ/k} & {\B^2 G=\B^2 \Z(G)}
                \arrow[from=1-2, to=2-2]
                \arrow[from=2-1, to=2-2]
                \arrow[from=1-1, to=2-1]
                \arrow[from=1-1, to=1-2]
            \end{tikzcd}
        \end{equation*}
        is a pullback diagram. This is the claim that $G\kz{z}$ is the central extension of $\ZZ/k$ by $G$ classified by $[z]\in G/kG\simeq \H^2(\ZZ/k; G)$ which is classical.

        For the general case one needs to verify that the following
        \begin{equation*}
            \begin{tikzcd}
                {\BG\kz{z}} & {\BG/\Z(G)} \\
                {\B\ZZ/k} & {\B^2\Z(G)}
                \arrow[from=1-2, to=2-2]
                \arrow[from=2-1, to=2-2]
                \arrow[from=1-1, to=2-1]
                \arrow[from=1-1, to=1-2]
            \end{tikzcd}
        \end{equation*}
        is a pullback diagram. 
        Let $P \coloneqq \B G/\Z(G) \times_{\B^2 \Z(G)} \B\ZZ/k$ and consider the following diagram
        \begin{equation*}
            \begin{tikzcd}
                {\B\Z(G)} & {\B\Z(G)\kz{z}} & \pt \\
                \BG & P & {\B G/Z(G)} \\
                \pt & {\B\ZZ/k} & {\B^2\Z(G).}
                \arrow[from=1-1, to=1-2]
                \arrow[from=1-1, to=2-1]
                \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-1, to=2-2]
                \arrow[from=1-2, to=1-3]
                \arrow[from=1-2, to=2-2]
                \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-2, to=3-3]
                \arrow[from=1-3, to=2-3]
                \arrow[from=2-1, to=2-2]
                \arrow[from=2-1, to=3-1]
                \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=2-1, to=3-2]
                \arrow[from=2-2, to=2-3]
                \arrow[from=2-2, to=3-2]
                \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=2-2, to=3-3]
                \arrow[from=2-3, to=3-3]
                \arrow[from=3-1, to=3-2]
                \arrow[from=3-2, to=3-3]
            \end{tikzcd}
        \end{equation*}
        Then the bottom-right square is a cartesian by definition, the right rectangle is cartesian as $\Z(G)$ is abelian, and the bottom rectangle and the full square are easily seen to be cartesian. Therefore all squares in the diagram are pullback squares. In particular, $P = \B K$ where $K$ is an extension of $\ZZ/k$ by $G$ and an extension of $G/\Z(G)$ by $\Z(G)\kz{z}$. 
        Choosing a base point for $\B\Z(G)$ we get a commutative diagram of groups where the middle row and middle column are exact
        \begin{equation*}
            \begin{tikzcd}
                && 1 \\
                & {\Z(G)} & {\Z(G)\kz{z}} \\
                1 & G & K & \ZZ/k & 1. \\
                && {G/\Z(G)} \\
                && 1
                \arrow[from=1-3, to=2-3]
                \arrow[from=2-2, to=2-3]
                \arrow[from=2-2, to=3-2]
                \arrow[from=2-3, to=3-3]
                \arrow[from=3-1, to=3-2]
                \arrow[from=3-2, to=3-3]
                \arrow[two heads, from=3-2, to=4-3]
                \arrow[from=3-3, to=3-4]
                \arrow[from=3-3, to=4-3]
                \arrow[from=3-4, to=3-5]
                \arrow[from=4-3, to=5-3]
            \end{tikzcd}
        \end{equation*}
        Let $x \in K$ be the image of $\sqrt[k]{z} \in \Z(G)\kz{z}$. Then $x^k = z$ and as the image of $x$ is trivial in $G/\Z(G)$, $x$ commutes with all elements of $G$, i.e.\ $K = G\kz{z}$.
    \end{proof}

    Finally, using the notations of \cref{not:not1,not:not2}, we deduce:
    \begin{Acorollary}
        Let $G$ be a finite group. Then 
            \begin{equation*}
                \L\B(G\wr \Sm) 
                \simeq \bigsqcup_{[\sigma] \in \Sm/\mrm{conj}} \ \bigsqcap_{k=1}^\degree \ \bigsqcup_{[\underline{g}] \in \Sm[\Nk] \backslash G^{\Nk} / \mrm{conj}} \ \bigsqcap_{x \in \underline{g}} \B (\cent_G(x)\kz{x} \wr \Sm[\mul_{\underline{g}}(x)]).
            \end{equation*}
    \end{Acorollary}

    \begin{proof}
        By \cref{cor:LB(G-wr-Sm)} and \cref{lem:cyclic-fixed-points-of-BG} 
        \begin{equation*}
            \begin{split}
                \L\B(G \wr \Sm) 
                & \simeq 
                    \bigsqcup_{[\sigma] \in \Sm/\mrm{conj}} \ 
                    \bigsqcap_{k=1}^\degree ((\bigsqcup_{[x] \in G/\mrm{conj}} \B\cent_G(x)\kz{x})^{\Nk})_{h \Sm[\Nk]} \\
                & \simeq 
                    \bigsqcup_{[\sigma] \in \Sm/\mrm{conj}} \ 
                    \bigsqcap_{k=1}^\degree \ 
                    \bigsqcup_{[\underline{g}] \in \Sm[\Nk] \backslash G^{\Nk}/\mrm{conj}} \ 
                    \bigsqcap_{x\in \underline{g}}(\B\cent_G(x)\kz{x}^{\mul_{\underline{g}}(x)})_{h \Sm[\mul_{\underline{g}(x)}]} \\
                & \simeq 
                    \bigsqcup_{[\sigma] \in \Sm/\mrm{conj}} \
                    \bigsqcap_{k=1}^\degree \ 
                    \bigsqcup_{[\underline{g}] \in \Sm[\Nk] \backslash G^{\Nk} / \mrm{conj}} \ 
                    \bigsqcap_{x \in \underline{g}} \B (\cent_G(x)\kz{x} \wr \Sm[\mul_{\underline{g}}(x)]).
            \end{split}
        \end{equation*}
    \end{proof}


