\subsection{Results}


 Let $F:\bT^2\to \bT^2$ be a map, $\tau: \bT^2 \to \bR$ be a centred observable\footnote{$\mu(\tau) = 0$ for each ergodic acip $\mu$.} and consider the ergodic sums 
 \begin{equation} \label{def:tau}\tau_n := \sum_{k=0}^{n-1} \tau \circ F^k.
 \end{equation}
 We will use the symbol $m$ to denote any initial probability measures absolutely continuous with respect to $\frm$, $f_m$ to be the associated density, i.e., $\dd m = f_m\, \dd \frm$ and by $\bP_m$ the associated probability distribution function.

 We say that $(F,\tau)$ satisfies a non-trivial CLT if there exist $\sigma>0$ and $A \in \bR$ such that
$$\lim_{n \to \infty }\bP_{m}\left(\frac{\tau_n}{\sqrt{n}}\leq z\right) = \int_{-\infty}^z \fn\left(\frac{y}{\sigma}\right)\, \dd y\,,\,\,\, z \in \bR$$
 and $\fn(y)=\frac{1}{\sqrt{2\pi}}e^{-y^2/2}$ is the standard normal density. 

More general CLT can be established when the initial measure is not an acip and $F$ is not ergodic but it has finitely many acips (see \cite[p.~119]{HeHe}). We recall this general form below.

Suppose $F$ has $\ell$ acips and then the general CLT, if it holds, takes the form 
\begin{equation}\label{CLT}
    \lim_{n \to \infty }\bP_{m}\left(\frac{\tau_n}{\sqrt{n}}\leq z\right) = \sum_{k=1}^\ell c_k \int_{-\infty}^z \fn\left(\frac{y}{\sigma_k}\right)\, \dd y\,,\quad \text{as}\\,,\,\,\, z \in \bR
\end{equation}
where $c_k$ and $\sigma_k$, $k=1,\dots, d$ are constants\footnote{We will find an explicit expression for the coefficients $c_k$ and $\sigma_k$ (see Theorem \ref{thmB}).} with $\sum c_k =1$ and $\sigma_k>0$. 

\begin{oss}
Intuitively, if the system is already at the equilibrium, the initial mass can be decomposed to individual ergodic basins and each component can be evolved independently. If each component evolves into a Gaussian, then the overall asymtptotic should be a convex combination of those Gaussians, weighted by how the system was initialised. For example, if the initial measure is supported in a single ergodic basin, then all $c_k$s except one will be $0$. 
\end{oss}

The Berry-Esseen estimate given below provides an elementary quantitative rate of convergence in the CLT. 
\begin{equation}\label{BEst}
    \sup_{z \in \mathbb R}\left|\bP_{m}\left(\frac{\tau_n}{\sqrt{n}}\leq z\right) - \sum_{k=1}^dc_k \int_{-\infty}^z \fn\left(\frac{y}{\sigma_k}\right)\, dy\,\right|  \leq \frac{C(\||m|\|+1)}{\sqrt{n}}
\end{equation}
where the norm $\||\cdot|\|$ is understood to be the norm in a suitable (dual) Banach space. In order to understand local statistics of $\tau_n$, we require LLTs. The following is such an LLT:
\begin{equation}\label{fLLT}
    \lim_{n\to\infty} \sup_{z\in \bR}\left|\sqrt{n} \bE_m\left(g(\tau_n - z)\right) - \frm(g)\sum_{k=1}^{\ell} c_k\fn\left(\frac{z}{\sigma_k\sqrt{n}}\right) \right| = 0
\end{equation}
where $g \in C^0(\bR)$ be bounded and $g(z) = o(z^{-2})$ as $z\to\infty$.\footnote{In particular, one can consider $g \in C^0_c(\bR)$\,.}

For these limit theorems to hold, our random variables must be non-degenerate. So, we make the following non-degeneracy assumptions on $\tau \in \cC^r(\bT^2,\bC)$.
\vspace{5pt}

\textbf{(B1)} There is no ergodic basin, $D$, of $F$ and that there are no $\Psi\in C^0(D, \bR)$, $c\in \mathbb R$ such that $\Psi\in L^1(\bT^2, \bR)$, $c\in \bR$ such that 
\[
\tau|_D=\Psi\circ F-\Psi+c.
\]

(This is a non-coboundary condition.)\vspace{5pt}

\textbf{(B2)} There is no ergodic basin, $D$, of $F$ and that there are no $\Psi\in C^0(D, \bR)$, $a>0, b\in \bR$ such that
\[
\tau|_D+\Psi-\Psi\circ F
\]

is $a\mathbb{Z}+b$ valued.

(This is a non-lattice condition.)

\begin{oss}
Note that when $F$ is ergodic these two conditions reduces to the usual non-coboundary and non-lattice conditions assumed in the literature. 
\end{oss}

We are ready to state our results, which proves are presented in Section \ref{sec:proof-thmA}. The first one is the CLT.
\begin{bigthm}\label{thmA}
Let $F$ be a SVPH satisfying \eqref{main-hp} and $\tau \in \cC^r(\bT^2, \bC)$ be such that \emph{\textbf{(B1)}} is true. Then the non-trivial CLT \eqref{CLT} and the Berry-Esseen estimate \eqref{BEst} hold.  
\end{bigthm}

\begin{oss}
From the proof it follows that, while the constants $c_k$s depend on the initial measure $m$, the constants $\sigma_k$ (aka diffusion coefficients) do not, i.e., they depend only on $F$ and $\tau$ and are independent of how the system is initialised.
\end{oss}

\begin{oss}
If $m$ is an invariant acip (not necessarily ergodic), then one can establish more general limit theorems where both $\tau_n$ and $\tau \circ F^n$ are tracked, e.g., the limiting behaviour of $\bE_m(f(\tau \circ F^n)g(\tau_n/\sqrt{n}))$ and $\bE_m(f(\tau \circ F^n)g(\tau_n-z))$ where $f$ and $g$ are appropriately chosen. We refer the reader to \cite{HeHe} for the exact statements. 
\end{oss}

To prove Theorem \ref{thmA} we will use the functional analytic framework presented in Appendix \ref{app:AbstractCLT} applied to the transfer operator $\cL_F$ associated to $F$ and the \textit{twisted transfer operators} $\cL_\nu,\,\,\, \nu \in \bR$. This will be the context of section \ref{sec:TraOp}. In section \ref{sec:twisted}, we do a further analysis of the spectral properties of $\cL_\nu$ to obtain the following LLTs, which proof can be found at the end of section \ref{sec:proof-thmA}. 

\begin{bigthm}\label{thmB}
Let $F$ be a SVPH satisfying \eqref{main-hp} and $\tau \in \cC^r(\bT^2, \bC)$ be such that \emph{\textbf{(B2)}} holds. Then the LLT \eqref{fLLT} holds for any initial measures $\dd m=f_m \dd\frm$. Also, there exists $C>0$ such that for all $a, b \in \bR$ with $0<b-a<1$ and for each $\delta>2$,
\begin{equation*}\label{LLT}
    \left|\bP_{m}\left(\frac{\tau_n}{\sqrt{n}}\in [a,b]\right) - \sum_{k=1}^dc_k \int_{a}^b \fn\left(\frac{y}{\sigma_k}\right)\, dy\,\right| \leq C\left(\frac{\max_k  \fn\big(\frac{a}{\sigma_k}\big)}{n^{\frac 12-\frac 1\delta}}+\frac{b-a}{\sqrt{n}}\right)\,,
\end{equation*}
where, recalling $\mu_k$ and $\rho_k$ from Lemma \ref{lem:invariants}, $c_k = \frm(\rho_k)\mu_k(f_m)$ and
$$\sigma^2_k = \mu_k(\tau_k^2)+2\sum_{j=1}^\infty \mu_k(\tau_k\cdot\tau_k\circ F^j)\,.$$
\end{bigthm}

\begin{oss}
To prove the second part of the above theorem, we follow the arguments given in \cite[Section 1.5]{DeKiLi} for expanding maps adapted to our non-ergodic partially hyperbolic setting. It is easy to note that the usefulness of the result depends on the size of the interval: if $b-a=O(n^{-\gamma})$ there is an interplay between $\delta$ and $\gamma$ in order to get a useful estimate, while if $a$ or $b$ are $O(\sqrt{\log n})$ we gain no information from the previous estimate. To get results more close to optimal, we would need an Edgeworth expansion (following the ideas in \cite{FeLi, FePe}) which will be established in a subsequent project.
\end{oss}
%\footnote{This is pointed out in \cite[Remark 1.26]{DeKiLi} for expanding maps as well. In fact, it is regardless of what the dynamic is.} 




