\section{Unperturbed transfer operator}\label{sec:TraOp}
\subsection{Quasi-compactness}
In this section we explore the spectral properties of the (SRB)-transfer operator associated to $F$ and defined via
\begin{equation}\label{L_F}
    \cL_F u(x)=\sum_{y\in F^{-1}(x)} \frac{u(y)}{|\det DF(y)|}, \quad u\in L^1(\bT^2),\; x,y \in \bT^2,
\end{equation}
which is the main tool to study the statistical properties of $F$.
%In order to exploit the available spectral information of $\cL_F$ we will work under the assumptions of \cite[Theorem 3.1]{CaLi}. 
%Note that, if all the preimages are non-transversal, then the sum in \eqref{NF} corresponds to the classical transfer operator applied to one, $\cL_{F}^n 1$.
%In essence, $\cL_{F}^n 1-\cN_F(n)$ provides a quantitative version of the notion of accessibility in our systems.\\

The main technical result of \cite{CaLi} is a Doeblin-Fortet-Lasota-Yorke (DFLY) inequality in suitable functional spaces, which implies quasi-compactness for the operator $\cL_F$, and it will be crucial for our arguments. To state this result, we recall the definition of the Banach spaces used. 

For a positive integer $s>1$ to be fixed later, $H^s(\bT^2, \bC)$ will denote the standard Hilbert space of $L^2(\bT^2, \bC)$ functions whose $s$-th weak derivative belongs to $L^2$, endowed with the norm\footnote{This is not the classical norm used in such a space, but it is equivalent to it and we will take this formulation for simplicity.}
\begin{equation}
\label{equivalence of norm H L}
\|u\|^2_{H^s}:= \sum_{\gamma+\beta=s} \| \partial_{x_1}^\gamma \partial_{x_2}^{\beta} u \|^2_{L^{2}}.
\end{equation}
We will denote by $\cB_s$ the completion of $\cC^{r-1}(\bT^2, \bR)$ with respect to the norm
\[
\|u\|_s=\|u\|_{H^s}+\|u\|^*_{s+2}
\]
where
\begin{equation}
\label{geom norm}
\| u \|^*_{\rho}:=\max_{|\alpha|\le \rho}\sup_{\gamma \in \Gamma} \sup_{\substack{\phi \in \mathcal{C}^{|\alpha|}(\mathbb{T}, \bR)\\\|\phi\|_{\mathcal{C}^{|\alpha|}}=1}} \int_{\mathbb{T}} \phi(t)(\partial ^{\alpha} u)(\gamma(t))dt, \quad \rho\in \bN
\end{equation}
where $\Gamma$ is a set of admissible curves in the central cone (recall assumption {\textbf{(A3)}). Note that the completion of $\cC^r$ with respect to the norm $\|\cdot\|^*_\rho$ defines a decreasing sequence of Banach spaces continuously embedded in $L^1$, namely
\begin{equation}
\label{relation norm rho rho' and L1}
\|u\|_{L^1}\le {C}\|u\|^*_{\rho_1}\le {C}\|u\|^*_{\rho_2}, \qquad \mbox{for every} \quad 0\le \rho_1\le \rho_2\le r-1.
\end{equation}
$(\cB_{s}, \|\cdot \|_s)$ is, in fact, a Banach algebra satisifying the following.
\begin{itemize}[leftmargin=20pt]
\item $\cC^{r-1}(\bT^2)\subset \cB_{s}\subset H^{s}(\bT^{2})\subset \cC^0(\bT^2)$ where the first inclusion is dense and the second follows because $s>1$.
\item $\cB_s$ is compactly embedded in $L^1(\bT^2)$. 
\end{itemize}
For further details, we refer the reader to \cite{CaLi}.

We also recall the following DFLY inequality.\footnote{The statement of the result  has been formulated here in a simpler way to accommodate what is essentially needed in the present work.}
\begin{thm}[Quasi-compactness of \texorpdfstring{$\cL_F$}{Lg} \cite{CaLi}]\label{thm:LY-F} Let $r \ge 4$ and $F\in \cC^r(\bT^2,\bT^2)$ be an SVPH satisfying \eqref{main-hp}. Then there exist $1< s\le r-3$, $\sigma_* \in (0,\lambda^{-1}\lambda_c^{\xi_s})$, $C_\sigma$ and $D_\sigma>0$ such that the (SRB)-transfer operator $\cL_F:\cB_{s}\to\cB_{s}$ satisfies\footnote{We will use $L^1$ as a short for $L^1(\bT^2)$.}
\begin{equation}\label{LY-F}
\begin{split}
&\|\cL_F^n u\|_{L^1}\le \|u\|_{L^1}\\
&\|\cL_F^n u\|_{s}\le C_{\sigma_*} \sigma_*^n \|u\|_s+D_\sigma \|u\|_{L^1}
\end{split}
\end{equation}
for each $n \in \bN$ and $u\in \cC^{r-1}(\bT^2,\bC)$.
\end{thm}
%By a result due to Hennion and Nussbaum (see, for example, \cite{HeHe} or \cite[Section 4.2]{FePe}), the above implies the quasi-compactness of $\cL_F$ and in particular, the existence of finitely many $F$-invariant measures with densities in $H^s(\bT^2)$. We establish the exponential decay of these measures with respect to H\"older observables in \Cref{app:decay}.   %\sout{To make the argument in the [section on Edgeworth exp] easier, we make the following additional assumption}:\marginnoter{Write the argument on spectral decomposition when we have finitely many densities and show that is ok if we restrict on the support of each mixing measure.}
%\[
%\text{There exists a unique invariant measure for $F$ with density $h\in \cB_s \subset \cH_s(\bT^2)$}.
%\]

From now on we fix $s>1$ as in Theorem \ref{thm:LY-F}.
 %which is proved in Section \ref{subsec:LYnu}.
The main consequences of the above theorem are summarized in the following proposition.

\begin{prop}\label{prop:spectral}
The following is true.
    \begin{enumerate}[leftmargin=*]
    \item[(i)]  $\cL_F$ is quasi-compact  when acting in $\cB_s$, with spectral radius $r(\cL_F)=1$ and essential spectral radius smaller than $1$,\footnote{That is $\cB_s = \cF \oplus \cH$ with $\cF,\cH$ subspaces $\cL_F$-invariant, $r(\cL_{F}|_{\cH}) < 1$, $\dim \cF < \infty$, and $r(\cL_{F}|_{\cH})< |\zeta| \le 1$.} and $\sup_n \|\cL_F^n\|_{L^1} < \infty\,.$
    \item[(ii)] There exist $F-$invariant probability measures $\mu_1, \dots,\mu_\ell$ in $\cB_s^\prime$ such that $\mu_k(\rho_m) = \delta_{k,m}$, each one being an exponentially mixing physical measure, %\footnote{That is, \[\operatorname{Leb}\left(x\in \bT^2: \frac 1n \sum_{k=0}^{n-1}\delta_{F^k(x)}\to \mu_i\right)>0.\]} 
    where $\rho_1,\dots,\rho_\ell$ are non-negative eigen-functions in $\cB_s$  that forms a basis for Ker$(\cL_F - \Id) \cap \cB_s\,$ and $\frm\left(\bT^2 \setminus \bigcup_{j=1}^\ell \supp \rho_j\right) =0\,.$
\end{enumerate}
\end{prop}
\begin{proof} The proof follows \cite[Appendix B]{BaGo} %which is done in the more complicated 
where piece-wise smooth hyperbolic maps are considered. We sketch the adapted proof here for the convenience of the reader.

The quasi-compactness of the operator $\cL_F$  and the existence of finitely many invariant probabilities follows from Theorem \eqref{thm:LY-F} and H\'ennion theorem \cite{Hen}. %and a standard argument using that the iterates of the operator are uniformly bounded) %we have that $1$ is the only eigenvalue of modulus $1$ \marginnotek{Unless the system is exact we cannot say this. We know that the eigenvalues of modulous 1 forms a finite group.} and  So its geometric and algebraic multiplicities are both finite. 
From \cite{CaLi} we also know that the eigenvalues of modulous 1 form a finite group, and their geometric and algebraic multiplicities are both finite. Let $h$ be such that $\cL_F h=h $ and $\Pi$ be the projector on the eigenspace $\cE_1$ corresponding to eigenvalue 1. %generated by $h$. 
So, $\Pi \varphi=\lim_{n} \frac 1n \sum_{k=0}^{n-1}\cL_F^k \varphi$ and the convergence holds in $\cB_s$. Moreover, letting $\dd \frm$ being the Lebesgue measure on $\bT^2$, for each $\varphi \in  \cB_s$ and $g\in L^1$, we have 
\[
\bigg|\int g\cdot\Pi \varphi \, \dd \frm\bigg| \le \|\varphi\|_{\infty} \bigg| \int g\cdot\Pi 1  \, \dd \frm \bigg|. 
\]
In particular, $h \, \dd \frm$ is absolutely continuous with respect to $$ \Pi 1 \, \dd \frm=: \mu_*\,.$$  Let us consider the space 
\[
\bV=\{\varphi \in L^\infty(\bT^2) : \varphi \ge 0, \;\varphi\circ F=\varphi\}
\]
and the map $\Phi: \cE_1\to \bV$ defined by $\Phi (h)=h_*$ where $h_*$ is the Radon-Nikodym derivative of the measure $h \, \dd \frm$ with respect to $\mu_*$. %(it is just the density of $\cC^1$ in $L^1$ (Lusin theorem)) 
Since $\cC^r$ is dense in $\cB_s$, this map is an isomorphism (see \cite[Appendix B]{BaGo} for the details), and in particular, given any $h\in \cE_1$ with $h_* \in \bV$, the function $h_* \Pi 1 \in \cB_s\subset H^s$. 

Next, let 
\[
\bV_1=\{\varphi \in \bV : \mu_*(\varphi)=1\} \subset \bV.
\]

Then $\bV_1$ is a (non empty) convex cone in $\bV$ whose extremal points are of the form $\mathds{1}_E$ for some minimal invariant set $E$. Such extremal points are automatically linearly independent. Since $\operatorname{dim} \bV_1 < \infty$, there is only a finite number of them, say $\mathds{1}_{E_1},..., \mathds{1}_{E_\ell}$, and a function $\varphi$ belongs to $\bV_1$ if and only if it can be written as
$\varphi=\sum_{j}\alpha_j \mathds{1}_{E_j}$ for some scalars $\alpha_1,..,\alpha_\ell$. The decomposition of the function $1\in \bV_1$
is given by $1 = \sum_j\mathds{1}_{E_j}$, hence the sets $E_j$ cover the whole space up to a set of zero $\mu_*-$measure.
It follows that $\dfrac{\mathds{1}_{E_j}}{\mu_*(E_j)}\in \bV_1$ and  the measures  $$\mu_j:= \dfrac{\mathds{1}_{E_j}\cdot \mu_*}{\mu_*(E_j)}$$ are $F$-invariant ergodic probability measures.

Moreover, from the previous result, the functions \begin{equation}\label{eq:rhoi}\rho_j:= \mathds{1}_{E_j} \Pi 1 \in H^s
\end{equation}
and any element of $\bV_1$ is a linear combination of the $\rho_j$. Consequently, for each $\phi \in \cC^1$
\[
\begin{split}
\int \Pi(\phi  \rho_j) \mathds{1}_{E_m} \, \dd \frm& =\lim _{n \rightarrow+\infty} \frac{1}{n} \sum_{k=0}^{n-1} \int \mathcal{L}_F^k\left(\phi\rho_j\right) \cdot \mathds{1}_{E_m} \mathrm{\dd \frm} \\
& =\lim _{n \rightarrow+\infty} \frac{1}{n} \sum_{k=0}^{n-1} \int \phi \cdot \mathds{1}_{E_j} \cdot \mathds{1}_{E_m} \circ F^k \mathrm{~d} \mu_* \\
&=\int_{E_j \cap E_m} \phi \mathrm{~d} \mu_*=\mu_*\left(E_j\right) \delta_{j, m} \int \phi \mathrm{~d} \mu_m
\end{split}
\]
which implies that
\[
\Pi\left(\phi \rho_j\right)=\left(\int \phi \mathrm{~d} \mu_j\right) \rho_j.
\]
We can now conclude the exponential mixing statement: let $\varphi,\phi \in \cC^1(\bT^2)$ (for H\"older observables we can use a standard density argument), then for some $\ve \in (0,1)$,

\[
\begin{split}
\int \phi \cdot \varphi \circ F^n \, \dd \mu_j&=\frac{1}{\mu_*(E_j)} \int \cL^n(\phi \rho_j) \varphi \, \dd \frm\\
&=\frac{1}{\mu_*(E_j)} \int (\cL^n-\Pi)(\phi \rho_j) \varphi \, \dd \frm+\frac{1}{\mu_*(E_j)} \int \Pi(\phi \rho_j) \varphi \, \dd \frm\\
&= O(\varepsilon^n)+ \frac{1}{\mu_*(E_j)} \int \left(\int \phi \mathrm{~d} \mu_j\right) \rho_j \varphi \, \dd \frm\\
&=O(\varepsilon^n)+ \left(\int \phi \mathrm{~d} \mu_j\right) \int  \varphi \cdot\frac{1}{\mu_*(E_j)} \mathds{1}_{E_j} \Pi 1  \, \dd \frm\\
&= O(\varepsilon^n)+ \left(\int \phi \mathrm{~d} \mu_j\right) \int  \varphi \cdot\frac{1}{\mu_*(E_j)} \mathds{1}_{E_j} \, \dd \mu_*\\
&=  O(\varepsilon^n)+ \left(\int \phi \mathrm{~d} \mu_j\right) \int  \varphi \, \dd \mu_j,
\end{split}
\]
which proves that each $\mu_j$ is exponentially mixing.

Finally, we claim that there is a partition %of Lebesgue-almost a
of all $\bT^2$ (up to a $\frm-$null set) into ergodic basins of the physical measures of $\mu_j$. In particular, there are $D_j \subset \bT^2$ such that $\frm(D_j\cap D_j)=0$ for $i \neq j$, $\frm(\sum_j \mathds{1}_{D_j})=1$ and, for each $f\in \cB_s$,
\begin{equation}\label{eq:projection}
\Pi(f)=\sum_{j} \frac{1}{\mu_*(E_j)}\frm(f \mathds{1}_{D_j})\rho_j,
\end{equation}
where the $\rho_j$ are defined in \eqref{eq:rhoi}. This prove the last statement of the proposition.

Let us suppose that $\Pi(f)=\sum_{j} \xi(f)\rho_j$ and let us find out who are the coefficients $\xi(f)$. Let us fix some $j$ and let us set
\[
h_{j,n}:=\lim_n \frac 1n \sum_{j=0}^{n-1}\mathds{1}_{E_j}\circ F^k \subset L^2(\bT^2).
\]
By the invariance of $E_j$,
\[
\lim_n \frm(h_{j,n}\cdot  f)=\langle \mathds{1}_{E_j}, \Pi(f) \rangle_{L^2}=\xi_j(f)\mu_*(E_j).
\]
Let $h_j^*$ be a weak limit of $h_{j,n}$. From the previous computation, we see that $h_j^*$ is $F$-invariant and such that
\begin{itemize}
    \item[(a)] $\xi_j(f)=\dfrac{\frm(h_j^* \cdot f)}{\mu_*(E_j)}$ 
    \item[(b)] $\xi_j(1)=1 \implies \frm(h^*_j)=\mu_*(E_j)$.
\end{itemize}
Moreover, again from invariance, for each $k$
\[
\begin{split}
\frm(h^*_k\cdot  h^*_j)&=\mu_*(E_j)\lim_n \xi_j\left(\mathds{1}_{E_k} \frac{1}{n}\sum_{r=0}^{n-1}\cL_F^r1\right)\\
&=\mu_*(E_j)\xi_j(\rho_k)=
\begin{cases} \mu_*(E_j) \qquad &\text{if} \quad j=k \\ 0 \qquad &\text{if} \quad j\neq k \end{cases}.
\end{split}
\]
It follows that $\frm((h^*_j)^2)=\mu_*(E_j)=\frm(h^*_j)$ which implies the existence of $D_j\in \bT^2$ such that
\begin{itemize}
    \item[(c)] $h_j^*=\mathds{1}_{D_j}$
    \item[(d)] $\frm(\mathds{1}_{D_j})=\mu_*(E_j)$
    \item[(e)] $\frm(D_j \cap D_k)=0$ for $j\neq k$.
\end{itemize}
The claim redly follows from (a)--(e).
%%
\end{proof}



\section{Perturbed transfer operators}\label{sec:twisted}
In order to deal with complex transfer operators, for any real Banach space $(\cB, \|\cdot \|)$ defined in this paper we use the auxiliary norm $\|\cdot\|_{\cB,\bR}$ and the norm $\|\cdot\|_{\cB,\bC}$ (see Appendix \ref{app:complex}) to define the complexification $(\cB, \|\cdot\|_{\cB,\bC})$ of $(\cB, \|\cdot \|)$. 

If $u \in \bC$ with $u=\re (u) + i \im  (u)$, by equations \eqref{eq: complex} the DFLY inequalities hold in the space $(\cB_s, \|\cdot\|_{s,\bC})$, where $\|u\|_{s,\bC}=\|u\|_{H^s}+\|u\|^*_{s+2, \bC}$ and
\begin{equation}\label{eq:def-complex-norm}
    \|u\|^*_{\rho,\bC}:=\sup_{\theta \in [0,2\pi]} \left|e^{i\theta}\star \big(\re (u) , \im  (u)\big)\right|%\sqrt{(\|\re u\|_\rho^*)^2+(\|\im u\|_\rho^*)^2}.
\end{equation}
where the product $\star $ is defined in \Cref{app:complex}.
\begin{oss}\label{rmk:confusion}
Henceforth, when the function $u$ is clear from the context, we will not specify if we are using the complex or real norms, and the same symbol will be used for both, depending whether $u\in \cC^r(\bT^2,\bR)$ or $u\in \cC^r(\bT^2,\bC)$.
\end{oss}

%To establish the result on higher order corrections in the spirit of \cite{FeLi}, the main estimate to check is a Dolgopyat type estimate for 

Next, we define twisted (or perturbed) transfer operators. 

\begin{defn}
 Given a local diffeomorphism $ F\in \cC^r(\bT^2,\bT^2)$ and $\tau \in \cC^r(\bT^2, \bR)\,,$ for any $\nu \in \bR$ and $u\in L^1(\bT^2, \bC)$ we define the twisted transfer operator $\cL_\nu$ associated to $F$ by
\[
\cL_\nu u (x)=	\sum_{y \in F^{-1}(x)} \dfrac{u(y)}{\det DF(y)} e^{i\nu \tau(y)}.
\]
\end{defn}Iterating the above formula we see that for each $n\in \bN$
\begin{equation}\label{L^n}
\cL^n_\nu u (y)=\sum_{y\in F^{-n}(x)} \dfrac{u(y)}{\det DF^n(y)} e^{i\nu \tau_n(y)}.
\end{equation}
where is defined in \eqref{def:tau}.

Our results rely on the following two Lemmas on the quasi-compactness of the twisted transfer operator.


\begin{lem}[Quasi-compactness of \texorpdfstring{$\cL_\nu$}{Lg}]\label{lem:LYnu}
There exists $\sigma\in (0,1)$ such that, for each $\nu \neq 0$, the spectrum of $\cL_\nu$ acting on $\cB_s$ is contained in the disk $\{z\in \bC: |z|\le 1\}$ and the essential spectrum is contained in the disk $\{z\in \bC: |z|\le \sigma\}$. 
\end{lem}


%\section{Quasi-compactness of the twisted transfer operator}\label{subsec:LYnu}
\begin{proof}
First of all we see that $\|\cL_\nu\|_{L^1}\le \|\cL_F\|_{L^1}\le 1\,.$
Therefore, the spectrum of $\cL_\nu$ is contained in the disk $\{z\in \bC: |z|\le 1|\}$. 

We claim that there exists $q_* \in \bN$ and $\sigma \in (0,1)$ there is $C>0$ such that, for each $\nu \neq 0$, for all $n\in\bN$ and $ u\in \cB_s$,
\begin{equation}\label{LYnu}
\|\cL_\nu^n u\|_{s}\le C(1+|\nu|)^{q_*}\left(\sigma^n\|u\|_{s}+\| u \|_{L^{1}}\right).
\end{equation}
Thanks to the H\'ennion theorem (see \cite{Hen}), the above DFLY inequality proves that the essential spectral radius of $\cL_\nu$ in $\cB_s$ is strictly smaller than $1$. 

Let us prove the claim. By the definition od the norm $\|\cdot\|_s$ we will estimate the norms $\|\cL_\nu u\|^*_{s+2}$ and $\|\cL_\nu u\|_{H^s}$ separately in two steps and then we merge the estimates in the final step.\\

\noindent\textit{Step 1} (estimate of $\|\cL_\nu u\|^*_{s+2}$). Recall that the complex norm $\|\cdot\|^*_{s+2}$ is defined via \eqref{eq:def-complex-norm}.
For any $q\in \bN$, $\alpha \le q$, $\phi \in \cC^{|\alpha|}(\bT)$ and  $\gamma \in \Gamma$, due to \eqref{commute}, we have
\begin{equation}\label{eq:J1+J2}
\begin{split}
&\int \phi\, (\partial^\alpha \cL^n_\nu u)\circ\gamma \\ &=\int \phi\,  [\cL_F^n(e^{i\nu \tau_n}P^{\alpha}_{n,q}u)]\circ\gamma \,\\&\qquad\qquad+\int \phi \, \Big[\cL^n_F\Big( e^{i\nu\tau_n}\sum_{k=1}^s (i\nu)^k\sum_{j=1}^{m_k}  a_{j, k}(\cD^u_{j,k}u)^{\beta_{j,k}}(\cD^\tau_{j,k}\tau_n)^{\gamma_{j,k}}\Big)\Big]\circ\gamma\\
&= \cJ_1+\cJ_2
\end{split}
\end{equation}
where 
$$\cJ_1:=\int \phi\,  [\cL_F^n(e^{i\nu \tau_n}P^{\alpha}_{n,q}u)]\circ\gamma$$
and 
$$\cJ_2:=\int \phi \, \Big[\cL^n_F\Big( e^{i\nu\tau_n}\sum_{k=1}^s (i\nu)^k\sum_{j=1}^{m_k}  a_{j, k}(\cD^u_{j,k}u)^{\beta_{j,k}}(\cD^\tau_{j,k}\tau_n)^{\gamma_{j,k}}\Big)\Big]\circ\gamma.$$
By Lemma \eqref{lem:commute} the term $\cJ_2$ involved only derivatives of $u$ up to order $\alpha-1\leq q-1$ so that, using the last statement of Lemma \ref{lem:commute}, equations \eqref{eq: complex} and \eqref{L-Y B2}, we can bound real part and imaginary part of $\cJ_2$ with  
$
C_{s,\tau}\lambda_c^n(1+|\nu|)^q \| u \|^*_{q-1}
$
for some constant $C_{s,\tau}>0$. 

Let us estimate $\cJ_1$. Setting
\[
x=\operatorname{Re}(P^\alpha_{n,q}u)  \qquad \mathrm{and} \qquad y=\operatorname{Im}(P^\alpha_{n,q}u),
\]
to be respectively the real part and the imaginary part of $P^\alpha_{n,q}u$, by \eqref{eq: complex}\footnote{Recall Remark \ref{rmk:confusion} for the following abuse of notation: for $f$ real, $\|f\|^*_0$ is the norm defined in \eqref{geom norm}, while if $f$ is complex valued, then $\|f\|^*_0$ is defined analogously to \eqref{eq:def-complex-norm}.}
\begin{equation}\label{eq:sqrt}
\begin{split}
|\re \cJ_1|&\le \|\cL^n_F(x e^{i\nu \tau_n})\|^*_0+\|\cL^n_F(y e^{i\nu \tau_n})\|^*_0\\
&\le \left[(\|\re(\cL^n_F(x e^{i\nu \tau_n})\|^*_0)^2+(\|\im(\cL^n_F(x e^{i\nu \tau_n})\|^*_0)^2\right]^{\frac 12}\\
&\qquad\qquad+\left[\|\re(\cL^n_F(y e^{i\nu \tau_n})\|^*_0)^2+(\|\im(\cL^n_F(y e^{i\nu \tau_n})\|^*_0)^2\right]^{\frac 12}.
\end{split}
\end{equation}
We thus want to estimate each of the terms in the square roots. Since for any $\phi \in \cC^q$ with $\|\phi\|_{\cC^q}\le 1$, any  $u\in \cC^r(\bT^2,\bR)$ and any $f \in \cC^0(\bT^2,\bR)$, we have
\[
\begin{split}
\int \phi \, \cL_F^n(f P^{\alpha}_{n,q}u)\circ\gamma%
&=\sum_{\tilde \gamma \in F^{-n}\gamma}\int \phi \, \frac{(f P^{\alpha}_{n,q}u)\circ\tilde\gamma }{J_n \circ \tilde \gamma}\\%
&\le \sup_{\psi \in \cC^0: \|\psi\|_{\cC^0}\le 1} \int \psi \sum_{\tilde \gamma \in F^{-n}\gamma}\frac{(fP^{\alpha}_{n,q}u)\circ\tilde\gamma }{J_n \circ \tilde \gamma}\le \|f\|_{\infty} \|\cL_F^n(P^\alpha_{n,q}u)\|_0^*\,,
\end{split}
\]
and
\[
\|\re(\cL^n_F(x e^{i\nu \tau_n})\|^*_0 =\|\cL_F^n(x\cos(\nu \tau_n))\|^*_0\le \|\cL_F^n(x)\|^*_0.
\]
Obviously, an analogous estimate is true for all the other terms in the square roots in \eqref{eq:sqrt}, from which we deduce, using \eqref{eq: complex} again, that
\[
\begin{split}
|\re \cJ_1 | &\le [(\|\cL^n_F(x)\|^*_0)^2+(\|\cL^n_F(x)\|
^*_0)^2]^{1/2}+[(\|\cL^n_F(y)\|^*_0)^2+(\|\cL^n_F(y)\|
^*_0)^2]^{1/2}\\
&=\sqrt 2 (\|\cL^n_F(x)\|^*_0+\|\cL^n_F(y)\|^*_0)\\
&\le 2 \|\cL^n_F(x+iy)\|^*_0\\
&=2 \|\cL_F^n(P^\alpha_{n,q}u)\|^*_0.
\end{split}
\]



Clearly, the same estimate holds for $\im \cJ_1$ and, recalling \eqref{eq: LnP=PLn}, we thus have
\[
\sqrt{(\re(\cJ_1)^2+(\im(\cJ_1)^2}\le  2\|\cL_F^n(P^\alpha_{n,q}u)\|_0^*=2\|\partial^\alpha\cL_F^n u\|_0^*\le C\|\cL_F^n u\|_q^*.
\] 


Taking the sup over $\phi\in \cC^{|\alpha|}$, $\gamma \in \Gamma$, and $|\alpha|\le q$ in \eqref{eq:J1+J2}, by the above estimates we have\footnote{We also use the elementary inequality $\sup \sqrt{a^2+b^2}\le \sqrt{(\sup a)^2+(\sup b)^2}$.}
\begin{equation}\label{LYstar}
\|\cL_\nu^n u\|^*_{q}\le C\|\mathcal{L}_F^n u\|^*_{q}+C_{s,\tau}\lambda_c^n(1+|\nu|)^{q} \| u \|^*_{q-1}.
\end{equation}
Note that the above estimates are easier in the case $q=0$ and give, using the first of \eqref{L-Y B2}, also the weak inequality
\begin{equation}\label{eq:weak-special}
    \|\cL_\nu^n u\|^*_{0}\le C\|\cL_F^n u\|^*_0\le C\lambda_c^n \|u\|^*_0. 
\end{equation}
By the second part of \eqref{L-Y B2} (recall also that $\|\cdot\|_0 \le \|\cdot \|_{q-1}$) we have
\[
\|\cL_\nu^n u\|^*_{q}\le C\delta_*^n\| u\|^*_{q}+C_{s,\tau}\lambda_c^n(1+|\nu|)^{q} \| u \|^*_{q-1}.
\]
{Let us fix $n_0$ such that $C\delta_*^{n_0}=: \sigma_0 %\sigma_1 
<1$ and $%\sigma_1
\sigma_0\lambda_c<1$, then the above inequality gives
\[
\|\cL_\nu^{n_0} u\|^*_{q}\le %\sigma_1^{n_0}
\sigma_0^{n_0}\| u\|^*_{q}+C_{s,\tau,n_0}(1+|\nu|)^{q} \| u \|^*_{q-1}.
\]
Therefore, writing any $n\in \bN$ as $n=kn_0+m$ with $0\le m\le n_0-1$, iterating the last inequality, using \eqref{eq:weak-special}, and slightly increasing the value of $\sigma_0$ to $\sigma_1$}, we obtain

\begin{equation}\label{eq:star1}
\begin{split}
\|\cL_\nu^{n} u\|^*_{q}&=\|\cL_\nu^{n_0}(\cL_\nu^{n-n_0}u)\|^*_{q} \le %\sigma_1^n
{\sigma_0^{n_0}}\|\cL_\nu^{n-n_0}u\| ^*_q+C(1+|\nu|)^q \|\cL_\nu^{n-n_0}u\|^*_{q-1}\\
&\le C\sigma_1^n \|u\|^*_q+C(1+|\nu|)^q \sum_{j=0}^{k-1}(\sigma_1 \lambda_c)^{jn_0}\|u\|^*_{q-1}\\
&\le C\sigma_1^n \|u\|^*_q+C(1+|\nu|)^q \lambda_c^n \|u\|^*_{q-1}.
\end{split}
\end{equation}
 Next, for reasons which will be clear soon, we want the $\|\cdot\|^*_0$- norm to be the weak norm. We can achieve that by iterating the above inequality $q$ times. We get:
 \[
\|\cL_\nu^{qn} u\|^*_{q}\le C_q \sum_{j=0}^{q-1}(\sigma_1^{q-j}\lambda_c^j)^n (1+|\nu|)^{\sum_{i=0}^{j}q-i}\|u\|^*_q+ C_q(1+|\nu|)^{\sum_{i=0}^{q-1}q-i} \lambda_c^{qn}\|u\|
^*_0. 
\]
Since $\sigma_1 \lambda^{\xi(q)}<1$ by assumption \eqref{pinching condition}, the worst case in the first term is given by $j=q-1$, so that
\[
\|\cL_\nu^{qn} u\|^*_{q}\le C_q (1+|\nu|)^{\frac{q(q+1)}{2}}\left[ (\sigma_1\lambda_c^{q-1})^n \|u\|^*_q+ \lambda_c^{qn}\|u\|
^*_0\right]. 
\]
Writing any $n\in \bN$ as $n=kq+m$ with $0\leq m\leq q-1$, and using the above inequality with $qk$ and the first part of \eqref{L-Y B2} we obtain
\begin{equation}\label{eq:LYgood}
\|\cL_\nu^{n} u\|^*_{q}\le C_q (1+|\nu|)^{\frac{q(q+1)}{2}}\left[ (\sigma_1\lambda_c^{q-1})^n \|u\|^*_q+ \lambda_c^{n}\|u\|
^*_0 \right], \qquad \forall n\in \bN. 
\end{equation}
This concludes the first step.\\

\noindent\textit{Step 2} (estimate of $\|\cL^n_\nu u\|_{H^s}$).
Let us fix $n_0\in \bN$. By inequality \eqref{LY-HB0}, 
\begin{equation}\label{eq:hatsig}
\begin{split}
\|\cL_\nu^{2n_0}u\|_{H^s}&=\|\cL_F^{n_0}(e^{i\nu\tau_{n_0} }\cL_\nu^{n_0} u)\|_{H^s}\\
&\le C \hat \sigma^{n_0} \|e^{i\nu\tau_{n_0} }\cL^{n_0}_\nu u\|_{H^s}+C\|e^{i\nu\tau_{n_0}} \cL_\nu^{n_0} u\|^*_{s+2}.
\end{split}
\end{equation}
Let us estimate the two norms in the right hand side above. By \eqref{LY Hs and Hs-1} and equation \eqref{commute} applied with\footnote{Note that, when $F$ is the identity map $\operatorname{Id}$, the operators $P_{n,s}^\alpha$ are just the derivatives.} $F=\operatorname{Id}$ we have
\[
\begin{split}
\|e^{i\nu\tau_{n_0} }\cL^{n_0}_\nu u\|_{H^s}
&\le C\lambda_c^{(2s+1){n_0}}\|e^{i\nu\tau_{n_0}}u\|_{H^s}\\
&\le C\lambda_c^{(2s+1){n_0}}\|u\|_{H^s}+ C^{n_0}(1+|\nu|)^s\|u\|_{H^{s-1}}.
\end{split}
\]
Since (\cite[Lemma E.1]{CaLi}) for each $\ve>0$ we can find $C_\ve$ such that
\[
\|u\|_{H^{s-1}}\le C \ve \|u\|_{H^s}+C_\ve \|u\|_{L^1},
\]
taking $\ve$ small enough we get
\[
\|e^{i\nu\tau_{n_0} }\cL^{n_0}_\nu u\|_{H^s}\le C\lambda_c^{(2s+1){n_0}}\|u\|_{H^s}+C_{n_0}(1+|\nu|)^s\|u\|_{L^1}.
\]

Similarly, for the second term in \eqref{eq:hatsig} we first  exploit \eqref{commute} and \eqref{LYstar} for $F=\operatorname{Id}$ and $u$ replaced by $\cL^{n_0}_\nu u$, and then we use inequality \eqref{eq:LYgood}, to get
\[
\begin{split}
\|e^{i\nu\tau_{n_0}} \cL_\nu^{n_0} u\|^*_{s+2}
&\le C (1+|\nu|)^{(s+2)(s+3)/2}[(\sigma_1\lambda_c^{s+2})^{n_0}\|u\|^*_{s+2}+C_{n_0}\|u\|^*_{0}],
\end{split}
\]
 Inserting the two above estimates into \eqref{eq:hatsig}, for each $s$ we find $\sigma_2\in (0,1)$ and $q_1>0$ such that
\[
\|\cL_\nu^{2{n_0}}u\|_{H^s}\le C(1+|\nu|)^{q_1}[\sigma_2^{n_0}(\|u\|_{H^s}+\|u\|^*_{s+2})+C_{n_0}(\|u\|^*_0+\|u\|_{L^1})].
\]
Writing any $n=kn_0+m$ and iterating the above inequality yields
\begin{equation}\label{eq:LYgood2}
\begin{split}
\|\cL_\nu^{{n}}u\|_{H^s}&\le C(1+|\nu|)^{q_2}[\sigma_2^{n}(\|u\|_{H^s}+\|u\|^*_{s+2})+C(\|u\|^*_0+\|u\|_{L^1})]\\
&= C(1+|\nu|)^{q_2}[\sigma_2^{n}\|u\|_s+C\lambda_c^n(\|u\|^*_0+\|u\|_{L^1})],
\end{split}
\end{equation}
for some $q_2>0$ depending on $s$. This concludes the second step.\\

\noindent\textit{Step 3} (Merging the estimates). By \eqref{eq:LYgood} and \eqref{eq:LYgood2} we obtained:
\[
\begin{split}
\|\cL^n_\nu u\|_s& =\|\cL^n_\nu u\|_{H^s}+\|\cL^n_\nu u\|_{s+2}^*\\
&\le   C_q (1+|\nu|)^{\frac{(s+2)(s+3)}{2}}\left[ (\sigma_1\lambda_c^{q-1})^n \|u\|^*_q+ \lambda_c^{n}\|u\|
^*_0 \right]\\
&+C(1+|\nu|)^{q_2}[\sigma_2^{n}\|u\|_s+C\lambda_c^n(\|u\|^*_0+\|u\|_{L^1})]\\
&\le C(1+|\nu|)^{q_*}[\sigma_3^{n}\|u\|_s+C\lambda_c^n(\|u\|^*_0+\|u\|_{L^1})] 
\end{split}
\]
for some $q_*>0$ and $\sigma_3 \in (0,1)$.
Finally, we want to compare the $\|\cdot\|^*_0$-norm with the $L^1$ norm. We use the following (see \cite[(9.11)]{CaLi}) which holds for each $\ell>0$:\[
\|u\|^*_0\leq \ell^{-1} \|u\|_{L^1}+ \frac {2\ell^{\frac 12}}3\|u\|_{H^1}.
\]
Choosing $\ell$ sufficiently small and possibly slightly changing $\sigma_3$ and $C$, we then obtain
\begin{equation*}\label{LYB}
\|\cL^n_\nu u\|_s \le  C(1+|\nu|)^{q_*}[\sigma^{n}\|u\|_s+C\lambda_c^n(\|u\|_{L^1})]. 
\end{equation*} 
for some $\sigma\in (0,1)$. 
\end{proof}

\begin{lem}\label{lem:NoUnitEigen}
In addition to the assumptions of \Cref{lem:LYnu}, if \emph{\textbf{(B2)}} holds, then the spectrum of $\cL_\nu$ is contained in the open disk $\{z\in \bC: |z|<1\}$.   
\end{lem}

\begin{proof}
% To show that $\cL_\nu$ has no eigenvalues on the unit circle under \textbf{(B2)}. 
Assume for contradiction that there exist $\theta$ and $h \in \cB_s$ (hence, continuous) such that $\cL_\nu h = e^{i\theta} h$. Then, $|h| = |e^{i\theta} h| = |\cL_\nu h| \leq \cL_F|h|$. But $\int|h|\dd\frm = \int \cL_F |h|\dd \frm$. So, it must be the case that $\cL_F|h| = |h|\,.$ Since $h \in \cB_s$ we have that $|h| \in \cB_s$. So, recalling \eqref{eq:projection}, $$|h| = \sum_j \frac{\int |h|\mathds{1}_{D_j}\dd\frm}{\mu_*(E_j)} \rho_j\,.$$ 
In particular, there is $j_0$ such that $|h|>0$ on $\supp \rho_{j_0}$. 
Write $h = |h|e^{ig_\nu}$ on $\supp \rho_{j_0}$. Since $h$ and $|h|$ are continuous, we can take $g_\nu$ to be continuous.  %Therefore, $$\,. 
Also, note that $\cL_\nu(h) = e^{i\theta}h = e^{\theta+g_\nu}|h|$ which implies that $\cL_F(e^{i(\nu \tau + g_\nu-g_\nu\circ F - \theta)}|h|) = |h| = \cL_F(|h|)\,.$ Then, $$\int_{\supp \rho_{j_0}} \im\, (e^{i(\nu \tau + g_\nu-g_\nu\circ F - \theta)}|h|)\dd\frm = \int_{\supp \rho_{j_0}} \im\, \cL_F(e^{i(\nu \tau + g_\nu-g_\nu\circ F - \theta)}|h|)\dd \frm = 0\,.$$ Therefore, 
$$\int_{\supp \rho_{j_0}} \sin (\nu \tau + g_\nu-g_\nu\circ F - \theta) |h| \dd \frm =0\,. $$
Hence, $\nu \tau+g_\nu-g_\nu\circ F+\theta=2\pi N$ for some $N:\supp \rho_{j_0}\to \bZ$. This contradicts assumption \textbf{(B2)} because it implies that
\[
\tau=\frac{2\pi N}{\nu}-\frac{\theta}{\nu},
\]
up to a continuous coboundary term.
\end{proof}

