\begin{proof}[Proof of \Cref{thmB}]
%We generalise the method of proof \cite[Theorem 1.22]{DeKiLi} borrowing some ideas from the proof of \cite[Theorem A']{HeHe}. 
%\KF{Assume without loss of generality that $a_k=\mu_k(\tau)=0$ for all $k$. If not, consider $\bar\tau = \sum_k (\tau - \mu_k(\tau))\mathds{1}_{E_k}\, $.} 
The first part of the theorem, the LLT \eqref{fLLT}, follows directly from \Cref{thm:Hehe3}
because we have already verified the conditions in the theorem in the previous proof, and we make the assumption \textbf{(B2)} of $\tau$ being non-arithmetic. 

For the second part, let $\dd m = f_m\, \dd\frm$ be the initial probability measure.  Note that using the duality of the transfer operator, the characteristic function of $\tau_n = \sum_{k=0}^{n-1}\tau \circ F^k$ can be coded as $$\mathbb E_{m}(e^{i\nu \tau_n})= \frm(\cL^n_\nu(f_m))\,.$$
Due to \Cref{eq:EigenSplit}, there exists $\varepsilon>0$ such that for all $\nu \in (-\varepsilon,\varepsilon)$,
$$\mathbb E_{m}(e^{i\nu \tau_n}) = \sum_{k=1}^\ell\lambda_k(\nu)^n  \frm(\rho_k)\mu_k(f_m) +  \frm( K_n(\nu)f_m) +\frm(\Lambda^n(\nu)f_m)$$
where all the symbols are as in \Cref{thm:Hehe1}. 

As in the proof of \cite[Theorem A']{HeHe}, we have that
$$\lambda_k\left(\frac{\nu}{\sqrt{n}}\right)^n =\sum_{k=1}^\ell \frm(\rho_k)\mu_k(f_m) e^{-\frac{\sigma^2_k\nu^2}{2}+O(\frac{1}{\sqrt{n}})}\,.$$
Also, we know that $|\frm( K_n(\nu)f_m)| \leq C\max_k{|\lambda_k(\nu)|^n} \inf\{|\nu|,1\} \|\frm\|\|f\|\,.$

Let $L \in \mathbb R$ be such that $0<\varepsilon<L$. From \Cref{lem:NoUnitEigen}, it follows that there exists $c\in (0,1)$ such that, for all $\nu$ such that $|\nu| \in [\varepsilon, L]$,  $|\mathbb E_{m}(e^{i\nu \tau_n})|\leq Cc^n\,.$ 


Let $Z$ be an independent and a zero average random variable such that $|Z|\leq 1$ and with a smooth density $\psi$. Consider the random variable $\tilde{\tau}_n = \frac{\tau_n}{\sqrt{n}}+rZ$. Then $\tilde{\tau}_n$ has a density, $\mathcal{N}_{n, r}$, that satisfies

\[
\begin{split}
\mathcal{N}_{n,r}(y)= & \frac{1}{2 \pi} \int_{\mathbb{R}} e^{-i\nu y} \mathbb{E}\left(e^{i\nu \tilde{\tau}_n}\right) d\nu \\
= & \frac{1}{2 \pi} \int_{\mathbb{R}} e^{-i\nu y} \mathbb E_{m}(e^{i\frac{\nu}{\sqrt{n}} \tau_n}) \widehat{\psi}(\varepsilon\nu) d\nu \\
= & \frac{1}{2 \pi} \int_{-\varepsilon\sqrt{n}}^{\varepsilon\sqrt{n}} e^{-i\nu y}\left[\sum_{k=1}^\ell c_k e^{-\frac{\sigma^2_k\nu^2}{2}+O(\frac{1}{\sqrt{n}})}+\frm( K_n\left(\frac{\nu}{\sqrt{n}}\right)f_m)+O\left(c^n\right)\right] \widehat{\psi}(\varepsilon\nu) d\nu \\
&\quad\quad+O\left(c^n\right)+\frac{1}{2 \pi} \int_{|\nu| \geqslant L\sqrt{n} } e^{-i\nu y} \mathbb E_{m}(e^{i\frac{\nu}{\sqrt{n}} \tau_n})  \widehat{\psi}(\varepsilon\nu) d\nu
\end{split}
\]
where $\, \widehat{\cdot}\,$ denotes the Fourier transform. To obtain the complete asymtptotics, we use \Cref{thm:Hehe1} and note that  for $n$ sufficiently large, there exists $c>0$ such that
\begin{align*}
    \int_{- \varepsilon\sqrt{n}}^{ \varepsilon\sqrt{n}}\frm(K_n\left(\frac{\nu}{\sqrt{n}}\right)f_m)\, \dd\nu &\lesssim \int_{-1}^{1}\frac{t}{\sqrt{n}}\,\dd\nu+\int_{1\leq|\nu|\leq \varepsilon\sqrt{n}}\frac{|t|}{\sqrt{n}} e^{-ct^2/4}\,dt\\ &=O\left(\frac{1}{\sqrt{n}}\right)+O\left(\frac{1}{\sqrt{n}}\right)e^{-ct^2/4}\Big|_{1}^{ \varepsilon\sqrt{n}} = O\left(\frac{1}{\sqrt{n}}\right). 
\end{align*}


Using that $|\widehat{\psi}(\nu) |\lesssim |v|^{-\delta}$ for all $\delta>0$, we have
$$\mathcal{N}_{n, r}(y) = \sum_{k=1}^\ell\frac{c_k}{\sqrt{2\pi \sigma^2_k}} e^{-\frac{y^2}{2\sigma^2_k}} + O \left(\frac{1}{\sqrt{n}}+\frac{1}{\ve^{\delta}n^{(\delta-1)/2}}\right)\,$$
where $c_k =\frm(\rho_k)\mu_k(f_m)$.


So, to have a meaningful estimate, we set $\delta>2$. From now on we can argue almost exactly as in the proof \cite[Theorem 1.22]{DeKiLi}: on the one hand we have,
\[
\begin{split}
\mathbb{P}_m\left(\frac{\tau_n}{\sqrt n} \in[a, b]\right)&\le \mathbb{P}_m\left(\frac{\bar{\tau}_n}{\sqrt n} \in[a-\ve, b+\ve]\right)\\
& \leqslant \int_{a-\varepsilon}^{b+\varepsilon}\sum_{k=1}^\ell\frac{c_k}{\sqrt{2\pi \sigma^2_k}} e^{-\frac{y^2}{2\sigma^2_k}}dy + (b-a)\,O \left(\frac{1}{\sqrt{n}}+\frac{1}{\ve^{\delta}n^{(\delta-1)/2}}\right)  \\
& \leqslant \sum_{k=1}^dc_k \int_{a}^b \fn\left(\frac{y }{\sigma_k}\right)\, dy+O\left(\varepsilon {\max_k \fn\left(\frac{a}{\sigma_k}\right)}\right)\\
&\quad\quad + (b-a)\,O\left(\frac{1}{\sqrt{n}}+\frac{1}{\ve^{\delta}n^{(\delta-1)/2}}\right)
\end{split}
\]
and similarly for the lower bound. Choosing $\ve=n^{\frac{1}{\delta}-\frac 12}$ we conclude that the error estimate is up to a constant times
$$\left(\frac{\max_k \fn\big(\frac{a}{\sigma_k}\big)}{n^{\frac 12-\frac 1\delta}}+\frac{b-a}{\sqrt{n}}\right)\,.$$ 
The statement on the $\sigma_k$, and the conclusion, follow from the Green-Kubo formula
\[\sigma^2_k = \mu_k(\tau_k^2)+2\sum_{j=1}^\infty \mu_k(\tau_k\cdot\tau_k\circ F^j).\qedhere\]
\end{proof}

