\section{Abstract functional analytic framework for the CLT}\label{app:AbstractCLT}

Let $(E, \mathcal{E}, \frm)$ be a measure space. Suppose $(\cB, \|\cdot\|)$ is a complex Banach lattice\footnote{$f\in \cB \implies |f|, \bar f \in \cB$} and algebra\footnote{for all $f, g \in \cB$, $f\cdot g \in \cB$} of measurable function on $E$. %such that $\frm \in \cB^\prime$\, and for all $f, g \in \cB$, $f\cdot g \in \cB$.
%\footnote{There is an additional assumption in the book $\delta_x \in \cB^\prime $ for all $x\in E$. But this is very restrictive and is, in fact, not necessary. See the next page.}


Let $F$ be a non-singular transformation on $E$. Let the Transfer operator $\cL_F : \cB \to \cB$ be defined by 
$$\frm (f \circ F \,\, g) = \frm (f \,\cL_F(g) ),\,\,\,\forall g \in L^{\infty}\,.$$
Suppose that:
\begin{enumerate}
    \item  $\cL_F$ is quasi-compact with spectral radius $r(\cL_F)=1$,\footnote{$\cB = J \oplus H$ with $J,H$ $\cL_F$-invariant $r(\cL_F|_H) < 1$, $\dim J < \infty$, and each eigenvalue of $\cL|_J$ has modulus $1$.} and $\sup_n \|\cL^n\| < \infty\,.$
    \item There exist $\ell$ non-negative functions of $\cB$, denoted by $\rho_1,\dots,\rho_\ell$ that forms a basis for Ker$(\cL_F - \Id) \cap \cB\,$ and $\frm\left(\bT^2 \setminus \bigcup_{j=1}^d \supp \rho_j\right) =0\,.$\footnote{This assumption can be dropped by restricting the spaces to $\bigcup_{j=1}^\ell \supp \rho_j$ as explained in \cite{HeHe}.}
    \item There exist $\cL_F-$invariant probability measures $\mu_1, \dots,\mu_\ell$ in $\cB^\prime$ such that $\mu_k(\rho_m) = \delta_{k,m}$. 
\end{enumerate}


\vspace{10pt}

Let $\tau$ be a measurable function and $\nu \in \bR$ and the twisted transfer operators $\cL_\nu$ be
$$\cL_{\nu}(\cdot) := \cL_F(e^{i\nu \tau} \cdot)\,.$$
Suppose that:
\begin{enumerate}[start=4]
    \item  For all $\nu$, $\cL_\nu$ is a bounded linear operator on $\cB$.
    %\item  $\nu \mapsto \cL_{\nu}$ is continuous as a function from $\bR$ to the space of bounded linear operators on $\cB$; $\fC(\cB,\cB)$.
    \item[(5-r)]There exists $\delta>0$ such that $\nu \mapsto \cL_{\nu}$ is $r$ times continuous differentiable as a function from $(-\delta, \delta)$ to $\fC(\cB,\cB)$, the space of linear bounded operators on $\cB$.\footnote{The derivative can be formally computed, e.g., $k$th derivative at $\nu$ is $\cL((i\tau)^ke^{i\nu\tau}\cdot)$} 
\end{enumerate}


\begin{oss}
In \cite{HeHe}, the assumptions cover the more general case of $\bigcup_{j=1}^d \supp \rho_j$ not having full measure and construct an auxiliary Banach space of functions restricted to $\bigcup_{j=1}^d \supp \rho_j$ (see \cite[Chapter XI]{HeHe}). However, for our applications this is too general. So, we make the assumption that $\bigcup_{j=1}^d \supp \rho_j$ is a full $\frm-$measure set, and we no longer require this auxiliary Banach space construction. Furthermore, due to the discussion in \cite{AV}, the assumption that $\delta_x \in \cB^\prime$ in \cite{HeHe} can also be dropped. 
\end{oss}

\begin{oss}
Define spaces $\cB_j, j=1,\dots,d$ as follows
$$\cB_j = \{ f|_{\supp \rho_j} | f \in \cB\}$$
and equip them with the norm $\|f\| = \inf \left\{\|g\| \big|\,g\in \cB\,, g|_{\supp \rho_j}=f \right\}$\,. Then $B_j$'s are Banach lattices (see \cite{HeHe}), and because $\cB$ is an algebra, $\cB_j$'s are algebras too. 
\end{oss}

Now, we can state the abstract results in \cite{HeHe} we have used in our paper which are adapted version of \cite[Theorem 2.3]{HeHe} and \cite[Theorem 4.1]{HeHe}.

\begin{thm}\label{thm:Hehe1}
Let $\tau \in L^r(\rho_j)$ for all $j$. Suppose the Assumptions (1) to (5-r) hold. Then there exist $C>0$, $c \in (0,1)$, $\varepsilon>0$, $C^r$ maps $\nu \mapsto \lambda_{k}(\nu), \nu \mapsto K_n(\nu), \nu \mapsto \Lambda(\nu)$ such that $\lambda_k(0)=1$, $\lambda^{\prime}_k(0)= i \mu_k(\tau)$, $\lambda^{\prime\prime}_k =: \sigma^2_k \geq 0$ and such that for all $n \geq 1$,  for all $\nu \in (-\varepsilon,\varepsilon)$, for all $f \in \cB$ and $g \in \cB^{\prime}$,
\begin{equation}\label{eq:EigenSplit}
    \langle  g , \cL_\nu (f) \rangle = \sum_{k=1}^\ell\lambda_k(\nu)^n  \langle g ,\rho_k \rangle \langle \mu_k , f \rangle + \langle g , K_n(\nu)f \rangle+\langle g , \Lambda^n(\nu)f \rangle\,.
\end{equation}
In addition, the following hold. 
\begin{enumerate}
    \item $|\langle g , K_n(\nu)f \rangle| \leq C\max_k{|\lambda_k(\nu)|^n} \inf\{|t|,1\} \|g\|\|f\|$\,.
    \item $|\langle g , \Lambda^n(\nu)f \rangle| \leq C c^n \inf\{|t|,1\} \|g\|\|f\|$\,.
\end{enumerate}
\end{thm}

\begin{thm}\label{thm:Hehe2} Let $\tau \in L^r(\rho_j)$ for all $j$ and assume there do not exist $c$ and $\xi \in  L^r(\rho_j)$ such that $\tau|_{\supp \rho_j} = c + \xi\circ F - \xi$. Suppose the Assumptions (1) to (5-r) hold
\begin{itemize}
    \item with $r=2$, then the general CLT \eqref{CLT} holds.  
    \item with $r=3$, then the general Berry-Esseen \eqref{BEst} estimate holds.
\end{itemize}
Further assume that for all $j$ there do not exist $a>0$ and $b \in \bR$ and $\xi \in  L^r(\rho_j)$ such that $\tau|_{\supp \rho_j} - \xi\circ F + \xi$ is $a\bZ+b$ valued. Suppose the Assumptions (1) to (5-r) hold with $r=2$, then the general LLT \eqref{fLLT} holds. 
\end{thm}

\begin{thm}\label{thm:Hehe3} Let $\tau \in L^r(\rho_j)$  and assume that for all $j$ there do not exist $a>0$ and $b \in \bR$ and $\xi \in  L^r(\rho_j)$ such that $\tau|_{\supp \rho_j} - \xi\circ F + \xi$ is $a\bZ+b$ valued. Suppose the Assumptions (1) to (5-r) hold with $r=2$, then the general LLT \eqref{fLLT} holds.
\end{thm}



