\section{Differential operators}
In this section we proof a Lemma about the commutation of the twisted transfer operator and the differential operators.





Before giving the statement, let us recall some notation and formulas derived in \cite{CaLi} for the commutator of the transfer operator $\cL_F$ with differential operators. All the derivatives in the following are meant in the weak sense. For a smooth function $u:\bR^2\to \bR$, a diffeomorphism $F:\bR^2\to \bR^2$ and a vector $v \in \bR^2$, %we define the functions from $\bR^2$ to $\bR$ by
define
\[
\begin{split}
&\partial_v u:=\langle \nabla u, v \rangle,		\\
&\partial_{{F^*}v} u:=\langle \nabla u, (DF)^{-1}v \rangle
\end{split}
\]
viewed as functions from $\bR^2$ to $\bR$. In addition, for any multi-index $\alpha=(\alpha_1,..,\alpha_k)\in \{1,2\}^k$ with $k\le s$, we define the linear operator $\partial^\alpha$ acting on $\cC^\infty(\bT^2)$ as
\[
\partial^\alpha u=\partial_{x_{\alpha_k}} \cdots \partial_{x_{\alpha_1}} u.
\]

Then, by \cite[Corollary 6.3]{CaLi},
\begin{equation}\label{eq: LnP=PLn}
\partial^{\alpha} \cL_F^n u=\cL_F^n P^{\alpha}_{n, k} u
\end{equation}
where\footnote{We denote by $\{e_{i}\}_{i=1}^2$ the usual orthonormal base of $\bR^2$.}
\begin{equation}\label{definition of P}
\begin{split}
&P^{\alpha}_{n, 0}u=u,\\
& P^{\alpha}_{n, 1}u=A_n^{\alpha_1}u-A_n^{\alpha_1}J_n\cdot u,\\
&\quad \vdots 
\\
&P^{\alpha}_{n,k}u=A^{\alpha}_{n,1}u
-\sum_{j=1}^{k}A^{\alpha}_{n,j+1}((A^{\alpha_{j}}_n J_n)
\cdot  P^{\alpha}_{n, j-1}u) \quad \textit{ for } k\ge 2,
\end{split}
\end{equation}
with $A_n^{\alpha_j}=\partial_{F^{n^*}e_{\alpha_j}}$, $A_{n,j}^{\alpha}:=A_n^{\alpha_k}\cdots A_n^{\alpha_{j}}$, $A_{n, %t+1
k+1}^{\alpha}=\text{Id}$ and $J_n:=\log |\det DF^n|$. For example, for  $s=1$, $\alpha_j$ corresponds to $\partial_{x_j}$ and we have
\begin{equation}\label{Lprime}
\begin{split}
\partial_{x_j} \mathcal{L}_F^n u= \mathcal{L}_F^n\left(\partial_{F^{n^*}e_j} u -\partial_{F^{n^*}e_j}  J_n\cdot  u\right)=\mathcal{L}_F^n \left( P^{\alpha}_{n, 1}u\right).
\end{split}
\end{equation}

Note that there exists $\Lambda>0$ such that, setting $d_{j,i}=\langle (DF^n)^{-1}e_{j}, e_j\rangle$, then $A_n^{\alpha_j} =\sum_{i=1}^2d_{j,i}\partial_{x_j}$ (i.e. $A_n^{\alpha_j} $ are differential operators) and   
\begin{equation}\label{diffop}
\|d_{j,i}\|_{\cC^k}\le \|(DF^{n})^{-1}\|_{\cC^k}\le \Lambda^{n},
\end{equation}
for each $1\le k\le s.$

\begin{lem}\label{lem:commute}
For each $s \ge 1, n\in \bN$ and for each $k\in \{1,..,s\}$, there exist\\ $m_k, \{a_{j,k}\}_{j\le m_k},\{ \beta_{j,k}\}_{j\le m_k}, \{\gamma_{j,k}\}_{j\le m_k}\in \bN$, with $j_k\le m_k$, and  operators $\{\cD^u_{j,k}\}_{j\le m_k}$ and $\{\cD^\tau_{j,k}\}_{j\le m_k}$  such that, for each $\nu$ and $\alpha$,
\begin{equation}\label{commute}
\partial^\alpha \cL^n_\nu u=\cL_F^n(e^{i\nu \tau_n}P^{\alpha}_{n,s}u)+\cL^n_F\left( e^{i\nu\tau_n}\sum_{k=1}^s (i\nu)^k\sum_{j=1}^{m_k}  a_{j, k}(\cD^u_{j,k}u)^{\beta_{j,k}}(\cD^\tau_{j,k}\tau_n)^{\gamma_{j,k}}\right).
\end{equation}
Moreover, for each $k\in \{1,..,s\}$ and $j\le m_k$, $\cD^u_{j,k}$ are differential operators of order smaller than $s-1$ and $\cD^{\tau}_{j,k}$ are differential operators of order smaller than $s$. Finally, the $\cC^k$ norm of the coefficients of $\cD^u_{j,k}$ and $\cD^{\tau}_{j,k}$ is bounded by $C_{s} \Lambda^n$, for some $C_s>0$.
\end{lem}
\begin{proof}
We are going to show the cases $s=1$ and $s=2$. The general case is just a straightforward generalization of those two using Leibniz formula for higher derivatives, and it is left to the reader. \\
For each vector $v\in \bR^2$
\[
\partial_{F^{n^*}v}(e^{i\nu\tau_n} u)=e^{i\nu\tau_n}(\partial_{F^{n^*}v} u+i\nu u \partial_{F^{n^*}v} \tau_n
),\]
and, for $\alpha=\alpha_1$,
\begin{equation}\label{eq:Palpha}
P^\alpha_{n,1}(e^{i\nu \tau_n} u)=e^{i\nu\tau_n}(P^\alpha_{n,1} u+i\nu A^{\alpha}_n \tau_n).
\end{equation}
Therefore, using $\cL^n_\nu(u)=\cL_F^n(e^{i\nu\tau_n}u)$ and \eqref{Lprime},  we have 
\[
\begin{split}
\partial_{x_1} \mathcal{L}_{\nu}^n u&= \mathcal{L}_F^n\left(e^{i\nu\tau_n}(\partial_{F^{n^*}e_1} u -\partial_{F^{n^*}e_1}  J_n\cdot  u)\right)+i\nu \cL_F^n(e^{i\nu\tau_n} u \cdot \partial_{F^{n^*}e_1} \tau_n )\\
&=\mathcal{L}_F^n\left(e^{i\nu\tau_n}P^{\alpha}_{n, 1}u\right)+i\nu \cL_F^n(e^{i\nu\tau_n} u \cdot A_n^{\alpha}\tau_n ).
\end{split}
\]
An analogous computation yields the formula for $x_2$. We can thus obtain \eqref{commute} with 
\[
 m_1=a_{1,1}=\beta_{1,1}=\gamma_{1,1}=1,\quad \cD^u_{1,1}=\Id,\quad\cD^\tau_{1,1}=A^{\alpha}_n.
\]
The bound on the norm of coefficients of $A^{\alpha}_n$ is given by \eqref{diffop}.\\
Differentiating again, for example in the $x_1$-direction, and using the above formula for the first derivative and \eqref{Lprime}, we have
\[
\begin{split}
\partial_{x_1}^2 \cL^n_\nu u&= \partial_{x_1}(\mathcal{L}_F^n\left(e^{i\nu\tau_n}P^{\alpha}_{n, 1}u\right))+i\nu \partial_{x_1}(\cL_F^n(e^{i\nu\tau_n} u \cdot A_n^{\alpha}\tau_n ))\\
&=\cL_F^n(P^{\alpha}_{n,1}(e^{i\nu \tau_n}P^{\alpha}_{n,1}u))+i\nu \cL_F^n(P^\alpha_{n,1}(e^{i\nu\tau_n} u \cdot A_n^{\alpha}\tau_n) ).
\end{split}
\]
Hence, using \eqref{eq:Palpha}, we obtain
\[
\begin{split}
\partial_{x_1}^2 \cL^n_\nu u&=\cL_F^n(e^{i\nu \tau_n}P^{\alpha}_{n,1}(P^{\alpha}_{n,1}u))\\
&+\cL^n_F\left( e^{i\nu\tau_n}(2i\nu (P^\alpha_{n,1}u)\cdot(A_{n,1}^\alpha \tau_n) +i\nu u\cdot P^{\alpha}_{n,1}(  A_{n,1}^\alpha \tau_n)-\nu^2 u\cdot ( A_{n,1}^\alpha \tau_n)^2 ) \right).
\end{split}
\]
A similar computation holds for the derivative in the $x_2$-direction.
So we obtain \eqref{commute} with $m_1=2, m_2=1$ and
\[
(a_{1,1}, a_{2,1}, a_{1,2})=(2,1,1), \quad (\beta_{1,1},\beta_{2,1}, \beta_{1,2})=(1,1,0), \quad (\gamma_{1,1},\gamma_{2,1}, \gamma_{1,2})=(1,1,2)
\]
and
\[
\begin{split}
&(\cD_{1,1}^u, \cD_{2,1}^u, \cD_{1,2}^u)=(P^\alpha_{n,1}, Id,Id)\\
&(\cD_{1,1}^\tau, \cD_{2,1}^\tau, \cD_{1,2}^\tau)=(A^\alpha_{n,1}, P_{n,1}^\alpha \circ A^\alpha_{n,1},A^\alpha_{n,1}).
\end{split}
\]
The $\cD_{j,k}^u$ operators, where $k\in\{1,2\}$, are up to order $1$, while the $\cD_{j,k}^u$ operators are up to order $2$. The bound on the norm of the coefficients is given again by \eqref{diffop}.
\end{proof}
