\section{Previous results on  \texorpdfstring{$F$}{Lg} and \texorpdfstring{$\cL_F$}{Lg}  }
For the convenience of the reader, in this Appendix we collect some consequences of several results obtained in \cite{CaLi} for the SVPH system $F$ and the associated transfer operator $\cL=\cL_F$ which are used throughout the paper.\\

\begin{itemize}
\item There are constant cones $\fC_u \supset e_1$ (which is $DF$-invariant) and $\fC_c \supset e_2$ (which is $(DF)^{-1}$-invariant), numbers $\lambda> \lambda_c>1$ and $C_1,C_2>0$ such that 
\begin{equation}\label{PHS}
\begin{split}
&\|DF^n|_{\fC_u}\|> C_1\lambda^{n}\\
(C_2 \lambda_c^n)^{-1}<&\|DF^n|_{\fC_c}\|<C_2 \lambda_c^n
\end{split}
\end{equation}
\item By the second equation of \cite[(5.17)]{CaLi}:
\begin{equation}\label{DF-1}
   { \|(DF^n)^{-1}\|_{\cC^0(\bT^2)}}\le C\lambda_c^n.
\end{equation}
\item 
By \cite[Prop. 5.6]{CaLi} there exists a constant $C_*\ge1$ such that, for every $z\in \mathbb{T}^2$, any $n\in\bN$, any vectors $v^u\in \mathbf{C}_u$ and $v^c\in \mathbf{C}_c$ such that $(a,b):=D_zF^{n}v^c\not\in \mathbf{C}_u$, we have :
\begin{equation}\label{det-form}
 C_*^{-1}\frac{\|D_zF^n v^u\|}{\|v^u\|}\frac{ |b|}{\|v^c\|}\le |\det D_zF^n|\le C_* \frac{\|D_zF^n_z v^u\|}{\|v^u\|}\frac{ |b|}{\|v^c\|}.
\end{equation}
In particular: there is $C_*>0$ such that for each $n\in \bN$, $z\in \bT^2$ 
\begin{equation}\label{det-est}
C_*^{-1} \lambda_c^{-n} \lambda^{n}\le |\det DF^n(z)|\le C_* \Lambda^n \lambda_c^n
\end{equation}
where $\lambda=\inf_{(x,y)\in\bT^2} \partial_x f(x,y)$ and $\Lambda=\sup_{(x,y)\in\bT^2}\partial_x f(x,y)$.\\
\item By \cite[Lemma 5.18 and Corollary 5.20]{CaLi} 
\begin{equation}\label{C1norm}
\begin{split}
&\|\cL^n 1\|_{\cC^0(\bT^2)}\le C\lambda_c^n\\
&\|\cL^n 1\|_{\cC^1(\bT^2)}\le C\lambda_c^{2n}.
\end{split}
\end{equation}\\
\item By \cite[Corollary 6.7]{CaLi}, for each $q\in \bN$ there exists $C,C_\sharp$ and $\delta_*\in (0,1)$ such that $\delta_*\lambda_c<1$ and, for each  and $u\in \cC^{r-1}(\bT^2)$, $n\in \bN$,
\begin{equation}
\label{L-Y B2} 
\begin{split}
\|\cL_F^n u\|^*_0 &\le C\lambda_c^n \|u\|^*_0 \\
\|\mathcal{L}^n_F u \|^*_{q} &\le  C_\sharp\delta_\ast^{n} \|u\|^*_{q}+ C\lambda_c^n\|u\|^*_{0}.
\end{split}
\end{equation}
    \item By \cite[Lemma 7.1]{CaLi} and \eqref{C1norm}, $\cL_F$ is bounded as an operator in $H^s(\bT^2)$ and for each $n\in \bN$ there are $C>0$ such that,
\begin{align}
&\| \cL^n u\|_{L^2}\le C\lambda_c^n \|u\|_{L^2}\label{L2 norm transfer}\\
&\|\mathcal{L}^n u\|^2_{H^s}  \le  C\lambda_c^{2(s+1)n}
\|u\|^2_{H^s}+C \lambda_c^{3n}\|u\|^2_{\cH^{s-1}}\label{LY Hs and Hs-1}.
\end{align}
Moreover, iterating \cite[(9.9)]{CaLi} there exist $C>0$ and $\hat \sigma_s\in (0,1)$ which can be chosen (see \cite[(9.3)]{CaLi} and the assumptions on the map $F$) equal to\footnote{Recall that $\xi_s=6(s+1)!$.} $\lambda_c^{\xi_s}\lambda_-^{-1}$, such that for each $n,s\in \bN$
\begin{equation}\label{LY-HB0}
\|\cL^n u\|_{H^s}\le \hat \sigma^n\|u\|_{H^s}+C\|u\|^*_{s+2}.
\end{equation}
\item By \cite[Lemma F.1, (G2) ]{CaLi} there exists\footnote{In our case the quantity $C_{\lambda_c,n}$ which appear in \cite{CaLi} can be bounded by a constant uniform in $n$ which might depends on $\lambda_c$ (see \cite[Remark 5.7]{CaLi}).} $C>1$ such that, for each $z_1,z_2\in \bT^2$, $v\in \fC^u$ unitary and $n\in \bN$
\begin{equation}\label{Lipsh}
\|D_{z_1}F^{n}v-D_{ z_2}F^{n}v\|\le L_{n}\|z_1-{z}_2\|
\end{equation}
where $L_n=C\lambda_c^{5n}$.
\end{itemize}


