\section{Viable investment}
To introduce what we mean here by a viable investment, consider an investor with initial capital $L$ (the value of the investment may be a cash or its equivalent labor value) whom invests on an asset  $R$ and expects the income $R_T$ at a futur time $T>0$.  Two situations may happen: 
 \begin{enumerate}
 \item[$\diamond$] even the operation has succeeded and the income $R_T$ at time $T$ is  greater than $L$, in which case  its {\em profit} is   $(R_T - L)^{+}$,
% \begin{equation*}
%  (R_T - L)^{+},
% \end{equation*}
  \item[$\diamond$] or, it failed because $R_T \le L$. In this case its {\em loss} is   $- (L-R_T)^{+}$.
%  \begin{equation*}
%  - (L-R_T)^{+}.
%   \end{equation*}
 \end{enumerate}
 Let us define the expected profit of such a given  investor as  $ \mathbb E (R_T - L)^{+}$, 
% \begin{equation}
% \mbox{E}_{\mbox{\tiny profit}} (R_T,L) : =  \mathbb E (R_T - L)^{+},
% \end{equation}
 and its expected loss as $  \mathbb E (L - R_T )^{+}$.
% \begin{equation}
% \mbox{E}_{\mbox{\tiny loss}} (R_T,L) : =  \mathbb E (L - R_T )^{+}.
% \end{equation}
% \textcolor{red}{ 
 We also define the  {\em expected investment profit} as  $ \Delta(R_T,L) =  \mathbb E (R_T - L)^{+}   -    \mathbb E (L - R_T )^{+}$, 
% \begin{equation}
% \Delta(R_T,L) =  \mathbb E (R_T - L)^{+}   -    \mathbb E (L - R_T )^{+} ,
% \end{equation}
 {\em the investment risk}  (supposing that $R_T \not \equiv L$, in which case $\mathbb E (R_T - L)^{+}  >0$) as 
 \begin{equation}
 \rho(R_T,L)  =  \frac{   \mathbb E (L - R_T )^{+}  }{  \mathbb E (R_T - L)^{+}   }
 \end{equation}
 and the {\em  expected investment return} (or the {\em investment opportunity}) as $ \beta(R_T,L):=$  $  \Delta(R_T,L)  \, / \, $  $  \mathbb E (R_T - L)^{+}   $  $= 1 - \rho(R_T,L)$.
% \begin{equation}
% \beta(R_T,L) =   \frac{ \Delta(R_T,L) }{  \mathbb E (R_T - L)^{+} }  = 1 - \rho(R_T,L).
% \end{equation}
