 Our aim now is to generalise Proposition \ref{Prop-Musharakah-d-Partners2Parts} to a {\em PL-sharing musharakah} contract with several partners.  


 \subsection{Fair profit  sharing ratio: the general framework} 


 We consider a {\em PL sharing - musharakah} contrat between $d$  partners: Partner  1, $\ldots$,   and  Partner $d$ (when $d=2$, the partnership  may be for example  between a bank and a company, between two companies, between two banks, etc), who contributed amounts to the  capital are   $L_1$, $\ldots$,  and $L_d$, respectively.  So, let $L=L_1+ \cdots + L_d$ be the initial  capital, and, define  $\kappa_{\ell} = L_{\ell}/L$,   as the equity stake of partners $\ell$, for every $\ell \in \{1, \ldots, d\}$. Finally,   let us denote by $(\gamma_1, \ldots,  \gamma_d)$, with $\gamma_1$ $+$ $\cdots$ $+$ $\gamma_d=1$, the profit sharing ratios of the partners. We want to determine the fair profit sharing between the  partners.  

 \medskip

 As previously,  $R_T$ denotes the net income process of the investment  at the maturity $T$ of the contract. Then,  at the maturity of the contract, the expected payoff of any Partner $\ell$ is given by 
 \begin{equation}  \label{Eq-Payoff-ell}
\mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell}) =  \gamma_{\ell} \,  \mathbb E(R_T-L)^{+}  - \kappa_{\ell} \, \mathbb E(L-R_T)^{+}.
 \end{equation}
%  \item[$\diamond$] the payoff of Partner $2$  is 
% \begin{equation}
% \gamma_2 \,  (R_T-L)^{+}  - \kappa_2 (L-R_T)^{+}.
% \end{equation}
% \end{enumerate}
We next  define a $(c_1, \ldots, c_d)$-fair {\em PL - musharakah} contract. 

\begin{defn} \label{Def-musharakah} A  viable $T$-term and $R$-asset based  {\em PL - musharakah} contract of  $d$ partners is said to be $(c_1, \ldots,c_d)$-{\em fair} if 
\begin{equation}  \label{Eq-Def-musharakah}
 c_1  \mbox{Pay}_1 (\gamma_1,\kappa_1) = \cdots =   c_{d} \,  \mbox{Pay}_d (\gamma_d,\kappa_d).
\end{equation}
\end{defn}

Now, define some sets that will be used in the sequel: we denote the set 
\begin{equation*}
\mathcal{P}_d = \{1, \ldots, d\}     \qquad \mbox{ and } \quad  \bar{\mathcal {P}}_d (\ell) = \mathcal {P}_d \backslash \{\ell\}.
\end{equation*}


The following result gives the profit sharing ratio of each partner of a  {\em PL - musharakah} contract. 




 \begin{prop}  \label{Prop-Musharakah-d-PartnersdParts} Consider  a  viable   $T$-term and $R$-asset based  {\em  PL - musharakah} contract of  $d$ partners whom manage themselves the project  and agree, according to their contribution to the funding and the management of the project,  to rate their respective payoff by the coefficients $c_1$, $\ldots$ and $c_d$, then, the $(c_1,\ldots, c_d)$-fair profit sharing ratios are given by
 \begin{eqnarray} 
 \gamma_{\ell}  &=& c_{\ell, \bar {\ell}}  \,\beta(R_T,L) + \kappa_{\ell}   \, \rho(R_T,L) \label{EqPart1-d-Prop1}  \\
  &=& c_{\ell, \bar {\ell}}  \,\big(1-\rho(R_T,L) \big) + \kappa_{\ell}   \, \rho(R_T,L),   \quad \mbox{ for any } \ \ell \in \mathcal{P}_d, \label{EqPart1-d-Prop2}
\end{eqnarray}
where the weights  $(c_{\ell, \bar {\ell}})_{\ell \in {\cal P}_d}$ are defined for every $\ell \in {\cal P}_d$ by
\begin{equation}  \label{Eq-weights}
c_{\ell, \bar {\ell}}  = \Big(\prod_{i \in \bar{\mathcal{P}}_d (\ell)} c_i \Big)\  \big /  \, \Big(\sum_{j=1}^d \prod_{i \in \bar{ \mathcal{P}}_d (j)} c_i \Big).
\end{equation}
Furthermore, the expected payoff of each partner $\ell$ is given by
\begin{equation}
\mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell})  = c_{\ell, \bar {\ell}}\, \Delta(R_T,L),  \qquad \ell =1, \ldots,d.
\end{equation}
This means that the partners will share the {\em expected investment profit}   $\Delta(R_T,L)$ with the respective weights  $c_{\ell, \bar {\ell}}$.
\end{prop}
\medskip

A particular case of interest is the situation where $d-1$ partners of a {\em PL-sharing musharakah } contract   appoint a manager (Partner $d$) outside of them and  are bounded to him by a {\em PL-sharing mudharabah} contract. This appears to be a  particular case of Proposition \ref{Prop-Musharakah-d-PartnersdParts} that  we state as a corollary.

 \begin{cor}  \label{Cor-Musharakah-d-PartnersdParts} Consider  a  viable   $T$-term and $R$-asset based  {\em  PL - musharakah} contract of  $d-1$ partners who  appoint a manager (Partner $d$) outside of them and  are bounded to him by a {\em PL-sharing mudharabah} contract.  If they agree, according to their contribution to the funding and the management of the project,  to rate their respective payoff by the coefficients $c_1$, $\ldots$ and $c_d$, then, the $(c_1,\ldots, c_d)$-fair profit sharing ratios are given by
 \begin{eqnarray} 
&&  \gamma_{\ell} \  = c_{\ell, \bar {\ell}}  \,\big(1-\rho(R_T,L) \big) + \kappa_{\ell}   \, \rho(R_T,L),  \quad \ell=1, \ldots,d-1,  \label{EqPart1-d-Cor1}   \\
  &&   \gamma_{d} \  = \ c_{d, \bar {d}}   \,\big(1-\rho(R_T,L) \big),    \label{EqPart1-d-Cor2}
\end{eqnarray}
where for any $\ell \in {\cal P}_d$, $c_{\ell, \bar {\ell}}$ is defined from \eqref{Eq-weights}. Furthermore, the expected payoff of each partner $\ell$ is given by
\begin{equation}
\mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell})  = c_{\ell, \bar {\ell}}\, \Delta(R_T,L),  \qquad \ell =1, \ldots,d.
\end{equation}
\end{cor}
\medskip


Let us make the following remarks  before giving the proof of Proposition \ref{Prop-Musharakah-d-PartnersdParts}.
\medskip

\begin{rem}  \label{Rem-MainResult-1} Recall that  the coefficients $(c_{\ell})_{\ell \in {\cal P}_d}$ are put to rate  the contribution on the management of the project.  The associated coefficients we define as the function 
 \begin{eqnarray*}
 &&  \mbox{w} : {\cal P}_d \longrightarrow {\cal P}_d\\
 &&                    \hspace{0.55cm} c_{\ell}\, \longmapsto \mbox{w} (c_{\ell}) =   c_{\ell, \bar {\ell}}
 \end{eqnarray*}
  are the corresponding sharing weights  of the {\em expected investment profit}  $\Delta(R_T,L)$  (note in fact that $\mbox{w} (c_{1}) + \cdots + \mbox{w} (c_{d}) =1$).  It is clear from Equation \eqref{Eq-weights} that the smaller is the rate coefficient $c_{\ell}$, the bigger will be the associated weight $\mbox{w} (c_{\ell}) =   c_{\ell, \bar {\ell}}$.  



  Besides, owing to Equation \eqref{EqPart1-d-Prop2} (or  to equations \eqref{EqPart1-d-Cor1} and \eqref{EqPart1-d-Cor2}) that may be decomposed as
  \begin{equation*}
  \gamma_{\ell} =   \underbrace{ c_{\ell, \bar {\ell}}  \, \big(1-\rho(R_T,L)  \big)}_{\footnotesize \mbox{labor reward}} + \underbrace{\kappa_{\ell}   \, \rho(R_T,L)}_{\footnotesize \mbox{funding reward}},
