Let us prove now Proposition \ref{Prop-Musharakah-d-PartnersdParts}).


\begin{proof}  (of Proposition \ref{Prop-Musharakah-d-PartnersdParts})] Let $\ell \in \{1, \ldots, d\}$. Supposing that the contract is $(c_1, 
\ldots, c_d)$-fair, we have in particular
  \begin{equation*} 
   \left\{
	 \begin{array}{lcl}
	 	c_{\ell} \, \mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell})   = c_1 \,  \mbox{Pay}_1 (\gamma_1,\kappa_1)  \\
		c_{\ell} \, \mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell})   = c_2 \,  \mbox{Pay}_2 (\gamma_2,\kappa_2)  \\
		\quad \vdots   \qquad \vdots \qquad \vdots  \qquad \quad  \vdots   \qquad \vdots  \\    
		  c_{\ell} \, \mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell})   = c_d \,  \mbox{Pay}_d (\gamma_d,\kappa_d) \\
		   \gamma_1 + \ldots +\gamma_d=1.
	\end{array}
	\right.  
  \end{equation*}
Il follows that
  \begin{equation*} 
   \left\{
	 \begin{array}{lcl} 
	 	\big(c_{\ell} \, \prod_{_{j \in \bar{\mathcal{P}}_d(1)}} c_j \big)\mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell})   = \big( \prod_{_{j \in \mathcal{P}_d}} c_j \big)   \mbox{Pay}_1 (\gamma_1,\kappa_1)  \\
		\big(c_{\ell} \, \prod_{_{j \in \bar{\mathcal{P}}_d(2)}} c_j \big) \mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell})   =  \big( \prod_{_{j \in \mathcal{P}_d}} c_j \big)   \mbox{Pay}_2 (\gamma_2,\kappa_2)  \\
		\quad \vdots   \qquad \vdots \qquad \vdots  \qquad \quad  \vdots   \qquad \vdots  \\    
		 \big(c_{\ell} \, \prod_{_{j \in \bar{\mathcal{P}}_d(d)}} c_j \big) \, \mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell})   =  \big( \prod_{_{j \in \mathcal{P}_d}} c_j \big)   \mbox{Pay}_d (\gamma_d,\kappa_d) \\
		   \gamma_1 + \ldots +\gamma_d=1.
	\end{array}
	\right.  
  \end{equation*}
Adding the left and right hand sides of the $d$ first equations of the previous system gives (setting $E_1: =  \mathbb E(R_T-L)^{+}$ and $E_2:=\mathbb E(L-R_T)^{+}$)
\begin{eqnarray*}
c_{\ell}  \Big(\sum_{i=1}^d \prod_{j \in \bar{ \mathcal{P}}_d (i)} c_j \Big) \big( \gamma_{\ell} \, E_1   - \kappa_{\ell}\, E_2  \big) = \Big(\prod_{i=1}^d c_i \Big)\big( E_1  -   E_2 \big)
\end{eqnarray*}
Then,
\begin{eqnarray*}
 \Big(\sum_{i=1}^d \prod_{j \in \bar{ \mathcal{P}}_d (i)} c_j \Big) \big( \gamma_{\ell} \, E_1   - \kappa_{\ell}\, E_2  \big) = \Big(\prod_{i \in \mathcal{\bar{P}}_d(\ell)} c_i \Big) \big( E_1  -   E_2 \big).
\end{eqnarray*}
We then deduce Equation \eqref{EqPart1-d-Prop2}. 

Now, the expected payoff $\mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell})$ of each partner $\ell$ is obtained by replacing in Equation \eqref{Eq-Payoff-ell},   $\gamma_{\ell}$ by its value in \eqref{EqPart1-d-Prop2}.
\end{proof}

\begin{example} \label{Example-Musharaka1}  Consider a    viable   $T$-term and $R$-asset based  {\em  PL - musharakah} contract of  $4$ partners (say, a joint venture between $4$ companies  to develop a product) who agree, according to their contributions to the capital (of amount $L$) and the management, to rate their respective payoff by the coefficients $c_i$, $i=1, \ldots, 4$.  We fix $\rho(R_T,L) \in \{\frac{1}{8},  \frac{3}{4}\}$,    the  rating coefficients $c_{\ell}$, and  want to determine the $(c_1, \ldots,c_4)$-fair profit sharing ratios.

\medskip



 Suppose that all the partners contributed to the same amount of the capital: $\kappa_{\ell} = 25\%$, for any $\ell \in \{1, 2, 3, 4\}$. 

\begin{enumerate} [leftmargin=*,itemsep=0cm]
\item[$\diamond$]  If we suppose that they have an equal contribution to the management of the project so that they agree to  set $(c_1, c_2,c_3,c_4)=(1,1,1,1)$, then,   the  allocation key of the expected investment profit  equals $(c_{1, \bar{1}},$ $ c_{2,\bar{2}},$ $c_{3, \bar{3}},$ $c_{4,\bar{4}})=$ $(1/4, $ $1/4, $ $1/4, $ $1/4)$ and, regardless of the value taken by $\rho(R_T,L)$, the $(c_1, \ldots,c_4)$-fair profit sharing ratios are equal (as discussed in Remark \ref{Rem-MainResult-3}):
\[
\gamma_{\ell} = 25\%, \qquad \mbox{for any partner } \ell \in \{1, \dots, 4\}.
\] 
\item[$\diamond$] If we suppose now that partners $1$ and $3$  contributed more  to the management of the project and that all partners agree to rate the maturity payoff as $(c_1, c_2,c_3,c_4)=(1,2,1,4)$, then, the distribution key of the expected investment profit  equals  $(c_{1, \bar{1}},$ $ c_{2,\bar{2}},$ $c_{3, \bar{3}},$ $c_{4,\bar{4}})=$ $\frac{1}{11} \, (4, $ $2, $ $4, $ $1)$. Furthermore, 
\begin{eqnarray*}
&& (\gamma_1, \gamma_2, \gamma_3, \gamma_4)  \ = \  (35\%,\ 11 \%,\ 35\%, \ 19\%) \qquad \mbox{if } \rho(R_T,L) =1/8 \\
&\mbox{and }& (\gamma_1, \gamma_2, \gamma_3, \gamma_4)  \ \simeq  \  (29\%,\ 20 \%,\ 29\%, \ 22 \%) \qquad \mbox{if } \rho(R_T,L) =2/3. 
\end{eqnarray*}
Since $ \kappa_{\ell} = \kappa_{\ell'}$, for any $\ell \not= \ell'$, $\ell, \ell' \in\{1, 2, 3, 4\}$, we deduce  from Remark  \ref{Rem-MainResult-2} that $\gamma_{\ell} \ge \gamma_{\ell'}$  whenever $c_{\ell, \bar{\ell}} \ge c_{\ell', \bar{\ell'}}$.
