\begin{rem} (About a {\em diminishing PL sharing - musharakah} contract) Equation \eqref{EqPart1-d-Prop2} is a very useful formula that allows to  update the sharing profit ratio of two (or more) partners in the case of a {\em diminishing PL sharing - musharakah} contract with respect to their share in the capital.

\end{rem}


We next consider  a generalisation of  Proposition \ref{Prop-Musharakah-d-Partners2Parts} 2. to $d$ partners, where the $(d-1)$ partners of a {\em PL sharing - musharakah} contract  appoint a manager (the $d$'th partner) outside of them and are bounded with him by a {\em Wakalah} (an agency) contract.  

\begin{prop}  \label{Prop-Mush-Mudh-Wakalah} Consider  a  viable   $T$-term and $R$-asset based  {\em  PL - musharakah} contract of  $d-1$ partners who appoint a manager outside of them (the $d$'th partner) and are bounded with him by a {\em Wakalah} contract   which arranges a fixed remuneration (a amount $p$ that is paid out  $k$ times up to the maturity $T$).  If the partners  agree  to rate their respective expected payoff by the coefficients $c_1, \ldots, c_d$, then, the $(c_1,\ldots,c_{d})$-fair profit sharing  ratios and periodic remuneration $p$ satisfy
 \begin{eqnarray}  
  \varpi(r,T,k) \, p &=&    c_{d,\bar {d}}    \, \Delta(R_T,L)\\
 \gamma_{\ell}  &=& \Big( \frac{c_{d, \bar d}}{d-1} + c_{\ell,\bar{\ell}}\Big) \,  \big(1-\rho(R_T,L) \big)   + \kappa_{\ell} \, \rho(R_T,L), \ \ell = 1, \ldots, d-1,  \label{EqPart1-Wakala-d-Prop1}  
\end{eqnarray}
where  
\[
\varpi(r,T,k) =  \frac{(1+r )^{ \mbox{\tiny $\frac{T}{k}$} } -1}{(1+r )^{ \mbox{\tiny $T$} } - 1}, 
\]
and  the weights  $(c_{\ell, \bar {\ell}})_{\ell \in {\cal P}}$ are defined for every $\ell \in {\cal P}_d$ by
\begin{equation}  \label{Eq-weights1}
 c_{\ell, \bar {\ell}}  = \Big(\prod_{i \in \bar{\mathcal{P}}_d (\ell)} c_i \Big)\  \big /  \, \Big(\sum_{i=1}^d \prod_{j \in \bar{ \mathcal{P}}_d (i)} c_j \Big).
\end{equation}
Furthermore, the expected payoff of each partner $\ell$ (even the partner $d$ who has a fixed $k$-periodic remuneration up to maturity) is given by
\begin{equation}
\mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell})  = c_{\ell, \bar {\ell}}\, \Delta(R_T,L),  \qquad \ell =1, \ldots,d.
\end{equation}
%
%\begin{eqnarray}
%  p  &=&  \,   \Delta(R_T,L), \\
%   \gamma_{\ell} & =& c_{\ell, \bar {\ell}}\, (1- \rho(R_T,L)) +  \kappa_{\ell}  \,  \rho(R_T,L)\\
%   &=&  c_{\ell, \bar {\ell}} \, \beta(R_T,L) +  \kappa_{\ell}  \,  \rho(R_T,L),
% \end{eqnarray}
%  where $\bar{\ell} = \{1,2\} \backslash \{ \ell \}$ and, for $\ell \in \{1, 2\}$, 
%  \[
%  c_{\ell,\bar {\ell}}  =   \frac{c_{ \bar{\ell} }}{c_1 c_2 + c_1 c_3 + c_2 c_3}  \Big( \frac{c_{\ell}}{2}  + c_3\Big).
%  \]

\end{prop}

Before giving the proof, we may observe that  \ $\gamma_1 + \ldots + \gamma_{d-1} =1$.  We may also note that a typical example  where Proposition \ref{Prop-Mush-Mudh-Wakalah} applies is the situation where we have three partners: 
\begin{enumerate} 
\item[$\diamond$] an investor (partner $1$)  that  brings all the capital  (so that $\kappa_1=1$),  
\item[$\diamond$] a bank (partner $2$) that acts as an  agent  for the investor via a {\em wakalah} contract and arranges a fixed remuneration  $p$ that is paid out  $k$ times up to the maturity $T$ and, 
\item[$\diamond$] a company (partner $3$) that needs a funding and that is bounded with the bank by a {\em PL-mudharabah} contract  (so that $\kappa_3=0$).
\end{enumerate}

\begin{proof}  The $(c_1, \ldots, c_d)$-fair assumption implies for any $\ell=1, \ldots, d-1$,
 \begin{equation}  \label{Eq-Wakalah-gen-proof}
c_{\ell}\, \mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell},p,k)  = c_d\, \mbox{Pay}_3 (p,k),
 \end{equation}  
where for any $\ell=1, \ldots, d-1$,
\begin{eqnarray}
\mbox{Pay}_{\ell} (\gamma_{\ell},\kappa_{\ell},p,k)   &=&   (1+r)^{\mbox{\tiny $-T$}}\, \big(\gamma_{\ell} \,  \mathbb E (R_T-L)^{+}  - \kappa_{\ell}\, \mathbb E (L-R_T)^{+} \big)  - \frac{\mbox{Pay}_3 (p,k)}{ d-1} \qquad   \label{Eq-Payoff-Wakalah-general1} \\
\mbox{ and } \quad \mbox{Pay}_3 (p,k) &=& p  \, \big(1+r \big)^{ \mbox{\tiny $-T$} }  \, \varpi(r,T,k).  \nonumber 
\end{eqnarray}
It follows  from \eqref{Eq-Wakalah-gen-proof} that   for any $\ell=1, \ldots, d-1$,
\[
 c_{\ell}\, \Big(\gamma_{\ell} \,  \mathbb E (R_T-L)^{+}  - \kappa_{\ell}\, \mathbb E (L-R_T)^{+}   -  \frac{p   \, \varpi(r,T,k)}{d-1}  \Big)  = c_d \,p   \, \varpi(r,T,k).
\]
Multiplying both sides of the previous equation by $ \prod_{i \in \bar{\cal P}_{d-1}(\ell)} c_i $  gives
\[
 \Big(\gamma_{\ell} \,  \mathbb E (R_T-L)^{+}  - \kappa_{\ell}\, \mathbb E (L-R_T)^{+}   -  \frac{p   \, \varpi(r,T,k)}{d-1}  \Big)  \prod_{i \in {\cal P}_{d-1}} c_i    =   p   \, \varpi(r,T,k) \prod_{i \in \bar{\cal P}_{d}(\ell)} c_i.
\]
Since $\gamma_1+ \ldots +\gamma_{d-1}=1$ and $\kappa_1 + \ldots + \kappa_{d-1}=1$, taking the sum over the $\ell$'s (from $1$ to $d-1$) yields:
\[
\Big(\Delta(R_T,L) - p   \, \varpi(r,T,k)  \Big)  \prod_{i \in {\cal P}_{d-1}} c_i   = p   \, \varpi(r,T,k)  \sum_{\ell \in {\cal P}_{d-1}} \prod_{i \in \bar{\cal P}_{d}(\ell)} c_i.
\]
We deduce that 
\begin{eqnarray*}
\Delta(R_T,L)   \prod_{i \in {\cal P}_{d-1}} c_i  &=& p   \, \varpi(r,T,k)  \Big(  \prod_{i \in {\cal P}_{d-1}} c_i  +  \sum_{\ell \in {\cal P}_{d-1}} \prod_{i \in \bar{\cal P}_{d}(\ell)} c_i \Big) \\
&=& p   \, \varpi(r,T,k)  \Big(  \prod_{i \in \bar{\cal P}_{d} (d)} c_i  +  \sum_{\ell \in {\cal P}_{d-1}} \prod_{i \in \bar{\cal P}_{d}(\ell)} c_i \Big) \\
&=&  p   \, \varpi(r,T,k)  \Big(  \sum_{\ell \in {\cal P}_{d}} \prod_{i \in \bar{\cal P}_{d}(\ell)} c_i \Big),
\end{eqnarray*}
and, finally, that,
\[
\varpi(r,T,k) \, p =    c_{d,\bar {d}}    \, \Delta(R_T,L).  
\]
Now, replacing $\varpi(r,T,k) \, p $ by its value in Equation \eqref{Eq-Wakalah-gen-proof} gives 
\[
c_{\ell}\, \Big(\gamma_{\ell} \,  \mathbb E (R_T-L)^{+}  - \kappa_{\ell}\, \mathbb E (L-R_T)^{+}   -  \frac{c_{d,\bar d} \, \Delta(R_T,L)}{d-1}  \Big)  = c_d \,p   \, \varpi(r,T,k).\]
This implies that
\begin{eqnarray*}
\gamma_{\ell} & = & \frac{c_{d,\bar d}}{c_{\ell}} \, \Big( \frac{c_{\ell}}{d-1} + c_{d}\Big) \,  \big(1-\rho(R_T,L) \big)   + \kappa_{\ell} \, \rho(R_T,L) \\
&=&\Big( \frac{c_{d, \bar d}}{d-1} + c_{\ell,\bar{\ell}}\Big) \,  \big(1-\rho(R_T,L) \big)   + \kappa_{\ell} \, \rho(R_T,L).
\end{eqnarray*}
Now, the expected payoff of  each partner $\ell$ is obtained by replacing $\varpi(r,T,k) \, p$ and $\gamma_{\ell}$ by their values in Equation \eqref{Eq-Wakalah-gen-proof}
\end{proof}
\begin{example}  \label{Exam-mudha-wakalah}
Consider the situation  where we have three partners: an investor (partner $1$)  that  brings all the capital  (so that $\kappa_1=1$),  a bank (partner $2$) that  acts as an  agent  for the investor via a {\em wakalah} contract and arranges a fixed remuneration  $p$ that is paid out  $k$ times up to the maturity $T$ and,  a company (partner $3$), that needs a funding and that is bounded with the bank by a {\em PL-mudharabah} contract  (so that $\kappa_3=0$).  

Suppose that they invest the amount $L$ on the company asset $R$ for a maturity $T$. We see here that the remuneration of the bank depends on its rating $c_1$ that will take account for example on the  logistics used for the management. When the rating vector $c = (c_1, c_2, c_3)$ is given, the share  of the bank, of the profit sharing ratios of the investor and the company are given respectively by
  \begin{eqnarray*}  
  \varpi(r,T,k) \, p &=&    c_{3,\bar {3}}    \, \Delta(R_T,L),\\
 \gamma_{1}  &=& \Big( \frac{c_{3, \bar 3}}{2} + c_{1,\bar{1}}\Big) \,  \big(1-\rho(R_T,L) \big)   +  \rho(R_T,L), \\  
 \gamma_{2}  &=& \Big( \frac{c_{3, \bar 3}}{2} + c_{2,\bar{2}}\Big). 
\end{eqnarray*}
If for example, $c = (1,1,1)$ and $\rho (R_T, L) = 1/2$, then, 
\[
 \varpi(r,T,k)  p = \frac{1}{3}  \Delta(R_T,L), \qquad \gamma_1 = \frac{3}{4}, \qquad \gamma_{2} = \frac{1}{4}, 
\]
that leads to an equal sharing of the expected investment profit between the three partners, means,  $\frac{1}{3}  \Delta(R_T,L)$ for each partner.

\end{example}


