\section{CNF Model}

This section describes optimal Kobon arrangement tables for certain values of~$n$, formalized as CNF models suitable for modern SAT solvers. Specifically, when $n \bmod 6 \in \{3,5\}$, arrangements meeting the upper bound $N(n) = \frac{1}{3}n(n-2)$ will have every finite non-overlapping segment as a side of a non-overlapping triangle~\cite{cb2007a}. This observation simplifies the model. We can further extend the approach to other values of~$n$ by adding segments with missing triangles (see Figure~\ref{fig:kobon-13}, etc.). A fully working CNF model implementation can be found at~\cite{koboncnf}. As SAT solvers become increasingly powerful, more results can be achieved through proper encoding (see, for example, \cite{kirchweger_et_al:LIPIcs.SAT.2023.14}).

\subsection{Variables}

In order to encode tables as a CNF statement, we define the following Boolean variables:\begin{enumerate}
\item $G(r,i,j)$ -- line $j$ is immediately after line $i$ in row~$r$ 
(for $r \neq i \land r \neq j \land i \neq j$).
\item $X(r,i,j)$ -- line $j$ is somewhere after line $j$ in row~$r$
(for $r \neq i \land r \neq j \land i \neq j$).
\item $A(r,i,k)$ -- line $i$ is in column~$k$ of row~$r$
(for $r \neq i$).
\item \textit{(Optional)} $M_k(r_k,i,j)$ -- segment $(i,j)$ on line~$r_k$ is missing a triangle.
\end{enumerate}
Here, lines are numbered from $1$ to $n$, rows from $1$ to $n$, and columns from $1$ to $n-1$. In total there are $O(n^3)$, or $\approx(3n^3-8n^2+5n)$ variables (see Table~\ref{tab:koboncnf-stats} for concrete numbers).


\subsection{Clauses}

Each rule is described textually, formalized in first-order logic, and expressed in CNF:

\begin{enumerate}

\item Each row contains all the other lines:
$$
\forall r,i \neq r: \exists k: A(r,i,k)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{r, i \neq r} \bigvee\limits_k A(r,i,k)
$$

\item Rows do not have duplicate entries:
$$
\forall r,i \neq r,k: A(r,i,k) \rightarrow \forall j \neq k: \neg A(r,i,j)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{r,i \neq r,k} \bigwedge\limits_{j \neq k} \neg A(r,i,k) \lor \neg A(r,i,j)
$$

\item Connection between $A$ (at) and $G$ (immediately after):
\begin{enumerate}
\item $
A(r,i,k) \land A(r,j,k+1) \rightarrow G(r,i,j)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{\substack{r,i \neq r\\ j \neq r, j \neq i\\ k<n-1}} 
\neg A(r,i,k) \lor \neg A(r,j,k+1) \lor G(r,i,j)
$
\item $
A(r,i,k) \land G(r,i,j) \rightarrow A(r,j,k+1)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{\substack{r,i \neq r\\ j \neq r, j \neq i\\ k<n-1}} 
\neg A(r,i,k) \lor A(r,j,k+1) \lor \neg G(r,i,j)
$
\item $
G(r,i,j) \land A(r,j,k+1) \rightarrow A(r,i,k)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{\substack{r,i \neq r\\ j \neq r, j \neq i\\ k<n-1}} 
A(r,i,k) \lor \neg A(r,j,k+1) \lor \neg G(r,i,j)
$
\end{enumerate}

\item Only one line can immediately follow another:
\small
$$
\forall r,i \neq r, j \neq r, i \neq j: G(r,i,j) \rightarrow \forall k\neq j: \neg G(r,i,k)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{\substack{r,i \neq r\\ j \neq r, i \neq j\\k \neq r, k \neq j, k \neq i}} 
\neg G(r,i,j) \lor \neg G(r,i,k)
$$
\normalsize

\item Connection between ``first'' and ``immediately after'':
\begin{enumerate}
\item $
A(r,i,1) \rightarrow \forall j \neq i, j \neq r: \neg G(r,j,i)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{r,i \neq r, j \neq i, j \neq r} 
\neg A(r,i,1) \lor \neg G(r,j,i)
$
\item $
\neg A(r,i,1) \rightarrow \exists j \neq i, j \neq r: G(r,j,i)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{r,i \neq r} 
A(r,i,1) \lor
\bigvee\limits_{\substack{j \neq i\\ j \neq r}} G(r,j,i)
$
\end{enumerate}

\item Relation between ``last'' and ``immediately after'':
\begin{enumerate}
\item $
A(r,i,n-1) \rightarrow \forall j \neq i, j \neq r: \neg G(r,i,j)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{r,i \neq r, j \neq i, j \neq r} 
\neg A(r,i,n-1) \lor \neg G(r,i,j)
$
\item $
\neg A(r,i,n-1) \rightarrow \exists j \neq i, j \neq r: G(r,i,j)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{r,i \neq r} 
A(r,i,n-1) \lor
\bigvee\limits_{\substack{j \neq i\\ j \neq r}}  G(r,i,j)
$
\end{enumerate}

\item $X(r,i,j)$ ($j$ somewhere after $i$) is \textit{total} (connected, complete):
$$
\forall r,i,j (i \neq r, j \neq r, i \neq j): X(r,i,j) \lor X(r,j,i)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{\substack{r,i,j\\(i \neq r, j \neq r, i \neq j)}}
X(r,i,j) \lor X(r,j,i)
$$

\item $X(r,i,j)$ ($j$ somewhere after $i$) is \textit{antisymmetric}:
$$
\forall r,i,j (i \neq r, j \neq r, i \neq j): X(r,i,j) \rightarrow \neg X(r,j,i)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{\substack{r,i,j\\(i \neq r, j \neq r, i \neq j)}}
\neg X(r,i,j) \lor \neg X(r,j,i)
$$

\item $X(r,i,j)$ ($j$ somewhere after $i$) is \textit{transitive}:
\begin{align*}
\forall r,i,j,k (i \neq r, j \neq r, k \neq r, i \neq j, i \neq k, j \neq k):
X(r,i,j) \land X(r,j,k) \rightarrow X(r,i,k) \ \ \ \ \ \Leftrightarrow 
\\
\Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{
\substack{r,i,j,k\ (i \neq r, j \neq r, k \neq r, i \neq j, i \neq k, j \neq k)}}
\neg X(r,i,j) \lor \neg X(r,j,k) \lor X(r,i,k)
\end{align*}

\item Relationship between $X(r,i,j)$ ($j$ somewhere after $i$) and ``first'' and ``last'' in a row:
\small
\begin{enumerate}
\item $
A(r,i,1) \rightarrow \forall j \neq i: X(r,i,j)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{\substack{r,i,j\\(i \neq r, j \neq r, i \neq j)}}
\neg A(r,i,1) \lor X(r,i,j)
$
\item $
A(r,i,n-1) \rightarrow \forall j \neq i: X(r,j,i)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{\substack{r,i,j\\(i \neq r, j \neq r, i \neq j)}}
\neg A(r,i,n-1) \lor X(r,j,i)
$
\item $
\bigl(\ \forall j \neq i: X(r,i,j)\ \bigr) \rightarrow A(r,i,1)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{\substack{r,i\\(i \neq r)}}
A(r,i,1) \lor 
\bigvee\limits_{\substack{j\\(j \neq r, j \neq i)}}
\neg X(r,i,j)
$
\item $
\bigl(\ \forall j \neq i: X(r,j,i)\ \bigr) \rightarrow A(r,i,n-1)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{\substack{r,i\\(i \neq r)}}
A(r,i,n-1) \lor 
\bigvee\limits_{\substack{j\\(j \neq r, j \neq i)}}
\neg X(r,j,i)
$
\end{enumerate}
\normalsize

\item Connection between ``immediately after'' ($G$) and ``somewhere after'' ($X$):
$$
\forall r,i,j (i \neq r, j \neq r, i \neq j): G(r,i,j) \rightarrow X(r,i,j)
\ \ \ \ \ \Leftrightarrow \ \ \ \ \ 
\bigwedge\limits_{\substack{r,i,j\\(i \neq r, j \neq r, i \neq j)}}
\neg G(r,i,j) \lor X(r,i,j)
$$

\item \textit{(Consistency + Optimality)} 
Consistency was previously defined in the general properties: the relative ordering of any two lines $i$ and $j$ in row~$j$ must be consistent with how (pseudo)line intersections behave in the triangle formed by $i$, $j$, and $r$ (see Figure~\ref{fig:consistency}). Because in our case every finite non-overlapping segment must also be a side of a non-overlapping triangle, we enforce this ``optimality'' almost in the same way as we enforce consistency. The clauses are identical, except that for consistency we use $X$ (somewhere after), and for optimality we use $G$ (immediately after). The clauses below are for $G$, but must also be included identically for~$X$:

