Now, using the above description of the sets with the cut point property, we compute the Krull dimension of the quotient ring of the binomial edge ideals of the crown graphs.
\begin{theorem}\label{thm:dim} 
Let $G=C_{n,n}$ with $n \ge 3$. Then,  $\dim\left(\frac{S}{J_{C_{n,n}}}\right) = 2n + 1$. Moreover, \begin{enumerate}
    \item[$(1)$] if $T=\emptyset$, then $\dim\left(\frac{S}{P_{T}(G)}\right) = 2n + 1$. 
    \item[$(2)$] if $T=X$ or $T=Y$, then $\dim\left(\frac{S}{P_{T}(G)}\right) = 2n$. 
    \item[$(3)$] if $T=X\setminus \{2i-1\}$ or $T=Y\setminus \{2j\}$ for some $ i, j \in [n]$, then $\dim\left(\frac{S}{P_{T}(G)}\right) = n+3$. 
    \item[$(4)$] if $T=A\cup \{a+1~:~a \in A\}$ with $A \subseteq X$ and $|A|=n-2$, then $\dim\left(\frac{S}{P_{T}(G)}\right) = 6$.
\end{enumerate}
\end{theorem}

\begin{proof} It follows from \cite[Lemma~3.1]{HHHKR10} that for any $T \subseteq [2n]$, $$\dim\left(\frac{S}{P_{T}(G)}\right) = 2n-|T|+c_G(T).$$
\par (1)  Since $T=\emptyset$,  $c_G(T)=1.$ Thus, $\dim\left(\frac{S}{P_{T}(G)}\right) = 2n-0+1=2n+1.$
 \par (2) Assume $T=X$ (the case for $T=Y$ is similar). Then, $G[\bar T]$ is a graph on $n$ vertices with no edges. So, $c_G(T)=n,$ and hence, $\dim\left(\frac{S}{P_{T}(G)}\right) = 2n-n+n=2n.$
 \par (3) Assume $T=X \setminus \{2i-1\}$ for some $i \in [n]$ (the case for $T=Y\setminus \{2j\}$ for some $j \in [n]$ is similar). Then, $G[\bar T]$ has two connected components; see Figure \ref{fig:cutset}. Therefore, $\dim\left(\frac{S}{P_{T}(G)}\right) = 2n-(n-1)+2=n+3.$
\par (4) Assume $T=A\cup \{a+1~:~ a\in A\}$, where $A\subseteq X$ and $|A|=n-2$. Then, $G[\bar{T}]$ has two connected components (see Figure \ref{A and A+1}). Thus, $\dim\left(\frac{S}{P_{T}(G)}\right) = 2n-2(n-2)+2=6$.

By Theorem \ref{thm:cut-point-prop}, we have a complete description of elements of $\mathcal{C}(G)$. Since $\dim\left(\frac{S}{J_G}\right) =\max\left\{\dim\left(\frac{S}{P_{T}(G)}\right)~:~ T \in \mathcal{C}(G)\right\}$, we get that $ \dim\left(\frac{S}{J_G}\right) =2n+1,$ as desired. 
\end{proof}

 Using Theorem~\ref{thm:dim}, we immediately determine the big height of the binomial edge ideals of crown graphs. The \textit{big height} of an ideal is the largest height of the minimal primes of that ideal.

 \begin{corollary}\label{cor:height}
     Let $G=C_{n,n}$ with $n \ge 3$. Then, $\height(J_G)=2n-1$ and $\bigheight(J_G)=4n-6.$
 \end{corollary}
 \begin{proof}
 It is well known that for a homogenous  ideal $I$ in $S$, $\height(I)=\dim(S)-\dim\left(\frac{S}{I}\right).$ We know that $\dim(S)=4n$. Therefore,  $$\height(J_G)=\dim(S)-\dim\left(\frac{S}{J_G}\right)=4n-(2n+1)=2n-1$$ and \begin{align*}
     \bigheight(J_G)&=\max\left\{ \height(P_T(G))~:~ T \in \mathcal{C}(G)\right\}\\&=\max\left\{\dim(S)-\dim\left(\frac{S}{P_T(G)}\right)~:~T \in \mathcal{C}(G)\right\}\\& =\dim(S)-\min\left\{\dim\left(\frac{S}{P_T(G)}\right)~:~T \in \mathcal{C}(G)\right\}\\&=4n-6.
 \end{align*} Hence, the assertion follows. 
 \end{proof}



\section{Projective dimension and big height of binomial edge ideals}\label{depth} The projective dimension of the quotient $\frac{S}{I}$ of a homogeneous ideal $I \subset S$ is known to be greater than or equal to the big height of $I$. When $\frac{S}{I}$ is Cohen-Macaulay, then the projective dimension of $\frac{S}{I}$ is the same as the $\bigheight(I)$. We want to understand which class of ideals(other than Cohen-Macaulay) has the same projective dimension as the big height of $I$. Specifically, we are looking at this question in the context of binomial edge ideals. In this section, we will explore this question for binomial edge ideals associated with various classes of graphs. 

The first known result about the projective dimension of binomial edge ideals is attributed to Ene, Herzog, and Hibi \cite{EHH11}. They investigated the Cohen-Macaulayness of binomial edge ideals of block graphs. As a first step in this direction, we verify that the quotient of binomial edge ideals of block graphs has the same projective dimension as the big height.

\begin{proposition}
    Let $G$ be a connected block graph on the vertex set $[n]$. Then, $$\pd\left(\frac{S}{J_G}\right)=\bigheight(J_G)=n-1.$$
\end{proposition}
\begin{proof}
   Based on \cite[Theorem 1.1]{EHH11}, we have $\pd\left(\frac{S}{J_G}\right)=n-1$. This implies that $\bigheight(J_G) \le \pd\left(\frac{S}{J_G}\right)=n-1$. 
To demonstrate that $\bigheight(J_G) \ge n-1$, we first note that since $G$ is a connected graph, it follows from \cite[Lemma 3.1]{HHHKR10} that $\height(P_\emptyset(G))=n-1$. Therefore, $n-1 = \height(P_\emptyset(G)) \le  \bigheight(J_G)$. 
Thus, the assertion follows.
\end{proof}

The projective dimension of the binomial edge ideals of cycles is well-documented by Zafar and Zahid \cite{betti}. In the following, we will confirm that the quotient of the binomial edge ideal of cycles has the same projective dimension as the big height. 

\begin{proposition} \label{prop:pd-bh-cycle}
    Let $G=C_n$ with $n \ge 4$. Then $\pd\left( \frac{S}{J_G}\right)=\bigheight (J_G)=n$.
\end{proposition}
\begin{proof}
    Based on \cite[Corollary 16]{betti}, we know that $\pd\left(\frac{S}{J_G}\right)=n$. This means that $\bigheight(J_G) \le \pd\left(\frac{S}{J_G}\right)=n$. To show that $\bigheight(J_G) \ge n$, we first observe that the set $T=\{1,3\}$ has the cut point property. Additionally, $G[\bar T]$ forms a disconnected graph with two connected components, meaning that $c_G(T)=2$. %\textcolor{violet}{(see Figure~\ref{fig: pd(C_n) = bight(C_n)})}. 
    As a result of \cite[Lemma 3.1]{HHHKR10}, we deduce that $\height(P_T(G))=n+|T|-c_G(T)=n$. Therefore, we have $n = \height(P_T(G)) \le  \bigheight(J_G)$. Hence, the claim follows.
\end{proof}

Kumar and Sarkar \cite{KS20} determined the projective dimension of the binomial edge ideals for both wheel graphs and complete multipartite graphs. They also provided a formula for the projective dimension of the binomial edge ideals for the join product of graphs. In the next few results, we examine the cone of a graph and complete multipartite graphs, focusing on when the quotient of the binomial edge ideal has the same projective dimension as the big height. The {\it cone} of a graph $G$ is a graph on the vertex set $V(G) \sqcup \{v\}$ and edge set $E(G) \sqcup \{ \{v,u\}~:~ u \in V(G)\}.$
\begin{proposition}\label{prop:pd-bh-cone}
    Let $G$ be a connected graph on the vertex set $[n]$ and let $v$ be a new vertex. Let $H=v*G$ and $S_H=S[x_v,y_v]$. Then, we have the following: 
    \begin{enumerate}
        \item[$(1)$] $\pd\left( \frac{S_H}{J_H}
        \right) =2+\pd\left( \frac{S}{J_G}
        \right).$
        \item[$(2)$] if $\height(P_T(G)) <n-1$ for all $T \in \mathcal{C}(G) \setminus \{\emptyset\},$ then $\bigheight(J_H)=n.$
        \item[$(3)$] if $\height(P_T(G)) \ge n-1$ for some  $T \in \mathcal{C}(G) \setminus \{\emptyset\},$ then $\bigheight(J_H)=2+\bigheight(J_G).$
        \item[$(4)$] $\pd\left( \frac{S_H}{J_H}\right)=\bigheight(J_H)$ if and only if  $\pd\left( \frac{S}{J_G}\right)=\bigheight(J_G)$ and    $\height(P_T(G)) \ge n-1$ for some  $T \in \mathcal{C}(G) \setminus \{\emptyset\}$.  \end{enumerate}
\end{proposition}
\begin{proof}
    (1) This part follows using the Auslander-Buchsbaum formula in  \cite[Theorem 3.4]{KS20}. 
    \par (2-3) Based on \cite[Proposition 4.1]{DS15}, we have $$\mathcal{C}(H)=\{\emptyset\} \cup \left\{\{v\} \cup T~:~ T \in \mathcal{C}(G) \setminus \{\emptyset\}\right\}.$$ Using \cite[Lemma 3.1]{HHHKR10}, we know that for any $A \in \mathcal{C}(H)$, $\height(P_A(H))=(n+1)+|A|-c_H(A)$. Consequently, $\height(P_\emptyset(H))=n$, and for any $A \in \mathcal{C}(H)$ with $A \neq \emptyset$, we have $$\height(P_A(H))=2+n+|A\setminus \{v\}| -c_G(A \setminus \{v\})=2+\height(P_{A \setminus \{v\}}(G)).$$
In this way, we get the respective conclusion by using the hypothesis of the respective part of the definition of the big height. 
\par (4) Using parts $(1)$ and $(3)$, we get $\pd\left( \frac{S_H}{J_H}\right)=\bigheight(J_H)$ if $\pd\left( \frac{S}{J_G}\right)=\bigheight(J_G)$ and $\height(P_T(G)) \geq n-1$ for some $T \in \mathcal{C}(G) \setminus \{\emptyset\}$.

 Conversely, suppose $\pd\left( \frac{S_H}{J_H}\right)=\bigheight(J_H)$. Since $G$ is a connected graph, $\pd\left(\frac{S}{J_G} \right) \geq \bigheight(J_G) \geq \height(P_\emptyset(G)) = n-1$. Using part $(1)$, we get $\pd\left(\frac{S_H}{J_H} \right) \geq n+1$, which means $\bigheight(J_H) \geq n+1$. According to parts $(2-3)$, this implies that $\height(P_T(G)) \geq n-1$ for some $T \in \mathcal{C}(G) \setminus \{\emptyset\}$, and hence, $\bigheight(J_H)=2+\bigheight(J_G)$. We get the desired result using part $(1)$. 
\end{proof}
As an immediate consequence of Proposition \ref{prop:pd-bh-cone}, we confirm that the projective dimension of the quotient of the binomial edge ideal of wheel graphs is the same as the big height. Recall that the {\it wheel graph} on $n+1$ vertices is the cone of a cycle graph on $n$ vertices. 

\begin{corollary}
    Let $H=v*C_n$ be the wheel graph on the vertex set $[n]\cup \{v\}$ with $n \ge 4.$ Then, $\pd\left( \frac{S_H}{J_H}\right)=\bigheight(J_H)=n+2,$ where $S_H=S[x_v,y_v].$
\end{corollary}
\begin{proof}
   By Proposition \ref{prop:pd-bh-cycle}, we know that  $\pd\left( \frac{S}{J_{C_n}}\right)=\bigheight(J_{C_n})=n.$ This implies that there exists $T \in \mathcal{C}(C_n)$ so that $\height(P_T(C_n)) =n\ge n-1.$ Thus, using Proposition \ref{prop:pd-bh-cone}, $\pd\left( \frac{S_H}{J_H}\right)=\bigheight(J_H)=n+2.$
\end{proof}


\begin{proposition}
    Let $G$ be a disconnected graph on the vertex set $[n]$ and let $v$ be a new vertex. Let $H=v*G$ and $S_H=S[x_v,y_v]$. Then, we have the following: 
    \begin{enumerate}
        \item[$(1)$] $\pd\left( \frac{S_H}{J_H}
        \right) =\max\left\{n, 2+\pd\left( \frac{S}{J_G}
        \right)\right\}.$
           \item[$(2)$]  $\bigheight(J_H)=\max\left\{n,2+\bigheight(J_G)\right\}.$
        \item[$(3)$] if $\bigheight(J_G) \ge n-2$, then $\pd\left( \frac{S_H}{J_H}\right)=\bigheight(J_H)$ if and only if  $\pd\left( \frac{S}{J_G}\right)=\bigheight(J_G).$ %\item[$(4)$] if $\pd\left( \frac{S}{J_G}\right) \le n-2$, then $\pd\left( \frac{S_H}{J_H}\right)=\bigheight(J_H)$.
        \item[$(4)$] if $\bigheight(J_G) < n-2$, then $\pd\left( \frac{S_H}{J_H}\right)=\bigheight(J_H)$ if and only if  $\pd\left( \frac{S}{J_G}\right)\le n-2.$   \end{enumerate}
\end{proposition}
\begin{proof}
    (1) This part follows using the Auslander-Buchsbaum formula in  \cite[Theorem 3.9]{KS20}. 
    \par (2) Based on \cite[Proposition 4.5]{DS15}, we have $$\mathcal{C}(H)=\{\emptyset\} \cup \left\{\{v\} \cup T~:~ T \in \mathcal{C}(G)\right\}.$$ Using \cite[Lemma 3.1]{HHHKR10}, we know that for any $A \in \mathcal{C}(H)$, $\height(P_A(H))=(n+1)+|A|-c_H(A)$. Consequently, $\height(P_\emptyset(H))=n$, and for any $A \in \mathcal{C}(H)$ with $A \neq \emptyset$, we have $$\height(P_A(H))=2+n+|A\setminus \{v\}| -c_G(A \setminus \{v\})=2+\height(P_{A \setminus \{v\}}(G)).$$
Thus, \begin{align*}
    \bigheight(J_H)&= \max\left\{\height(P_\emptyset(H)), \max\left\{ \height(P_A(H))~:~ A\in \mathcal{C}(H)\right\} \right\}\\& =\max\left\{n,\max\left\{ 2+\height(P_{A \setminus \{v\}}(G))~:~ A \setminus \{v\} \in \mathcal{C}(G)\right\}\right\}\\& =\max\left\{n, 2+\max\left\{ \height(P_{T}(G))~:~ T \in \mathcal{C}(G)\right\}\right\} \\& =\max\left\{n, 2+\bigheight(J_G)\right\} .
\end{align*} 
\par (3) Assume that $\bigheight(J_G) \ge n-2.$ Then, $\pd\left(\frac{S}{J_G}\right) \ge \bigheight(J_G) \ge n-2.$ Therefore, by parts $(1-2)$, $\pd\left( \frac{S_H}{J_H}
        \right) =\max\left\{n, 2+\pd\left( \frac{S}{J_G}
        \right)\right\}=2+\pd\left( \frac{S}{J_G}
        \right) $
 and            $\bigheight(J_H)=\max\left\{n,2+\bigheight(J_G)\right\}=2+\bigheight(J_G).$ Thus, the desired result follows. 

\par (4) Assume that $\bigheight(J_G) < n-2$. Then, by part (2), $\bigheight(J_H) =n$. Therefore, by part (1), $\pd\left( \frac{S_H}{J_H} \right) =\bigheight(J_H)$ if and only if $\pd\left( \frac{S_H}{J_H} \right) =n$ if and only if  $\pd\left( \frac{S}{J_G}\right)\le n-2$. Thus, the desired result follows. 
\end{proof}

Next, we study complete multipartite graphs where the quotient of the binomial edge ideals has the same projective dimension as the big height.

\begin{proposition}\label{prop:com-bip}
    Let $G=K_{n_1,\ldots,n_k}$ be a complete multipartite graph with $2 \le n_1 \le \cdots \le n_k.$ Then, we have the following: \begin{enumerate}
        \item[$(1)$] $\pd\left(\frac{S}{J_G}\right)=2(n_2+\cdots+n_k)+n_1-2.$
        \item[$(2)$] $\bigheight(J_G)=2(n_2+\cdots + n_k).$
        \item[$(3)$] $\pd\left(\frac{S}{J_G}\right)=\bigheight(J_G)$ if and only if $n_1=2.$
    \end{enumerate}
\end{proposition}
\begin{proof}
    (1) We use the Auslander-Buchsbaum formula in  \cite[Corollary 4.5]{KS20} to get the projective dimension.
    \par (2) 
Let $V_1 \sqcup \cdots \sqcup V_k$ be a partition of the vertex set $V(G)$, where $|V_i|=n_i$ for $ i \in [k]$. According to \cite[Lemma 2.2]{Oh11}, we have $\mathcal{C}(G)=\{\emptyset\} \cup \{V(G) \setminus V_i~:~ i \in [k]\}$. It's important to observe that the connected components of $G[\bar {V(G) \setminus V_i}]$ correspond to the vertices that are part of $V_i$. Therefore, using \cite[Lemma 3.1]{HHHKR10}, we get  
$$\height(P_{V(G)\setminus V_i}(G))= (n_1+\cdots +n_k)+|V(G) \setminus V_i|-|V_i|=2(n_1+\cdots+n_k)-2n_i.$$ 
Applying the definition of the big height, we get 
\[
\begin{aligned}
\bigheight(J_G) & =\max\{ \height(P_T(G))~:~ T \in \mathcal{C}(G)\}\\
 & = \max\{ n_1+\cdots+n_k-1, \max\{2(n_1+\cdots+n_k)-2n_i~:~i \in [k]\}\}\\
 & =2(n_2+\cdots+n_k).
\end{aligned}
\]
    \par (3) This part clearly follows using parts $(1-2). $
\end{proof}

Malayeri et al. \cite[Theorem~5.3]{small-depth} proved that the projective dimension of the quotient of the binomial edge ideals is at most $2n-4$. They also \cite{small-depth} characterized graphs whose binomial edge ideals have the maximal projective dimension. Here, we verify that for binomial edge ideals of maximal projective dimension, the projective dimension is the same as the big height. 

\begin{proposition}
    Let $G$ be a graph on the vertex set $[n]$ with $\pd\left(\frac{S}{J_G}\right)=2n-4.$ Then, $$\pd\left(\frac{S}{J_G}\right)=\bigheight(J_G)=2n-4.$$
\end{proposition}
\begin{proof}
First, it is sufficient to prove that $\bigheight(J_G) \ge 2n-4$. From \cite[Theorem 5.3]{small-depth} and the Auslander-Buchsbaum formula, we know that $\pd\left(\frac{S}{J_G}\right)=2n-4$ if and only if $G=2K_1*H$, where $H$ is any graph on $n-2$ vertices. According to \cite[Propositions 4.5, 4.14]{DS15}, we also know that  $T=V(H) \in \mathcal{C}(G)$. It is important to note that $G[\bar T]$ is a disconnected graph with two isolated vertices. Therefore, we have $\height(P_T(G))=n+|T|-c_G(T)=n+(n-2)-2=2n-4$, and hence, $\bigheight(J_G) \ge \height(P_T(G)) =2n-4.$ This concludes the proof.
 \end{proof}


