\begin{proposition}\label{prop:Crownv}
    Let $G = C_{n,n}$ with $n\ge 4$. Then,  $\vn_{P_T(G)} (J_G)\le 4$ for all $T \in\mathcal{C}(G)$. 
\end{proposition}
\begin{proof} 
We know by \cite[Theorem 3.2]{JS23} (see also \cite[Theorem~3.6]{vnumberbinomial}) that if $G$ is a connected graph, then $\vn_{P_\emptyset(G)} (J_G) = \gamma_c(G)$. Therefore, by Lemma~\ref{lem:mindomset} we see $\vn_{P_\emptyset(G)} (J_G) = 4$. Let $T \in \mathcal{C}(G)$ be a nonempty set. Then, by Theorem \ref{thm:cut-point-prop}, we have the following cases:  
    \begin{itemize}
        \item Suppose $T =X$. Take $f=(x_2y_4-x_4y_2)(x_{2i}y_{2i+2}-x_{2i+2}y_{2i})$ for some $3\le i \le n-1$. Notice that $x_2y_4-x_4y_2 \in P_{\emptyset}(G)$. Since $x_2,y_2 \in P_Y(G)$ and   for any $1 \le j \le n$, either $x_2,y_2  \in  P_{Y\setminus \{2j\}}(G)$ or $x_4,y_4  \in  P_{Y\setminus \{2j\}}(G)$, we get $x_2y_4-x_4y_2 \in P_{Y}(G), P_{Y\setminus \{2j\}}(G)$. Also, if $T'=A \cup \{a+1~:~a \in A\}$ for some $A \subseteq X$ with $|A|=n-2$, then either $x_2,y_2 \in P_{T'}(G)$ or $x_4,y_4 \in P_{T'}(G)$ or $x_{2i},y_{2i} \in P_{T'}(G)$. This implies that $f\in P_{T'}(G).$ Finally, if $T'=X \setminus \{2j-1\}$ for some $1 \le j \le n$, then  either $x_2y_4-x_4y_2 \in P_{T'}(G)$ or $x_{2i}y_{2i+2}-x_{2i+2}y_{2i} \in P_{T'}(G)$  which implies that $f \in P_{T'}(G).$  Thus, $f \in P_{T'}(G)$ for all $T' \in \mathcal{C}(G) \setminus \{X\}$, and $f \not\in P_X(G)$. So, $(J_G : f)= P_X(G)$, and hence, $\vn_{P_X(G)} (J_G) \le 4$.
        \item Suppose $T=Y$. Take $f=(x_1y_3-x_3y_1)(x_{2i-1}y_{2i+1}-x_{2i+1}y_{2i-1})$ for some  $3\le i \le n-1$. Using similar argument as above, we get $(J_G : f)= P_Y(G)$, and hence, $\vn_{P_Y(G)}(J_G) \le 4$

        \item Suppose $T=X \setminus \{2i-1\}$ for some $i \in [n].$ Take $f=x_{2i-1}x_{2k}( x_{2i}y_{2j}-x_{2j}y_{2i})$, where $i,j,k$ are distinct with $1\le k,j \le n$. Notice that $x_{2i-1} \in P_X(G), P_{X \setminus \{ 2 \ell-1\}}(G)$ for any $\ell \ne i.$ This implies that $f \in P_X(G)$ and $f \in P_{X \setminus \{ 2 \ell-1\}}(G)$ for any $\ell \ne i.$ Since  $x_{2i}y_{2j}-x_{2j}y_{2i} \in P_\emptyset(G)$, we get $f \in P_{\emptyset}(G)$. Next, $x_{2k} \in P_Y(G)$ and either $x_{2k}$ or $x_{2i},y_{2i}$ are elements of $P_{Y\setminus \{2\ell\}}(G)$, we know that $f \in P_Y(G), P_{Y\setminus \{2\ell\}}(G)$ for any $1 \le \ell \le n.$ Finally, if $T'=A \cup \{a+1~:~a \in A\}$ for some $A \subseteq X$ with $|A|=n-2$, then either $x_{2i},y_{2i} \in P_{T'}(G)$ or $x_{2j},y_{2j} \in P_{T'}(G)$ or $x_{2k} \in P_{T'}(G)$. In either case, we get $f\in P_{T'}(G).$ Thus, $f \in P_{T'}(G)$ for all $T' \in \mathcal{C}(G) \setminus \{X\}$, and $f \not\in P_X(G)$. So, $(J_G : f)= P_X(G)$, and hence, $\vn_{P_{X \setminus \{2i-1\}}(G)} (J_G) \le 4$. 

        \item Suppose $T=Y \setminus \{2i\}$ for some $i \in [n]$. Take $f=x_{2k-1}x_{2i}
        (x_{2i-1}y_{2j-1}-x_{2j-1}y_{2i-1})$ where $i,j,k$ are distinct with $1\le j,k \le n$. Using the similar arguments to the previous case, we get $(J_G: f)= P_{Y\backslash\{2i\}}(G)$. Thus, $\vn_{P_{Y\setminus \{2i\}}(G)}(J_G) \le 4 $.

        \item Suppose $T=A \cup \{a+1~:~ a\in A\}$ where $A \subseteq X$ with $|A|=n-2$ and $2i-1,2i,2j-1,2j \notin T$. Take  $f=(x_{2i-1}y_{2j-1}-x_{2j-1}y_{2i-1})(x_{2i}y_{2j}-x_{2j}y_{2i})$. Then $x_{2i-1}y_{2j-1}-x_{2j-1}y_{2i-1}$ is in $P_\emptyset(G), P_X(G), P_{X\setminus \{2\ell -1\}}$ for every $1 \le \ell \le n$. Also,  $x_{2i}y_{2j}-x_{2j}y_{2i}\in P_Y(G)$ and $P_{Y\backslash\{2\ell\}}$ for $1 \le \ell \le n$. Finally, for any subset $B \ne A$ of $X$ with $|B|=n-2$, either $2i-1 \in B$ or $2j-1 \in B$, i.e., $x_{2i-1}y_{2j-1}-x_{2j-1}y_{2i-1} \in P_{T'}(G)$, where $T'=B \cup \{b+1~:~b \in B\}.$  So, if we take  $f=(x_{2i-1}y_{2j-1}-x_{2j-1}y_{2i-1})(x_{2i}y_{2j}-x_{2j}y_{2i})$, then  $(J_G:f)=P_{T}(G)$. Hence, $\vn_{P_T(G)}(J_G)\le 4.$
    \end{itemize}
The desired result follows from all the considered cases
    \end{proof}

\begin{remark}\label{rmk}
When $G=C_{3,3}$, using the same reasoning as in the proof of Proposition \ref{prop:Crownv}, we find that $\vn_{P_T(G)}(J_G)\le 4 $ for all $T \in \mathcal{C}(G) \setminus \{X,Y\}$. This implies that Proposition \ref{prop:Crownv} applies to all cases except for certain instances where $T \in \mathcal{C}(G)$. It's worth mentioning that $C_{3,3}$ is a cycle graph with six vertices. \end{remark}

\begin{lemma}\label{lem:vlb}
    Let $G=C_{n,n}$ with $n \ge 3.$ Then $\vn_{P_T(G)}(J_G) \ge 3$ for all $T \in \mathcal{C}(G).$
\end{lemma}
\begin{proof}
It is known from \cite[Theorem 3.20]{vnumberbinomial} that for a connected graph $H$ on the vertex set $[n]$, $\vn(J_H)=1$ if and only if $H$ has a vertex of degree $n-1.$ Since $G$ is a connected graph on $2n$ vertices and $G$ has no vertex of degree $2n-1$, $\vn(J_G) \ge 2. $ 

For any two vertices $u$ and $v$ in the graph $G$, we have $\deg_G(u) = n-1 = \deg_G(v)$. If $\{u,v\} \in E(G)$, then $|N_G(u) \cup N_G(v)| \le 2n-2$, which means that $N_G(u) \cup N_G(v)$ is not equal to $V(G)$. Also, if $\{u,v\} \not\in E(G)$, then either $N_G(u) \cap N_G(v) = \emptyset$ or $|N_G(u) \cap N_G(v)| = n-2$. From Proposition \ref{prop:graph-connectivity}, we conclude that $N_G(u) \cap N_G(v)$ is not a cut set of $G$. Therefore, by \cite[Theorem 4.1]{vconjecture}, we  infer that $\vn(J_G) \neq 2$, and thus, $\vn(J_G) \ge 3$. \end{proof}



Based on Proposition~\ref{prop:Crownv} and Lemma~\ref{lem:vlb}, we deduce that for the crown graph $G = C_{n,n}$ with $n \ge 4$, 
\[
3 \le \vn(J_G) \le \vn_{P_T(G)}(J_G) \le 4 \quad \text{for every } T \in \mathcal{C}(G).
\]
In particular, we have the following result: 
\begin{theorem}\label{thm:vertex_number_bound}
Let $G = C_{n,n}$ with $n \ge 4$. Then, 
\[
3 \le \vn(J_G) \le 4.
\]
\end{theorem}


We strongly believe that $\vn(J_G)=4$. In light of Proposition~\ref{prop:Crownv}, this is equivalent to asserting that $\vn_{P_T(G)}(J_G)=4$ for every $T \in \mathcal{C}(G)$. Indeed, we have already established the case $T=\emptyset$ in Lemma~\ref{lem:mindomset}, where $\vn_{P_{\emptyset}(G)}(J_G)=4$. These observations motivate the following conjecture:

\begin{conjecture}
Let $G=C_{n,n}$ with $n \ge 4$. Then, for every $T \in \mathcal{C}(G)$, we have
\[
\vn_{P_T(G)}(J_G)=4.
\]
\end{conjecture}


To further support the conjecture, we now examine the local $\vn$-numbers of binomial edge ideals of crown graphs. Our approach employs the recursive method introduced by Ohtani \cite{Oh11} to analyze the $\vn$-numbers of both crown graphs and cycles. In \cite{Oh11}, Ohtani established that for any graph $G$ and any internal vertex $v$ of $G$,
\[
J_G = J_{G_v} \cap \Big( (x_v, y_v) + J_{G \setminus v} \Big).
\]
This key technical result was first used by the first author in \cite{K21} and his thesis, and was later generalized to the setting of generalized binomial edge ideals (see \cite{genbin}). Since then, it has become a central tool in the study of binomial edge ideals and has found numerous applications. In the remainder of this section, we showcase a few more applications of this method.







\begin{lemma}\label{lem:v-A}
    Let $G=C_{n,n}$ with $n \ge 3.$ Let $A \subset X$ with $|A|=n-2$.  Then $\vn_{P_T(G)}(J_G) =4$ for  $T=A \cup \{i+1~:~ i \in A\}$.
\end{lemma}
\begin{proof} Due to \cite[Proposition 4.2]{CSTPV20}, it follows that $$\vn_{P_T(G)}(J_G)= \alpha\left( \frac{J_G:P_T(G)}{J_G} \right),$$  here for a finitely generated positively graded module $M$, $\alpha(M)$ denoted the least positive integer $n$ so that $M_n \neq 0$. This means that to calculate $\vn_{P_T(G)}(J_G)$, we need to examine $J_G:P_T(G)$. We present the proof for the case where $A=\{1,3,\ldots, 2n-5\}$ for simplicity, noting that the same proof applies to any $A\subset X$ with $|A|=n-2$, with some changes in notation. According to Theorem \ref{thm:cut-point-prop}, $P_T(G)$ is a minimal prime of $J_G$ and $$P_T(G)=\langle x_i,y_i~:~ i\in T\rangle+\langle x_{2n-3}y_{2n}-x_{2n}y_{2n-3}\rangle + \langle x_{2n-1}y_{2n-2}-x_{2n-2}y_{2n-1}\rangle .$$

    According to \cite[Lemma 4.8]{Oh11},  for every internal vertex $v$ of $G$: $$J_G=J_{G_v}\bigcap \left(( x_v,y_v) +J_{G\setminus v}\right).$$ This implies that $J_G:x_v=J_G:y_v=J_{G_v}$ for every $v\in  T.$ As a result,  $(J_G:x_v) \cap (J_G:y_v)=J_{G_v}$ for all $v \in T$. We also know that $x_{2n-3}y_{2n}-x_{2n}y_{2n-3},~   x_{2n-1}y_{2n-2}-x_{2n-2}y_{2n-1} \in J_G$. Thus, we have $J_G:x_{2n-3}y_{2n}-x_{2n}y_{2n-3}=S=J_G:  x_{2n-1}y_{2n-2}-x_{2n-2}y_{2n-1}.$ 

Therefore, we can express $J_G:P_T(G)$ as follows:
\begin{align*} 
J_G:P_T(G) & = \left(\bigcap_{v \in T} (J_G :x_v)  \right)\cap (J_G: x_{2n-3}y_{2n}-x_{2n}y_{2n-3}) \cap (J_G:  x_{2n-1}y_{2n-2}-x_{2n-2}y_{2n-1})\\
& =\left(\bigcap_{v \in T} (J_G :x_v)  \right) \cap S \cap S= \bigcap_{v \in T} J_{G_v}. 
\end{align*} 

    Let $f$ be a homogeneous polynomial such that $J_G:f=P_T(G)$. Then, $f \in \left( J_G:P_T(G)\right)$ and $f \notin J_G$ which implies that  $f \in J_{G_v} \setminus J_G$ for $v \in T.$ Thus, for every $v \in T$, $f$ can be expressed as $$\displaystyle f= \sum_{e \in E(G_v)} c_{v,e}f_e,$$  where $c_{v,e}$ are homogeneous polynomials in $S$, and $f_e=x_iy_j-x_jy_i$ if $e=\{i,j\}$. For some $u \in T$,  we may assume that  $$\displaystyle f= \sum_{e \in E(G_u) \setminus E(G)} c_{u,e}f_e.$$ Indeed, if not, then we can replace $f$ by $f'$ where $f=f'+f''$ with $\displaystyle f'= \sum_{e \in E(G_u) \setminus E(G)} c_{u,e}f_e$ and $\displaystyle f''= \sum_{e \in  E(G)} c_{u,e}f_e.$ Without loss of generality, we may assume that $u=1.$ 

    We know from Lemma \ref{lem:vlb} that $\deg(f) \ge 3.$ Suppose that $\deg(f)=3.$ Then, every nonzero homogeneous polynomial $c_{v,e}$ appearing in the expression of $f$ is of degree one. Since $f \in J_{G_v} \setminus J_G$, there exists $e_v \in E(G_v) \setminus E(G)$ such that $c_{v,e_v} \neq 0$, i.e., $c_{v,e_v}$ is a degree one homogeneous polynomial. Now, for $u=1$, $f_{e} \in \langle x_i, y_i ~:~ i\in \{2,4\ldots, 2n\}\rangle^2$ for all $e \in E(G_u) \setminus E(G).$ Thus, at most one variable from each terms of $f$  can be in $\langle \{x_i,y_i~:~ i \in \{1,3,\ldots, 2n-1\}\}\rangle.$ This implies that for all $v \in \{a+1~:~a \in A\}$, $$\displaystyle f= \sum_{e \in E(G_v)} c_{v,e}f_e =\sum_{e \in E(G_v)\setminus E(G)} c_{v,e}f_e+\sum_{e \in E(G)} c_{v,e}f_e\not \in J_{G_v} \setminus J_G$$ as $f_{e_v} \in \langle \{x_i,y_i~:~ i \in \{1,3,\ldots, 2n-1\}\}\rangle^2.$ This leads to a contradiction. Thus, $\deg(f) \ge 4,$ and hence, using Proposition \ref{prop:Crownv}, we get that $\vn_{P_T(G)}(J_G) =4. $ 
\end{proof}




\subsection{v-numbers of binomial edge ideals of cycles:}\label{vcycle}
 Deblina et al. in \cite{vconjecture} conjectured that (see \cite[Conjecture 4.13]{vconjecture}) the $\vn$-number of binomial edge ideal of $C_n$ is $\left\lceil\frac{2n}{3}\right\rceil.$ In this subsection, we prove this conjecture. 




\begin{theorem}\label{thm: vT-cycle}
Let $G=C_n$ with $n\ge 6$. Then,  $\vn(J_G)= \left\lceil\frac{2n}{3}\right\rceil.$ 
\end{theorem}
\begin{proof}
    Let $T\in\mathcal{C}(G)$ be any subset. If $T$ is empty, then by \cite[Theorem 3.2]{JS23} (also see \cite[Theorem~3.6]{vnumberbinomial}), we know that $\vn_{P_\emptyset(G)}(J_G)=\gamma_c(G)$. It is well-known that $\gamma_c(C_n)=n-2$. Therefore, we have $\vn_{P_\emptyset(G)} (J_G) =n-2 \ge \left\lceil\frac{2n}{3}\right\rceil$. Now, assume that $T$ is not empty, i.e., there exists a vertex $v$ such that $v \in T$. Without loss of generality, let's assume that $v=n$. Let $f\in S$ be a homogeneous polynomial such that $J_G: f = P_T(G)$. According to \cite[Lemma~4.8]{Oh11}, we have $$J_G=J_{G_v}\bigcap \left(( x_v,y_v)+J_{G\setminus v}\right).$$ 

    Since $f\in P_A(G)$ for all $A \in \mathcal{C}(G)$ with $A\neq T$, it follows that $f\in P_A(G)$ when $v\notin A$. This means that $f \in J_{G_v}$. It's worth noting that $G_v$ is a graph with vertex set $[n]$ and edge set $E(G_v)=E(G) \cup \{\{1,n-1\}\}$. Thus, we can express $f$ as $f = \sum_{e\in E(G_v)} c_ef_e$, where $c_e$ are homogeneous polynomials in $S$, and $f_e=x_iy_j-x_jy_i$ if $e=\{i,j\}$. We set $e'=\{1,n-1\}$. It is easy to  observe that $f=g+c_{e'}f_{e'}$ where $g \in J_G$, and hence,  $J_G:f=J_G:(c_{e'}f_{e'})$. This leads to $P_T(G)=J_G: c_{e'}f_{e'} =(J_G:f_{e'}):c_{e'}$.

    It follows from \cite[Theorem~3.7]{Hilbbino} that
    \begin{align*}\label{eq: vn}
        P_T(G) &= \left(J_{G_{e'}} + \langle x_n, y_n, x_2x_3\cdots x_{n-2}, y_2x_3\cdots x_{n-2}, \ldots, y_2y_3\cdots y_{n-2}\rangle \right) : c_{e'},
    \end{align*}
where $G_{e'}$ is the graph on the vertex set $[n]$ and edge set $E(G_{e'})=E(G) \cup \left\{\{2,n\},n-2,n\} \right\}.$ One can observe that $J_{G_{e'}}+(x_n,y_n)=J_{P_{n-1}} +\langle x_n,y_n \rangle $, where $P_{n-1}$ is the path graph on vertices $1,2,\ldots,n-1$. We set $K = \langle x_2x_3\cdots x_{n-2}, y_2x_3\cdots x_{n-2}, \ldots, y_2y_3\cdots y_{n-2} \rangle$. Then,   
    $P_T(G)= \left(\langle x_n, y_n\rangle + J_{P_{n-1}} + K\right) : c_{e'}.$ 
If $x_n$ or $y_n$ appear in some terms of $c_{e'}$, we can express $c_{e'}$ as $ax_n+by_n+c$ where $a$, $b$, and $c$ are homogeneous polynomials in $S$. Then, we have $P_T(G)=\left(\langle x_n, y_n \rangle + J_{P_{n-1}} + K\right) : c_{e'} =\left(\langle x_n, y_n \rangle + J_{P_{n-1}} + K\right) : c$. Without loss of generality, we assume that $c=c_{e'}$, meaning $x_n$ or $y_n$ do not appear in any term of $c_{e'}$. From \cite[Lemma 3.6]{HJKN}, we have $P_T(G)= \langle x_n, y_n \rangle  + \left(J_{P_{n-1}} + K\right) : c_{e'}$. Let $R=\KK[x_i,y_i~:~ i\in[n-1]]$. Contracting $P_T(G)$ to $R$, we obtain $P_{T\setminus \{n\}}(G\setminus \{n\})= \left(J_{P_{n-1}} + K\right) : c_{e'}.$

Let $A=T\setminus \{n\}.$ Note that $A \in \mathcal{C}(P_{n-1})$ and $A \neq \emptyset.$ Suppose now, to the contrary, $\deg(f) \le \left\lceil\frac{2n}{3}\right\rceil-1.$ Then, $\deg(c) =\deg(f)-2\le \left\lceil\frac{2n}{3}\right\rceil-3.$ Now, for any $i \in A$,  $x_i,y_i \in P_A(P_{n-1})$ which implies  $x_ic, y_ic \in  J_{P_{n-1}} + K$ as $P_A(P_{n-1})= \left(J_{P_{n-1}} + K\right):c$. That is, $$x_ic= \sum_{e \in E(P_{n-1})}u_ef_e+v_1(x_2x_3\cdots x_{n-2})+v_2(y_2x_3\cdots x_{n-2})+\cdots +v_{n-2} (y_2y_3\cdots y_{n-2}),$$ where $u_e$'s and $v_i$'s are homogeneous polynomials in $R$. Since $n\ge 6$,  $\left\lceil\frac{2n}{3}\right\rceil-2 <n-3$. Thus, we get that $x_ic \in J_{P_{n-1}}$ by comparing degrees on both sides. Similarly, we get $y_ic \in J_{P_{n-1}}.$ That is $x_i,y_i \in J_{P_{n-1}}:c.$ Now, for each $i\in A$, it holds that $2 \le i \le n-2$. Thus, we have $K \subseteq J_{P_{n-1}}:c$. Additionally, we also know that $J_{P_{n-1}} \subseteq J_{P_{n-1}}:c$. As a result, $J_{P_{n-1}}+K \subseteq J_{P_{n-1}}:c$, implying that $\left( J_{P_{n-1}}+K \right) :c\subseteq J_{P_{n-1}}:c^2=J_{P_{n-1}}:c $. Therefore, $P_A(P_{n-1})= \left(J_{P_{n-1}} + K\right):c=  J_{P_{n-1}}:c $. Now, due to  \cite[Corollary 3.6]{vconjecture},  $\deg(c) \ge \vn_{P_A(P_{n-1})}(J_{P_{n-1}}) \ge \vn(J_{P_{n-1}}) =\left\lceil\frac{2(n-2)}{3}\right\rceil$. This leads to a contradiction as we assume $ \deg(c) \le \left\lceil\frac{2n}{3}\right\rceil-3.$ Therefore, $\deg(f) \ge \left\lceil\frac{2n}{3}\right\rceil $, and hence, $\vn_{P_T(G)}(J_{G}) \ge \left\lceil\frac{2n}{3}\right\rceil$, which further implies that  $\vn\left(J_{G}\right)\ge \left\lceil\frac{2n}{3}\right\rceil$. Now, the rest follows from  \cite[Corollary~4.12]{vconjecture}.
\end{proof}


As an immediate consequence, we obtain the $\vn$-number of the binomial edge ideal of the crown graph $C_{3,3}.$

\begin{corollary}
    Let $G=C_{3,3}$. Then, $\vn(J_G)=4.$
\end{corollary}
\begin{proof}
    As we pointed out in Remark \ref{rmk} $C_{3,3}$ is a cycle graph on six vertices. The rest follows from Theorem \ref{thm: vT-cycle}. 
\end{proof}

We conclude the article by posing the following question: 

\begin{question}
What are the local $\vn$-numbers of the binomial edge ideal of cycles?\end{question}

