\caption{Initial activity ($a_0$) of runs starting from different zones of attractant concentration as function of wave speed for large $\lambda$. The zones have been chosen such that the entire concentration range is split in roughly four equal parts, as shown in the legends. The maximum error-bar in these data is $10^{-5}$. All other simulation parameters are as in Fig. \ref{fig:v500}.}
\label{fig:acwhol}
\end{figure}  
