	\title{Spectrum of the Laplacian in waveguide shaped surfaces}

\author{Diana C. S. Bello \footnote{dianasuarez@estudante.ufscar.br} \\
{\small Departamento de Matemática – UFSCar, São Carlos, SP, 13565-905, Brazil}} 




	\date{\today}

	\maketitle 

	\begin{abstract}




	\end{abstract}


Let $-\Delta_{\cal S}$ be the Laplace operator in ${\cal S} \subset \mathbb{R}^3$ on a waveguide shaped surfaces, i.e., ${\cal S}$ is built by translating a closed curve in a constant direction along an
unbounded spatial curve. Under the condition that the tangent vector
of the reference curve admits a finite limit at infinity, we find the essential spectrum of $-\Delta_{\cal S}$ and discuss conditions under which discrete eigenvalues emerge. Furthermore, we analyze the Laplacian in the case of a broken sheared waveguide shaped surface.

	\

	\noindent {\bf Mathematics Subject Classification (2020).} Primary: 49R05, 58J50;
	Secondary: 47A75, 47F05.

	\

	\noindent    {\bf Keywords:} Surface, Laplacian, Essential spectrum, Discrete spectrum.
	\

	%\noindent {Running head:} XXXXXXXXXXXXXX

	%


	\section{Introduction}


The spectral properties of the Laplace operator on unbounded domains 
$\Omega \subset \mathbb{R}^n$ have received considerable attention in recent years. In these domains, the existence of discrete eigenvalues is a non-trivial problem, influenced by both the geometric characteristics of the domain and the type of boundary conditions imposed, typically Dirichlet, Neumann, or mixed Dirichlet–Neumann conditions \cite{avishai, belloverri, bori2, bori1, briet, bulla, carini, duclosfk, dittrichakriz2, duclos, exnerseba, solomyak0, gold, daviddn, davidkriz, davidlu, davidmainpaper, olendski, renger, verri}. In these works the authors investigated the spectrum of the Laplace operator inside unbounded domains, such as strips or waveguides. Nevertheless, a natural question arises when one considers an alternative perspective: what spectral properties emerge if the waveguide surface itself is taken as the domain of analysis, without imposing conventional boundary conditions? In this scenario, the spectral behaviour is no longer governed primarily by external constraints, but rather by the intrinsic geometry of the surface. Understanding how this intrinsic geometry influences the spectral properties of the associated Laplace operator opens new avenues in spectral geometry and mathematical physics.


The main motivation of the present work is to explore  the spectrum of the Laplace operator  on waveguide-shaped surfaces without imposing boundary conditions. Specifically, inspired by the results in \cite{ohv, verri}, we demonstrate that the essential spectrum of the operator is determined by the asymptotic behaviour of the surface at infinity. Moreover, we establish sufficient conditions under which discrete spectrum arises.


Let $\{e_1, e_2, e_3\}$ the canonical basis of $\mathbb{R}$., and  $\xi: [0,1] \longrightarrow \mathbb{R}^2$ be a simple closed curve $C^2$ in the $\{e_2, e_3\}$ plane, parametrized by arc length $t$ (i.e., $\|\xi'(t)\|=1$, $\forall t \in [0,1]$) with $\xi(t)=  (\xi_1(t), \xi_2(t))$. Suppose that $f,g:\mathbb{R} \longrightarrow \mathbb{R}$ are locally Lipschitz continuous functions, differentiable almost everywhere, with derivatives $f', g' \in L^\infty(\mathbb{R})$. Next, we consider the spatial curve 
\begin{equation*}
	r(x)= (x, f(x), g(x)), \quad x \in \mathbb{R}.
	\end{equation*}
Define the mapping
\begin{equation*}
		\begin{array}{lcll}
			\mathcal{P} : & \mathbb{R} \times {\cal C}  & \longrightarrow & \mathbb{R}^3\\
			& (x,t)          & \longmapsto     & r(x) + \xi_1(t) e_2 +\xi_2(t) e_3 ,
		\end{array}
	\end{equation*}
where  ${\cal C}$ denotes the circle with length equal to one,  and the surface given by
\begin{equation*}
		{\cal S} := \mathcal{P} (\mathbb{R} \times {\cal C}).
	\end{equation*} 
such that, ${\cal S}$ is obtained by translating the curve $\xi$ along $r(x)$, as illustrated in Figure \ref{fig_surf}.  

	Let  $-\Delta_{\cal S}$ the Laplace operator in ${\cal S}$, i.e., , the self-adjoint operator associated with the quadratic form	%
	\begin{equation*}
Q_{\cal S} (\psi) 
		= \int_{\cal S} |\nabla \psi|^2 {\rm d}{\bf x}, \quad \dom Q_{\cal S}
		= {\cal H}^1({\cal S}),
	\end{equation*}
	%
	where ${\bf x} = (x, y,z)$ denotes a point of ${\cal S}$ and $\nabla \psi$ denotes the gradient vector of  $\psi$. The objective of this paper is to study the spectral problem of $-\Delta_{\cal S}$. Motivated by \cite{verri}, we assume that  
\begin{equation}\label{eq:condlim_surf}
    \lim_{|x| \to \infty} f'(x) =: \beta_1, \quad  \lim_{|x| \to \infty} g'(x) =: \beta_2, \quad \beta_1, \beta_2 \in \mathbb{R}.
\end{equation}


 \begin{figure}[ht]
    \centering
    \hspace{0.5cm}
    \begin{tabular}{cc}
    \adjustbox{valign=m}{\subfloat[Surface ${\cal S}$.\label{subfig-1:dummy}]{%
          \includegraphics[width=0.4\textwidth]{Surf_fg_corr2.pdf}}}
    &      
    \adjustbox{valign=m}{\begin{tabular}{@{}c@{}}
    \subfloat[$xy$-plane view. \label{subfig-2:dummy}]{%
          \hspace{1cm}\includegraphics[width=0.07\textwidth]{Surf_fg_corr_planexy.pdf} 
          \hspace{1cm}}  
          \vspace{0.5cm}
          \\ 
    \subfloat[$xz$-plane view.\label{subfig-3:dummy}]{%
          \hspace{1cm}\includegraphics[width=0.07\textwidth]{Surf_fg_corr_planexz.pdf} \hspace{1cm}} 
    \end{tabular}}
    \end{tabular}
    \caption{Waveguide shaped surface.}\label{fig_surf}
  \end{figure}

Our first objective is to characterize the essential spectrum of $-\Delta_{\cal S}$. For this purpose, we consider the two-dimensional operator
\begin{equation}\label{fourpp:surf_surf}
    		T_{\beta_1, \beta_2}:=- \frac{\partial}{\partial t} \left[ \left(\frac{1+\beta_1^2 + \beta_2^2}{h_{\beta_1,\beta_2}^2}\right) \partial_t \right] + (1+\beta_1^2 + \beta_2^2) \left[\left(\frac{(h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^4} \right)' + \left( \frac{(h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^3}\right)^2\right] ,
	\end{equation}
 \begin{equation*}
     \dom T_{\beta_1,\beta_2} :=\{v \in {\cal H}^1({\cal C}):  T_{\beta_1,\beta_2} v \in L^2({\cal C}), \; v'(0)=v'(1)\},
 \end{equation*}
 where $h_{\beta_1,\beta_2}^2 := 1+(\beta_1 \xi'_2 - \beta_2 \xi'_1)^2$. Denote by $E_1(0)$ the first eigenvalue of $T_{\beta_1,\beta_2}$ and by $\chi$ its corresponding normalized eigenfunction. Since $T_{\beta_1,\beta_2}$ is an elliptic operator with real coefficients, $E_1(0)$ is simple.  

\vspace{0.2cm}	
\begin{Theorem}\label{theo:surfess_surf}
	Suppose that the conditions in \eqref{eq:condlim_surf} hold. Then, $$\sigma_{ess}(-\Delta_{\cal S}) = [E_1(0), \infty).$$
	\end{Theorem}

The proof of Theorem \ref{theo:surfess_surf} is presented in Section \ref{sec3}.  


 The next step is to analyze the existence of discrete eigenvalues for  $-\Delta_{\cal S}$. Define, for all $x \in \mathbb{R}$,  the functions  
 \begin{equation*}
   A(x) := \int_{\cal C} \frac{1}{h^2} |\chi^2| \dt, \quad
   B(x):= \int_{\cal C}    \left[(f' \xi'_1+ g' \xi'_2) \frac{ \partial_t h^2}{2 h^4} +\frac{\partial}{\partial t}\left(\frac{f' \xi'_1+ g' \xi'_2}{h^2}\right)  -  \frac{\partial_x h^2}{2h^4}
   \right] |\chi|^2 \dt,
 \end{equation*}
 \begin{equation*}
     C(x):= \int_{\cal C} \left[\left (\frac{\partial_x h^2}{4h^3} \right)^2   - \frac{\partial}{\partial t}  \left( (f' \xi'_1+ g' \xi'_2) \frac{ \partial_x h^2}{4 h^4} \right)  -  (f' \xi'_1+ g' \xi'_2)\frac{ \partial_x h^2 \partial_t h^2}{8 h^6} \right] |\chi|^2 \dt,
 \end{equation*}
 \begin{equation*}
     D(x):= \int_{\cal C} \left(\frac{1}{h^2} |\chi'|^2 + \left[
  \frac{\partial}{\partial t} \left(\frac{\partial_t h^2}{4 h^4} \right) + 
 \left(\frac{ \partial_t h^2}{4 h^3}\right)^2 \right] |\chi|^2 \right)  \dt,
 \end{equation*}
 the constant 
 \begin{equation*}
     E:= \int_{\cal C} \left( \frac{1}{h_{\beta_1, \beta_2}^2} |\chi'|^2 + \left[ \left(\frac{(h_{\beta_1, \beta_2}^2)'}{4 h_{\beta_1, \beta_2}^4} \right)' +  \left(\frac{ (h_{\beta_1, \beta_2}^2)'}{4 h_{\beta_1, \beta_2}^3}\right)^2 \right] |\chi|^2 \right) \dt,
 \end{equation*}
and the function 
\begin{equation*}
  V(x):=  C(x) + (1+(f')^2 + (g')^2) D(x) -  
 (1+\beta_1^2 + \beta_2^2)  E, \quad x \in \mathbb{R}.  
\end{equation*}


\begin{Theorem}\label{exidisspc_surf}
	Suppose that the conditions in \eqref{eq:condlim_surf} hold, $V(x) \in L^1(\mathbb{R})$ and $\int_\mathbb{R} V(x)<0$. Then,  $$\inf \sigma (-\Delta_{\cal S}) < E_1(0),$$
 i.e., 
	$\sigma_{dis}(-\Delta_{\cal S}) \neq \emptyset$. 
\end{Theorem}

The proof of this result is given in Section \ref{sec4}. Note that the condition $\int_{\mathbb{R}} V(x) \dx<0$ implies the existence of discrete eigenvalues for $-\Delta_{\cal S}$. However, it is not a necessary condition for this happen. For instance,

\begin{Theorem}\label{exidisspc_surf2}
    Suppose that the conditions in  \eqref{eq:condlim_surf} hold, $V(x), B(x) \in L^1(\mathbb{R})$,  $\int_\mathbb{R} V(x)=0$ and $B(x)$ is not constant. Then,  $$\inf \sigma (-\Delta_{\cal S}) < E_1(0),$$
 i.e., 
	$\sigma_{dis}(-\Delta_{\cal S}) \neq \emptyset$. 
\end{Theorem}
The proof of this result is also presented in Section \ref{sec4}.

Now, motivate by \cite{belloverri}, we consider a ``broken sheared waveguide shaped surfaces'', in which $f(x)$ is a null function and $g(x)=\beta|x|$, for all $x \in \mathbb{R}$. Observe that in this case, we are not under the conditions of the Theorems \ref{exidisspc_surf} and \ref{exidisspc_surf2}. Thus, take $\beta \in (0, \infty)$, consider the spatial curve
\begin{equation*}
		r_\beta(x)= (x, 0, g(x)), \quad x \in \mathbb{R}.
	\end{equation*}
 Define the mapping
\begin{equation}\label{lmas_surfcant}
		\begin{array}{lcll}
			\mathcal{P}_\beta : & \mathbb{R} \times {\cal C}  & \longrightarrow & \mathbb{R}^3\\
			& (x,t)          & \longmapsto     & (x, \xi_1(t), \xi_2(t) + \beta |x|),
		\end{array}
	\end{equation}
and the surface  
\begin{equation*}
		{\cal S}_\beta := \mathcal{L}_\beta (\mathbb{R} \times {\cal C}).
	\end{equation*} 
Similarly to the surface $\cal S$, geometrically, ${\cal S}_\beta$ is obtained by translating the closed curve $\xi$ along the curve $r_\beta(x)$. Furthermore,  note that ${\cal S}_\beta$ is symmetric with respect to the $\{e_2,e_3\}$ plane, and it has a ``corner'' lying in this plane, as shown in the Figure \ref{fig:surf_beta}. 

\begin{figure}[ht]
	\centering
	\includegraphics[width=0.7\textwidth]{Surface_beta.pdf}
	%\caption{Subfigure}
	\caption{Broken sheared waveguide shaped surfaces, with $\beta=0.5$.}
	\label{fig:surf_beta}
\end{figure}


	Denote by  $-\Delta_{{\cal S}_\beta}$ the Laplace operator in ${\cal S}_\beta$, i.e., the self-adjoint operator associated with the quadratic form 
	%
	\begin{equation*}
Q_{{\cal S}_\beta} (\psi) 
		= \int_{{\cal S}_\beta} |\nabla \psi|^2 {\rm d}{\bf x}, \quad \dom Q_{{\cal S}_\beta}
		= {\cal H}^1({\cal S}_\beta).
	\end{equation*}
	%

In this case, consider the two-dimensional operator  
\begin{equation*}
    		T(\beta):=- \frac{\partial}{\partial t} \left[ \left(\frac{1+\beta^2}{h_\beta^2}\right) \partial_t \psi\right] + (1+\beta^2) \left[  \left(\frac{(h_\beta^2)'}{4 h_\beta^4} \right)'  + \left| \frac{(h_\beta^2)'}{4 h_\beta^3}\right|^2  \right],
	\end{equation*}
 \begin{equation*}
     \dom T(\beta)=\{v \in {\cal H}^1({\cal C}):  T(\beta) v \in L^2({\cal C}), \; v'(0)=v'(1)\}.
 \end{equation*}
where $h_\beta^2(t) = 1+ \beta^2 (\xi'_1(t))^2$. Denote $E_1(\beta)$ and $\chi_1$ to be the first eigenvalue and the corresponding normalized eigenfunction associated to $T(\beta)$, respectively.

\begin{Theorem}\label{propress_surfcant}
	For each $\beta \in (0, \infty)$, the essential spectrum of  $-\Delta_{{\cal S}_\beta}$ is the interval $[E_1 (\beta),\infty)$. 
\end{Theorem}

In order to analyze the existence of discrete eigenvalues for $-\Delta_{{\cal S}_\beta}$. Define the constants 
 \begin{align*}
   A &:= \int_{\cal C} \frac{|\chi_1|^2}{h_\beta^2} \dt \quad \mbox{and} \quad 
   B:= \int_{\cal C}   \left( \left(\frac{\xi'_2(t)}{h_\beta^2} \right)' + \frac{ \xi'_2(t) (h_\beta^2)'}{2 h_\beta^4} \right) |\chi_1|^2 \dt.
 \end{align*}


\begin{Theorem}\label{exidisspc_surfcant}
    Suppose that $B$ a nonzero constant. For each  $\beta \in (0, \infty)$, one has  $\inf \sigma (-\Delta_{{\cal S}_\beta}) < E_1(\beta)$, i.e., 
	$\sigma_{dis}(-\Delta_{{\cal S}_\beta}) \neq \emptyset$.
\end{Theorem}

The proof of Theorems  \ref{propress_surfcant} and \ref{exidisspc_surfcant} are presented in Section \ref{sec5}.



\begin{Remark}\label{remidn1}{\rm 
Let $f(x)$ be a null function and $g(x)$ an even function, so that $\lim_{x \to \infty} g'(x)= \beta$. In this scenario, the waveguide shaped surface $\cal S$ would possess symmetry relative to the $\{e_2, e_3\}$ plane. Thus, following the ideas from the proofs in the Section \ref{sec5}, we can show the existence of elements in the discrete spectrum of $-\Delta_{\cal S}$.}
	\end{Remark}
