The present work is organized as follows. In Section \ref{sec2} we describe the usual changes of coordinates to work in the Hilbert space $L^2(\Sigma)$ with the usual metric. In Section \ref{sec3} we study the essential spectrum of  $-\Delta_{\cal S}$ as well as the proof of Theorem \ref{theo:surfess_surf}. Next, Section \ref{sec4} is dedicated to study the discrete spectrum of $-\Delta_{\cal S}$. Where, we present the proofs of Theorems  \ref{exidisspc_surf} and  \ref{exidisspc_surf2}. Finally, Section \ref{sec5} concerns the spectral analysis of the Laplace operator in a broken sheared waveguide shaped surfaces, in turns, containing the proofs of Theorems \ref{propress_surfcant} and \ref{exidisspc_surfcant}. 


\section{Change of coordinates} \label{sec2}

Recall that  ${\cal S} = {\cal P}(\Sigma)$, where $\Sigma := \mathbb{R \times {\cal C}}$. Then, in this section we perform a change of coordinates such that $Q_{\cal S}(\psi)$ starts to act in the Hilbert space $L^2(\Sigma)$ instead of $L^2(\cal S)$.

Let $G=(G_{ij})$ be the metric induced by   ${\cal P}$, i.e.,
	\[G_{ij} = \langle {\cal G}_i, {\cal G}_j \rangle = G_{ji}, \quad i,j=1,2,\]
	where
	\[{\cal G}_1 = \frac{\partial {\cal P}}{\partial x}= (1, f'(x), g'(x)), \quad 
	{\cal G}_2 = \frac{\partial {\cal P}}{\partial t}=(0, \xi'_1(t), \xi'_2(t)).\]
	More precisely,
	\[G = \nabla {\cal P} \cdot (\nabla {\cal P})^t = \left(
	\begin{array}{cc}
		1 + (f'(x))^2+(g'(x))^2  & f'(x)\xi'_1(t) +  g'(x)\xi'_2(t)   \\
	f'(x)\xi'_1(t) +  g'(x)\xi'_2(t)    &  1
	\end{array} \right),\]
and $\det G = 1+ (f'(x)\xi'_2(t)-g'(x)\xi'_1(t))^2 \neq 0$, for all $(x,t) \in \Sigma$. Since ${\cal P}$ is a global diffeomorphism between $\Sigma$ and ${\cal S}$, a change of variables can be performed. 

Denote by $h(x,t) :=  h_{f',g'}(x,t) =\sqrt{\det G}$. The norm in the Hilbert space  $L^2(\Sigma, h(x,t) \dx \dt)$ is given by
\begin{equation*}
    \|\psi\|^2 := \int_{\Sigma} |\psi|^2 h \dx \dt.  
\end{equation*}

Now, we consider the unitary operator  
\begin{equation*}
		\begin{array}{llll}
			{\cal U}: &   L^2({\cal S})  &  \to &  L^2(\Sigma, h \,\dx \dt) \\
			&    \psi   &  \mapsto  &        \psi \circ {\cal P}
		\end{array},
	\end{equation*}
 and, we define
	\begin{align*}
		Q_{f',g'}(\psi)  := & \; Q_{\cal S}({\cal U}^{-1} \psi)  
		= \int_{\Sigma} \langle \nabla \psi, G^{-1} \nabla \psi \rangle \sqrt{{\rm det}\, G} \, \dx \dt  \nonumber \\ 
		= &  \int_{\Sigma}  \text{\small $\left(\left|\psi' - (f'(x) \xi'_1(t) + g'(x) \xi'_2(t)) \frac{\partial \psi}{\partial t} \right|^2 + (1 + (f'(x) \xi'_2(t) - g'(x) \xi'_1(t))^2) \left| \frac{\partial \psi}{\partial t} \right|^2 \right) \frac{\dx \dt}{h (x,t)}$} \nonumber \\
  	= &  \int_{\Sigma} \frac{\left|\psi' - (f'(x) \xi'_1(t) + g'(x) \xi'_2(t)) \partial_t \psi \right|^2}{h (x,t)} \dx \dt  + \int_{\Sigma} 
 h(x,t) \left| \partial_t \psi \right|^2 \dx \dt,
	\end{align*}
	%
	\[\dom Q_{f',g'} := {\cal U}(\dom Q_{\cal S}),\]
	%
	where
	$\psi' := \partial \psi / \partial x$. Since $f', g' \in L^\infty(\mathbb{R})$, one get $ \dom Q_{f',g'} = {\cal H}^1(\Sigma)$.  Denote by $H_{f',g'}$ the self-adjoint operator associated with the quadratic form
 $Q_{f',g'}(\psi)$. %Assim, podemos identificar $-\Delta_{\cal S}$ com o operador autoadjunto $H_{f',g'}$.


Considering an additional unitary operator 
\begin{equation*}
