   % & = \partial_x ((1+ (f'(x)\xi'_2(t)-g'(x)\xi'_1(t))^2)^{-1/4}) \psi + (1+ (f'(x)\xi'_2(t)-g'(x)\xi'_1(t))^2)^{-1/4} \psi'\\
   % & = \left(-\frac{1}{2} h^{-5/2}(f'(x)\xi'_2(t)-g'(x)\xi'_1(t))(f''(x)\xi'_2(t)-g''(x)\xi'_1(t))\right) \psi + h^{-1/2} \psi'\\
   % & = h^{-1/2} \left[  \psi' - \frac{1}{2}  h^{-2}(f'(x)\xi'_2(t)-g'(x)\xi'_1(t))(f''(x)\xi'_2(t)-g''(x)\xi'_1(t)) \psi \right]\\
   % & =  h^{-1/2} \left[  \psi' - \frac{\partial_x h^2}{4h^2}  \psi \right],
\end{align*}
%
and
%
\begin{align*}
\partial_t(h_\beta^{-1/2} \psi) & =  \partial_t((1+ (f'(x)\xi'_2(t)-g'(x)\xi'_1(t))^2)^{-1/4} \psi) = h^{-1/2}  \left[ \partial_t \psi -\frac{\partial_t h^2}{4h^{2}} \psi \right].%\\
%& = \partial_t((1+ (f'(x)\xi'_2(t)-g'(x)\xi'_1(t))^2)^{-1/4}) \psi +(1+ (f'(x)\xi'_2(t)-g'(x)\xi'_1(t))^2)^{-1/4}  \partial_t \psi\\
%& =  \left( -\frac{1}{2}h^{-5/2} (f'(x)\xi'_2(t)-g'(x)\xi'_1(t))(f'(x)\xi''_2(t)-g'(x)\xi''_1(t))\right) \psi +h^{-1/2}  \partial_t \psi\\
%& = h^{-1/2}  \left[ \partial_t \psi -\frac{1}{2}h^{-2} (f'(x)\xi'_2(t)-g'(x)\xi'_1(t))(f'(x)\xi''_2(t)-g'(x)\xi''_1(t)) \psi \right]\\
%& = h^{-1/2}  \left[ \partial_t \psi -\frac{\partial_t h^2}{4h^{2}} \psi \right].
