Then, 
\begin{align*}
    \hat{Q}_{f',g'}(\psi) 
    %= & \int_{\Sigma} \frac{\left|h^{-1/2} \left[  \psi' - \frac{\partial_x h^2}{4h^2}  \psi \right] - (f' \xi'_1+ g' \xi'_2) h^{-1/2}\left[\partial_t \psi - \frac{ \partial_t h^2}{4 h^2} \psi  \right] \right|^2}{h} \dx \dt \\
    % & + \int_{\Sigma}  h \left| h^{-1/2}\left[\partial_t \psi - \frac{ \partial_t h^2}{4 h^2} \psi \right] \right|^2 \dx \dt\\
 & =  \int_{\Sigma} \frac{1}{h^2} \left| \psi' - \frac{\partial_x h^2}{4h^2}  \psi  - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \psi - \frac{ \partial_t h^2}{4 h^2} \psi  \right] \right|^2 \dx \dt + \int_{\Sigma} 
 \left|\partial_t \psi - \frac{ \partial_t h^2}{4 h^2} \psi  \right|^2 \dx \dt. %\\
 % = & \int_{\Sigma}  \Bigg[  \frac{|\psi'|^2}{h^2} -  \frac{\partial_x h^2}{2h^4}  \psi \psi'  - \frac{2(f' \xi'_1+ g' \xi'_2)}{h^2} \left(\psi' \partial_t \psi  - \frac{ \partial_t h^2}{4 h^2} \psi \psi' \right) + \left (\frac{\partial_x h^2}{4h^3} \right)^2  |\psi|^2  \\
  % & +  \frac{(1+(f')^2 + (g')^2)}{h^2} \left|\partial_t \psi - \frac{ \partial_t h^2}{4 h^2} \psi  \right|^2  + (f' \xi'_1+ g' \xi'_2) \left( \frac{ \partial_x h^2}{2 h^4} \psi \partial_t \psi -  \frac{ \partial_x h^2 \partial_t h^2}{8 h^6} |\psi|^2\right) \Bigg] \dx \dt
