 Since, $f', g' \in L^\infty(\mathbb{R})$, one has $ \dom \hat{Q}_{f',g'} = {\cal H}^1(\Sigma)$.   Denote by $\hat{H}_{f',g'}$ the self-adjoint operator associated with the quadratic form $\hat{Q}_{f',g'}(\psi)$. Therefore, since $H_{f',g'}$ and $\hat{H}_{f',g'}$ are unitarily equivalent, we can identify  $-\Delta_{\cal S}$ with the self-adjoint operator $\hat{H}_{f',g'}$.

\section{Essential spectrum} \label{sec3}


This section concerns the proof of Theorem \ref{theo:surfess_surf}.  Inspired by \cite{briet}, we examine the situation in which $\beta_1$ and $\beta_2$ take finite values.  

	\begin{Lemma}\label{lemma:tiafg_surf}
	A real number $\lambda$ belongs to the essential spectrum of $\hat{H}_{f',g'}$ if, and only if, there exists a sequence $\{\psi_n\}_{n \in \mathbb{N}} \subset \dom \hat{Q}_{f',g'}$ such that the following three conditions hold:
 \begin{enumerate} [label=(\roman*)]
			\item $\|\psi_n\|_{L^2(\cal S)}=1$, $\forall n \in \mathbb{N}$;
			\item $(\hat{H}_{f',g'} -\lambda \Id) \psi_n \rightarrow 0$, as $n \rightarrow \infty$, in $(\dom \hat{H}_{f',g'})^{*}$,
      	\item $\operatorname{supp} \psi_n \subset {\cal S}\setminus (-n,n) \times {\cal C}$, $\forall n \in \mathbb{N}$.
		\end{enumerate}
	\end{Lemma}
	\begin{proof}
By the general Weyl criterion modified to quadratic forms, $\lambda \in \sigma_{ess}(\hat{H}_{f',g'})$ if, and only if, there exists a sequence $\{\upsilon_n\}_{n \in \mathbb{N}} \subset \dom \hat{Q}_{f',g'}$ such that $(i)$ and $(ii)$ hold but $(iii)$ is replaced by $(iii')$ $\upsilon_n \overset{w}{\rightarrow} 0$, as $n \rightarrow \infty$ in $L^2(\cal S)$

The sequence  $\{\psi_n\}_{n \in \mathbb{N}}$ satisfying $(i)$ and $(iii)$ clearly converges weakly to zero. Hence, one implication of the lemma is obvious. Conversely, let $\lambda \in \sigma_{ess}(\hat{H}_{f',g'})$. By the quadratic form criterion, there exists a sequence $\{\upsilon_n\}_{n \in \mathbb{N}} \subset \dom \hat{Q}_{f',g'}$ satisfying $(i)$, $(ii)$ and $(iii')$. Using this, we will construct a sequence $\{\psi_n\}_{n \in \mathbb{N}}$ satisfying $(i)$, $(ii)$ and $(iii)$. 

Note that in the condition $(ii)$,  $(\dom \hat{H}_{f',g'})^{*}$ denotes the dual space of $\dom (\hat{Q}_{f',g'})$. Furthermore, recall that condition $(ii)$ means that 
		\begin{equation}\label{dualf_surf}
			  \|(\hat{H}_{f',g'} - \lambda \Id) \psi_n\|_{-1} := \|(\hat{H}_{f',g'} - \lambda \Id) \psi_n\|_{(\dom \hat{Q}_{f',g'})^{*}}= \sup_{\phi \in \dom \hat{Q}_{f',g'} \setminus \{0\}} \frac{|\langle \phi, (\hat{H}_{f',g'} - \lambda \Id) \psi_n \rangle|}{\|\phi\|_1} \rightarrow 0, 
		\end{equation}
		as $n \rightarrow \infty $, where
		\begin{equation*}
			\|\phi\|_1^2 := \hat{Q}_{f',g'} (\phi) +\|\phi\|_{L^2(\cal S)}^{2}.
		\end{equation*}

By writing
\begin{equation}\label{eq:dualfg_surf}
    \upsilon_n = (\hat{H}_{f',g'} + \Id)^{-1} (\hat{H}_{f',g'} - \lambda \Id) \upsilon_n + (1+\lambda) (\hat{H}_{f',g'} + \Id)^{-1} \upsilon_n,
\end{equation}
and using  $(ii)$, we observe that the sequence  
 $\{\upsilon_n\}_{n \in \mathbb{N}}$ is bounded in $\dom \hat{Q}_{f',g'}$. 

  Let $\varphi \in C^\infty(\mathbb{R})$ be a real function such that  $\varphi(x) =0$, if $x \in [-1,1]$ and $\varphi(x)=1$,  if $x \in \mathbb{R}\setminus (-2,2)$. Define, for each $k \in \mathbb{N}$,
  \begin{equation*}
      \varphi_k(x) = \varphi\left(\frac{x}{k}\right);
  \end{equation*}
and we keep the same notation for the function  $\varphi_k \otimes \Id$ on $\mathbb{R} \times {\cal C}$, as well as,
for their derivatives $\varphi'$ and $\varphi''$. Note that $\operatorname{supp} \varphi_k \subset {\cal S} \setminus (-k,k) \times {\cal C}$. 


For each $k \in \mathbb{N}$, the operator $(1-\varphi_k)(\hat{H}_{f',g'} + \Id)^{-1}$ is compact in $L^2(\cal S)$, hence, $\lim_{n \to \infty}( 1-\varphi_k)(\hat{H}_{f',g'} + \Id)^{-1} \upsilon_n =0$ in $L^2(\cal S)$. Then, there exists a subsequence  $\{\upsilon_{n_k}\}_{k\in \mathbb{N}}$ of $\{\upsilon_{n}\}_{n\in \mathbb{N}}$ such that $\lim_{k \to \infty} (1-\varphi_k)(\hat{H}_{f',g'} + \Id)^{-1} \upsilon_{n_k} =0$ em $L^2(\cal S)$. Consequently, by \eqref{eq:dualfg_surf} and $(ii)$  one has  $\lim_{k \to \infty}(1-\varphi_k)\upsilon_{n_k} = 0$ in $L^2(\cal S)$. Thus, we may assume $\|\varphi_k \upsilon_{n_k}\| \geq 1/2$, for each $k \in \mathbb{N}$, and define
  \begin{equation*}
      \psi_k := \frac{\varphi_k \upsilon_{n_k}}{\|\varphi_k \upsilon_{n_k}\|} \in \dom \hat{Q}_{f',g'}.
  \end{equation*}
  Note that $\psi_k$ satisfies $(i)$ and $(iii)$. It remains to verify $(ii)$. 

	Now, for every $\phi \in \dom \hat{Q}_{f',g'} \setminus \{0\}$, one has
		\begin{equation*}
				|\langle \phi, (\hat{H}_{f',g'} - \lambda \Id)\psi_k \rangle| = |\hat{Q}_{f',g'}(\phi,\psi_k) - \lambda \langle \phi,\psi_k \rangle_{L^2(\cal S)}|. 
		\end{equation*}
	Without loss of generality, assume $\|\varphi_k \upsilon_{n_k}\| =1$.	Integrating by parts, 
  % 

  	\begin{align*} 
\hat{Q}_{f',g'}(\phi,\psi_k )  = &  \int_{\Sigma} \frac{1}{h^2 }\left( \phi' - \frac{\partial_x h^2}{4h^2}  \phi - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \phi - \frac{ \partial_t h^2}{4 h^2} \phi  \right] \right) \left( \psi_k' - \frac{\partial_x h^2}{4h^2}  \psi_k - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \psi_k - \frac{ \partial_t h^2}{4 h^2} \psi_k  \right] \right)  \dx \dt\\
&+ \int_{\Sigma} 
 \left( \partial_t \phi - \frac{\partial_t h^2}{4 h^2} \phi  \right) \left( \partial_t \psi_k - \frac{\partial_t h^2}{4 h^2} \psi_k  \right) \dx \dt\\
 = & \; \hat{Q}_{f',g'}(\phi \varphi_k,\upsilon_{n_k}) + 2 \left\langle  \frac{1}{h} \left(\phi' - \frac{\partial_x h^2}{4h^2}  \phi - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \phi - \frac{ \partial_t h^2}{4 h^2} \phi  \right]\right), \frac{1}{h}\varphi'_k \upsilon_{n_k} \right\rangle_{L^2(\Sigma)}\\
 & +  \left\langle  \frac{1}{h^2}  \phi, \varphi''_k \upsilon_{n_k} \right\rangle_{L^2(\Sigma)}  - \left \langle \left(
  \frac{\partial_x h^2}{2h^4} -(f'\xi'_1 + g'\xi'_2)\frac{\partial_t h^2}{2h^4} + \frac{(f'\xi''_1 + g'\xi''_2)}{h^2} \right)
 \phi, \varphi'_k \upsilon_{n_k} \right\rangle_{L^2(\Sigma)}, 
   \end{align*}
   and
  $ - \lambda \langle \phi,\psi_n \rangle_{L^2(\Sigma)}  = 
 - \lambda \langle \phi \varphi_k,\upsilon_{n_k} \rangle_{L^2(\Sigma)}$, for every test function $\varphi \in C_0^\infty(\Sigma)$. From (\ref{dualf_surf}), it follows that
{\small
\begin{align*}
     \sup_{\phi \in  C_0^\infty(\Sigma)\setminus \{0\}} \frac{|\hat{Q}_{f',g'}(\phi \varphi_k,\upsilon_{n_k})  - \lambda \langle \phi \varphi_k,\upsilon_{n_k} \rangle_{L^2(\Sigma)}|}{\|\phi\|_1} \leq &  \sup_{\substack{\phi \in   C_0^\infty(\Sigma) \setminus \{0\}\\ \phi \varphi_k \neq 0}} \frac{|\hat{Q}_{f',g'} (\phi \varphi_k,\upsilon_{n_k})  - \lambda \langle \phi \varphi_k,\upsilon_{n_k} \rangle_{L^2(\Sigma)}|}{\|\phi \varphi_k\|_1} \\
     = & \|(\hat{H}_{f',g'} - \lambda \Id) \upsilon_{n_k}\|_{-1} \to 0,
\end{align*}}
 as $k \to \infty$. At the same time, using the Cauchy-Schwarz inequality and the estimate 
 \begin{equation*}
     \left\|\frac{1}{h} \left( \phi' - \frac{\partial_x h^2}{4h^2}  \phi - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \phi - \frac{ \partial_t h^2}{4 h^2} \phi  \right] \right) \right\|^2 \leq \hat{Q}_{f',g'} (\phi) \leq \|\phi\|_1^2, 
 \end{equation*}
 we get 
 \begin{equation*}
         \sup_{\phi \in   C_0^\infty(\Sigma) \setminus \{0\}} \frac{\left| 2 \left\langle  \frac{1}{h} \left(\phi' - \frac{\partial_x h^2}{4h^2}  \phi - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \phi - \frac{ \partial_t h^2}{4 h^2} \phi  \right]\right), \frac{1}{h}\varphi'_k \upsilon_{n_k} \right\rangle_{L^2(\Sigma)} \right|}{\|\phi\|_1} \leq \|\varphi'_k\|_{\infty} \|\upsilon_{n_k}\| \frac{2}{\inf|h|},
 \end{equation*}
 where $\|\varphi'_k\|_{\infty}$ denotes the supremum norm of $\varphi'_k$. By the normalization $(i)$ and since $\|\varphi'_k\|_\infty = k^{-1}\|\varphi'\|_\infty$, we see that also this terms to zero as $k \to \infty$. Moreover, using the estimate $\|\phi\| \leq \|\phi\|_1$, and given that $\|\varphi''_k\|_\infty = k^{-2}\|\varphi''\|_\infty$, we conclude that
 \begin{equation*}
         \sup_{\phi \in   C_0^\infty(\Sigma) \setminus \{0\}} \frac{\left|  \left\langle  \frac{1}{h^2} \phi , \varphi''_k \upsilon_{n_k} \right\rangle_{L^2(\Sigma)} \right|}{\|\phi\|_1} \leq \|\varphi''_k\|_{\infty} \|\upsilon_{n_k}\| \frac{1}{\inf|h^2|} \to 0,
 \end{equation*}
and
\begin{equation*}
         \sup_{\phi \in  C_0^\infty(\Sigma) \setminus \{0\}} \frac{\left|  \left \langle \left(
  \frac{\partial_x h^2}{2h^4} -(f'\xi'_1 + g'\xi'_2)\frac{\partial_t h^2}{2h^4} + \frac{(f'\xi''_1 + g'\xi''_2)}{h^2} \right)
 \phi, \varphi'_k \upsilon_{n_k}  \right\rangle_{L^2(\Sigma)} \right|}{\|\phi\|_1} \leq \|\varphi'_k\|_{\infty} \|\upsilon_{n_k}\| K \to 0,
 \end{equation*}
as $k \to 0$, where in the last inequality  $K:= \sup\left|
  \frac{\partial_x h^2}{2h^4} -(f'\xi'_1 + g'\xi'_2)\frac{\partial_t h^2}{2h^4} + \frac{(f'\xi''_1 + g'\xi''_2)}{h^2} \right|$.

In summary, we have verified that $\|(\hat{H}_{f',g'} - \lambda \Id) \psi_k \|_{-1} \to 0$ as $k \to \infty$. Therefore, the sequence $\{\psi_k\}_{n \in \mathbb{N}}$ satisfies condition $(ii)$, which completes the proof.  
	\end{proof}

 Using the previous lemma, we immediately obtain the following result (which states that the essential spectrum of the Laplace operator is determined  by the surface's behaviour at infinity only)

\begin{Proposition}\label{prop:essfg_surf}
	Suppose that the conditions in  \eqref{eq:condlim_surf} hold. Then, $\sigma_{ess}(\hat{H}_{f',g'}) = \sigma_{ess}(\hat{H}_{\beta_1,\beta_2})$.
	\end{Proposition}

\begin{proof}
    Let $\lambda \in \sigma_{ess}(\hat{H}_{\beta_1,\beta_2})$. By Lemma \ref{lemma:tiafg_surf} , there exists a sequence $\{\psi_n\}_{n \in \mathbb{N}} \subset \dom \hat{H}_{\beta_1,\beta_2}$ satisfying the properties $(i)-(iii)$. By \eqref{eq:dualfg_surf}, for every $n \in \mathbb{N}$, we write
    \begin{equation*}
         \psi_n = (\hat{H}_{\beta_1, \beta_2} + \Id)^{-1} (\hat{H}_{\beta_1, \beta_2} - \lambda \Id) \psi_n + (1+\lambda) (\hat{H}_{\beta_1, \beta_2} + \Id)^{-1} \psi_n.
    \end{equation*}
    By $(ii)$ of Lemma \ref{lemma:tiafg_surf}, we can see that the sequence $\{\psi_n\}_{n \in \mathbb{N}}$ is bounded in  $\dom \hat{Q}_{\beta_1, \beta_2}$.

Let
  	\begin{align*} 
\hat{Q}_{f',g'}(\phi,\psi_n )  = &  \int_{\Sigma} \frac{1}{h^2 }\left( \phi' - \frac{\partial_x h^2}{4h^2}  \phi - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \phi - \frac{ \partial_t h^2}{4 h^2} \phi  \right] \right) \left( \psi_n' - \frac{\partial_x h^2}{4h^2}  \psi_n - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \psi_n - \frac{ \partial_t h^2}{4 h^2} \psi_n  \right] \right)  \dx \dt\\
&+ \int_{\Sigma} 
 \left( \partial_t \phi - \frac{\partial_t h^2}{4 h^2} \phi  \right) \left( \partial_t \psi_n - \frac{\partial_t h^2}{4 h^2} \psi_n  \right) \dx \dt,
 \end{align*}
 and
  	\begin{align*} 
\hat{Q}_{\beta_1,\beta_2}(\phi,\psi_n )  = &  \int_{\Sigma} \frac{1}{h_{\beta_1,\beta_2}^2 }\left( \phi' - (\beta_1 \xi'_1+ \beta_2 \xi'_2)\left[\partial_t \phi - \frac{ (h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^2} \phi  \right] \right) \left( \psi'_n  - (\beta_1 \xi'_1+ \beta_2 \xi'_2)\left[\partial_t \psi_n - \frac{  (h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^2} \psi_n  \right] \right)  \dx \dt\\
&+ \int_{\Sigma} 
 \left( \partial_t \phi - \frac{(h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^2} \phi  \right) \left( \partial_t \psi_n - \frac{ (h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^2} \psi_n  \right) \dx \dt.
 \end{align*}

Some calculations show that 
\begin{equation}\label{ident:2_surf}
    \begin{split}
  \hat{Q}_{f',g'}(\phi, \psi_n)   = & \;\hat{Q}_{\beta_1,\beta_2}(\phi, \psi_n)
    + \int_\Sigma \Bigg(\left[\frac{1}{h^2} - \frac{1}{h_{\beta_1, \beta_2}^2} \right] \phi' \psi'_n  + \left[\frac{1+(f')^2 +(g')^2}{h^2} - \frac{1+\beta_1^2 +\beta_2^2}{h_{\beta_1, \beta_2}^2}  \right] \partial_t \phi \partial_t  \psi_n\\
    & + \left[(f' \xi'_1+ g'\xi'_2)  \frac{\partial_t h^2}{4h^4} - (\beta_1 \xi'_1+ \beta_2\xi'_2)  \frac{ (h_{\beta_1, \beta_2}^2)'}{4h_{\beta_1, \beta_2}^4}   \right](\phi' \psi_n +\phi \psi'_n) \\
    & - \left[\frac{f' \xi'_1+ g'\xi'_2}{h^2} -\frac{\beta_1 \xi'_1+ \beta_2\xi'_2}{h_{\beta_1, \beta_2}^2}\right](\phi' \partial_t  \psi_n + \partial_t \phi \psi'_n) \\
    & - \left[(1+(f')^2 +(g')^2) \frac{\partial_t h^2}{4h^4} - (1+\beta_1^2 +\beta_2^2) \frac{( h_{\beta_1, \beta_2}^2)'}{4h_{\beta_1, \beta_2}^4} \right] (  \partial_t\phi \psi_n + \phi \partial_t \psi_n)  \\
    &   + \left[(1+(f')^2 +(g')^2) \left(\frac{\partial_t h^2}{4h^3} \right)^2 - (1+\beta_1^2 +\beta_2^2) \left(\frac{( h_{\beta_1, \beta_2}^2)'}{4h_{\beta_1, \beta_2}^3}\right)^2\right]  \phi \psi_n \Bigg) \dx \dt\\
    & - \left\langle  \frac{1}{h} \left(\phi' - \frac{\partial_x h^2}{4h^2}  \phi - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \phi - \frac{ \partial_t h^2}{4 h^2} \phi  \right]\right),   \frac{\partial_x h^2}{4h^3} \psi_{n} \right\rangle_{L^2(\Sigma)}\\
    & - \left\langle \phi , \frac{\partial_x h^2}{4h^4} \left(\psi'_n - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \psi_n - \frac{\partial_t h^2}{4 h^2} \psi_n  \right]\right)\right\rangle_{L^2(\Sigma)}.
\end{split}
\end{equation}
Since  $\{\psi_n\}_{n \in \mathbb{N}}$ is bounded in  $\dom \hat{Q}_{\beta_1, \beta_2}$,  $\|\phi\|_1^2 := \hat{Q}_{f',g'} (\phi) +\|\phi\|_{L^2(\cal S)}^{2}$, using the Cauchy-Schwarz inequality and the fact that $\| \partial_x h^2 / 4 h^i\|_{L^\infty(\Sigma \setminus (-n,n) \times {\cal C})} \to 0$,  as $n \to \infty$, para $i=3,4$, we obtain  
\begin{align*}
         & \sup_{\substack{\phi \in  \dom \hat{Q}_{f',g'} \\ \phi \neq 0}}    
          \frac{\left| \left\langle  \frac{1}{h} \left(\phi' - \frac{\partial_x h^2}{4h^2}  \phi - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \phi - \frac{ \partial_t h^2}{4 h^2} \phi  \right]\right),  \frac{\partial_x h^2}{4h^3} \psi_{n} \right\rangle_{L^2(\Sigma)} \right|}{\|\phi\|_1} \leq  \left\| \frac{\partial_x h^2}{4h^3} \right\|_{L^\infty(\Sigma \setminus (-n, n) \times {\cal C})} \|\psi_{n}\| \to 0,
 \end{align*}
 and 
\begin{align*}
         & \sup_{\substack{\phi \in  \dom \hat{Q}_{f',g'} \\ \phi \neq 0}}    \frac{\left| \left\langle \phi , \frac{\partial_x h^2}{4h^4} \left(\psi'_n - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \psi_n - \frac{\partial_t h^2}{4 h^2} \psi_n  \right]\right)\right\rangle_{L^2(\Sigma)} \right|}{\|\phi\|_1} \\
         & \qquad  \leq  \left\| \frac{\partial_x h^2}{4h^4} \right\|_{L^\infty(\Sigma \setminus (-n, n) \times {\cal C})} 
 \left( \|\psi'_n\| + \|(f' \xi'_1+ g' \xi'_2)\|_{L^\infty(\Sigma)} \left[\|\partial_t \psi_n\| +\left\| \frac{\partial_t h^2}{4 h^2}\right\|_{L^\infty(\Sigma)} \|\psi_n\|  \right] \right) \to 0,
 \end{align*}
 as $n \to \infty$. Moreover, observe that 
\begin{gather*}
\left\| \frac{1}{h^2} - \frac{1}{h_{\beta_1, \beta_2}^2} \right\|_{L^\infty(\Sigma \setminus (-n, n) \times {\cal C})}  \to 0, \quad \left\| \frac{1+(f')^2 +(g')^2}{h^2} - \frac{1+\beta_1^2 +\beta_2^2}{h_{\beta_1, \beta_2}^2} \right\|_{L^\infty(\Sigma \setminus (-n, n) \times {\cal C})}  \to 0, \\
\left\| (f' \xi'_1+ g'\xi'_2)  \frac{\partial_t h^2}{4h^4} - (\beta_1 \xi'_1+ \beta_2\xi'_2)  \frac{ (h_{\beta_1, \beta_2}^2)'}{4h_{\beta_1, \beta_2}^4} \right\|_{L^\infty(\Sigma \setminus (-n, n) \times {\cal C})}  \to 0, \\
\left\| \frac{f' \xi'_1+ g'\xi'_2}{h^2} -\frac{\beta_1 \xi'_1+ \beta_2\xi'_2}{h_{\beta_1, \beta_2}^2} \right\|_{L^\infty(\Sigma \setminus (-n, n) \times {\cal C})} \to 0, \\
\left\| (1+(f')^2 +(g')^2) \frac{\partial_t h^2}{4h^4} - (1+\beta_1^2 +\beta_2^2) \frac{( h_{\beta_1, \beta_2}^2)'}{4h_{\beta_1, \beta_2}^4} \right\|_{L^\infty(\Sigma \setminus (-n, n) \times {\cal C})}  \to 0,\\
\left\| (1+(f')^2 +(g')^2) \left(\frac{\partial_t h^2}{4h^3} \right)^2 - (1+\beta_1^2 +\beta_2^2) \left(\frac{( h_{\beta_1, \beta_2}^2)'}{4h_{\beta_1, \beta_2}^3}\right)^2\right\|_{L^\infty(\Sigma \setminus (-n, n) \times {\cal C})}  \to 0,
 \end{gather*}
as $n \to \infty$. Due to the fact that $\operatorname{supp}  \psi'_n, \, \operatorname{supp}  \partial_t \psi_n \subseteq \operatorname{supp}  \psi_n$ and $\|(\hat{H}_{\beta_1, \beta_2} - \lambda \Id) \psi_n\|_{-1} \to 0$, as $n \to \infty$,  by $(ii)$ of Lemma \ref{lemma:tiafg_surf}, it follows from \eqref{ident:2_surf} and \eqref{dualf_surf} that $\|(\hat{H}_{f',g'} - \lambda \Id) \psi_n\|_{-1} \to 0$, as $n \to \infty$. Therefore, $\lambda \in \sigma_{ess}(\hat{H}_{f',g'})$. Analogously, we obtain the inclusion   $\sigma_{ess}(\hat{H}_{f',g'}) \subset \sigma_{ess}(\hat{H}_{\beta_1,\beta_2})$.
\end{proof}

In view of Proposition \ref{prop:essfg_surf}, we are going to the study the essential spectrum of the operator $\hat{H}_{\beta_1, \beta_2}$ instead of $\hat{H}_{f', g'}$. It remains to determine the essential spectrum of the operator  $\hat{H}_{\beta_1, \beta_2}$. 

\begin{Proposition} \label{prop:essfg2_surf}
		The spectrum of the operator $\hat{H}_{\beta_1, \beta_2}$ is purely essential and equals the interval  $[E_1(0), \infty)$.
	\end{Proposition}
\begin{proof}
    Let ${\cal F}_x : L^2(\Sigma) \longrightarrow L^2(\Sigma)$ be the partial Fourier transform in the longitudinal variable $x$. ${\cal F}_x$ is a unitary
operator and, for functions $\psi \in L^1(\Sigma)$, the explicit expression for this transformation is given by 
    \begin{equation*}
        ({\cal F}_x \psi)(p,t) = \frac{1}{\sqrt{2 \pi}} \int_{\mathbb{R}} e^{-ipx} \psi(x,t) \dx.
    \end{equation*}
    We consider the operator $\tilde{H}_{\beta_1,\beta_2} := {\cal F}_x \hat{H}_{\beta_1,\beta_2} {\cal F}_x^{-1}$ which admits a direct integral decomposition  
    \begin{equation*}
        \tilde{H}_{\beta_1,\beta_2} = \int_{\mathbb{R}}^{\oplus} \hat{H}_{\beta_1,\beta_2}(p) {\rm d}p,
    \end{equation*}
    where, for every $p \in \mathbb{R}$, in the distributional sense
    \begin{align*}
        \hat{H}_{\beta_1,\beta_2}(p)  =& 
        -\frac{1}{h_{\beta_1,\beta_2}^2} (ip)^2  + 2ip  \frac{(\beta_1 \xi'_1 + \beta_2 \xi'_2)}{h_{\beta_1,\beta_2}^2}\partial_t  - \frac{\partial}{\partial t} \left[ \left(\frac{1+\beta_1^2 + \beta_2^2}{h_{\beta_1,\beta_2}^2}\right) \partial_t \right] + (1+\beta_1^2 + \beta_2^2) \left[\left(\frac{(h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^4} \right)' + \left( \frac{(h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^3}\right)^2\right], 
    \end{align*}
    $\dom \hat{H}_{\beta_1, \beta_2}(p) = \{v \in {\cal H}^1({\cal C}): \hat{H}_{\beta_1, \beta_2}(p) v \in L^2({\cal C}), \; v'(0)=v'(1)\}$; if $p=0$ we obtain the operator $T_{\beta_1, \beta_2}$ given by \eqref{fourpp:surf_surf} in the Introduction. Since 
    \begin{equation}\label{uniesp_surf}
        \sigma(\hat{H}_{\beta_1, \beta_2}) = \bigcup_{p \in \mathbb{R}} \sigma(\hat{H}_{\beta_1, \beta_2}(p)),
    \end{equation}
the strategy is to study the family of operators $\{\hat{H}_{\beta_1, \beta_2}(p) : p \in \mathbb{R}\}$. By the compactness of the embedding  ${\cal H}^1 ({\cal C}) \hookrightarrow L^2({\cal C})$, each operator $\hat{H}_{\beta_1, \beta_2}(p)$ has a purely discrete spectrum. In particular, denote by   $ \{E_n(0)\}_{n \in \mathbb{N}}$  the non-decreasing sequence of the eigenvalues of  $\hat{H}_{\beta_1, \beta_2}(0)=T_{\beta_1, \beta_2}$. Note that 
 \begin{align*}
        \hat{H}_{\beta_1,\beta_2}(p)  =& 
        - \frac{1+\beta_1^2 + \beta_2^2}{h_{\beta_1,\beta_2}^2} \left( \partial_t - i \frac{p(\beta_1 \xi'_1 + \beta_2 \xi'_2)}{1+\beta_1^2 + \beta_2^2}\right)^2 - \frac{p^2 (\beta_1 \xi'_1 + \beta_2 \xi'_2)^2}{h_{\beta_1,\beta_2}^2 (1+\beta_1^2 + \beta_2^2)} + \frac{p^2}{h_{\beta_1,\beta_2}^2}\\
        & -  \left(\frac{1+\beta_1^2 + \beta_2^2}{h_{\beta_1,\beta_2}^2}\right)' \partial_t  + (1+\beta_1^2 + \beta_2^2) \left[\left(\frac{(h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^4} \right)' + \left( \frac{(h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^3}\right)^2\right]\\
        = & - \frac{1+\beta_1^2 + \beta_2^2}{h_{\beta_1,\beta_2}^2} \left( \partial_t - i \frac{p(\beta_1 \xi'_1 + \beta_2 \xi'_2)}{1+\beta_1^2 + \beta_2^2}\right)^2  + \frac{p^2}{1+\beta_1^2 + \beta_2^2}\\
        & -  \left(\frac{1+\beta_1^2 + \beta_2^2}{h_{\beta_1,\beta_2}^2}\right)' \partial_t  + (1+\beta_1^2 + \beta_2^2) \left[\left(\frac{(h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^4} \right)' + \left( \frac{(h_{\beta_1,\beta_2}^2)'}{4 h_{\beta_1,\beta_2}^3}\right)^2\right]\\
        = &  \; e^{i \gamma(p)} t  \left[ T_{\beta_1, \beta_2}    + \frac{p^2}{1+\beta_1^2 + \beta_2^2} \right] e^{-i \gamma(p)} t,
    \end{align*}
    where
    \begin{equation*}
        \gamma(p) := \frac{p(\beta_1 \xi'_1 + \beta_2 \xi'_2)}{1+\beta_1^2 + \beta_2^2}.  
    \end{equation*}
As a consequence, 
\begin{equation}\label{sigmap_surf}
    \sigma(\hat{H}_{\beta_1, \beta_2}(p)) = \left\{ E_n(0)    + \frac{p^2}{1+\beta_1^2 + \beta_2^2} \right\}_{n \in \mathbb{N}}.
\end{equation}
Therefore, by \eqref{uniesp_surf} and \eqref{sigmap_surf}, we obtain the desired result.

\end{proof}

{\bf Proof of Theorem \ref{theo:surfess_surf}:} 
 It remains to apply Propositions \ref{prop:essfg_surf} and \ref{prop:essfg2_surf}. \qed



	\section{Discrete spectrum}\label{sec4}




This section is dedicated to prove Theorems \ref{exidisspc_surf} and  \ref{exidisspc_surf2} stated in the introduction. 

At first, we fix some notations that we will be useful in this section. Let $Q$ be a closed and lower bounded sesquilinear form with domain  $\mathrm{dom}~ Q$ dense in a Hilbert space  $H$. Denote by $A$ the self-adjoint operator associated with $Q$. The Rayleigh quotients of $A$ can be defined by %
\begin{equation}\label{rayquoin}
	\lambda_j(A) = \inf_{\substack{G \subset \mathrm{dom}~ Q \\ \dim G=j}}   \sup_{\substack{ \psi \in G \\ \psi \neq 0}}  \frac{Q (\psi)}{ \|\psi \|^2_{H}}.
\end{equation}
%
Let $\mu = \inf \sigma_{ess} (A)$. The sequence $\{\lambda_j(A)\}_{j \in \mathbb{N}}$ is non-decreasing and satisfies: (i) if $\lambda_j(A) < \mu$, then it is a discrete eigenvalue of $A$; (ii) If $\lambda_j(A) \geq \mu$, then 
$\lambda_j(A) = \mu$; (iii) The $j$-th  eigenvalue of $A$ less than $\mu$ (it is exists) coincides with $\lambda_j(A)$.


\vspace{0.2cm}
	\noindent	
{\bf Proof of Theorem \ref{exidisspc_surf}:}
 	Consider the quadratic form  
	\begin{equation*}
		\hat{q}_{f',g'} (\psi) = \hat{Q}_{f',g'}(\psi) - E_1(0)\|\psi\|_{L^2(\Sigma)}^{2}, \quad \dom \hat{q}_{f',g'} = \dom \hat{Q}_{f',g'}.
	\end{equation*}
	According to (\ref{rayquoin}) and Theorem  \ref{theo:surfess_surf}, it is enough show that there exists a function  $\psi \in \dom \hat{q}_{f',g'} \setminus \{0\}$ such that $\hat{q}_{f',g'}(\psi) < 0$. 

	The first step is to find a sequence  $\{\psi_n\}_{n \in \mathbb{N}} \subset \dom \hat{q}_{f',g'}$ such that $\hat{q}_\beta (\psi_n) \to 0$ as $n \to \infty$. To that end, let $w \in C^\infty(\mathbb{R})$ be a real-valued function such that $w=1$ for $x \in [-1,1]$, and $w=0$ for $x \in \mathbb{R} \setminus [-2,2]$. For each every $n \in \mathbb{N}$, define
	\begin{equation*}
		w_n(x) = w \left(\frac{x}{n}\right) \quad \mbox{and} \quad \psi_n(x,t) = w_n(x) \chi (t),
	\end{equation*}  
	where $\chi$ denotes the normalized eigenfunction corresponding to the eigenvalue $E_1(0)$ of the two-dimensional operator $T_{\beta_1, \beta_2}$ given by \eqref{fourpp:surf_surf}.

 In particular, 
	\begin{equation}\label{estdericuoff1_surf}
		\int_{\mathbb{R}} |w'_n|^2 \dx = \frac{1}{n} \int_{\mathbb{R}} |w'|^2 \dx \to 0, \quad \mbox{as} \quad n \to \infty,
	\end{equation}
	%
	and
	% 
 \begin{equation}\label{firsteigcross1_surf}
		\int_{\cal C} 
 (1+\beta_1^2 + \beta_2^2) \left( \frac{|\chi'|^2}{h_{\beta_1, \beta_2}^2}  +  \left[
  \left(\frac{ (h_{\beta_1, \beta_2}^2)'}{4 h_{\beta_1, \beta_2}^4} \right)' + 
 \left(\frac{ (h_{\beta_1, \beta_2}^2)'}{4 h_{\beta_1, \beta_2}^3}\right)^2 \right] |\chi|^2 \right)  \dt = E_1(0).
	\end{equation}
	By (\ref{firsteigcross1_surf}), one has 
	\begin{equation*}
		\begin{split}
	\hat{q}_{f',g'}(\psi_n) = &  \; \hat{Q}_{f',g'}(\psi_n) - E_1(0)\|\psi_n\|_{L^2(\Sigma)}^{2}\\
= & \int_{\Sigma}  \Bigg[  \frac{|w'_n|^2 |\chi|^2}{h^2} -  \frac{\partial_x h^2}{2h^4}  w_n w'_n |\chi|^2  - \frac{2(f' \xi'_1+ g' \xi'_2)}{h^2} \left(w'_n \chi w_n  \chi'  - \frac{ \partial_t h^2}{4 h^2} w_n w'_n |\chi|^2 \right)   \\
  & + \left (\frac{\partial_x h^2}{4h^3} \right)^2  |w_n|^2 |\chi|^2 + (f' \xi'_1+ g' \xi'_2) \left( \frac{ \partial_x h^2}{2 h^4} |w_n|^2 \chi \chi' -  \frac{ \partial_x h^2 \partial_t h^2}{8 h^6} |w_n|^2 |\chi|^2\right) \\
  & +  (1+(f')^2 + (g')^2) \left( \frac{|w_n|^2 |\chi'|^2}{h^2}  +  \left[
  \frac{\partial}{\partial t} \left(\frac{\partial_t h^2}{4 h^4} \right) + 
 \left(\frac{ \partial_t h^2}{4 h^3}\right)^2 \right] |w_n|^2 |\chi|^2 \right) \Bigg] \dx \dt
 \\
  & - \int_{\Sigma}  
 (1+\beta_1^2 + \beta_2^2) \left( \frac{|w_n |^2 |\chi'|^2}{h_{\beta_1, \beta_2}^2}  +  \left[ \left(\frac{(h_{\beta_1, \beta_2}^2)'}{4 h_{\beta_1, \beta_2}^4} \right)' + 
 \left(\frac{ (h_{\beta_1, \beta_2}^2)'}{4 h_{\beta_1, \beta_2}^3}\right)^2 \right] |w_n |^2 |\chi|^2 \right)   \dx\dt.
 \end{split}
	\end{equation*}
Note that 
\begin{gather*}
     \int_{\cal C}  \frac{2(f' \xi'_1+ g' \xi'_2)}{h^2} \chi  \chi'\dt 
     = -\int_{\cal C}  \frac{\partial}{\partial t}\left(\frac{f' \xi'_1+ g' \xi'_2}{h^2} \right) |\chi|^2 \dt,\\
    \int_{\cal C}  (f' \xi'_1+ g' \xi'_2)\frac{\partial_x h^2}{2h^2} \chi  \chi'\dt  = -\int_{\cal C}  \frac{\partial}{\partial t}\left( (f' \xi'_1+ g' \xi'_2)\frac{\partial_x h^2}{4h^2} \right) |\chi|^2 \dt.
\end{gather*}
      Then,
 	\begin{equation*}
		\begin{split}
	\hat{q}_{f',g'}(\psi_n) = & \int_{\mathbb{R}}   A(x)|w'_n|^2 \dx + \int_{\mathbb{R}} B(x)  w_n w'_n \dx \\
 & +  \int_{\mathbb{R}} \left( C(x) + (1+(f')^2 + (g')^2) D(x) -  
 (1+\beta_1^2 + \beta_2^2)  E \right) |w_n |^2   \dx \\
  \leq &  \int_{\mathbb{R}}   A(x)|w'_n|^2 \dx + \left(\int_{\mathbb{R}} |B(x)|^2|w_n|^2 \dx \right)^{1/2} \left(  \int_{\mathbb{R}} |w^{\prime}_n|^2 \dx \right)^{1/2}  +  \int_{\mathbb{R}} V(x)|w_n |^2 \dx.
  \end{split}
	\end{equation*}
 By (\ref{estdericuoff1_surf}) and since $\|w_n\|_\infty \leq 1$ and $\int_\mathbb{R} V(x) \dx <0$,  by the dominated convergence theorem, it follows that
\begin{equation*}
    \hat{q}_{f',g'}(\psi_n) \to \int_{\mathbb{R}} V(x) \dx, \quad \mbox{as} \quad n \to \infty. 
\end{equation*}
Thus, there exists $N \in \mathbb{N}$ such that $\hat{q}_{f',g'}(\psi_N)<0$.  \qed



\vspace{0.2cm}
	\noindent
{\bf Proof of Theorem \ref{exidisspc_surf2}:}

  For every $n \in \mathbb{R}$, consider the functions $w_n$ and $\psi_n$ as defined in the proof of Theorem \ref{exidisspc_surf}.  However, we now introduce a small perturbation and define
	\begin{equation*}
		\psi_{n,\varepsilon}(x,t) := \psi_n(x,t) + \varepsilon \phi(x,t),  
	\end{equation*}
where $\varepsilon \in \mathbb{R}$ and $\phi \in \dom \hat{q}_\beta$. In this case,
	\begin{equation*}
		\hat{q}_{f',g'}(\psi_{n,\varepsilon}) = \hat{q}_{f',g'}(\psi_n) + 2 \varepsilon \,  {\rm Re} \, (\hat{q}_{f',g'}(\psi_n, \phi))
		+ \varepsilon^2 \hat{q}_{f',g'}(\phi).
	\end{equation*}

	The strategy is to show that there exists $\phi$ satisfying 
	\begin{equation}\label{rbetaneez:surf}
		\lim_{n \to \infty} \hat{q}_{f',g'}(\psi_n, \phi) \neq 0.
	\end{equation}	
	Indeed, if (\ref{rbetaneez:surf}) holds true, it is enough to chosen $\varepsilon$ such that $\hat{q}_{f',g'}(\psi_{n,\varepsilon})<0$, for some $n$ large enough. 

	Consider $\eta \in C^\infty_0 (\mathbb{R})$, with $\operatorname{supp}  \eta \subset (-1,1)$.  Define $\phi(x,t) = \eta(x) \chi(t)$. We get 
\begin{align*}
    \hat{q}_{f',g'}(\psi_n, \phi )  = &  \int_{\Sigma} \frac{1}{h^2 } \left( \psi_n' - \frac{\partial_x h^2}{4h^2}  \psi_n - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \psi_n - \frac{ \partial_t h^2}{4 h^2} \psi_n  \right] \right) \left( \phi' - \frac{\partial_x h^2}{4h^2}  \phi - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \phi - \frac{ \partial_t h^2}{4 h^2} \phi  \right] \right)  \dx \dt\\
&+ \int_{\Sigma} 
  \left( \partial_t \psi_n - \frac{\partial_t h^2}{4 h^2} \psi_n  \right) \left( \partial_t \phi - \frac{\partial_t h^2}{4 h^2} \phi  \right) \dx \dt - E_1(0) \int_{\Sigma} \psi_n \phi \, \dx \dt\\
 % = & \int_{\Sigma} \frac{1}{h^2 } \Bigg(  \psi_n'\phi' - \frac{\partial_x h^2}{4h^2}  \psi_n'\phi - (f' \xi'_1+ g' \xi'_2) \psi_n' \left[\partial_t \phi - \frac{ \partial_t h^2}{4 h^2} \phi  \right]  \\
 % & -  \frac{\partial_x h^2}{4h^2}  \psi_n \phi' + \frac{\partial_x h^2}{4h^2}  \frac{\partial_x h^2}{4h^2}  \psi_n \phi + (f' \xi'_1+ g' \xi'_2)  \frac{\partial_x h^2}{4h^2}  \psi_n\left[\partial_t \phi - \frac{ \partial_t h^2}{4 h^2} \phi  \right] \\
 % & - (f' \xi'_1+ g' \xi'_2)\left[\partial_t \psi_n \phi' - \frac{ \partial_t h^2}{4 h^2} \psi_n \phi' - \frac{ \partial_x h^2}{4 h^2} \partial_t \psi_n\phi + \frac{\partial_x h^2}{4h^2} \frac{ \partial_t h^2}{4 h^2} \psi_n \phi\right] \Bigg) \dx \dt\\
%&+ \int_{\Sigma} \frac{(1+(f')^2 + (g')^2)}{h^2} \left( \partial_t \psi_n - \frac{\partial_t h^2}{4 h^2} \psi_n  \right) \left( \partial_t \phi - \frac{\partial_t h^2}{4 h^2} \phi  \right) \dx \dt - E_1(0) \int_{\Sigma} \psi_n \phi\, \dx \dt\\
   = & \int_{\Sigma} \frac{1}{h^2 } \Bigg(  w'_n \eta' |\chi|^2  - \frac{\partial_x h^2}{4h^2}  w'_n \eta |\chi|^2 - (f' \xi'_1+ g' \xi'_2) w'_n \chi \left[\eta \chi' - \frac{ \partial_t h^2}{4 h^2} \eta \chi  \right]  \\
  & -  \frac{\partial_x h^2}{4h^2}  w_n  \eta' |\chi|^2 + \frac{\partial_x h^2}{4h^2}  \frac{\partial_x h^2}{4h^2}  w_n \eta |\chi|^2  + (f' \xi'_1+ g' \xi'_2)  \frac{\partial_x h^2}{4h^2}  w_n \chi \left[\eta \chi' - \frac{ \partial_t h^2}{4 h^2} \eta \chi  \right] \\
  & - (f' \xi'_1+ g' \xi'_2)\left[ w_n  \chi' \eta' \chi - \frac{ \partial_t h^2}{4 h^2} w_n  \eta' |\chi|^2 - \frac{ \partial_x h^2}{4 h^2} w_n \chi' \eta \chi + \frac{\partial_x h^2}{4h^2} \frac{ \partial_t h^2}{4 h^2} w_n \eta |\chi|^2 \right] \Bigg) \dx \dt\\
&+ \int_{\Sigma} \frac{(1+(f')^2 + (g')^2)}{h^2}
  \left( w_n \chi' - \frac{\partial_t h^2}{4 h^2} w_n \chi  \right) \left( \eta \chi' - \frac{\partial_t h^2}{4 h^2} \eta \chi   \right) \dx \dt - E_1(0) \int_{\Sigma} w_n  \eta |\chi|^2 \dx \dt\\
   \to &   \int_{\Sigma} \eta'\left[ -  \frac{\partial_x h^2}{4h^4}  + \frac{\partial}{\partial t}\left(\frac{f' \xi'_1+ g' \xi'_2}{2h^2} \right)  + (f' \xi'_1+ g' \xi'_2) \frac{ \partial_t h^2}{4 h^4}   \right] |\chi|^2 \dx \dt\\
& + \int_{\Sigma} \eta \left[\left(\frac{\partial_x h^2}{4h^3}\right)^2  - \frac{\partial}{\partial t}\left((f' \xi'_1+ g' \xi'_2)  \frac{\partial_x h^2}{4h^4} \right)    - (f' \xi'_1+ g' \xi'_2)  \frac{\partial_x h^2 \partial_t h^2}{8h^6} \right] |\chi|^2 \dx \dt  \\
&+ \int_{\Sigma} \frac{(1+(f')^2 + (g')^2)}{h^2} \eta
  \left( \chi' - \frac{\partial_t h^2}{4 h^2} \chi  \right)^2 \dx \dt - E(0) \int_{\Sigma} \eta |\chi|^2 \dx \dt\\
  = & \int_{\mathbb{R}} \eta' \frac{B(x)}{2} \dx  + \int_{\mathbb{R}} \eta V(x) \dx\\
  = & \int_{\mathbb{R}} \left(V(x)-\frac{B'(x)}{2}  \right) \dx,
\end{align*}
as $n \to \infty$. If the last integral vanishes for all $\eta \in C_0^\infty(\mathbb{R})$, we would have $ V(x) -B'(x)/2 = 0$ almost everywhere, which implies $B(x) = 2 \int_{\mathbb{R}} V(x) \dx + C = C$. This yields a contradiction since, by hypothesis, $B(x)$ is not constant. Therefore, there exists a function  $\phi$ satisfying \eqref{rbetaneez:surf}. \qed


\section{Broken sheared waveguides shaped surfaces} \label{sec5}


This section is devoted to the proof of Theorems \ref{propress_surfcant} and \ref{exidisspc_surfcant}. 

	Recall the mapping ${\cal P}_\beta$ given by \eqref{lmas_surfcant}. Namely, ${\cal S}_\beta = \mathcal{P}_\beta(\Sigma)$. Following the same change of coordinates approach as in Section \ref{sec3}, and since ${\cal P}_\beta$ is a global diffeomorphism between $\Sigma$ and ${\cal S}_\beta$, we have that
\begin{align*}
    \hat{Q}_{\beta }(\psi) 
 & =  \int_{\Sigma} \frac{1}{h_\beta^2} \left| \psi'  -  g'(x) \xi'_2(t) \left[\partial_t \psi - \frac{ (h_\beta^2)'}{4 h_\beta^2} \psi  \right] \right|^2 \dx \dt + \int_{\Sigma} 
 \left|\partial_t \psi - \frac{(h_\beta^2)'}{4 h_\beta^2} \psi  \right|^2 \dx \dt, \quad  \dom \hat{Q}_{\beta} = {\cal H}^1(\Sigma).  
\end{align*}
  Denote by $\hat{H}_{\beta}$ the self-adjoint operator associated with the quadratic form 
 $\hat{Q}_{\beta}(\psi)$. Therefore, since $-\Delta_{{\cal S}_\beta}$ and $\hat{H}_{\beta}$ are unitarily equivalent, we can identify $-\Delta_{{\cal S}_\beta}$ with the self-adjoint operator $\hat{H}_{\beta}$.

\vspace{0.2cm}
	\noindent
{\bf Proof of Theorem \ref{propress_surfcant}:} It remains to apply Theorems \ref{prop:essfg_surf} and  \ref{prop:essfg2_surf}  to the case where $\hat{H}_{\beta_1, \beta_2} = \hat{H}_{\beta}$, with $\beta_1^2 = 0$ and $\beta_2^2 = \beta$.   \qed


\vspace{0.2cm}
	\noindent
{\bf Proof of Theorem \ref{exidisspc_surfcant}:} 
	Consider the quadratic form  
	\begin{equation*}
		\hat{q}_\beta (\psi) = \hat{Q}_\beta(\psi) - E_1(\beta)\|\psi\|_{L^2({\cal S}^+)}^{2}, \quad \dom \hat{q}_\beta = \dom \hat{Q}_\beta.
	\end{equation*}
	According to (\ref{rayquoin}) and Theorem \ref{propress_surfcant}, it is enough to show that there exists a non null function $\psi \in \dom \hat{q}_\beta$ for which $\hat{q}_\beta(\psi) < 0$. A function with this property will be constructed below.

	The first step is to find a sequence $\{\psi_n\}_{n \in \mathbb{N}} \subset \dom q_\beta$ such that $q_\beta (\psi_n) \to 0$, as $n \to \infty$. For that,   let $w \in C^\infty(\mathbb{R})$ a real function where $w=1$ for $x \in [-1,1]$, and $w=0$ for $x \in \mathbb{R} \setminus [-2,2]$. Define, for each $n \in \mathbb{N}$,
	\begin{equation*}
		w_n(x) = w \left(\frac{x}{n}\right) \quad \mbox{and} \quad \psi_n(x,t) = w_n(x) \chi_1 (t),
	\end{equation*}  
	where $\chi_1$ denotes  a denotes the normalized eigenfunction corresponding to the eigenvalue $E_1(\beta)$ of the operator $T(\beta)$. In particular 
    \begin{equation*}
	\hat{q}_{\beta}(\psi_n) =  \hat{Q}_{\beta}(\psi_n) - E_1(\beta)\|\psi_n\|_{L^2(\Sigma)}^{2}
= \int_{\Sigma}  \Bigg[  \frac{|w'_n|^2 |\chi_1|^2}{h_\beta^2}  - \frac{2g'(x) \xi'_2(t)}{h_\beta^2} \left(w'_n \chi_1 w_n  \chi'_1  - \frac{ (h_\beta^2)'}{4 h_\beta^2} w_n w'_n |\chi_1|^2 \right) \Bigg] \dx \dt.
	\end{equation*}
Note that
\begin{equation*}
     \int_{\cal C}  \frac{ \xi'_2(t)}{h_\beta^2} \chi_1  \chi'_1\dt 
     = -\frac{1}{2}\int_{\cal C} \left(\frac{\xi'_2(t)}{h_\beta^2} \right)' |\chi_1|^2 \dt.
\end{equation*}
It can be verified that
 	\begin{equation*}
	\hat{q}_{\beta}(\psi_n) =  A\int_{\mathbb{R}}   |w'_n|^2 \dx + B\int_{\mathbb{R}} g'(x)  w_n w'_n \dx  \leq A \int_{\mathbb{R}}   |w'_n|^2 \dx + \beta^2 |B|\left(\int_{\mathbb{R}} |w_n|^2 \dx \right)^{1/2} \left(  \int_{\mathbb{R}} |w^{\prime}_n|^2 \dx \right)^{1/2}.
	\end{equation*}
 By (\ref{estdericuoff1_surf}) and since $\|w_n\|_\infty \leq 1$, for all $n \in \mathbb{N}$, by dominated convergence theorem, 
\begin{equation*}
    \hat{q}_\beta(\psi_n) \to 0, \quad \mbox{as} \quad n \to \infty. 
\end{equation*}


Now, fix $\varepsilon \in \mathbb{R}$.  For each $n \in \mathbb{N}$, define 
	\begin{equation*}
		\psi_{n,\varepsilon}(x,t) :=  \psi_n(x,t) + \varepsilon \phi(x,t).  
	\end{equation*}
	for some $\phi \in \dom \hat{q}_\beta$. In this case,
	\begin{equation*}
		\hat{q}_\beta(\psi_{n,\varepsilon}) = \hat{q}_\beta(\psi_n) + 2 \varepsilon \,  {\rm Re} \, (\hat{q}_\beta(\psi_n, \phi))
		+ \varepsilon^2 \hat{q}_\beta(\phi).
	\end{equation*}


The strategy is to show that there exists $\phi$ satisfying 
	\begin{equation}\label{rbetaneez_surfcant}
		\lim_{n \to \infty} \hat{q}_\beta(\psi_n, \phi) \neq 0.
	\end{equation}	
	In fact, if (\ref{rbetaneez_surfcant}) holds true, it is enough to chosen  $\varepsilon$ such that $\hat{q}_\beta(\psi_{n,\varepsilon})<0$, for some $n$ large enough. 

 	Consider $\eta \in C^\infty_0 (\mathbb{R})$, with $\operatorname{supp} \eta \subset (-1,1)$ and $\eta(0) \neq 0$.  Define $\phi(x,t) = \eta(x) \chi_1(t)$. One has 
\begin{align*}
    \hat{q}_{\beta}(\psi_n, \phi )  = &  \int_{\Sigma} \frac{1}{h_\beta^2 } \left( \psi_n' - g' \xi'_2 \left[\partial_t \psi_n - \frac{  (h_\beta^2)'}{4 h_\beta^2} \psi_n  \right] \right) \left( \phi' -  g' \xi'_2 \left[\partial_t \phi - \frac{ (h_\beta^2)'}{4 h_\beta^2} \phi  \right] \right)  \dx \dt\\
&+ \int_{\Sigma} 
  \left( \partial_t \psi_n - \frac{(h_\beta^2)'}{4 h^2} \psi_n  \right) \left( \partial_t \phi - \frac{(h_\beta^2)'}{4 h_\beta^2} \phi  \right) \dx \dt - E_1(\beta) \int_{\Sigma} \psi_n \phi \, \dx \dt\\
   = & \int_{\Sigma} \frac{1}{h_\beta^2 } \Bigg(  w'_n \eta' |\chi_1|^2  -  g' \xi'_2 w'_n \chi_1 \left[\eta \chi'_1 - \frac{(h_\beta^2)'}{4 h_\beta^2} \eta \chi_1  \right]  -  g' \xi'_2\left[ w_n  \chi'_1 \eta' \chi_1 - \frac{(h_\beta^2)'}{4 h_\beta^2} w_n  \eta' |\chi_1|^2 \right] \Bigg) \dx \dt\\
&+ \int_{\Sigma} \frac{(1 + \beta^2)}{h^2}
  \left( w_n \chi'_1 - \frac{(h_\beta^2)'}{4 h_\beta^2} w_n \chi_1  \right) \left( \eta \chi'_1 - \frac{(h_\beta^2)'}{4 h_\beta^2} \eta \chi_1   \right) \dx \dt - E_1(\beta) \int_{\Sigma} w_n  \eta |\chi_1|^2 \dx \dt\\
   \to &   \int_{\Sigma} \eta'  g'\left[ \left(\frac{ \xi'_2}{2h_\beta^2} \right)'  +   \frac{\xi'_2 (h_\beta^2)'}{4 h_\beta^4}   \right] |\chi_1|^2 \dx \dt + \int_{\Sigma} \frac{(1+ \beta^2)}{h^2} \eta
  \left( \chi'_1 - \frac{\partial_t h_\beta^2}{4 h_\beta^2} \chi_1  \right)^2 \dx \dt - E(\beta) \int_{\Sigma} \eta |\chi_1|^2 \dx \dt\\
  = & \frac{B}{2} \int_{\mathbb{R}} \eta' g'  \dx,
\end{align*}
as $n \to \infty$.  Finally,  since $\eta(0) \neq 0$, $B/2\neq 0$, 
\begin{equation*}
    \frac{B}{2} \int_{\mathbb{R}} \eta' g'  \dx = -\frac{\beta B}{2} \int_{-1}^0 \eta'  \dx + \frac{\beta B}{2} \int_{0}^1 \eta'  \dx = -\beta B \eta(0) \neq 0. 
\end{equation*}  
 Thus, \eqref{rbetaneez_surfcant} holds true. \qed


