\subsubsection{Adaptive Minimum Stable Expectation}
\label{subsec:adaptive:MSE}

One difficulty in using \ref{eq:MinSE} is tuning the stability parameters $\eta$ and $\tau$. For instance, assume a user has access to $\numborac$ conformal predictors, each with coverage at least $1-\alpha'$, and wishes to apply \ref{eq:MinSE} to select among them such that the coverage after selection is at least $1-\alpha$. Then, they may choose any values of $\tau$ and $\eta$ satisfying $\alpha' \leq (\alpha - \tau) e^{-\eta}$. In particular, the utility tradeoff between $\tau$ and $\eta$ is not immediately clear. 

To address this, we propose \ref{eq:AdaMinSE}, an adaptive version of \ref{eq:MinSE}, which also optimizes over the choice of $\tau$ and $\eta$. Similarly to \ref{eq:MinSE}, \ref{eq:AdaMinSE} also makes use of a prior $b \in \Delta^{\numborac-1}$ (which can be chosen depending on the past as in \Cref{alg:adaptive_COMA}). However, instead of requiring the parameters $(\eta, \tau)$ as input, it simply takes the current level of miscoverage $\alpha'$ and the desired miscoverage level $\alpha$ after selection. The following proposition introduces \ref{eq:AdaMinSE}, together with its coverage guarantee.

\medskip

\begin{proposition}[Adaptive Minimum Stable Expectation]
\label{lemma:stability:aminse}
Let $\alpha', \alpha \in \open{0,1}$ with $\alpha'\leq \alpha$, and let $b \in \Delta^{\numborac-1}$ be fixed. Consider the following linear program
\begin{align}
\label{eq:AdaMinSE}
\begin{split}
\pstarstar{b}{\xi} =  \argmin_{d} \;\; &\sum_{i=1}^{\numborac} d_i\lambda\open{C_i^{\alpha'}\open{X}}\\
 \mathrm{s.t. \quad} & d\in \Delta^{\numborac-1}, \quad s\in \rset_+^{\numborac},\quad \tau, \eta \geq 0, \\ &d_i\leq {e^\eta}b_i + s_i, \ \quad  \sum_{i\in[\numborac]} s_i \leq \tau,\ \quad   e^\eta \alpha' +\tau   \leq  \alpha  \nonumber
 \end{split}
 \tag{\textcolor{black}{AdaMinSE}}
\end{align}
Let $\prob\ens{Y\in  C_i^{\alpha'}(X)}\geq 1-\alpha'$, for all $i\in[K]$. Moreover, consider the selection algorithm $\hatSxiepsilon$ with $\prob\{\hatSxiepsilon=i|\xi\} = \pstarstar{b}{\xi}$. Then, $\prob\ens{Y \in C_{\hatSxiepsilon}^\alpha(X)} \geq 1-\alpha$.
\end{proposition} 

\Cref{lemma:stability:aminse} ensures that \ref{eq:AdaMinSE} achieves the desired coverage. By optimizing over $(\eta, \tau)$, it removes the need for manual tuning, making it a practical and reliable approach for selection. 


\subsubsection{Derandomizing the Prediction Set}
\label{subsec:derandomization}


One potential limitation of the stable selection algorithms presented in Section~\ref{subsec:stability:application:conformal} is that they produce a random confidence set, which may be undesirable in certain applications. In such cases, the stable selection process can be derandomized using the same techniques as \citet{gasparin2024merging}. This is formalized in the following proposition.

\medskip

\begin{proposition}[Derandomized smallest conformal set]
\label{prop:derandomization}
Let $\hatSxiepsilon$ be an $(\eta,\tau)$-stable selection algorithm, and define $p_i(\xi) \coloneqq  \prob\ens{\hatSxiepsilon=i|\xi}$. Then, consider the derandomized confidence set 
\begin{align*}
  C_{\mathrm{dr}}(X,\xi) := \left\{y \in \mathcal Y:\sum_{i=1}^{\numborac} p_i(\xi)\mathds{1}\left\{y\in C_i^\alpha(X)\right\} \geq \frac{1}{2}\right\}.
\end{align*}
If ${C^{\alpha}\open{\cdot}_1,\ldots,C^\alpha\open{\cdot}_\numborac}$ satisfy \eqref{eq:basic:CP:guarantee}, it holds that $\prob\ens{Y\in C_{\mathrm{dr}}(X,\xi) }\geq 1- 2(\alpha e^\eta +\tau)$.
\end{proposition}



We highlight that while the set $C_{\mathrm{dr}}(\cdot, \xi)$ is still random with respect to the randomness of $\{C_i^\alpha(\cdot)\}_{i=1}^K$, the derandomization here refers to the fact that the stable selection process does not introduce additional randomness due to $\eps$.






\subsubsection{Conditional Coverage}\label{app:conditional_coverage_details}
A stronger guarantee than marginal coverage \eqref{eq:basic:CP:guarantee} is conditional coverage. Let $G:\xcal\rightarrow\gcal$ be a function that maps an input $X$ to a group attribute $G(X) \in \gcal$. A conformal predictor $C(X)$ is said to satisfy $(1-\alpha)$ conditional coverage with respect to $G$ if,
\begin{equation}
\label{eq:conditional:coverage:def}
    \prob\ens{Y \in C(X) | G(X)} \geq 1 - \alpha.
\end{equation}
This ensures that the coverage guarantee holds not just on average over all $X$, but also when restricted to specific subpopulations defined by $G$.  An example is the case where $\cal G$ is finite, which then corresponds to Group-Conditional validity~\citep{gibbs2025conformal}.  Such guarantees are crucial for added reliability in many applications.

Our stability-based selection framework can be extended to preserve conditional coverage. Suppose we have $\numborac$ conformal predictors $\{C_i^{\alpha}(X)\}_{i=1}^{\numborac}$, each satisfying $(1-\alpha)$ conditional coverage with respect to $G$. That is, for each $i \in [\numborac]$,
\begin{equation}
\label{eq:initial:conditional:coverage}
    \prob\ens{Y \in C_i^{\alpha}(X) | G(X)} \geq 1 - \alpha.
\end{equation}
% Let $\hatSxiepsilon$ be an $(\eta,\tau)$-stable selection algorithm for choosing among these predictors, as in \Cref{subsec:algorithmic:stability}. $(\eta,\tau)$-stability implies that there exists a fixed distribution $S_0$ over $[\numborac]$ such that for any input $\xi$,
% $ \hatSxiepsilon \approx^{|\xi}_{\eta,\tau} S_0 $.
% \begin{equation}
% \label{eq:stability:expectation:ineq_app}
%     \mathbb{E}_\eps[\phi(\hatS(\xi,\eps)) \mid \xi] \leq e^\eta \mathbb{E}_{S_0}[\phi(S_0)] + \tau.
% \end{equation}

We can now state the conditional coverage guarantee for the selected set.


\medskip

\begin{proposition}[Conditionally valid stable selection]
\label{prop:stable:CP:selection:conditional}
Assume that each conformal predictor $C_i^{\alpha}(X)$ satisfies $(1-\alpha)$ conditional coverage  with respect to $G$, for all $i \in [\numborac]$. If $\hatS:\Xi\times \E \to [\numborac]$ is an $(\eta,\tau)$-stable selection algorithm (with $\xi = [\lambda(C_1^{\alpha}(X)),\ldots, \lambda(C_\numborac^{\alpha}(X))]$), then it holds that
\begin{align}
\label{eq:stable:CP:selection:conditional}
    \prob\ens{Y\in C_{\hatSxiepsilon}^{\alpha}(X) \mid G(X)} \geq 1-(\alpha e^{\eta}+\tau).
\end{align}
\end{proposition}


This result shows that if the original conformal predictors provide conditional coverage, the stable selection mechanism allows for selecting among them while retaining a (correspondingly adjusted) conditional coverage guarantee. The required level for the initial predictors would be $1 - (\alpha - \tau)e^{-\eta}$ to achieve $1-\alpha$ conditional coverage post-selection.
















