\subsection{Adaptive Conformal Online Model Aggregation.}
\label{subsec:coma}

Conformal Online Model Aggregation (COMA) \citep{gasparin2024conformal} extends online conformal prediction by addressing the challenge of model aggregation. It combines prediction sets from multiple algorithms through a voting mechanism, where weights are dynamically adjusted over time based on past performance. Formally, at each time step $t$, COMA assigns weights $w^{(t)} = [w_1^{(t)}, \dots, w_\numborac^{(t)}] \in \Delta^{\numborac-1}$, which reflect the relative importance of each of the $\numborac$ underlying conformal predictors according to the following rule 
% \begin{align*}
  $  w_i^{(t)} \propto \exp\big( - \gamma_{t-1} \sum_{j=1}^{t-1} \, \lambda\big( C_i^{(j)}(X_j) \big) \big),$
% \end{align*}
where $\gamma_t$ is the adaptive learning rate from the AdaHedge algorithm \citep{de2014follow}, an adaptive version of the Hedge algorithm \citep{freund1997decision}. COMA then outputs the aggregated prediction set  $C^{(t)} \coloneqq \big\{ y \in \mathcal{Y} \big|\, \sum_{i=1}^{\numborac} w_i^{(t)} \mathds{1} \{ y \in C_i^{(t)}(X_t) \} \geq \frac{1}{2} \big\},$
% \end{align*}
which can be interpreted as the aggregated set obtained by selecting the $i$-th conformal set with probability $w_i^{(t)}$.

\textbf{Non-adaptiveness of {COMA}.} Crucially, at time $t$, the COMA framework assigns weights to the $\numborac$ conformal algorithms using only the observations up to time $t-1$, \textit{without} access to $X_t$ or the prediction sets $\{C_i^{(t)}(X_t)\}_{i=1}^{\numborac}$. Furthermore, due to its AdaHedge formulation, COMA optimizes the weights on average over time, without adapting to each individual $X_t$. 

\begin{algorithm}[t]
   \caption{Adaptive COMA (AdaCOMA)}
   \label{alg:adaptive_COMA}
\begin{algorithmic}
   \STATE \textbf{Input:} $\numborac$ conformal algorithms $\{C_i^{(t)}\}_{i=1}^{\numborac}$, stability parameter $(\eta,\tau)$, initial weights $w^{(1)} = (1/k, \ldots, 1/k)$.
   \STATE \textbf{For: }{$t = 1, 2, \ldots$}
  \STATE Compute $w^{(t)}$ using COMA. 
  \STATE Compute $\pstar{(w^{(t)})}{\xi_t} \in \Delta^{\numborac-1}$ using \ref{eq:MinSE}  with $b=w^{(t)}$ and parameters $(\eta,\tau)$.
    \STATE \textbf{Output:} Any of the following two options:
    \STATE {Option 1}: Combined set $C_{\mathrm{comb}}^{(t)}(X_t)$ equal to $\ens{y\in \ycal\big|\sum_{i=1}^{\numborac} \pstari{w^{(t)}}{\xi_t}   \one\ens{y\in C_i^{(t)}(X_t)}\geq \frac{1}{2}}$.
    \STATE {Option 2}: Combined predictor leading to  $C_{\hatS_{(\xi_t,\eps_t)}}^{(t)}(X_t)$, with $\prob\ens{\hatS_{(\xi_t,\eps_t)} = i |\xi_t} = \pstari{w^{(t)}}{\xi_t} $.
\end{algorithmic}
\end{algorithm}

\textbf{{AdaCOMA}.} To achieve the best of both worlds,  we incorporate COMA into our stable selection algorithm. Specifically, at iteration~$t$, we use {COMA}'s weights $w^{(t)}$ as the prior for a stable selection mechanism, which selects after observing both $X_t$ and the sets $\{C_i^{(t)}(X_t)\}_{i=1}^{\numborac}$, allowing for pointwise adaptability. The combined procedure, termed {AdaCOMA}, is detailed in Algorithm~\ref{alg:adaptive_COMA}. COMA does not have assumption-free coverage guarantees for a fixed target level. However, letting
\begin{align}
\label{eq:COMA:beta_t}
    \beta_t \coloneqq \mathbb E \bigg[{\sum_{i=1}^{\numborac} w_i^{(t)}\one\ens{Y_t \notin C_i^{(t)}(X_t)}}\bigg],
\end{align}
\citet{gasparin2024conformal} show that the following holds
\begin{align}
\label{eq:guarantee:coma}
    \prob\ens{Y_t \notin  C^{(t)}} \leq 2 \beta_t.
\end{align}
In the remainder of this section, we analyze the coverage guarantees of AdaCOMA in comparison to the bound in~\eqref{eq:guarantee:coma} for COMA. Detailed bounds on $\beta_t$ under additional assumptions, are given in \citet{gasparin2024conformal}. 


\medskip

\begin{proposition}[Adaptive COMA] 
\label{prop:adaptive:coma}
Consider Algorithm~\ref{alg:adaptive_COMA}, and let $\beta_t$ be defined as in \eqref{eq:COMA:beta_t}. Then, 
\begin{itemize}
    \item[(i)] the set $C_{\mathrm{comb}}^{(t)}(X_t)$ satisfies
% \begin{align}
% \label{prop:adaptive:coma:C_comb}
 $   \prob\ens{Y_t \in  C^{(t) }_{\mathrm{comb}}(X_t)} \geq 1 - 2\open{\beta_t e^{\eta} +  \tau}$;
% \end{align}
\item[(ii)] the set $C_{\hatS_{(\xi_t,\eps_t)}}^{(t)}(X_t)$ satisfies $\prob\ens{Y_t\in C_{\hatS_{(\xi_t,\eps_t)}}^{(t)} (X_t)} \geq 1 - \beta_t e^{\eta} - \tau$.
\end{itemize}
\end{proposition}
Proposition~\ref{prop:adaptive:coma} demonstrates that AdaCOMA inherits the flexibility of COMA while improving its adaptability to current observations through the stable selection mechanism.





