The proof of Theorem~\ref{thm:stable:selection} requires the following lemma from \citet{zrnic2023post}, which is inspired by the approach in \citet{bassily2016algorithmic}.

\begin{lemma}\citep[Lemma 1]{zrnic2023post}
\label{lemma:tijana:alg:stab}
Let $\hatS: \Xi \times \E \to \mathcal{S}$ be an $(\eta,\tau,\nu)$-stable selection algorithm and ${S}_0$ be the corresponding random variable. Then, $(\xi,\hatSxiepsilon) \approx_{\eta,\tau+\nu} (\xi,{S}_0)$.
\end{lemma}


% ---------------------------------------------------------------

\begin{proof}[Proof of ~\Cref{thm:stable:selection}] In this proof, similar to analogous results in \citet{zrnic2023post}, a lot of the heavy lifting is done by \Cref{lemma:tijana:alg:stab}. Nonetheless, the selection dependence on the confidence sets themselves introduces some subtleties, making direct application of the steps of \citet{zrnic2023post} non-straightforward. Thus, we take a different starting step by defining a shadow algorithm. 

Let us define $\hatS':\Xi \times \mathcal{Z}\times \E\rightarrow\mathcal{S}$ such that $\hatS'(\xi,\zeta, \eps)=\hatSxiepsilon$, for all $(\xi,\zeta) \in \Xi \times \mathcal{Z}$. Then, if $\hatS$ is $(\eta, \tau, \nu)$-stable with respect to $\mathcal{P}$ on $\Xi$, we also have that $\hatS'$ is $(\eta, \tau, \nu)$-stable with respect to the product distribution $\mathcal{P} \otimes \mathcal{Q}$, where $\mathcal{Q}$ is the distribution of $\zeta$. Combining this with Lemma~\ref{lemma:tijana:alg:stab}, we obtain $(\zeta, \xi, \hatSxiepsilon) \approx_{\eta, \tau+\nu} (\zeta, \xi, S_0)$. Now, defining the event $O_\delta \coloneqq \{(\zeta ,\xi, \hatSxiepsilon) \in \mathcal{Z} \times \Xi \times \mathcal S : \zeta \not\in \mathrm{CI}_{\hatSxiepsilon}^{\delta e^{-\eta}}\}$, we have that
\begin{align*}
    \prob\left\{\zeta \not\in \mathrm{CI}_{\hatSxiepsilon}^{(\delta e^{-\eta})}\right\} &\leq e^\eta \prob\ens{(\zeta ,\xi, S_0)\in O_\delta} +\tau+\nu \\
    &= e^\eta \prob\left\{\zeta \not\in \mathrm{CI}_{S_0}^{\delta e^{-\eta}}\right\} +\tau+\nu
    \leq e^\eta \delta e^{-\eta} +\tau+\nu \leq \delta + \tau + \nu,
\end{align*}
where the first inequality follows from the definition of indistinguishability, and the second inequality follows from the assumption that $\prob\ens{\zeta \notin \mathrm{CI}_s^{\alpha}}\leq \alpha$ holds for all $s\in \mathcal{S}$.% The result now follows from the substitution $\alpha = \delta e^{-\eta}$.
\end{proof}


