\begin{proof}[Proof of \Cref{lem:stability:Laplace}]
Let $S_0 = \argmin_{i \in [\numborac]} \eps_i$, with $\eps_i \stackrel{\mathrm{i.i.d.}}{\sim} \mathrm{Lap}\left({1}/{\eta}\right)$. Moreover, note that $\hatSxiepsilon = i$ if and only if $\eps_i \leq \min_{j \neq i} \left\{\eps_j + \lambda\open{\mathrm{C}^\alpha_j(X)} - \lambda\open{\mathrm{C}^\alpha_i(X)}\right\} \leq \min_{j \neq i} \eps_j + 1$, where we used the fact that $\lambda(C_i^{\alpha}(X)) \in [0,1]$. Finally, for all $i\in [\numborac]$
\begin{align*}
    \prob\left\{ \hatSxiepsilon = i\ \bigg | \ \sigma(\xi, \{\eps_j\}_{j \neq i}) \right\} &\leq \prob \left\{ \eps_i \leq \min_{j \neq i} \eps_j + 1 | \sigma(\xi, \{\eps_j\}_{j \neq i})\right\}
    \\& \leq e^\eta \prob \left\{ \eps_i \leq \min_{j \neq i} \eps_j | \sigma(\xi, \{\eps_j\}_{j \neq i})\right\}
    \\& =  e^\eta \prob\left\{ S_0 = i | \sigma(\xi, \{\eps_j\}_{j \neq i})\right\},
\end{align*}
where the second inequality uses the fact that the densities ratio ${p_{\eps_i - 1} }/{ p_{\eps_i}}$ is upper bounded by $e^\eta$. The result now follows by taking expectation on both sides.
\end{proof}


