\begin{proof}[Proof of Lemma~\ref{lem:stability:exponential:mechanism}]
Let $S_0$ be a uniform r.v. with $\prob\{S_0 = i\} = {1}/{k}$. Then,
\begin{align*}
    \frac{\prob\ens{\hatSxiepsilon=i \bigg | \ \xi  }}{\prob\ens{S_0=i}} &= \frac{k \exp\open{-\eta\lambda\open{\mathrm{C}^\alpha_i(X)} }}{\sum_{i\in [\numborac]}\exp\open{-\eta\lambda\open{\mathrm{C}^\alpha_i(X)}}} 
    \\&\leq \frac{k \exp\open{\eta}}{k \exp\open{-\eta}} = \exp{2\eta},
\end{align*}
where we used the fact that $\lambda(C_i^{\alpha}(X)) \in [0,1]$.
\end{proof}


