\begin{proof}[Proof of Proposition~\ref{prop:derandomization}]
The proof builds upon the reasoning in \cite{gasparin2024merging}. Since $\hatSxiepsilon$ is $(\eta,\tau)$-stability, we know that there exists a fixed point $b\in \Delta^{\numborac-1}$ such that $p_i(\xi) \leq \exp\open{\eta}b_i + s_i$ and $\sum_{i=1}^{\numborac} s_i\leq \tau$. It follows that 
\begin{align*}
    \expec\closed{\sum_{i=1}^{\numborac} p_i(\xi)\one \ens{Y\notin C_i^\alpha(X)}} &\leq  \exp\open{\eta}\alpha +\tau.
\end{align*}
Moreover, using the Markov inequality, we have that
\begin{align*}
  \prob\ens{Y\notin  C_{\text{dr}}(X,\xi)} &= \prob\ens{\sum_{i=1}^{\numborac} p_i(\xi)\one\ens{Y\notin C_i^\alpha(X)}\geq  \frac{1}{2}}
  \leq 2\expec\closed{\sum_{i=1}^{\numborac} p_i(\xi)\one \ens{Y\notin C_i^\alpha (X)}},
\end{align*}
from which the result follows immediately.
\end{proof}


