\begin{proof}[Proof of Proposition~\ref{prop:stable:CP:selection:conditional}]
We want to bound the conditional miscoverage probability
$$ P_{\mathrm{miscover}|G(X)} \coloneqq \prob\ens{Y \notin C_{\hatS(\xi(X),\eps)}^{\alpha}(X) \mid G(X)}. $$
By the law of total expectation, conditioning on $X$ we have
$$ P_{\mathrm{miscover}|G(X)} = \mathbb{E}_{X|G(X)} \left[ \prob\ens{Y \notin C_{\hatS(\xi(X),\eps)}^{\alpha}(X) \mid X, G(X)} \right]. $$
Since $G(X)$ is determined by $X$, the inner probability is $\prob\ens{Y \notin C_{\hatS(\xi(X),\eps)}^{\alpha}(X) \mid X}$.
Since the randomness $\eps$ in $\hatS(\xi(X),\eps)$ is independent of $Y$ given $X$, we have
$$ \prob\ens{Y \notin C_{\hatS(\xi(X),\eps)}^{\alpha}(X) \mid X}  = \sum_{s=1}^{\numborac} \prob\ens{Y \notin C_s^{\alpha}(X) \mid X} \prob_\eps\ens{\hatS(\xi(X),\eps)=s \mid X}. $$
Using $(\eta,\tau)$-stability (conditional on $\xi(X)$) property of $\shat$, we have 
\begin{align*}
    \sum_{s=1}^{\numborac} \prob\ens{Y \notin C_s^{\alpha}(X) \mid X} \prob_\eps\ens{\hatS(\xi(X),\eps)=s \mid X} &\leq e^\eta \sum_{s=1}^{\numborac} \prob\ens{Y \notin C_s^{\alpha}(X) \mid X} \prob\ens{S_0=s \mid X}+\tau\\
    & \leq e^\eta \sum_{s=1}^{\numborac} \prob\ens{Y \notin C_s^{\alpha}(X) \mid X} \prob\ens{S_0=s}+\tau .
\end{align*} 
for some random $S_0$ variable with support $[\numborac]$. It follows that 
\begin{align*}
    P_{\mathrm{miscover}|G(X)} &= e^\eta\sum_{i=1}^\numborac\prob\ens{S_0=i}\mathbb{E}_{X|G(X)}\closed{\prob\ens{Y \notin C_{i}^{\alpha}(X)}|X}+\tau\\
    &\leq e^\eta \alpha +\tau. 
\end{align*}
\end{proof}


