\begin{proof}[Proof of Corollary~\ref{cor:stable:online:CP}]
Since $\hatS(\xi_t, \varepsilon_t)$ is $(\eta,\tau)$-stability. Using the same starting derivation as the proof of \Cref{prop:minse_optimality}, we know that there exists a fixed point $b\in \Delta^{\numborac-1}$ such that $p_i(\xi_t) \leq \exp\open{\eta}b_i + s_i$ and $\sum_{i=1}^{\numborac} s_i\leq \tau$. Thus,
\begin{align*}
    \prob\ens{Y_t\notin C_{\hatS(\xi_t, \varepsilon_t)}^{(t)}(X_t)} = \expec\closed{\one\ens{Y_t\notin C_{\hatS(\xi_t, \varepsilon_t)}^{(t)}(X_t)}} &= \sum_{i=1}^K p_i\open{\xi_t}\one\ens{Y_t\notin C_{i}^{(t)}(X_t)}\\
    &\leq \sum_{i=1}^K e^\eta b_i \one\ens{Y_t\notin C_{i}^{(t)}(X_t)} +\tau,
\end{align*}
from which we have that
\begin{align*}
    \limsup_{T \to \infty}\, \frac{1}{T} \sum_{t=1}^T \prob\ens{Y_t\notin C_{\hatS(\xi_t, \varepsilon_t)}^{(t)}(X_t)} &\leq \limsup_{T \to \infty}\, \frac{1}{T} \sum_{t=1}^T \left(\sum_{i=1}^K e^\eta b_i \one\ens{Y_t\notin C_{i}^{(t)}(X_t)} +\tau\right)\\
    &\leq e^\eta \sum_{i=1}^K b_i \left(\limsup_{T \to \infty}\, \frac{1}{T} \sum_{t=1}^T  \one\ens{Y_t\notin C_{i}^{(t)}(X_t)}\right) +\tau \\
    & \leq e^\eta \alpha + \tau,
\end{align*}
where the second inequality follows from Fubini's theorem, which allows us to interchange the two sums, and the subadditivity of $\limsup$. This concludes the proof.
\end{proof}


\begin{proof}[Proof of Proposition~\ref{prop:adaptive:coma}]
Using the definition of $C^{(t)}_{\mathrm{comb}}$ in Algorithm~\ref{alg:adaptive_COMA}, together with Markov's inequality, we have that
\begin{align*}
    \prob\ens{Y_t \notin  C^{(t)}_{\mathrm{comb}}} =& \prob\ens{ \sum_{i=1}^{\numborac} \pstari{w^{(t)}}{\xi_t}   \one\ens{Y_t\notin C_i^{(t)}(X_t)} \geq \frac{1}{2}} 
    \\ \leq& 2\expec\closed{\sum_{i=1}^{\numborac} \pstari{w^{(t)}}{\xi_t} \one\ens{Y_t\notin C_i^{(t)}(X_t)}}.
\end{align*}
Moreover, from \ref{eq:MinSE}, we know that $\pstari{w^{(t)}}{\xi_t} \leq e^\eta w_i^{(t)} + s_i$ and $\sum_{i=1}^{\numborac} s_i\leq \tau$. Therefore,
\begin{align*}
    \prob\ens{Y_t \notin  C^{(t)}_{\mathrm{comb}}} \leq 2 \left( e^\eta \expec\closed{\sum_{i=1}^{\numborac} w^{(t)} \one\ens{Y_t\notin C_i^{(t)}(X_t)}} + \tau \right) = 2 \left( e^\eta \beta_t + \tau \right),
\end{align*}
where the equality follows from \eqref{eq:COMA:beta_t}. This concludes the proof.

\end{proof}






