\paragraph{Notation reminder.} Before providing the proof of Theorem~\ref{thm:recalibrated_result}, we introduce some additional notation and recall some notation in the main text. We consider a calibration dataset $\dcal_\cal = \ens{(X_i, Y_i)_{i\in[m]}}$ and a test point $(X,Y)$. We interchangeably denote $(X,Y)$ as $\open{X_{m+1},Y_{m+1}}$ and define $\dcal_\cal^+ = \ens{\open{X_i, Y_i}_{i\in[m+1]}}$. In addition, for each base predictor $k \in [\numborac]$, we compute the non-conformity scores on the calibration data, for $i \in [m],$
\begin{equation*}
    \order_{k,i} \coloneqq s_k(X_i, Y_i, f_k) \quad
\end{equation*}
and denote the score of the test point as $\order_{k,m+1} = s_k(X_{m+1}, Y_{m+1}, f_k)$. Let $\scoreset_k \coloneqq \{\order_{k,1}, \dots, \order_{k,m}\}$ denote the set of these calibration scores for model $k$. We also define $\scoreset^+_k \coloneqq \scoreset_k \cup \{\order_{k,m+1}\}$. We use $\order_{k,(r)}$ and $\order^{+}_{k,(r)}$ to denote the $r$-th order statistic in $\scoreset_k$ and $\scoreset^+_k$. Furthermore, we denote the ranks of a score $\order_{k,i}$ within the two sets as follows $\rank_{k,i} \coloneqq \sum_{j=1}^{m} \mathds{1}\{\order_{k,j} \le \order_{k,i}\}$ and $\rank^{+}_{k,i} \coloneqq \sum_{j=1}^{m+1} \mathds{1}\{\order_{k,j} \le \order_{k,i}\}$. Similarly to \Cref{sec:rank_calibration}, we parameterize the conformal prediction sets using ranks. For a rank index $R \in [m]$, define, respectively:
\begin{gather*} \label{eq:param_calib_cont_unnumbered_cont}
 C_k(X, R) \coloneqq \ens{ y \in \mathcal{Y} : s_k(X, y, f_k) \le \order_{k,(R)} }, \\
 C^+_k(X, R) \coloneqq \ens{ y \in \mathcal{Y} : s_k(X, y, f_k) \le \order^{+}_{k,(R)} }.
\end{gather*}

Both set families are monotonic: $C_k(X, R_1) \subseteq C_k(X, R_2)$ if $R_1 \le R_2$; similarly for $C^+_k$. The relationship $\order_{k,(R)} \ge \order^{+}_{k,(R)}$ holds for $R \in [m]$, implying the set inclusion $C_k^+(X, R) \subseteq C_k(X, R)$.
To relate with the standard perspective on split conformal threshold, note that for $i'\in[m]$
\begin{equation*}
\prob\ens{\rank^{+}_{k,m+1}\leq i'} =\prob\ens{\order^{+}_{k,m+1}\leq\order^{+}_{k,(i')}}\leq \prob\ens{\order^{+}_{k,m+1}\leq \order_{k,(i')}}  = \prob\ens{Y_{m+1}\in C_k(X_{m+1},i')},
\end{equation*}
where $\prob\ens{\rank^{+}_{k,m+1}\leq i'}\geq i'/(m+1)$ by exchangeability. Note that this is equivalent up to a reparameterization to the split conformal method introduced in \Cref{sec:preliminaries:CP}, by setting $i' = \ceil{(1-\alpha)(m+1)}$.


For each point $i \in [m+1]$, we apply the selection rule using its feature vector $X_i$ and independent randomness $\eps_i \sim \pcal_\eps$. Let $k_i \coloneqq \hatS(X_i, \eps_i)$ be the index of the predictor selected for the $i$-th data point. By our assumption, $k_i$ is independent of $\dcal_{\mathrm{cal}}$, conditionally to $X_i$. We now define the \textbf{effective rank} for the $i$-th point. This is the rank of the $i$-th point's score calculated using the predictor $k_i$ that was selected specifically for $X_i$: $$\hat \rank^+_i \coloneqq \rank^+_{k_i, i} = \rank^+_{\hatS(X_i, \eps_i), i}.$$ 

Similarly, for $i\in[m]$, we define $$\hat \rank_i \coloneqq \rank_{k_i, i} = \rank_{\hatS(X_i, \eps_i), i}.$$ Finally, we define the following two sequences $\mathcal \rank^+ \coloneqq (\hat \rank^+_1, \dots, \hat \rank^+_{m+1})$ and $\mathcal\rank\coloneqq (\hat \rank_1, \dots, \hat \rank_{m})$, with $\hat R^+_{(i)}$ and $\hat R_{(i')}$ denoting their $i$-th and $i'$-th order statistics respectively, for $i\in[m+1]$ and $i'\in [m]$.


\begin{proof}[Proof of Theorem~\ref{thm:recalibrated_result}]
Notice that $\mathcal R^+$ forms an exchangeable sequence \citep[Lemma 2.2]{angelopoulos2024theoretical}. This follows from the exchangeability of the original data pairs $\ens{(X_i, Y_i)}_{i=1}^{m+1}$ and the fact that the procedure to obtain $\hat \rank^+_i$ is symmetric w.r.t.~$\dcal_\cal^+$. In addition, $\mathcal R \subset \mathcal R^+$ implies that $\hat\rank^+_{(m)}\leq \hat\rank_{(m)}$. As a direct consequence, for $i\in [m]$, we get
\begin{align*} \label{eq:effective_rank_prob}
   \frac{i}{m+1} \le \prob \ens{ \hat \rank^+_{m+1}\leq \hat \rank^+_{(i)}} &\le \prob\ens{\order^+_{k_{m+1},\left(R^+_{k_{m+1},m+1}\right)}\leq \order_{k_{m+1}, \open{\hat \rank^+_{(i)}}}}\\
   &= \prob\ens{\order^+_{k_{m+1},m+1}\leq \order_{k_{m+1}, \open{\hat \rank^+_{(i)}}}}\\
   &\leq \prob\ens{\order^+_{k_{m+1},m+1}\leq \order_{k_{m+1}, \open{\hat \rank_{(i)}}}}\\
   &= \prob\ens{Y_{m+1}\in C_{k_{m+1}} \left(X_{m+1},\hat R_{(i)} \right)} .
\end{align*}
Here, the first line follows from the monotonicity of the order statistics of the series $\open{\order^+_{k_{m+1},1},\ldots, \order^{+}_{k_{m+1},m+1}}$ and the definition of $\hat \rank^+_{m+1}$. The second line is by the fact that for any $k\in [\numborac], i'\in[m+1]$, we have $s^+_{k, (\rank^+_{k,i'})}= s^+_{k,i'}$. The third by $\hat \rank^+_{(i)}\leq \hat \rank_{(i)}$ for any $i\in [m]$  and the fourth by the monotonicity of the split conformal set w.r.t.~increasing score. Finally, choosing $i = \ceil{(1-\alpha)(m+1)}$, we get
\begin{equation*}
    \prob\ens{Y_{m+1}\in C_{\hatS(X_{m+1})}(X_{m+1},R_{(i)})} = \prob\ens{Y_{m+1}\in C_{k_{m+1}}(X_{m+1},R_{(i)})}\geq 1-\alpha,
\end{equation*}
and recover the theorem.
% In words, using the rank parametrization of the split conformal prediction andrank $R_{(i)}$, we are able to achive $1-\alpha$ coverage after arbitrary selection as long as it is independant from the calibration set $\dcal_{\mathrm{cal}}$. Now that we presented the proof, we can elaborate more on why we need $\hatS$ to not depend on $\dcal_{\cal}$, this is to maintain exchangeability of the sequence $R^+$. This excheageability requires $\hatS$ to treat $(X_1,Y_{1}),\ldots, (X_{m},Y_m),(X_{m+1},Y_{m+1})$, which would be violates if it depends on $\dcal_{\mathrm{cal}}$, which does not contain the test point.
\end{proof}



