\begin{proof}
We follow the proof for the single-species system from~\cite{Tamura1984,dressler1987stationary}. We consider the following linearized stationary equation
\begin{equation}
 \label{eq: linearised stationary eqn}
\L_i[\rho_1,\ldots, \rho_M](\mu)=0, 
\end{equation}
where $\rho_1,\ldots \rho_M \in (L^1(\bRb^d))^M$ are given and 
\begin{align*}
\L_i[\rho_1,\ldots, \rho_M](\mu)&=\div\bigg[\Big(\nabla V_i+\sum_{j=1}^M a_j\nabla F_{ij}\ast\rho_j\Big)\mu \bigg]+\frac{\sigma_i^2}{2}\Delta\mu\\
&=\div\bigg[\Big(\nabla V_i+\sum_{j=1}^M a_j\nabla F_{ij}\ast\rho_j +\frac{\sigma_i^2}{2}\frac{\nabla \mu}{\mu}\Big)\mu\bigg],\quad i=1,\ldots M.
\end{align*}
Note that $\L_i$ is a linear operator with respect to $\mu$. 
%Then an equilibrium point of \eqref{eq: multi-species PDE} satisfies
%\[
%\L_i[\mu_1,\ldots, \mu_N](\mu_i)=0,\quad i=1,\ldots, M.
%\]
We define
\[
v_i(x):=\frac{1}{Z_i}\exp\Big[-\frac{2}{\sigma_i^2}\Big(V_i(x)+\sum_{j=1}^M a_j F_{ij}\ast\rho^j(x)\Big)\Big],\quad i=1,\ldots, M,  
\]
where the $Z_i$'s are the normalization constants so that $\|v_i\|_{L^1}=1$. We will show that $v_i$ is the unique solution of \eqref{eq: linearised stationary eqn} in $\mathcal{P}(\mathbb{R}^d)\times H^1(\mathbb{R}^d)$.
%the space
%\[
%A_i:=\{v: \R^d\to \R\big\vert v\in H^1(\R^d)~\text{and}~ f:= v v_i^{-1/2}~\text{satisfies}~ f\in H^1(1+|g_i|)\,dx, \Delta f\in L^2(
%R^d)\},
%\]
%where $g_i:=\nabla V_i+\sum_{j}a_j \nabla F_{ij}\ast \rho^j$. 
In fact, due to the growth conditions of $V_i$ in Assumption~\ref{asp: assumption}, direct computations show that $v_i \in \mathcal{P}(\mathbb{R}^d)\times H^1((\mathbb{R}^d))$ (in fact $v_i$ is smooth, see \cite{Tamura1984}). In addition, we have
\[
\nabla v_i=-\frac{2}{\sigma_i^2}\Big(\nabla V_i+\sum_{j=1}^M a_j \nabla F_{ij}\ast \rho^j\Big) v_i.
\]
Thus
\[
\frac{\sigma_i^2}{2}\frac{\nabla v_i}{v_i}+\Big(\nabla V_i+\sum_{j=1}^M a_j \nabla F_{ij}\ast \rho^j\Big)=0.
\]
It follows that $v_i$ solves the linearized stationary equation \eqref{eq: linearised stationary eqn}. Now suppose this equation has another solution $w_i \in A_i$, that is $\L_i(w_i)=0$. Let $f_i:=w_i v_i^{-1/2}$. Define
\[
\Q_if:=-v_i^{-1/2}\L_i(f v_i^{1/2}).
\]
Thus $\Q_i f_i=-v_i^{-1/2}\L_i(f_i v_i^{1/2})=-v_i^{-1/2}\L_i(w_i)=0$. We have
\begin{align*}
\div\Big( v_i^{-1/2}f_i\nabla v_i\Big)&=-\frac{2}{\sigma_i^2}\div \bigg[ v_i^{-1/2}f_i \Big(\nabla V_i+\sum_{j=1}^M a_j \nabla F_{ij}\ast \rho^j\Big) v_i\bigg]
\\&=-\frac{2}{\sigma_i^2}\div \bigg[ v_i^{1/2}f_i \Big(\nabla V_i+\sum_{j=1}^M a_j \nabla F_{ij}\ast \rho^j\Big)\bigg],
\end{align*}
that is
\[
\frac{\sigma_i^2}{2}\div\Big( v_i^{-1/2}f_i\nabla v_i\Big)+\div \bigg[ v_i^{1/2}f_i \Big(\nabla V_i+\sum_{j=1}^M a_j \nabla F_{ij}\ast \rho^j\Big)\bigg]=0.
\]
Therefore,
\begin{align*}
    \L_i (w_i)&=\div\bigg[\Big(\nabla V_i+\sum_{j=1}^M a_j\nabla F_{ij}\ast\rho_j\Big)w_i+\frac{\sigma_i^2}{2}\nabla w_i \bigg]
    \\&=\div\bigg[\Big(\nabla V_i+\sum_{j=1}^M a_j\nabla F_{ij}\ast\rho_j\Big)f_i v_i^{1/2}+\frac{\sigma_i^2}{2}\nabla ( v_i v_i^{-1/2} f_i ) \bigg]
    \\&=\div\bigg[\Big(\nabla V_i+\sum_{j=1}^M a_j\nabla F_{ij}\ast\rho_j\Big)f_i v_i^{1/2}\bigg]+\frac{\sigma_i^2}{2}\bigg\{\div\Big[v_i\nabla (v_i^{-1/2} f_i)\Big]+\div\Big[(v_i^{-1/2} f_i)\nabla v_i  \Big]\bigg\}
    \\&=\frac{\sigma_i^2}{2}\div\Big[v_i\nabla (v_i^{-1/2} f_i) \Big].
\end{align*}
Hence,
\[
\Q_i f_i=-v_i^{-1/2}\L_i(w_i)=-\frac{\sigma_i^2}{2}v_i^{-1/2}\div\Big[v_i\nabla (v_i^{-1/2} f_i)\Big].
\]
Thus we obtain
\begin{align*}
 0&=\langle \Q_i f_i, f_i\rangle_{L^2}=-\frac{\sigma_i^2}{2}\int_{\bRb^d}v_i^{-1/2}\div\Big[v_i\nabla (v_i^{-1/2} f_i)\Big]\, f_i
 \\&=\frac{\sigma_i^2}{2}\int_{\bRb^d}v_i\Big|\nabla (v_i^{-1/2} f_i)\Big|^2.
\end{align*}
It follows that $\nabla (v_i^{-1/2} f_i)=0$. Hence $ v_i^{-1/2}f_i=C=\mathrm{const}$, so $w_i=v_i^{1/2} f_i=C\, v_i$.  Since $\|w_i\|=\|v_i\|=1$, it implies that $C=1$. That is, $ w_i=v_i$. 

Now suppose that $(\mu^k(\ddx)=\mu^k(x)\ddx)_{k=1}^M$ is a stationary solution of \eqref{eq: multi-species PDE}. Then we have
\[
\mathcal{L}_k[\mu_1,\ldots, \mu_M](\mu_i)=0,\quad{for}\quad k=1,\ldots, M.
\]
According the above statement, $\mu_i$ must satisfy \eqref{eq: muk}. This completes the proof.
\end{proof}

Proposition~\ref{jugnot} provides us with the essential structure of the invariant measures for the multi-species McKean-Vlasov PDE. This Gibbs-like structure, Eqn.~\eqref{eq: muk}, will play a crucial role in the following sections: to prove the existence of an equilibrium state, it is necessary and sufficient to solve the system of equations~\eqref{eq: muk}-\eqref{eq: Zk}.


\subsection{The free-energy functional}
\label{subsec:free_energy}

In this subsection, we only assume that the symmetry Assumption~\ref{asp: assumptionter}, i.e. Newton's third law, is satisfied. In particular, we have $F_{k\ell}=F_{\ell k}$ for any $1\leq k,\ell\leq M$. This assumption implies that the McKean-Vlasov PDE system \eqref{eq: multi-species PDE} is of gradient flow form. Therefore, we can define the free energy functional of this gradient flow. This functional has been used in \cite{BCCP,CMV} to prove convergence towards a steady state for the single-species model when the confining potential is convex. This was later extended to the non-convex case in \cite{AOP,SPA}. We emphasize the fact that the formal calculations that follow are valid for arbitrary interaction potentials, and that they are not restricted to the quadratic case. In particular, in this section we are not imposing Assumption~\ref{asp: assumptionbis}.

%\medskip

For the single-species McKean-Vlasov PDE, the free-energy functional is the following:
\begin{equation}\label{e:free_energy_single_species}
\Upsilon_\sigma(\mu):=\frac{\sigma^2}{2}\int_{\bRb^d}\mu(x)\log(\mu(x))\ddx+\int_{\bRb^d}V(x)\mu(x)\ddx+\frac{1}{2}\iint_{\bRb^d\times\bRb^d}F(x-y)\mu(x)\mu(y)\ddx\ddy\,,
\end{equation}
where $V$ is the confining potential, $F$ is the interacting intra-species potential and $\sigma$ is the diffusion coefficient of the McKean SDE. As is well known, the free energy functional~\eqref{e:free_energy_single_species} provides us with a Lyapunov function for the McKean-Vlasov evolution PDE. We point out that the latter definition requires that $\mu$ is absolutely continuous with respect to the Lebesgue measure (and its density is denoted as $\mu$ also for simplicity). If this hypothesis is not respected, then $\Upsilon_\sigma(\mu):=+\infty$.

We will mimic the strategy in \cite{BCCP,AOP} to prove convergence of solutions to the multi-species mean field PDE system to a stationary state. For this, we need to show that the free energy is nonincreasing and that it is lower bounded. Moreover, we will show that the time derivative of the free energy (i.e. the entropy dissipation functional) evaluated at the solution of the mean-field PDE system $\mu_t$ vanishes if and only if $\mu_t = \mu$ is a stationary state.

%\medskip

For any $\mu=(\mu^1,\ldots,\mu^M)$ where $\mu^\ell$ is a measure in $\bRb^d$ admitting a density with respect to the Lebesgue measure (which we continue to denote as $\mu^\ell$) and for any $\sigma=(\sigma_1,\ldots,\sigma_M)\in\left(\bRb_+^*\right)^M$, we introduce the following quantity that will play the role of a free energy functional for the McKean-Vlasov PDE system \eqref{eq: multi-species PDE}.

\begin{align}
\label{eq: free energy}
\Upsilon_\sigma(\mu)=\Upsilon_\sigma(\mu^1,\ldots,\mu^M):=&\sum_{k=1}^M a_k\left\{\frac{\sigma_k^2}{2}\int_{\bRb^d}\mu^k(x)\log(\mu^k(x))\ddx+\int_{\bRb^d}V_k(x)\mu^k(x)\ddx\right\}\\
&+\frac{1}{2}\sum_{k=1}^M\sum_{\ell=1}^M a_ka_\ell\iint_{\bRb^d\times\bRb^d}F_{k\ell}(x,y)\mu^k(x)\mu^\ell(y)\ddx\ddy\,. \nonumber  
\end{align}
It is worth noting that the free-energy functional can be written in the form
\[
\Upsilon_\sigma(\mu)=\sum_{k=1}^Ma_k\F_k(\mu^k)\,,
\]
where, compare with~\eqref{e:free_energy_single_species},
\[
\F_k(\mu^k):=\frac{\sigma_k^2}{2}\int_{\bRb^d}\mu^k(x)\log(\mu^k(x))\ddx+\int_{\bRb^d}V_k(x)\mu^k(x)\ddx+\frac{1}{2}\iint_{\bRb^d\times\bRb^d}W_k^\mu(x,y)\mu^k(x)\ddx\,.
\]
Here, the potential $W_k^\mu$ contains all the interactions from the species:
\[
W_k^\mu(x):=\sum_{\ell=1}^Ma_\ell F_{k\ell}\ast\mu^\ell(x)\,.
\]
Thus, the total free-energy of the multi-species mean field system can be expressed as the weighted, with respect to the weights $a_1,\ldots,a_M$, average of the free-energy for each species.

We calculate the functional derivative of the free energy:
\[
\frac{\delta\Upsilon_\sigma}{\delta \mu^k}=a_k\Big[\frac{\sigma_k^2}{2}\left(\log\left(\mu^k\right)+1\right)+V_k+\sum_{\ell=1}^M a_\ell F_{k\ell}\ast \mu^\ell\Big]\,,
\]
which leads us to
\begin{equation*}
\nabla\frac{\delta\Upsilon_\sigma}{\delta \mu^k}= a_k\Bigg[\frac{\sigma_k^2}{2}\frac{\nabla\mu^k}{\mu^k}+\nabla V_k+\sum_{\ell=1}^M a_\ell\nabla F_{k\ell}\ast \mu^\ell\Bigg]\,.
\end{equation*}
In particular, we (formally) deduce that the coupled McKean-Vlasov PDE system~\eqref{eq: multi-species PDE} can be written as a Wasserstein gradient flow 
\[
\partial_t\mu^k=\div\Big[a_k^{-1}\mu^k\nabla\frac{\delta\Upsilon_\sigma}{\delta \mu^k}\Big]\,,
\]
for any $k=1,\ldots,M$.

We now compute the time derivative of the free-energy functional \eqref{eq: free energy} along the McKean-Vlasov PDE~\eqref{eq: multi-species PDE} flow:
\begin{align*}
\frac{\dd}{\ddt}\Upsilon_\sigma(\mu_t^1,\ldots, \mu_t^N)&=\sum_{k=1}^M \int_{\bRb^d}\partial_t\mu_t^k\frac{\delta\Upsilon_\sigma}{\delta \mu_t^k}\,\ddx\\
&=\sum_{k=1}^M\int_{\bRb^d}\left\{\div\Big[\Big(\nabla V_k+\sum_{\ell=1}^M a_\ell\nabla F_{k\ell}\ast\mu_t^\ell\Big)\mu_t^k\Big]+\frac{\sigma_k^2}{2}\Delta\mu_t^k\right\}\frac{\delta\Upsilon_\sigma}{\delta \mu_t^k}\,\ddx\,.
\end{align*}
We perform an integration by parts to obtain:
\begin{align*}
&\frac{\dd}{\ddt}\Upsilon_\sigma(\mu_t^1,\ldots, \mu_t^N)\\
&=-\sum_{k=1}^M\int_{\bRb^d}\Bigg[\Big(\nabla V_k+\sum_{\ell=1}^M a_\ell\nabla F_{k\ell}\ast\mu_t^\ell\Big)\mu_t^k+\frac{\sigma_k^2}{2}\nabla \mu_t^k\Bigg]\cdot\nabla\frac{\delta\Upsilon_\sigma}{\delta \mu_t^k}\,\ddx\\
&=-\sum_{k=1}^M\int_{\bRb^d}a_k\Bigg[\Big(\nabla V_k+\sum_{\ell=1}^M a_\ell\nabla F_{k\ell}\ast\mu_t^\ell\Big)\mu_t^k+\frac{\sigma_k^2}{2}\nabla \mu_t^k\Bigg]\cdot\Bigg[\frac{\sigma_k^2}{2}\frac{\nabla\mu_t^k}{\mu_t^k}+\nabla V_k+\sum_{\ell=1}^M a_\ell\nabla F_{k\ell}\ast \mu_t^\ell\Bigg]\,\ddx\\
&=-\sum_{k=1}^M\int_{\bRb^d}a_k\Big|\frac{\sigma_k^2}{2}\frac{\nabla\mu_t^k}{\mu_t^k}+\nabla V_k+\sum_{\ell=1}^M a_\ell \nabla F_{k\ell}\ast \mu_t^\ell\Big|^2\mu_t^k\,\ddx.
 \end{align*}
Thus, $\Upsilon_\sigma$ is always non-increasing, and 
\begin{equation*}
\frac{\dd}{\ddt}\Upsilon_\sigma(\mu^1,\ldots,\mu^N)=0
\end{equation*}
if and only if for any $1\leq k\leq M$, we have:
\[
\frac{\sigma_k^2}{2}\frac{\nabla\mu^k}{\mu^k}+\nabla V_k+\sum_{\ell=1}^M a_\ell \nabla F_{k\ell}\ast\mu^\ell=0.
\]
This immediately implies that $(\mu^1,\ldots,\mu^M)$ satisfies
\[
\nabla\frac{\delta\Upsilon_\sigma}{\delta\mu^k}=0, \quad 1\leq k\leq M.
\]
We conclude that the time-derivative of the free-energy is equal to $0$ if and only if $(\mu^1,\ldots,\mu^M)$ is a stationary state.

We now show that the free-energy functional is lower-bounded. We restrict ourselves to the symmetric quadratic case; in particular, Assumptions~\ref{asp: assumptionbis} and~\ref{asp: assumptionter} are satisfied. The idea is similar to the one in \cite{BCCP,AOP}. First, we introduce the following quantities:
\[
\beta:=\inf\left\{\alpha_{k\ell}\,\,:\,\,1\leq k,\ell\leq M\right\}\,,
\]
and
\[
\lambda_+:=\inf\left\{V_k(x)\,\,:\,\,x\in\bRb^d, 1\leq k\leq M\right\}\,.
\]
Then, we immediately deduce that the potential part of the free-energy functional may be lower-bounded in the following way:
\[
\sum_{k=1}^Ma_k\int_{\bRb^d}\left(V_k(x)+\frac{1}{2}\sum_{\ell=1}^Ma_\ell F_{k\ell}\ast\mu^\ell(x)\right)\mu^k(x)\ddx\geq\lambda_+\,,
\]
provided that $\beta>0$. If $\beta\leq0$, then we have:

\[\sum_{k=1}^Ma_k\int_{\bRb^d}\left(V_k(x)+\frac{1}{2}\sum_{\ell=1}^Ma_\ell F_{k\ell}\ast\mu^\ell(x)\right)\mu^k(x)\ddx\geq\sum_{k=1}^Ma_k\int_{\bRb^d}\left(V_k(x)+\frac{\beta}{2}|x|^2\right)\mu^k(x)\ddx\,.
\]
Indeed, since the potentials $F_{k\ell}$ are quadratic, only the first and second moments appear. And, if $\beta\leq0$, then the first-moment contribution is nonnegative.

It remains to deal with the entropy part. We have%To do so, we remind the reader that from Theorem~\ref{thm: well-posedness}, we have control of moments of order up to $8p^2$, and therefore of second moments; see \cite{DuongTugaut2020} for the proof. We deduce that there exists $C>0$ such that for any $1\leq k\leq M$ and for any $t\geq0$, we have
\begin{align*}
&\int_{\bRb^d}\mu_t^k(x)\log\left(\mu_t^k(x)\right)\ddx=\int_{\bRb^d}\mu_t^k(x)\log\left(\mu_t^k(x)\right)\mathds{1}_{\left\{\mu_t^k(x)\geq1\right\}}\ddx\\
&+\int_{\bRb^d}\mu_t^k(x)\log\left(\mu_t^k(x)\right)\mathds{1}_{\left\{\eee^{-|x|}\leq\mu_t^k(x)\leq1\right\}}\ddx+\int_{\bRb^d}\mu_t^k(x)\log\left(\mu_t^k(x)\right)\mathds{1}_{\left\{\mu_t^k(x)\leq\eee^{-|x|}\right\}}\ddx\\
&\geq-\int_{\bRb^d}|x|\mu_t^k(x)\mathds{1}_{\left\{\eee^{-|x|}\leq\mu_t^k(x)\leq1\right\}}\ddx+\int_{\bRb^d}\sqrt{\mu_t^k(x)}\left[\sqrt{\mu_t^k(x)}\log\left(\mu_t^k(x)\right)\right]\mathds{1}_{\left\{\mu_t^k(x)\leq \eee^{-|x|}\right\}}\ddx\\
&\geq-\frac{1}{2}\int_{\bRb^d}(1+|x|^2)\mu_t^k(x)\ddx-2{\rm e}^{-1}\int_{\bRb^d}\sqrt{\mu_t^k(x)}\mathds{1}_{\left\{\mu_t^k(x)\leq\eee^{-|x|}\right\}}\ddx\,.
\end{align*}
Note that to obtain the last inequality, we have used the fact that, for any $u\in(0;1)$, $\sqrt{u}\log(u)>-2\eee^{-1}$. This immediately implies that
\begin{align}
\mathcal{F}_k(\mu^k)&=\int_{\bRb^d}\left(V_k(x)+\frac{1}{2}\sum_{\ell=1}^Ma_\ell F_{k\ell}\ast\mu^\ell(x)\right)\mu^k(x)\ddx+\frac{\sigma_k^2}{2}\int_{\bRb^d}\mu_t^k(x)\log\left(\mu_t^k(x)\right)\ddx \notag\\
&\geq-2\eee^{-1}\int_{\bRb^d}\eee^{-\frac{|x|}{2}}\ddx-\frac{\sigma_k^2}{2}+\int_{\bRb^d}\left(V_k(x)+\frac{\beta-\sigma_k^2}{2}|x|^2\right)\mu^k(x)\ddx\,.
\label{lowerbound Fk}
\end{align}
We then introduce
\[
\lambda_-:=\inf\left\{V_k(x)+\frac{\beta-\sigma_k^2}{2}|x|^2\,\,:\,\,x\in\bRb^d, 1\leq k\leq M\right\}\,,
\]
which, by multiplying \eqref{lowerbound Fk} by $a_k$ and then adding over $k$ from $1$ to $M$, noting that $\sum_{k=1}^M a_k=1$, leads us to the estimate
\[
\Upsilon_\sigma(\mu^1,\cdots,\mu^M)\geq C+\lambda_-\,.
\]
This completes the proof that the free-energy functional is lower-bounded.
%\[
%\int_{\bRb^d}\mu_t^k(x)\log\left(\mu_t^k(x)\right)\ddx\geq-\frac{1+C}{2}-2\eee^{-1}\int_{\bRb^d}\eee^{-\frac{|x|}{2}}\ddx\geq-\rho\,,
%\]

%where $\rho>0$ is finite.


