\begin{equation} \label{e:linearized_struct}
\partial_t \mu_t^{L,i}=\div\Big[\Big(\nabla\bar{V}+\sum_{j=1}^Ma_j\alpha_j(x-m_j^{\infty})\Big) \mu_t^{L,i} - \sum_{j=1}^Ma_j\alpha_j m_j(t) \mu_{\infty}^i \Big]+\frac{\sigma^2}{2}\Delta \mu_t^{L,i},
