\section{Convergence}
\label{sec:converg}
In this section, we study convergence to a stationary state for the multi-species coupled mean field PDE system. Throughout the section, we assume that the initial conditions for the coupled PDEs are absolutely continuous with respect to the Lebesgue measure and with finite entropy, which implies that the free-energy is finite. We deduce that the probability measures $\mu_t^\ell$ are all absolutely continuous with respect to the Lebesgue measure, for any $t\geq0$. Consequently, the weak convergence of the measures $\mu_t^\ell$ is equivalent to convergence of the corresponding densities with respect to Lebesgue measure in a function space. Since the moments of $\mu_t^\ell$ are uniformly upper-bounded, see~\cite{DuongTugaut2020}, we immediately deduce that the families $\left\{\mu_t^\ell\,;\,t\geq0\right\}$ are tight for any $1\leq\ell\leq M$.

\begin{defn}
\label{sangoku}
By $\mathcal{A}_\sigma$ (resp. $\mathcal{S}_\sigma$), we denote the set of the limiting values of the family $\left\{\mu_t^\ell\,;\,t\geq0\right\}$ (resp. the set of the invariant probabilities of the mean field SDE~\eqref{eq: mean-field SDE}).
\end{defn}


\begin{defn}
\label{sangohan}
We say that a set $\mathcal{D}$ of measures in $\bRb^M$ is discrete if for any $\nu\in\mathcal{D}$, there exists a neighbourhood $\mathcal{V}$ of $\nu$ for the topology of weak convergence such that $\mathcal{D}\bigcap\mathcal{V}=\left\{\nu\right\}$. Similarly, we say that $\mathcal{D}$ is path-connected if it is path-connected for the topology of weak convergence.
\end{defn}


We now give the three main results of this section. The first one concerns the topology of the set $\mathcal{A}_\sigma$.

\begin{thm}
\label{chichi}
Let Assumptions~\ref{asp: assumption}, \ref{asp: assumptionbis} and \ref{asp: assumptionter} hold. Then, the set $\mathcal{A}_\sigma$ contains either a single element $\mu^\sigma\in\mathcal{S}_\sigma$ or a path-connected subset of $\mathcal{S}_\sigma$. Moreover, for all $\mu\in\mathcal{A}_\sigma$, we have $\displaystyle\Upsilon_\sigma(\mu)=L_\sigma:=\lim_{t\to+\infty}\Upsilon_\sigma(\mu_t)$.
\end{thm}



From this theorem, we deduce the following statements.

\begin{cor}
\label{piccolo}
Let assumptions of Theorem~\ref{chichi} hold and assume, in addition, that the set $\mathcal{S}_\sigma\bigcap\Upsilon_\sigma^{-1}\left(\left\{\lambda\right\}\right)$ is discrete for any $\lambda\in\bRb$. Then  the probability measure $\mu_t$ weakly converges to an invariant probability $\mu^\sigma\in\mathcal{S}_\sigma$, as $t$ goes to infinity.
\end{cor}

\begin{cor}
\label{piccolo2}
Let assumptions of Theorem~\ref{chichi} hold, together with the synchronization assumption~\ref{asp: assumption:synchronization}. 
%and by admitting that we are in the synchronized case, 
Then, the following limit holds for any $1\leq k\leq M$:
\begin{equation*}
\limsup_{\sigma\to0}\inf_{a\in\mathcal{G}_k}\limsup_{t\to+\infty}\int_{\bRb^d}\gaga x-a\drdr^2\mu_t^k(x)\ddx=0\,.
\end{equation*}
where $\mathcal{G}_k:=\left\{x\in\bRb^d\,\,\left|\right.\,\,\nabla V_k(x)=0\right\}$ denotes the set of critical points of $V_k$.

\end{cor}

\begin{defn}
\label{fightclub}
We define the function space $\mathcal{M}$ as the set of positive $L^1$ functions $f$ with bounded moments of order $8 p^2$, where $p$ is defined in Assumption~\ref{asp: assumption}:\\[2pt]
{\bf 1.} For all $x\in\bRb^M$, $f(x)>0$.\\
{\bf 2.} We have $\int_{\bRb^M} f = 1$. \\
{\bf 3.} There exists an $M_0 >0$ such that  $\displaystyle\max_{1\leq\ell\leq8p^2}\int_{\bRb^d}\left| x\right|^\ell f(x)\ddx\leq M_0$.
\end{defn}

Set 
\[
\xi(t):=\Upsilon_\sigma\left(\mu_t^1,\ldots,\mu_t^M\right)\, ,
\]
where $\Upsilon_\sigma$ denotes the free energy~\eqref{eq: free energy}.
Due to the lower-bound of the free-energy functional $\Upsilon_\sigma$ and the fact that $\xi$ is non-increasing (see Section \ref{subsec:free_energy}), we obtain the next lemma.
\begin{lem}
\label{lem:fr:conv}
Under Assumption~\ref{asp: assumption}, Assumption~\ref{asp: assumptionbis} and Assumption~\ref{asp: assumptionter}, there exists a constant $L_\sigma\in\bRb$ such that $\Upsilon_\sigma(\mu_t^1,\ldots,\mu_t^M)$ converges to $L_\sigma$ in the limit as $t \rightarrow +\infty$.
\end{lem}
The second main result of this section shows the convergence of the solutions of the mean-field PDE \eqref{eq: multi-species PDE} to a stationary state.
\begin{prop}
\label{thm:fr:subconv}
There exists a stationary state $\left(\mu_\infty^1,\ldots,\mu_\infty^M\right)$ and a sequence $\{ t_k \}_{k\in\mathbb{N}}$ that converges to infinity such that, for any $1\leq\ell\leq M$, $\mu_{t_k}^\ell$ converges weakly to $\mu_\infty^\ell$, in the limit as $t_k \rightarrow +\infty$.
\end{prop}

\begin{proof}

{\bf Plan:} we adapt the proof of \cite[Proposition 2.1]{JOTP}. We will use dots to denote differentiation with respect to time. First, we use the convergence of $\int_t^\infty \dot{\xi}(s) \, ds$ towards $0$ when $t$ tends to infinity  and we deduce the existence of a sequence $(t_k)_k$ such that $\dot{\xi} \left(t_k\right)$ tends to $0$ when $k$ goes to infinity. Then, the tightness of the sequences $\left\{\mu_{t_k}^\ell\,;\,k\in\mathbb{N}\right\}$ allows us to extract a subsequence of $\{ t_k \}_k$ - we will continue to write it $\{ t_k \}_k$ - such that for any $1\leq\ell\leq M$, $\mu_{t_k}^\ell$ weakly converges towards a limiting value of the family $\left\{\mu_{t}^\ell\,;\,t\in\mathbb{R}_+\right\}$. By using an appropriate test function and Weyl's lemma, we prove that this adherence value satisfies the system of equations~\eqref{eq: muk}. We deduce that $(\mu_\infty^1,\ldots,\mu_\infty^M)$ is a stationary state. Let us give now the details of the proof.


\noindent{}{\bf Step 1:} Lemma~\ref{lem:fr:conv} implies that the quantity $\zeta(t):=\int_t^\infty \dot{\xi}(s)ds$ converges to $0$ as $t \rightarrow +\infty$. 
%collapses at infinity
Since the free-energy functional is lower-bounded on $\mathcal{M}$, $\xi(t)$ is monotonous so we deduce the existence of an increasing sequence $\{ t_k\})_{k\in\mathbb{N}}$ with $t_k \rightarrow +\infty$ such that $\dot{\xi}(t_k) \longrightarrow 0$.


\noindent{}{\bf Step 2:} The uniform boundedness with respect to time of the second moment allows us to use Prohorov's theorem: we can extract a subsequence, still denoted by $\{t_k \}_{k}$, such that $\mu_{t_k}^\ell$ weakly converges to a probability measure $\mu_\infty^\ell$, for all $1\leq\ell\leq M$.

\noindent{}{\bf Step 3:} We now consider a test function $\varphi^\ell\in\mathcal{C}^\infty\left(\mathbb{R}^d,\mathbb{R}^d\right)\bigcap L^2\left(\mathbb{R}^d, \, \mu_\infty^\ell\right)$ with compact support and we estimate the following quantity:
\[
\left|\int_{\mathbb{R}^d}\left\langle\varphi^\ell(x)\, , \,\eta_{t_k}^\ell(x)\right\rangle\ddx\right|\,,
\]
where $\langle \cdot , \cdot \rangle$ denotes the Euclidean inner product and
\begin{equation}
\label{lanvin}
\eta_t^\ell(x):=\frac{\sigma_\ell^2}{2}\nabla\mu_t^\ell(x)+\left(\nabla V(x)+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast\mu_t^j(x)\right)\mu_t^\ell(x)\,.
\end{equation}
We calculate the time derivative of the free energy, as was done in Section~\ref{subsec:free_energy}, to derive the bound
\[
\dot{\xi}(t)\leq-\sum_{\ell=1}^M\int_{\bRb^d} a_\ell\frac{\left|\eta_t^\ell(x)\right|^2}{\mu_t^\ell(x)}\ddx\,.
\]
We use the Cauchy-Schwarz inequality to deduce that
\begin{align*}
\left|\int_{\mathbb{R}^d}\left\langle\varphi^\ell(x)\, , \,\eta_{t_k}^\ell(x)\right\rangle \ddx\right|&=\left|\int_{\mathbb{R}^d}\left\langle\varphi^\ell(x)\sqrt{\mu_{t_k}^\ell(x)}\, , \,\frac{\eta_{t_k}^\ell(x)}{\sqrt{\mu_{t_k}^\ell(x)}}\right\rangle\ddx\right|\\
&\leq\sqrt{\int_{\mathbb{R}^d}\left|\varphi^\ell(x)\right|^2\mu_{t_k}^\ell(x)\ddx}\times\sqrt{\int_{\mathbb{R}^d}\frac{1}{\mu_{t_k}^\ell(x)}\left|\eta_{t_k}^\ell(x)\right|^2\ddx}
\end{align*}
We combine the above two estimates to obtain:


\[
\left|\int_{\mathbb{R}^d}\left\langle\varphi^\ell(x)\,, \,\eta_{t_k}^\ell(x)\right\rangle \ddx\right|\leq\sqrt{-\frac{\dot{\xi}(t_k)}{a_\ell}}\sqrt{\int_{\mathbb{R}^d}\left|\varphi^\ell(x)\right|^2\mu_{t_k}^\ell(x)\ddx}\longrightarrow0
\]
as $k \rightarrow +\infty$. We use our assumption that $\varphi$ has compact support, together with an integration by parts, to deduce that


\begin{align*}
&\int_{\mathbb{R}^d}\left\langle\varphi^\ell(x)\, , \,\frac{\sigma_\ell^2}{2}\nabla\mu_{t_k}^\ell(x)+\mu_{t_k}^\ell(x)\left[\nabla V(x)+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast \mu_{t_k}^j(x)\right]\right\rangle\ddx\\
=&\int_{\mathbb{R}^d}\left\langle\varphi^\ell(x)\, , \,\nabla V(x)+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast \mu_{t_k}^j(x)\right\rangle \mu_{t_k}^\ell(x)\ddx-\int_{\mathbb{R}^d}\frac{\sigma_\ell^2}{2}{\rm div }\left(\varphi^\ell(x)\right)\mu_{t_k}^\ell(x)\ddx%\\
%=&\int_{\mathbb{R}}\left\langle\varphi^\ell(x)\,;\,\nabla V(x)+\sum_{j=1}^Ma_j\nabla F\ast\mu_{t_k}^j(x)\right\rangle \mu_{t_k}^\ell(\ddx)-\int_{\mathbb{R}}\frac{\sigma_\ell^2}{2}{\rm div }\left(\varphi^\ell(x)\right)\mu_{t_k}^\ell(\ddx)\,.
\end{align*}
The weak convergence of $\mu_{t_k}^j$ towards $\mu_\infty^j$ for all $1\leq j\leq M$ implies that this term converges towards 

\[
\int_{\mathbb{R}^d}\left\langle\varphi^\ell(x)\, , \,\nabla V(x)+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast \mu_\infty^j(x)\right\rangle \mu_\infty^\ell(\ddx)-\int_{\mathbb{R}^d}\frac{\sigma_\ell^2}{2}{\rm div }(\varphi^\ell(x)) \mu_\infty^\ell(\ddx)
\]

On the other hand, it was proved previously that $\int_{\mathbb{R}^d}\left\langle\varphi^\ell(x)\, , \,\eta_{t_k}^\ell(x)\right\rangle\ddx$ converges to $0$ as $k  \rightarrow  \infty$. We deduce that, for any test function $\varphi^\ell\in\mathcal{C}^\infty\left(\mathbb{R}^d,\mathbb{R}^d\right)\bigcap L^2\left(\mu_\infty^\ell\right)$ with compact support, we have : 
\begin{eqnarray}
\label{eq:fr:weaksol}
\int_{\mathbb{R}^d}\left\langle\varphi^\ell(x)\, , \,\nabla V(x)+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast \mu_\infty^j(x)\right\rangle \mu_\infty^\ell(\ddx)-\int_{\mathbb{R}^d}\frac{\sigma_\ell^2}{2}{\rm div }\left(\varphi^\ell(x)\right)\mu_\infty^\ell(\ddx)=0\,.
\end{eqnarray}

\noindent{}{\bf Step 4:} This means that $\mu_\infty^\ell$ is a weak solution of the equation
\begin{eqnarray*}
\frac{\sigma_\ell^2}{2}\nabla\rho+\left[\nabla V+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast \mu_\infty^j(x)\right]\rho=0\,,
\end{eqnarray*}

for any $1\leq\ell\leq M$. By applying Weyl's lemma, we deduce that the measure 
\begin{eqnarray*}
\exp\left[\frac{2}{\sigma_\ell^2}\left(V(x)+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast \mu_\infty^j(x)\right)\right]\mu_\infty^\ell(\ddx)
\end{eqnarray*}
admits a $\mathcal{C}^\infty$ density with respect to the Lebesgue measure, still denoted by $\mu_\infty^\ell$. Furthermore, its gradient is zero and so the measure $\mu_\infty^\ell$ satisfies Equation~\eqref{eq: muk}. Consequently, the collection of measures $\left(\mu_\infty^1,\ldots,\mu_\infty^M\right)$ is a stationary state, according to Theorem~\ref{jugnot}.

\end{proof}

From now and until the end of the section, we do not restrict ourself to the case where the interacting potentials are quadratic. However, we assume that $F_{i,j}(x)=G_{i,j}(|x|)$ where each $G_{i,j}$ is a polynomial even function of order less than $q\in\bNb^*$.

\begin{lem}
\label{johnkramer}
Let Assumptions~\ref{asp: assumption} hold. Then, for any stationary state $\left(\mu^1,\cdots,\mu^M\right)$ and for any $1\leq\ell\leq M$, the measure $\mu^\ell$ is uniquely determined by its moments. In particular, if a measure $\nu$ has the same moments as $\mu^\ell$, we deduce $\nu=\mu^\ell$.
\end{lem}
\begin{proof}
Let $(\mu^1,\cdots,\mu^M)$ be a stationary state and let $\ell$ be such that $1\leq\ell\leq M$. By Theorem~\ref{jugnot}, it is absolutely continuous with respect to Lebesgue measure and its density $\mu^\ell$ satisfies the equation
\begin{equation*}
\mu^\ell(x)=\frac{\exp\left[-\frac{2}{\sigma_\ell^2}\left(V(x)+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast \mu^j(x)\right)\right]}{\int_{\bRb^d}\exp\left[-\frac{2}{\sigma_\ell^2}\left(V(y)+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast \mu^j(y)\right)\right]\ddy}\,.
\end{equation*}
Consequently, for all $r>0$, we have
\begin{equation*}
\int_{\bRb^d}{\rm e}^{\frac{2}{\sigma_\ell^2}r|x|}\mu^\ell(x)\ddx=\frac{\int_{\bRb^d}\exp\left[-\frac{2}{\sigma_\ell^2}\left(V(x)+\sum_{j=1}^Ma_jF_{\ell j}\ast \mu^j(x)-r|x|\right)\right]\ddx}{\int_{\bRb^d}\exp\left[-\frac{2}{\sigma^2}\left(V(x)+\sum_{j=1}^Ma_jF_{\ell j}\ast \mu^j(x)\right)\right]\ddx}\,.
\end{equation*}
Since $F$ is convex and since $\nabla^2V(x)>0$ if $|x|$ is sufficiently large, we deduce that 

\[
\int_{\bRb^d}\eee^{\frac{2}{\sigma_\ell^2}r|x|}\mu^\ell(x)\ddx<+\infty\,.
\]


Consequently, the series $\sum_{k=0}^\infty\frac{\nu_k}{k!}r^k$, with $\nu_k:=\int_{\bRb}|x|^k\mu^\ell(x)\ddx$, has a positive convergence radius. After applying Fourier's criteria, the statement follows.
\end{proof}



\begin{defn}
\label{tototo}
For any $d$-index of integers $q$ with $q_1+\cdots+q_d\geq1$, by $\Lambda_q$, we denote the mapping from $\mathcal{M}^M$ to $\bRb^{dM}$ defined by
\begin{equation*}
\Lambda_q\left(\mu^1,\ldots,\mu^M\right):=\left(\int_\bRb|x|^q\mu^1(x)\ddx,\ldots,\int_\bRb|x|^q\mu^M(x)\ddx\right)\,.
\end{equation*}
\emph{Namely, the linear function $\Lambda_q$ corresponds to the vector of moments of order $q$.}
\end{defn}

In \cite[Proposition 2.5]{AOP}, it has been shown that the free energy of any limiting value of the stationary state is less than the limit of the free energy in the trajectories. We now prove that equality holds under some additional hypotheses. The following proposition is the third main result of this section.

\begin{prop}
\label{jigsaw}
Let the assumptions of Theorem ~\ref{chichi} hold. Let $\{ t_k\}_{k\in\mathbb{N}}$ be an increasing sequence such that $t_k \rightarrow +\infty$, $\dot{\xi}(t_k) \rightarrow 0$ and $\left(\mu_{t_k}^1,\ldots,\mu_{t_k}^M\right)$ converges to $\left(\mu_\infty^1,\ldots,\mu_\infty^M\right)\in\mathcal{A}_\sigma$ as $k \rightarrow +\infty$ . Then, we have :
\[
\Upsilon_\sigma(\mu_\infty^1,\ldots,\mu_\infty^M)=L_\sigma:=\lim_{t\to+\infty}\Upsilon_\sigma(\mu_t^1,\ldots,\mu_t^M)\,.
\]
\end{prop}

The proof is similar to the one of \cite[Proposition 1.8]{AOP}. 



\begin{proof}
From now on, by $\mu_{t_k}^\ell$ (resp. $\mu_\infty^\ell$), we denote the density with respect to the Lebesgue measure of the probability measure $\mu_{t_k}^\ell$ (resp. $\mu_\infty^\sigma$). The convergence from the term 


\[
\int_{\bRb^d}V(x)\mu_{t_k}^\ell(x)\ddx+\frac{1}{2}\sum_{j=1}^Ma_j\int_{\bRb^d}\left(F_{\ell j}\ast \mu_{t_k}^j(x)\right)\mu_{t_k}^\ell(x)\ddx
\]

towards 

\[
\int_{\bRb^d} V(x)\mu_\infty^\ell(x)\ddx+\frac{1}{2}\sum_{j=1}^Ma_j\int_{\bRb^d}\left(F_{\ell j}\ast \mu_\infty^j(x)\right)\mu_\infty^\ell(x)\ddx
\]

is implied by the convergence hypothesis of $\mu_{t_k}^j$ to $\mu_\infty^j$ for any $1\leq j\leq M$. Hence, we focus on the entropy term.


\noindent{}{\bf Step 1.} \emph{Here, we aim to prove the existence of a constant $C>0$ such that $\mu_{t_k}^\ell(x)\leq C$ for all $k\in\mathbb{N}^*$, for all $x\in\bRb^d$ and for any $1\leq\ell\leq M$.}

To show this, we bound the integral of $\left|\nabla \mu_{t_k}^\ell\right|$ on $\mathbb{R}^d$. Using the triangle inequality we obtain
\begin{align*}
\int_{\bRb^d}\left|\nabla \mu_{t_k}^\ell(x)\right|\ddx\leq&\frac{2}{\sigma_\ell^2}\int_{\bRb^d}\left|\eta_{t_k}^\ell(x)\right|\mu_{t_k}^\ell(x)\ddx\\
&+\frac{2}{\sigma_\ell^2}\int_{\bRb^d}\left|\nabla V(x)+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast \mu_{t_k}^j(x)\right|\mu_{t_k}^\ell(x)\ddx\,,
\end{align*}
where $t\mapsto\eta_t$ has been introduced in~\eqref{lanvin}. The growth property on $\nabla V$ and the particular form of the interaction potentials yield
\begin{align*}
\int_{\bRb^d}\left|\nabla V(x)+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast \mu_{t_k}^j(x)\right| \mu_{t_k}^\ell(x)\ddx\leq C_1(\ell)\int_{\bRb^d}\left(1+|x|^{2p}\right)\mu_{t_k}^\ell(x)\ddx\leq C_2(\ell)\,,
\end{align*}
where $C_2(\ell)>0$ is a constant. By using Cauchy-Schwarz's inequality and the entropy dissipation, we obtain
\begin{equation*}
\int_{\bRb^d}\left|\eta_{t_k}^\ell(x)\right|\mu_{t_k}^\ell(x)\ddx\leq\sqrt{\int_{\bRb^d}\left|\eta_{t_k}^\ell(x)\right|^2\mu_{t_k}^\ell(x)\ddx}\leq\sqrt{-\frac{1}{a_\ell} \dot{\xi}(t_k)}\,.
\end{equation*}
The quantity $\sqrt{-\dot{\xi}(t_k)}$ tends to $0$ as $k \rightarrow +\infty$; therefore, it is bounded. We conclude that there  exists  a positive constant $C_3$ independent from $k\in\mathbb{N}^*$ and from $1\leq\ell\leq M$ such that
\begin{equation*}
\int_{\bRb^d}\left|\nabla \mu_{t_k}^\ell(x)\right|\ddx\leq C_3\,.
\end{equation*}
Consequently, $\mu_{t_k}^\ell(x)\leq \mu_{t_k}^\ell(0)+C$ for all $x\in\mathbb{R}$, for all $k\in\mathbb{N}^*$ and for any $1\leq\ell\leq M$. However, the sequences $\left\{\mu_{t_k}^\ell(0)\right\}_{k\in\mathbb{N}}$ converge so that they are bounded. Hence, there exists a constant $C_4$ such that $\mu_{t_k}^\ell(x)\leq C_4$ for all $k\in\mathbb{N}$, for any $1\leq\ell\leq M$ and $x\in\mathbb{R}^d$.

\noindent{}{\bf Step 2.} The application $x\mapsto \mu_{t_k}^\ell(x)\log\left(\mu_{t_k}^\ell(x)\right)$ is uniformly lower-bounded with respect to $k$ and $\ell$. Then, we can apply Lebesgue's dominated convergence theorem which can be used to show the convergence as, $k \rightarrow +\infty$  of the integral term
\begin{equation*}
\int_{\bRb^d}\mu_{t_k}^\ell(x)\log\left(\mu_{t_k}^\ell(x)\right)\mathds{1}_{\{|x|\leq R\}}\ddx
\end{equation*}

to $\int_{\bRb^d}\mu_\infty^\ell(x)\log\left(\mu_\infty^\ell(x)\right)\mathds{1}_{\{|x|\leq R\}}\ddx$ for any $R\geq0$.


\noindent{}{\bf Step 3.} The remainder of the entropy integral, i.e. for $|x| > R$,  is split into three terms.

\noindent{}{\bf Step 3.1.} The first term is
\begin{equation*}
I_1(k):=\int_{\bRb^d}\mu_{t_k}(x)\log\left(\mu_{t_k}(x)\right)\mathds{1}_{\{|x|>R\,\,;\,\,\mu_{t_k}^\ell(x)\geq1\}}\ddx\,.
\end{equation*}
Due to the upper-bound from Step 1, the uniform boundedness of the moments and Markov's inequality, we obtain
\begin{align*}
I_1(k)\leq\log(C_4)\mu_{t_k}^\ell\left(\mathbb{B}\left(0\,;\,R\right)^c\right)\leq\frac{\log(C_4)\,M_0}{R^2}\,.
\end{align*}
{\bf Step 3.2.} The second term is defined as
\begin{equation*}
I_2(k):=\int_{\bRb^d}\mu_{t_k}^\ell(x)\log\left(\mu_{t_k}^\ell(x)\right)\mathds{1}_{\{|x|>R\,\,;\,\,\mu_{t_k}^\ell(x)<1\,\,;\,\,\mu_{t_k}^\ell(x)\geq \eee^{-|x|}\}}\ddx<0\,.
\end{equation*}
We bound it in the following way:
\begin{align*}
\left|I_2(k)\right|=-I_2(k)\leq\int_{\mathbb{B}\left(0\,;\,R\right)^c}|x|\mu_{t_k}^\ell(x)\ddx\leq\frac{M_0}{R^2}\,.
\end{align*}


\noindent{}{\bf Step 3.3.} We now consider the third term,
\begin{equation*}
I_3(k):=\int_{\bRb^d}\mu_{t_k}^\ell(x)\log\left(\mu_{t_k}^\ell(x)\right)\mathds{1}_{\{|x|>R\,\,;\,\,\mu_{t_k}^\ell(x)<1\,\,;\,\,\mu_{t_k}^\ell(x)<\eee^{-|x|}\}}\ddx<0\,.
\end{equation*}
We introduce the function $\gamma(x):=\sqrt{x}\log(x)\mathds{1}_{\{x<1\}}$. We have $-C'\leq\gamma(x)\leq0$ for all $x\in\bRb$, where $C'$ is a positive constant. This provides
\begin{align*}
\left|I_3(k)\right|=-I_3(k)\leq-\int_{\mathbb{B}\left(0\,;\,R\right)^c}\gamma\left(\mu_{t_k}(x)\right)\eee^{-\frac{1}{2}|x|}\ddx\leq\Theta(R)\,,
\end{align*}
$\Theta$ being a decreasing function from $\bRb_+$ to itself such that $\displaystyle\lim_{R\to+\infty}\Theta(R)=0$.


\noindent{}{\bf Step 4.} Let $\epsilon$ be a positive real, arbitrarily small. By taking $R$ sufficiently large, we have the upper-bound
\begin{equation*}
\sup_{1\leq\ell\leq M}\sup_{k\in\mathbb{N}^*}\max\left\{I_1(k)\,;\,I_2(k)\,;\,I_3(k)\right\}<\frac{\epsilon}{9}\,.
\end{equation*}
Moreover, for $R$ large enough, we have the inequality
\begin{equation*}
\int_{\bRb^d}\mu_\infty^\ell(x)\log\left(\mu_\infty^\ell(x)\right)\mathds{1}_{\{|x|\geq R\}}\ddx<\frac{\epsilon}{3}\,.
\end{equation*}
The two previous inequalities do not depend on $k$. Then, by taking $k$ sufficiently large, the following upper-bound holds:
\begin{equation*}
\left|\int_{\bRb^d}\mu_{t_k}^\ell(x)\log\left(\mu_{t_k}^\ell(x)\right)\mathds{1}_{\{|x|\leq R\}}\ddx-\int_{\bRb^d}\mu_\infty^\ell(x)\log\left(\mu_\infty^\ell(x)\right)\mathds{1}_{\{|x|\leq R\}}\ddx\right|<\frac{\epsilon}{3}\,.
\end{equation*}
This implies the inequality $\left|\Upsilon_\sigma\left(\mu_{t_k}^1,\ldots,\mu_{t_k}^M\right)-\Upsilon_\sigma(\mu_\infty^1,\ldots,\mu_\infty^M)\right|<\epsilon$. Namely, the free-energy $\Upsilon_\sigma\left(\mu_{t_k}^1,\ldots,\mu_{t_k}^M\right)$ converges to $\Upsilon_\sigma(\mu_\infty^1,\ldots,\mu_\infty^M)$. Due to the monotonicity of the free-energy along the trajectories, $\Upsilon_\sigma\left(\mu_t^1,\ldots,\mu_t^M\right)$ converges to $L_\sigma$ which implies $\Upsilon_\sigma(\mu_\infty^1,\ldots,\mu_\infty^M)=L_\sigma$.
\end{proof}



\begin{prop}
\label{edeka}
Let Assumption~\ref{asp: assumption} %, \ref{asp: assumptionbis} and \ref{asp: assumptionter}
 hold and assume further that the interaction potentials are polynomial functions. Let $(\nu^1,\ldots,\nu^M)$ be $M$ measures with densities $(\nu^1,\ldots,\nu^M)\in\mathcal{M}^M$. We also assume $(\nu^1,\ldots,\nu^M)\notin\mathcal{S}_\sigma$. Thus, there exist $q\in\mathbb{N}^*$ and $\rho>0$ such that
\begin{equation*}
\inf_{(\mu^1,\ldots,\mu^M)\in\mathcal{S}_\sigma}\max_{1\leq\ell\leq M}\left|\int_{\bRb^d}x^q\mu^\ell(x)\ddx-\int_{\bRb^d}x^q\nu^\ell(x)\ddx\right|\geq\rho\,.
\end{equation*}
\end{prop}




\begin{proof}
By arguing as in \cite{AOP}, we can easily show that all the moments of $\mu_t^\ell$ are bounded for any $1\leq\ell\leq M$ and for any $t\geq1$. Moreover, for any $N_0\in\mathbb{N}^*$, we have
\[
\sup_{t\geq1}\int_{\bRb^d}\left|x\right|^{2N_0}\mu_t^\ell(x)\ddx<+\infty\,.
\]
Let us proceed a \emph{reductio ad absurdum} by assuming that there exists $n\in\mathbb{N}^*$ such that for all $k\geq n$, there exists $\mu_k^\ell\in\mathcal{S}_\sigma$ satisfying
\begin{equation*}
\left|\int_{\bRb^d}x^q\mu_k^\ell(x)\ddx-\int_{\bRb^d}x^q\nu^\ell(x)\ddx\right|\leq\frac{1}{k}\,.
\end{equation*}
We deduce that the sequence $\left(\int_{\bRb^d}x^q\mu_k^\ell(x)\ddx\right)_{k\in\mathbb{N}^*}$ is bounded. Consequently, we can extract a subsequence $\left\{\phi(k)\right\}_{k\in\mathbb{N}^*}$ such that the sequence $\left\{\int_{\bRb^d}x^q\mu_{\phi(k)}^\ell(x)\ddx\right\}_{k\geq n}$ converges to $m_\infty^\ell\in\bRb$. Since the family $\left\{\mu_t^\ell\,;\,t\geq0\right\}$ is tight, Prokhorov's theorem allows us to assume, without any loss of generality, that the measure $\mu_{\phi(k)}^\ell$ converges weakly to a measure $\mu_\infty^\ell$ as $k \rightarrow +\infty$  (along a subsequence of $\mu_{\phi(k)}^\ell$).

Furthermore, $\Lambda_q\left(\mathcal{S}_\sigma\right)$ (see Definition~\ref{tototo} for the introduction of the function $\Lambda_q$) satisfies an algebraic equation in $\bRb^M$ and so it is closed. Consequently, $\left(\mu_\infty^1,\ldots,\mu_\infty^M\right)$ is a stationary state.

In addition, we have that
\begin{equation*}
\left|\int_{\bRb^d}x^q\mu_\infty^\ell(x)\ddx-\int_{\bRb^d}x^q\nu^\ell(x)\ddx\right|=0
\end{equation*}
for any $1\leq\ell\leq M$ and $p\geq 1$. In other words, the stationary state $(\mu_\infty^1,\ldots,\mu_\infty^M)$ has the same moments as $\nu$. Since the stationary state is uniquely determined by its moments, we deduce that $\nu^\ell=\mu_\infty^\ell$ so $(\nu^1,\ldots,\nu^M)$ is a stationary state. We have arrived at a contradiction.
\end{proof}

\subsection{Proof of Theorem~\ref{chichi}}
In this subsection, we present the proof of the main theorem, Theorem \ref{chichi}, of the section.

\subsubsection{Outline of the proof}
First, we provide the main ideas of the proof. The details will be presented in the following subsections. By Proposition \ref{thm:fr:subconv}, we know that there exists a stationary state $\left(\mu_\infty^1,\ldots,\mu_\infty^M\right)$ such that
\begin{itemize}
 \item the $M$-uple of measures $\left(\mu_\infty^1,\ldots,\mu_\infty^M\right)$ is in $\mathcal{A}_\sigma$.
 \item it is a stationary state.
 \item The free energy of $\left(\mu_\infty^1,\ldots,\mu_\infty^M\right)$ is equal to $L_\sigma:=\lim_{t\to0}\Upsilon_\sigma(\mu_t^1,\ldots,\mu_t^M)$.
\end{itemize}
If $\mathcal{A}_\sigma=\left\{\left(\mu_\infty^1,\ldots,\mu_\infty^M\right)\right\}$, the proof is achieved. From now on, we assume that $\#\mathcal{A}_\sigma>1$. The proof now consists in establishing that
\begin{enumerate}
 \item The set $\mathcal{A}_\sigma$ is included in $\mathcal{S}_\sigma$.
 \item The set $\mathcal{A}_\sigma$ is connected to the path.
 \item The free energy is constant on $\mathcal{A}_\sigma$.
\end{enumerate}


\noindent{}{\bf Step 1.} \emph{We proceed a \emph{reductio ad absurdum} in order to prove the first statement. The details are given in Subsection~\ref{tomhanks}}


We assume the existence of $(\nu^1,\ldots,\nu^M)\in\mathcal{A}_\sigma$ such that $(\nu^1,\ldots,\nu^M)\notin\mathcal{S}_\sigma$. According to Proposition \ref{edeka}, there exists a closed set with nonempty interior $\mathcal{H}$ that contains $(\nu^1,\ldots,\nu^M)$ and which has an empty intersection with $\mathcal{S}_\sigma$.

Since $(\nu^1,\ldots,\nu^M)$ is an adherence value, we can prove that for some $1\leq\ell\leq M$, there exists a smooth function with compact support $\varphi^\ell$, a constant $\rho>0$ and two increasing sequences $\left(r_k\right)_{k\in\mathbb{N}}$ and $\left(s_k\right)_{k\in\mathbb{N}}$ such that $r_k<s_k$ and for all $t\in[r_k;s_k]$, we have
\begin{equation*}
\int_\bRb\varphi^\ell(x)\nu^\ell(\ddx)=0<\rho=\int_{\bRb}\varphi^\ell(x)\mu_{r_k}^\ell(\ddx)\leq\int_{\bRb}\varphi^\ell(x)\mu_t^\ell(\ddx)\leq\int_{\bRb}\varphi^\ell(x)\mu_{s_k}^\ell(\ddx)=2\rho\,.
\end{equation*}
Moreover, for all $t\in[r_k;s_k]$, $\mu_t^\ell\in\mathcal{H}$. Applying Proposition \ref{prop:a:othermeasure}, we can construct a stationary state $(\widetilde{\nu}^1,\ldots,\widetilde{\nu}^M)\in\mathcal{S}_\sigma\bigcap\mathcal{H}$. This is a contradiction.


\noindent{}{\bf Step 2.} \emph{The details of the proof of the second statement are in Subsection~\ref{tomhanks2}.}


We use the previous result: all the limiting values are stationary states. Since the interacting potentials are quadratic, the function $\Lambda_1$ (defined as in Definition~\ref{tototo} with $q_i=1$ for any $1\leq i\leq d$) is a bijection from $\mathcal{S}_\sigma$ to $\Lambda_1\left(\mathcal{S}_\sigma\right)\subset\bRb^M$, hence we deduce that $\Lambda_1$ is a bijection from $\mathcal{A}_\sigma$ to $\mathcal{C}_\sigma:=\Lambda_1\left(\mathcal{A}_\sigma\right)\subset\bRb^M$.\\
Due to the continuity of the functions $t\mapsto\int_{\bRb^d}x\mu_t^\ell(x)\ddx$, we deduce that $\mathcal{C}_\sigma$ is path-connected. This implies that $\mathcal{A}_\sigma$ is also path-connected.


\noindent{}{\bf Step 3.} \emph{The proof of the third point is presented in Subsection~\ref{tomhanks3}.}


We proceed a \emph{reductio ad absurdum} by assuming the existence of $(\nu^1,\ldots,\nu^M)\in\mathcal{A}_\sigma\subset\mathcal{S}_\sigma$ such that $\Upsilon_\sigma\left(\nu^1,\ldots,\nu^M\right)\neq L_\sigma$. We recall that $\Lambda_1$ is a bijection of $\mathcal{A}_\sigma$ to $\mathcal{C}_\sigma\subset\bRb^M$. Due to the continuity of $\Lambda_1$ and $\Upsilon_\sigma$, there exists a closed set $\mathcal{D}_\sigma\subset\bRb^M$ that contains the point $\Lambda_1\left(\nu^1,\ldots,\nu^M\right)$ in its interior and such that $\Upsilon_\sigma(\mu^1,\ldots,\mu^M)\neq L_\sigma$ for all states $(\mu^1,\ldots,\mu^M)$ satisfying $\Lambda_1\left(\mu^1,\ldots,\mu^M\right)\in\mathcal{D}_\sigma$.

We now use similar arguments to the ones in the first step. For some $1\leq\ell\leq M$, there exists a smooth function with compact support $\varphi^\ell$, a constant $\rho>0$ and two increasing sequences $\left(r_k\right)_{k\in\mathbb{N}}$ and $\left(s_k\right)_{k\in\mathbb{N}}$ such that $r_k<s_k$ and for all $t\in[r_k;s_k]$, we have
\begin{equation*}
\rho=\int_{\bRb}\varphi^\ell(x)\mu_{r_k}^\ell(\ddx)\leq\int_{\bRb}\varphi^\ell(x)\mu_t^\ell(\ddx)\leq\int_{\bRb}\varphi^\ell(x)\mu_{s_k}^\ell(\ddx)=2\rho\,.
\end{equation*}
Moreover, for all $t\in[r_k;s_k]$, $\Lambda_1\left(\mu_t^\ell\right)\in\mathcal{D}_\sigma$. By applying Proposition \ref{prop:a:othermeasure}, we construct a stationary state $(\widetilde{\nu}^1,\ldots,\widetilde{\nu}^M)\in\mathcal{S}_\sigma$ with free energy equal to $L_\sigma:=\lim_{t\to+\infty}\Upsilon_\sigma(\mu_t^1,\ldots,\mu_t^M)$ and such that $\Lambda_1\left(\widetilde{\nu}^1,\ldots,\widetilde{\nu}^M\right)\in\mathcal{D}_\sigma$. By construction of the set $\mathcal{D}_\sigma$, we have arrived at a contradiction.


\mathversion{bold}
\subsubsection{The set \texorpdfstring{$\mathcal{A}_\sigma$}{Asigma} is included into \texorpdfstring{$\mathcal{S}_\sigma$}{Ssigma}}
\label{tomhanks}
\mathversion{normal}
We proceed a \emph{reductio ad absurdum} by assuming the existence of $(\nu^1,\ldots,\nu^M)\in\mathcal{A}_\sigma$ such that $(\nu^1,\ldots,\nu^M)$ is not a stationary state. According to Proposition \ref{edeka}, there exist $1\leq\ell\leq M$, $q\in\left(\mathbb{N}^*\right)^d$ and $\rho>0$ such that 
\begin{equation*}
\inf_{(\mu^1,\ldots,\mu^M)\in\mathcal{S}_\sigma}\left|\int_{\bRb^d} x^q\mu^\ell(x)\ddx-\int_{\bRb^d} x^q\nu^\ell(x)\ddx\right|\geq\rho\,.
\end{equation*}
Let $H^q_\kappa\subset\bRb^M$ be defined as
\begin{equation*}
H^q_\kappa:=\bRb^{\ell-1}\times\left[\int_\bRb x^q\nu^\ell(x)\ddx-\kappa;\int_\bRb x^q\nu^\ell(x)\ddx+\kappa\right]\times\bRb^{M-\ell}\,.
\end{equation*}
It is a closed bounded set with nonempty interior. Let us define $\mathcal{H}_\kappa^q:=\Lambda_q^{-1}\left(\left\{H^q_\kappa\right\}\right)$. By construction, $(\nu^1,\ldots,\nu^M)\in\mathcal{H}_{\frac{\rho}{4}}^q$ and $\mathcal{H}_{\frac{\rho}{2}}^q\bigcap\mathcal{S}_\sigma=\emptyset$. In particular, $\mu_\infty^\ell\notin\mathcal{H}_{\frac{\rho}{2}}^q$ where $\mu_\infty^\ell$ has been introduced in Proposition~\ref{jigsaw}.

Nonetheless, $(\mu_\infty^1,\ldots,\mu_\infty^M)$ and $(\nu^1,\ldots,\nu^M)$ are adherence values of the family of $M$-uple measures $\left\{(\mu_t^1,\ldots,\mu_t^M)\,;\,t\geq0\right\}$. Consequently, for any $\ell$ such that $1\leq \ell\leq M$, there exist two increasing sequences $(r_k)_{k\in\mathbb{N}}$ and $(s_k)_{k\in\mathbb{N}}$ such that for all $k\in\mathbb{N}$, $\mu_{r_k}^\ell\in\partial\mathcal{H}_{\frac{\rho}{4}}^p$, $\mu_{s_k}^\ell\in\partial\mathcal{H}_{\frac{\rho}{2}}^p$ and for all $r_k<t<s_k$, we have
\begin{equation*}
\frac{\rho}{4}<\left|\int_{\bRb^d}x^q\mu_t^\ell(x)\ddx-\int_{\bRb^d} x^q\nu^\ell(x)\ddx\right|<\frac{\rho}{2}\,.
\end{equation*}
By construction of the sequences $(r_k)_{k\in\mathbb{N}}$ and $(s_k)_{k\in\mathbb{N}}$, $\int_{\bRb^d}x^q\mu_{r_k}^\ell(x)\ddx=\int_{\bRb^d} x^q\nu(x)\ddx+\frac{\rho}{4}\theta_k^{1}$ and $\int_{\bRb^d} x^q\mu_{s_k}^\ell(x)\ddx=\int_{\bRb^d}x^q\nu(x)\ddx+\frac{\rho}{2}\theta_k^{2}$ where $\theta_k^1:=\pm1$ and $\theta_k^2\in[-1;1]$.


We can extract two subsequences (we continue to write $r_k$ and $s_k$ for the comfort of the reading) such that there exists $\theta\in\{-1\,;\,1\}$, independent from the index $k$, which satisfies
\begin{align*}
\theta\int_{\bRb^d}x^q\mu_{r_k}^\ell(x)\ddx=\theta\int_{\bRb^d} x^q\nu^\ell(x)\ddx+\frac{\rho}{4}\,,\quad\theta\int_{\bRb^d} x^q\mu_{s_k}^\ell(x)\ddx=\theta\int_{\bRb^d}x^q\nu^\ell(x)\ddx+\frac{\rho}{2}
\end{align*}
and for all $t\in[r_k;s_k]$, we have
\begin{align*}
\theta\int_{\bRb^d}x^q\nu^\ell(x)\ddx+\frac{\rho}{4}\leq\theta\int_{\bRb^d} x^q\mu_t^\ell(x)\ddx\leq\theta\int_{\bRb^d}x^q\nu^\ell(x)\ddx+\frac{\rho}{2}\,.
\end{align*}
Moreover, for all $t\in[r_k;s_k]$, $(\mu_t^1,\ldots,\mu_t^M)\in\mathcal{H}_{\frac{\rho}{2}}^q$. Without loss of generality, we assume that $\theta=1$.\\[2pt]
We apply Proposition \ref{prop:a:othermeasure} with a smooth function with compact support which is equal to $x^q$ if $|x|\leq R$ and equal to $0$ if $|x|\geq R+1$.\\
Taking $R$ sufficiently large, we deduce the existence of $\left(\widetilde{\nu}^1,\ldots,\widetilde{\nu}^M\right)\in\mathcal{H}_{\frac{\rho}{2}}^q\bigcap\mathcal{A}_\sigma\bigcap\mathcal{S}_\sigma$. However, $\mathcal{S}_\sigma\bigcap\mathcal{H}_{\frac{\rho}{2}}^q=\emptyset$. We have arrived at a contradiction.

\mathversion{bold}
\subsubsection{The set \texorpdfstring{$\mathcal{A}_\sigma$}{Asigma} is path-connected}
\mathversion{normal}
\label{tomhanks2}
According to the previous paragraph, the set $\mathcal{A}_\sigma$ is included in $\mathcal{S}_\sigma$, the set of stationary states. We now consider the application $\Lambda_q$ from the set of the probability measures to $\bRb^M$ as defined in Definition~\ref{tototo}.

By $\mathcal{C}_\sigma$, we denote the set $\Lambda_1\left(\mathcal{A}_\sigma\right)$. Due to the continuity of the application $t\mapsto\Lambda_1(\mu_t)$, we deduce that the set of limiting values of the family $\left\{\Lambda_1\left(\mu_t\right)\,;\,t\geq0\right\}$ is path-connected. In other words, the set $\mathcal{C}_\sigma$ is path-connected.

Consequently, for all $M$-uple of probability measures $(\mu_0^1,\ldots,\mu_0^M)$ and $(\mu_1^1,\ldots,\mu_1^M)$ in $\mathcal{A}_\sigma$, there exists an application from $[0;1]$ to the set of the $M$-uple of probability measures, $\theta\mapsto(\mu_\theta^1,\ldots,\mu_\theta^M)$ such that for all $1\leq\ell\leq M$, the functions $\theta\mapsto\int_{\bRb^d} x\mu_\theta^\ell(x)\ddx$ are continuous.

We deduce that for all $x\in\bRb$, for all $1\leq\ell\leq M$, the function $\theta\mapsto V_\ell(x)+\sum_{j=1}^Ma_jF_{\ell j}\ast\mu_\theta^j(x)$ is continuous. We know that for all $\theta\in[0;1]$, the measure $\mu_\theta^\ell$ is absolutely continuous with respect to the Lebesgue measure with a density $\mu_\theta^\ell$ that satisfies
\begin{equation*}
\mu_\theta^\ell(x)=\frac{\exp\left[-\frac{2}{\sigma_\ell^2}\left(V_\ell(x)+\sum_{j=1}^Ma_jF_{\ell j}\ast \mu_\theta^j(x)\right)\right]}{\int_{\bRb^d}\exp\left[-\frac{2}{\sigma_\ell^2}\left(V_\ell(y)+\sum_{j=1}^Ma_jF_{\ell j}\ast \mu_\theta^j(y)\right)\right]\ddy}\,.
\end{equation*}
Hence, for any smooth function with compact support $\varphi^\ell$, the application $\theta\mapsto\int_{\bRb^d}\phi^\ell(x)\mu_\theta^\ell(x)\ddx$ is continuous. Therefore, the set $\mathcal{A}_\sigma$ is path-connected.


\mathversion{bold}
\subsubsection{The free energy is constant on \texorpdfstring{$\mathcal{A}_\sigma$}{Asigma}}
\mathversion{normal}
\label{tomhanks3}
We introduce $L_\sigma:=\lim_{t\to+\infty}\Upsilon_\sigma(\mu_t^1,\ldots,\mu_t^M)$. We know that for any $(\mu^1,\ldots,\mu^M)\in\mathcal{A}_\sigma$, we have the estimate $\Upsilon_\sigma(\mu^1,\ldots,\mu^M)\leq L_\sigma$. In particular, the free energy of a limiting value is less than $L_\sigma$, the limit of the free energy.

We will argue again by contradiction; we assume that there exist $(\nu^1,\ldots,\nu^M)\in\mathcal{A}_\sigma$ and $\eta>0$ satisfying $\Upsilon_\sigma\left(\nu^1,\ldots,\nu^M\right)=L_\sigma-2\eta$. We use arguments similar to those of the previous subsections.


Due to the continuity of $\Lambda_q$, we deduce that there exists $\rho>0$ sufficiently small such that $\Upsilon_\sigma(\mu^1,\ldots,\mu^M)\leq L_\sigma-\eta$ for all $(\mu^1,\ldots,\mu^M)\in\mathcal{S}_\sigma\bigcap\mathcal{H}_\rho^q$ where $\mathcal{H}_\rho^q$ is defined like in Subsection~\ref{tomhanks}, as the set of the stationary states $(\mu^1,\ldots,\mu^M)$ such that
\[
\left|\int_{\bRb^d} x^q\mu^\ell(x)\ddx-\int_{\bRb^d}x^q\nu^\ell(x)\ddx\right|\leq\rho\,,
\]
for all $1\leq\ell\leq M$.

Nevertheless, the stationary state $(\mu_\infty^1,\ldots\mu_\infty^M)\in\mathcal{A}_\sigma$ introduced in Proposition~\ref{jigsaw} satisfies the equality $\Upsilon_\sigma\left(\mu_\infty^1,\ldots\mu_\infty^M\right)=L_\sigma$. Hence, $(\mu_\infty^1,\ldots\mu_\infty^M)\notin\mathcal{H}_\rho$.


We now proceed exactly as in Subsection~\ref{tomhanks}. We obtain the existence of two increasing sequences $(r_k)_{k\in\mathbb{N}}$ and $(s_k)_{k\in\mathbb{N}}$, of $1\leq\ell_0\leq M$ and $\theta\in\{-1\,;\,1\}$, all independent of the index $k$, which satisfy
\begin{align*}
\theta\int_{\bRb^d} x^q\mu_{r_k}^{\ell_0}(x)\ddx=\theta\int_{\bRb^d} x^q\nu^{\ell_0}(x)\ddx+\frac{\rho}{4}\,,\quad\theta\int_{\bRb^d} x^q\mu_{s_k}^{\ell_0}(x)\ddx=\theta\int_{\bRb^d} x^q\nu^{\ell_0}(x)\ddx+\frac{\rho}{2}
\end{align*}
and for all $t\in[r_k;s_k]$, we have
\begin{align*}
\theta\int_{\bRb^d} x^q\nu^{\ell_0}(x)\ddx+\frac{\rho}{4}\leq\theta\int_{\bRb^d} x^q\mu_t^{\ell_0}(x)\ddx\leq\theta\int_{\bRb^d} x^q\nu^{\ell_0}(x)\ddx+\frac{\rho}{2}\,.
\end{align*}
Moreover, for all $t\in[r_k;s_k]$, $(\mu_t^1,\ldots,\mu_t^M)\in\mathcal{H}_\rho^q$. Without any loss of generality, we assume that $\theta=1$. We apply Proposition \ref{prop:a:othermeasure} with a smooth function with compact support equal to $x^p$ if $|x|\leq R$ and equal to $0$ if $|x|\geq R+1$. By taking $R$ sufficiently large, we deduce the existence of a $M$-uple of measures $\left(\widetilde{\nu}^1,\ldots\widetilde{\nu}^M\right)\in\mathcal{H}_{\frac{\rho}{2}}^q\bigcap\mathcal{A}_\sigma$ such that $\Upsilon_\sigma\left((\widetilde{\nu}^1,\ldots\widetilde{\nu}^M\right)=L_\sigma$. Nonetheless, by construction of $\mathcal{H}_{\frac{\rho}{2}}^q$, we have $\Upsilon_\sigma\left((\widetilde{\nu}^1,\ldots\widetilde{\nu}^M\right)\leq L_\sigma-\eta$. We have arrived at a contradiction.


\subsection{Proof of Corollary~\ref{piccolo}}
According to Theorem~\ref{chichi}, the set of the limiting values $\mathcal{A}_\sigma$ is a path-connected subset of $\mathcal{S}_\sigma$ in which the free-energy is constant. Due to the hypothesis of Corollary~\ref{piccolo}, any path-connected subset of $\mathcal{S}_\sigma$ with constant free-energy is a single element. This achieves the proof.




\subsection{Proof of Corollary~\ref{piccolo2}}

\noindent{}{\bf Step 1.} We introduce $\mathcal{S}_0$, the set of stationary states $(\mu^1,\ldots,\mu^M)$ such that there exist decreasing sequences $(\sigma_\ell^k)_{k\in\mathbb{N}}$ which go to $0$ for any $1\leq\ell\leq M$ and a sequence $\left(\nu^{1,\sigma_1^k},\ldots\nu^{M,\sigma_M^k}\right)_{k\in\mathbb{N}}$ of stationary states of diffusion \eqref{eq: mean-field SDE} which converges weakly to $(\mu^1,\ldots,\mu^M)$, as $k$ goes to infinity.


\noindent{}{\bf Step 2.} By proceeding exactly like in \cite{JOTP} (Proposition 3.10, Lemma 3.3, Theorem 3.7 and Proposition 3.8 of the aforementioned paper hold under the set of assumptions of this section), we obtain that the set $\mathcal{S}_0$ is included into $\left\{\delta_{(a_1,\cdots,a_M)}\,;\,a_1\in\mathcal{G}_1\,,\cdots,a_M\in\mathcal{G}_M\right\}$.


\noindent{}{\bf Step 3.} We deduce that for any $\rho>0$, there exists $\sigma_0>0$ sufficiently small such that for all $\sigma_1,\ldots,\sigma_M<\sigma_0$, for all $\nu\in\mathcal{S}_\sigma$ and for all $1\leq\ell\leq M$, we have $\displaystyle\min_{a_\ell\in\mathcal{G}_\ell}\int_{\bRb^d}|x-a_\ell|^2\nu^\ell(x)\ddx\leq\rho$.


\noindent{}{\bf Step 4.} Theorem~\ref{chichi} tells us that $\mathcal{A}_\sigma\subset\mathcal{S}_\sigma$. This achieves the proof.

\bigskip

Let us remark that we do not have \emph{a priori} the existence of $a_\ell\in\mathcal{G}_\ell$ such that
\begin{equation*}
\limsup_{\sigma_1,\ldots,\sigma_M\to0}\limsup_{t\to+\infty}\int_{\bRb^d}|x-a_\ell|^2\mu_t^\ell(x)\ddx=0\,.
\end{equation*}
