\subsection{The two-species system in a double-well potential}
\[
V(x)=\frac{x^4}{4}-\frac{x^2}{2}, \quad V'(x)=x^3-x,\quad V''(x)=3x^2-1.
\]
Thus, if $\alpha>1$, there are no other equilibria apart from the critical points of $V$.

Now, consider $\alpha<1$
\begin{align*}
0&=\frac{1}{\alpha}\int_0^1 V''\left(m_2+t\frac{V'(m_2)}{a\alpha}\right)\,\ddt +1
\\&=\frac{1}{\alpha}\int_0^1 \Big[3\left(m_2+t\frac{m_2^3-m_2}{a\alpha}\right)^2-1\Big]\,\ddt+1
\\&=\frac{1}{\alpha}\Big[(3m_2^2-1)+\frac{3m_2^2(m_2^2-1)}{a \alpha}+\frac{m_2^2(m_2^2-1)^2}{a^2\alpha^2}\Big]+1
\end{align*}
which can be obtained in fact using \eqref{eq: eqn for m2 V polynomial}. This gives, for $X:=m_2^2$
\begin{equation}
\label{eq: cubic for m2}
X^3+(3a\alpha -2) X^2 +[3a\alpha(a\alpha-1)+1] X+a^2\alpha^2(\alpha-1)=0.    
\end{equation}
Note that $3a\alpha(a\alpha-1)+1>0$. If $a\alpha\geq \frac{2}{3}$ then $3a\alpha-2\geq 0$, the coefficients of this cubic equation has only one change of signs. Therefore, by Descartes' rule of sign, it has exactly one positive root. When $0<a\alpha<2/3$, it may have one or three positive roots (including multiplicity).

We point out that the synchronization assumption is $a\alpha_{11}+(1-a)\alpha>1$, which is different from hypothesis $a\alpha\geq \frac{2}{3}$.


The following lemma determines the conditions for the coefficients of a general cubic equation so that it has a certain number of positive roots. 
\begin{lemma}
Consider the cubic equation
\[
P(x)=x^3+ px^2+qx+r=0
\]
and the associated discriminant
\[
\Delta=\Delta(p,q,r):=-27 r^2+18pqr-4q^3-4p^3 r+p^2q^2.
\]
Then
\begin{enumerate}[(i)]
    \item $P$ has three real, distinct, positive roots if and only if
\begin{align*}
    \Delta> 0, \quad p<0, \quad q>0, \quad r<0.
\end{align*} 
  \item $P$ has two real positive roots (i.e, a double root $x_1>0$ and a single root $x_1\neq x_2=x_3>0$) if and only if
\begin{align*}
    \Delta=0, \quad p^2\neq 3q,\quad p<0, \quad q>0, \quad r<0.
\end{align*} 
  \item $P$ has  one positive root and two non-real complex conjugate roots if and only if
\begin{align*}
    \Delta<0, \quad r<0.
\end{align*} 
  \item $P$ has a triple positive root if and only if
\begin{align*}
        \Delta=0, \quad p^2= 3q,\quad p<0.
\end{align*} 
  \end{enumerate}
\end{lemma}
