\section{Quadratic confining potentials}
\label{app:quadr}

We perform explicit calculations for the case of quadratic potentials.
\[
V_1(x)=\frac{1}{2} x^T p x, \quad V_2(x)=\frac{1}{2}x^T q x,
\]
where $p,q\in\R^{d\times d}$ are two positive symmetric definite matrices.

Using the following Gaussian integrals, where $A\in\R^{d\times d}$ is a given symmetric positive definite matrix and $B\in\R^d$ is a given vector:
\begin{align*}
&\int_{\R^d}\exp\Big(-\frac{1}{2}x^T A x+ x^TB\Big)\,\ddx=\sqrt{\frac{(2\pi)^d}{\det A}}\, \exp\Big(\frac{1}{2}B^T A^{-1}B\Big),
\\ &\int_{\R^d}x\exp\Big(-\frac{1}{2}x^T A x+ x^TB\Big)\,\ddx=\sqrt{\frac{(2\pi)^d}{\det A}}\, \exp\Big(\frac{1}{2}B^T A^{-1}B\Big) A^{-1}B,
\end{align*}
we calculate
\begin{align*}
(i)\quad &\int_{\R^d} \exp\Big(-\frac{2}{\sigma^2}\big[V_1(x)+a\big(\frac{1}{2}x^T\alpha_{11} x-x^T\alpha_{11} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{12} x-x^T\alpha_{12} m_2\big)\big]\Big)\,\ddx
\\&=\int_{\R^d} \exp\Big(-\frac{2}{\sigma^2}\Big[\frac{1}{2}x^T(p+a\alpha_{11}+(1-a)\alpha_{12})x-x^T\big(a\alpha_{11} m_1+(1-a)\alpha_{12} m_2\big)\Big]\Big)\,\ddx
\\&=\int_{\R^d} \exp\Big(-\frac{1}{2}x^T A_1 x+x^TB_1\Big)\,\ddx
\\&=\sqrt{\frac{(2\pi)^d}{\det A_1}}~ \exp\Big(\frac{1}{2}B_1^T A_1^{-1}B_1\Big),
\\ \\
(ii)\quad &\int_{\R^d} x\exp\Big(-\frac{2}{\sigma^2}\big[V_1(x)+a\big(\frac{1}{2}x^T\alpha_{11} x-x^T\alpha_{11} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{12} x-x^T\alpha_{12} m_2\big)\big]\Big)\,\ddx
\\&=\int_{\R^d} x\exp\Big(-\frac{1}{2}x^T A_1 x+x^TB_1\Big)\,\ddx
\\&=\sqrt{\frac{(2\pi)^d}{\det A_1}}~ \exp\Big(\frac{1}{2}B_1^T A_1^{-1}B_1\Big)A_1^{-1}B_1
\\ \\
(iii)\quad& \int_{\R^d}\exp\Big(-\frac{2}{\sigma^2}\big[V_2(x)+a\big(\frac{1}{2}x^T\alpha_{21} x-x^T\alpha_{21} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{22} x-x^T\alpha_{22} m_2\big)\big]\Big)\,\ddx
\\&=\int_{\R^d} \exp\Big(-\frac{1}{2}x^T A_2 x+x^TB_2\Big)\,\ddx
\\&=\sqrt{\frac{(2\pi)^d}{\det A_2}}~ \exp\Big(\frac{1}{2}B_2^T A_2^{-1}B_2\Big),\\ \\
(iv)\quad& \int_{\R^d} x \exp\Big(-\frac{2}{\sigma^2}\big[V_2(x)+a\big(\frac{1}{2}x^T\alpha_{21} x-x^T\alpha_{21} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{22} x-x^T\alpha_{22} m_2\big)\big]\Big)\,\ddx
\\&=\int_{\R^d} x \exp\Big(-\frac{1}{2}x^T A_2 x+x^TB_2\Big)\,\ddx
\\&=\sqrt{\frac{(2\pi)^d}{\det A_2}}~ \exp\Big(\frac{1}{2}B_2^T A_2^{-1}B_2\Big)A_2^{-1}B_2,
\end{align*}
where
\begin{align*}
A_1&=\frac{2}{\sigma^2} (p+a\alpha_{11}+(1-a)\alpha_{12}),\\
B_1&=\frac{2}{\sigma^2}\big(a\alpha_{11} m_1+(1-a)\alpha_{12} m_2\big),\\
A_2&=\frac{2}{\sigma^2} (q+a\alpha_{21}+(1-a)\alpha_{21}),\\
B_2&=\frac{2}{\sigma^2}\big(a\alpha_{21} m_1+(1-a)\alpha_{22} m_2\big).
\end{align*}
Substituting these computations to \eqref{eq: m-systems} we obtain
\begin{subequations}
 \begin{align*}
 m_1&=A_1^{-1} B_1=(p+a\alpha_{11}+(1-a)\alpha_{12})^{-1}\big(a\alpha_{11} m_1+(1-a)\alpha_{12} m_2\big),
 \\ m_2&=A_2^{-1} B_2=(q+a\alpha_{21}+(1-a)\alpha_{22})^{-1}\big(a\alpha_{21} m_1+(1-a)\alpha_{22} m_2\big).
 \end{align*}
\end{subequations}
This system can be simplified to 
\begin{subequations}
 \begin{align*}
 (p+(1-a)\alpha_{12})m_1-(1-a)\alpha_{12}m_2&=0,\\
-a\alpha_{21}m_1+ (q+a\alpha_{21})m_2&=0,
 \end{align*}
\end{subequations}
which is equivalent to
 \begin{equation}
\label{eq: m-system-reduced}     
 m_2=\Big(\frac{1}{1-a}\alpha_{12}^{-1}p+I\Big)m_1\quad\text{and}\quad
\Big[-a \alpha_{21}+(q+a\alpha_{21})\Big(\frac{1}{1-a}\alpha_{12}^{-1}p+I\Big)\Big] m_1=0.
\end{equation}
Thus for all $\sigma>0$:
\begin{enumerate}[(1)]
    \item If $-a \alpha_{21}+(q+a\alpha_{21})\Big(\frac{1}{1-a}\alpha_{12}^{-1}p+I\Big)$ is non-singular, then \eqref{eq: m-system-reduced} has a unique solution $m_1=m_2=0$. In this case, the coupled McKean-Vlasov diffusions has a unique equilibrium where both $\mu$ and $\nu$ are Gaussian measures
    \begin{align*}
    &\mu(x)\propto \exp\Big(-\frac{1}{\sigma^2}x^T(p+a \alpha_{11}+(1-a)\alpha_{12})x\Big),
    \\&\nu(x)\propto \exp\Big(-\frac{1}{\sigma^2}x^T(q+a \alpha_{21}+(1-a)\alpha_{22})x\Big).
    \end{align*}
In particular, this is the case when $\alpha_{21}=\alpha_{12}$.
    \item If $-a \alpha_{21}+(q+a\alpha_{21})\Big(\frac{1}{1-a}\alpha_{12}^{-1}p+I\Big)$ is singular, then \eqref{eq: m-system-reduced} has infinitely number of solutions. Thus the coupled McKean-Vlasov diffusions has infinitely number of equilibria (including the above Gaussian measures). 
    \end{enumerate}
It is interesting to note that the condition does not depend on $\alpha_{11}$ and $\alpha_{22}$, that is, it does not depend on self-interacting potentials.


