\section{A Technical Lemma Used in the Proof of Theorem~\ref{chichi}}
\label{app:converg}

In this appendix, we present the following proposition, which is used several times in the proof of Theorem~\ref{chichi} to construct elements of $\mathcal{S}_\sigma$ satisfying some hypotheses.
\begin{prop}
\label{prop:a:othermeasure}
Let the assumptions of Theorem~\ref{chichi} hold. We also assume the existence of two polynomial functions $\mathcal{P}$ and $\mathcal{Q}$, a smooth function $\varphi^\ell$ from $\bRb^d$ to $\bRb$ with compact support such that
$\left|\varphi^\ell(x)\right|\leq\mathcal{P}\left(|x|\right)$ and
$\left|\nabla\varphi^\ell(x)\right|^2\leq\mathcal{Q}\left(|x|\right)$, $\kappa>0$ and two sequences $(r_k)_{k\in\mathbb{N}}$ and $(s_k)_{k\in\mathbb{N}}$ which go to infinity such that
for all $r_k\leq t\leq s_k<r_{k+1}$, we have
\begin{equation*}
\kappa=\int_{\bRb^d}\varphi^\ell(x)\mu_{r_k}^\ell(x)\ddx\leq\int_{\bRb^d}\varphi^\ell(x)\mu_t^\ell(x)\ddx\leq\int_{\bRb^d}\varphi^\ell(x)\mu_{s_k}^\ell(x)\ddx=2\kappa\,.
\end{equation*}
Thus, there exists a stationary state $(\nu^1,\ldots,\nu^M)\in\mathcal{A}_\sigma\bigcap\mathcal{S}_\sigma$ that satisfies $\int_{\bRb^d}\varphi^\ell(x)\nu^\ell(x)\ddx\in[\kappa;2\kappa]$. Moreover, $\displaystyle\Upsilon_\sigma(\nu^1,\ldots,v^M)=\lim_{t\to+\infty}\Upsilon_\sigma(\mu_t^1,\ldots,\mu_t^M)$.
\end{prop}
\begin{proof}
%{\bf Outline.} We proceed exactly like in the proof of Proposition 2.1 in \cite{JOTP}. We just neeed to find a sequence $(q_k)_{k\in\mathbb{N}}$ which tends to infinity as $k$ goes to infinity and which verifies the two following conditions:
%\begin{itemize}
% \item $\xi'(q_k)$ converges to $0$.
% \item $r_k\leq q_k\leq s_k$.
%\end{itemize}
%For doing so, we remark that the inequality $\xi'(s)\leq0$ and the convergence of $\int_t^\infty\xi'(s)ds$ to $0$ implies that $\sum_{p=k}^\infty\int_{r_p}^{s_p}\xi'(s)ds$ vanishes when $k$ is going to infinity. \emph{However, to obtain the existence of such a sequence $\left(q_k\right)_{k\in\mathbb{N}}$, we need to prove that $\displaystyle\liminf_{k\longrightarrow+\infty}\left(s_k-r_k\right)>0$.} This is done like in the proof of \cite[Proposition A.1]{AOP}.\\[3pt]
{\bf Step 1.} We begin to prove that
$\displaystyle\liminf_{k\longrightarrow+\infty}\left(s_k-r_k\right)>0$. We
introduce the function
\begin{equation*}
\Phi(t):=\int_{\bRb^d}\varphi^\ell(x)\mu_t^\ell(x)\ddx\,.
\end{equation*}
This function is well defined, as $\left|\varphi^\ell(x)\right|$ is bounded by $\mathcal{P}\left|x|\right)$. The derivation of $\Phi$ and an integration by parts lead to
\begin{align*}
\Phi'(t)&=-\int_{\bRb^q}\left\langle\nabla\varphi^\ell(x)\,;\,\frac{\sigma_\ell^2}{2}\nabla \mu_t^\ell(x)+\mu_t^\ell(x)\left(\nabla V_\ell(x)+\sum_{j=1}^Ma_j\nabla F_{\ell j}\ast \mu_t^j(x)\right)\right\rangle\ddx\\
&=-\int_{\bRb^d}\left\langle\nabla\varphi^\ell(x)\,;\,\eta_t^\ell(x)\right\rangle\mu_t^\ell(x)\ddx\,.
\end{align*}
The Cauchy-Schwarz inequality implies
\begin{equation*}
\left|\Phi'(t)\right|\leq\sqrt{-\frac{1}{a_\ell}\xi'(t)}\sqrt{\int_{\bRb^d}\left|\nabla\varphi^\ell(x)\right|^2\mu_t^\ell(x)\ddx}\,,
\end{equation*}
by reminding that $\xi(t):=\Upsilon_\sigma\left(\mu_t^1,\ldots,\mu_t^M\right)$. The
quantity $\left|\nabla\varphi^\ell(x)\right|^2$ is bounded by $\mathcal{Q}\left(|x|\right)$ and
$\int_{\bRb^d}|x|^{2N_0}\mu_t(x)\ddx$ is uniformly bounded with respect to $t\geq1$ for all $N_0\in\mathbb{N}$. So, there exists $C>0$ such that
$\int_{\bRb^d}\left|\nabla\varphi^\ell(x)\right|^2\mu_t^\ell(x)\ddx\leq C^2$ for all
$t\geq1$. We deduce
\begin{equation}
\label{eq:a:majoration}
\left|\Phi'(t)\right|\leq C\sqrt{\left|\xi'(t)\right|}\,.
\end{equation}
By definition of the two sequences $(r_k)_{k\in\mathbb{N}}$ and $(s_k)_{k\in\mathbb{N}}$, we have
\begin{equation*}
\Phi(s_k)-\Phi(r_k)=\kappa\,.
\end{equation*}
Combining this identity with Inequality \eqref{eq:a:majoration} and the monotonicity of $\xi$ yields
\begin{equation*}
C\int_{r_k}^{s_k}\sqrt{-\xi'(t)}\ddt\geq\kappa\,.
\end{equation*}
We apply the Cauchy-Schwarz inequality and we obtain
\begin{equation*}
C\sqrt{s_k-r_k}\sqrt{\xi(r_k)-\xi(s_k)}\geq\kappa\,.
\end{equation*}
Moreover, $\xi(t)$ converges as $t$ goes to infinity (see Lemma \ref{lem:fr:conv}). It implies the convergence of $\xi(r_k)-\xi(s_k)$ to $0$ when $k$ goes to infinity. Consequently, $s_k-r_k$ converges to infinity so
\begin{equation*}
\liminf_{k\longrightarrow+\infty}s_k-r_k>0\,.
\end{equation*}


\noindent{}{\bf Step 2.} By Lemma \ref{lem:fr:conv}, $\Upsilon_\sigma(\mu_t)-L_\sigma=-\int_t^\infty\xi'(s)\dd s$ converges to $0$. As $\xi'$ is nonpositive, we deduce that $\sum_{k=N}^\infty\int_{r_k}^{s_k}\xi'(s)\dd s$ also converges to $0$ when $N$ goes to infinity. As $\displaystyle\liminf_{k\longrightarrow+\infty}s_k-r_k>0$, we deduce the existence of an increasing sequence $q_k\in[r_k;s_k]$ which goes to infinity and such that $\xi'\left(q_k\right)$ converges to $0$ as $k$ goes to infinity. Furthermore, $\int_{\bRb^d}\varphi^\ell(x)\mu_{q_k}^\ell(x)\ddx\in[\kappa;2\kappa]$, for all $k\in\mathbb{N}$.



\noindent{}{\bf Step 3.} By proceeding similarly to the proof of \cite[Theorem 2.7]{JOTP}, we extract a subsequence of $(q_k)_{k\in\mathbb{N}}$ (we continue to write it $q_k$ to simplify the reading) such that $(\mu_{q_k}^1,\ldots,\mu_{q_k}^M)$ weakly converges to a stationary state $(\nu^1,\ldots,\nu^M)$ such that $\int_{\bRb^d}\varphi^\ell(x)\nu^\ell(x)\ddx\in[\kappa;2\kappa]$.


\noindent{}{\bf Step 4.} Since $\xi'(q_k)$ goes to $0$ as $k$ goes to infinity, we can apply Proposition~\ref{jigsaw}. Thus, we deduce $\Upsilon_\sigma(\nu^1,\ldots,\nu^M)=L_\sigma:=\lim_{t\to+\infty}\Upsilon_\sigma(\mu_t^1,\ldots,\mu_t^M)$.
\end{proof}

