\section{two-species}
In this paper, we study a two-species model in the form of a coupled system of nonlinear stochastic differential equations \cite{DuongTugaut2020}
\begin{subequations}
\label{eq: SDEs}
\begin{align}
&d X_t=-\nabla V_1(X_t)\,dt-a\nabla F_{11}\ast\mu_t(X_t)\,dt-(1-a)\nabla F_{12}\ast\nu_t(X_t)\,dt+\sigma\, dW_t,
\\&d Y_t=-\nabla V_2(Y_t)\,dt-a\nabla F_{21}\ast\mu_t(Y_t)\,dt-(1-a)\nabla F_{22}\ast\nu_t(Y_t)\,dt+\sigma\, d \widehat{W}_t,
\\ &\mathbb{P}(X_t\in dx)=\mu_t(x)\,dx,~~\mathbb{P}(Y_t\in dx)=\nu_t(x)\,dx.
\end{align}
\end{subequations}
Here $0\leq a\leq 1$ and $\sigma>0$ are given constants; $V_1, V_2$ are two external potentials; $F_{11}, F_{22}$ are self-interacting potentials describing the interactions among individuals of the same
species; $F_{12}, F_{21}$ are cross-interacting potentials representing the interactions between individuals belonging to different species; $\sigma$ is the diffusion intensity;  $(W_t, t\geq 0)$ and $(\widehat{W}_t, t\geq 0)$ are independent Wiener processes and finally $\ast$ denotes the standard convolution operator: for a function $G$ and a measure $\gamma$, the convolution between $G$ and $\gamma$, $G\ast\gamma$, is given by
\[
(G\ast \gamma)(x)=\int G(x-y)\gamma(y)\,dy.
\]
In \eqref{eq: SDEs} the evolution of $X_t$ and $Y_t$ depend on their own laws, $\{\mu_t,t\geq 0\}$ and $\{\nu_t, t\geq 0\}$ respectively, that are unknown. Using It\^{o} formula one can show that  $\{\mu_t,t\geq 0\}$ and $\{\nu_t, t\geq 0\}$ satisfy the following system of nonlinear nonlocal partial differential equations
\begin{subequations}
\label{eq: PDEs}
\begin{align}
&\partial_t\mu_t=\div\Big(\big(\nabla V_1+a(\nabla F_{11}\ast\mu_t)+(1-a)(\nabla F_{12}\ast \nu_t)\big)\mu_t\Big)+\frac{\sigma^2}{2}\Delta\mu_t,\\
&\partial_t\nu_t=\div\Big(\big(\nabla V_2+a(\nabla F_{21}\ast\mu_t)+(1-a)(\nabla F_{22}\ast \nu_t)\big)\nu_t\Big)+\frac{\sigma^2}{2}\Delta\nu_t,\\
&\mu_0(dx)=\mathbb{P}(X_0\in dx),~~\nu_0(dx)=\mathbb{P}(Y_0\in dx).
\end{align}
\end{subequations}



\section{Equilibria}



An equilibrium point of the coupled McKean-Vlasov diffusions \eqref{eq: SDEs} is a pair of probability measures $(\mu, \nu)\in \P(\R^d)\times \P(\R^d)$ that solve
\begin{subequations}
\label{eq: equilibria}
\begin{align}
\div\Big(\big(\nabla V_1+a(\nabla F_{11}\ast\mu)+(1-a)(\nabla F_{12}\ast \nu)\big)\mu\Big)+\frac{\sigma^2}{2}\Delta\mu&=0,\\
\div\Big(\big(\nabla V_2+a(\nabla F_{21}\ast\mu)+(1-a)(\nabla F_{22}\ast \nu)\big)\nu_t\Big)+\frac{\sigma^2}{2}\Delta\nu&=0
\end{align}
\end{subequations}
The above system can be equivalently formulated as
\begin{subequations}
\begin{align}
\label{eq: invariant measures}
\mu(x)&=\frac{\exp\Big(-\frac{2}{\sigma^2}\big(V_1(x)+a F_{11}\ast \mu(x)+(1-a)F_{12}\ast\nu(x)\big)\Big)}{\int \exp\Big(-\frac{2}{\sigma^2}\big(V_1(x)+a F_{11}\ast \mu(x)+(1-a)F_{12}\ast\nu(x)\big)\Big)\,dx},\\
\nu(x)&=\frac{\exp\Big(-\frac{2}{\sigma^2}\big(V_2(x)+a F_{21}\ast \mu(x)+(1-a)F_{22}\ast\nu(x)\big)\Big)}{\int \exp\Big(-\frac{2}{\sigma^2}\big(V_2(x)+a F_{21}\ast \mu(x)+(1-a)F_{22}\ast\nu(x)\big)\Big)\,dx}.
\end{align}
\end{subequations}
\textcolor{red}{number of equilibria? stablility? phase-transition, etc....}

We first focus on quadratic interaction potentials
\begin{equation}
\label{eq: interaction potentials}    
F_{ij}(x)=\frac{1}{2}x^T\alpha_{ij} x,
\end{equation}
where $\alpha_{ij}\in \R^{d\times d}, i,j\in\{1,2\}$ are given symmetric positive definite matrices.

We define the mean vectors of $\mu$ and $\nu$ respectively by
\begin{equation*}
m_1:=\int x\mu(x)\,dx\quad\text{and}\quad m_2=\int x\nu(x)\,dx,\quad m_1, m_2\in \R^d.
\end{equation*}
Substituting \eqref{eq: interaction potentials} to \eqref{eq: equilibria}, we obtain
\begin{subequations}
\begin{align*}
\mu(x)&=\frac{\exp\Big(-\frac{2}{\sigma^2}\big[V_1(x)+a\big(\frac{1}{2}x^T\alpha_{11} x-x^T\alpha_{11} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{12} x-x^T\alpha_{12} m_2\big)\big]\Big)}{\int \exp\Big(-\frac{2}{\sigma^2}\big[V_1(x)+a\big(\frac{1}{2}x^T\alpha_{11} x-x^T\alpha_{11} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{12} x-x^T\alpha_{12} m_2\big)\big]\Big)\,dx},\\
\nu(x)&=\frac{\exp\Big(-\frac{2}{\sigma^2}\big[V_2(x)+a\big(\frac{1}{2}x^T\alpha_{21} x-x^T\alpha_{21} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{22} x-x^T\alpha_{22} m_2\big)\big]\Big)}{\int \exp\Big(-\frac{2}{\sigma^2}\big[V_2(x)+a\big(\frac{1}{2}x^T\alpha_{21} x-x^T\alpha_{21} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{22} x-x^T\alpha_{22} m_2\big)\big]\Big)\,dx}.
\end{align*}
 \end{subequations}
Therefore, $(m_1,m_2)$ satisfies the following system

\begin{subequations}
\label{eq: m-system}
 \begin{align}
m_1&=\frac{\int x \exp\Big(-\frac{2}{\sigma^2}\big[V_1(x)+a\big(\frac{1}{2}x^T\alpha_{11} x-x^T\alpha_{11} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{12} x-x^T\alpha_{12} m_2\big)\big]\Big)}{\int \exp\Big(-\frac{2}{\sigma^2}\big[V_1(x)+a\big(\frac{1}{2}x^T\alpha_{11} x-x^T\alpha_{11} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{12} x-x^T\alpha_{12} m_2\big)\big]\Big)\,dx},\label{eq: m1}\\
m_2&=\frac{\int x\exp\Big(-\frac{2}{\sigma^2}\big[V_2(x)+a\big(\frac{1}{2}x^T\alpha_{21} x-x^T\alpha_{21} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{22} x-x^T\alpha_{22} m_2\big)\big]\Big)}{\int \exp\Big(-\frac{2}{\sigma^2}\big[V_2(x)+a\big(\frac{1}{2}x^T\alpha_{21} x-x^T\alpha_{21} m_1\big)+(1-a)\big(\frac{1}{2}x^T\alpha_{22} x-x^T\alpha_{22} m_2\big)\big]\Big)\,dx}.\label{eq: m2}
 \end{align}
\end{subequations}
We define 
\begin{align*}
\Phi:\quad\R^d\times \R^d&\rightarrow \R^d\times \R^d
\\(m_1,m_2)&\mapsto (\Phi_1(m_1,m_2), \Phi_2(m_1,m_2))
\end{align*}
where $\Phi_1(m_1, m_2)$ and $\Phi_2(m_1,m_2)$ are the right-hand sides of \eqref{eq: m1} and \eqref{eq: m2}, respectively. Then we can reformulate \eqref{eq: m-system} as a fixed point problem for $\Phi$ 
