        \infer[\ern \Box]{\varphi^y}{(\Box\varphi)^x & xRy}\\[3mm]
        % Diamond rules
        \infer[\irn \Diamond]{(\Diamond\varphi)^x}{\varphi^y & xRy}&
        \infer[\ern \Diamond^{**}]{\psi^z}{(\Diamond\varphi)^x & \deduce{\psi^z}{[\varphi^y]\,[xRy]}}\\[3mm]
        % Comments
        *\text{ The label $y$ is different to $x$ and} & **\text{ The label $y$ is different to $x$ and $z$}\\
        \text{the labels of any open assumptions.} & \text{ and the labels of any open assumptions.}
