\section{Derivability in a Base and Base-extension Semantics} \label{sec:BDS}

Following the approach of Sandqvist \cite{Tor2015}, we start by defining a notion of atomic derivability, which is the basis of the base-extension semantics.

\begin{definition}[Basic sentence]
    A basic sentence is either a labelled propositional letter or a relational assumption. % on labels. 
    $\Basic$ denotes the set of all basic sentences. \fillBox
\end{definition}

For the remainder of this paper, we adopt the convention that lower case Latin letters refer to basic sentences, except for the variable letters $v,w,x,y,z,a,b$. Lower case Greek letters, except for $\gamma$, will refer to intuitionistic modal formulae and uppercase Latin and Greek letters, except for the relation symbol $R$, will refer to finite sets thereof. A basic sentence written without a superscript is taken to mean \emph{either} a labelled propositional letter \emph{or} a relational assumption. We also henceforth use the word atom to mean labelled \emph{atom}. 
%\emph{propositional letter}.

\begin{definition}[Basic sequent]
    A basic sequent is an ordered pair $\langle P,p\rangle$ where $P$ is a (finite) set of basic sentences and $p$ is an % labelled 
    atom if $P\neq\emptyset$. Else $p$ is a basic sentence. We write this pair as $P\seq p$ and omit the $P$ if it is empty. \fillBox
\end{definition}

\begin{definition}[Basic rule]
    A basic rule is an ordered pair $\langle\mathbf{Q},r\rangle$ where $\mathbf{Q}$ is a (finite) set of basic sequents and $r$ is a labelled atom if $\mathbf{Q}\neq\emptyset$. Else, $r$ is a basic sentence. We write this as $(P_1\seq p_1, \dots, P_n\seq p_n)\seq r$ where each $P_i\seq p_i\in \mathbf{Q}$ and omit the $(P_1\seq p_1, \dots, P_n\seq p_n)$ if $\mathbf{Q}$ is empty. \fillBox
\end{definition}

\begin{definition}[Base]
    A base is a set of basic rules. \fillBox
\end{definition}

\begin{definition}[Basic derivability relation]
    Given a set of frame conditions $\gamma$ and a base $\baseB$, we can inductively define a relation of derivability on basic sequents as follows:
    \[
    \begin{array}{r@{\quad}l}
    \mbox{\rm (Ref)} & \mbox{$S, p \deriveBaseIML{\baseB}p$} \\[1mm]
    %
    \mbox{\rm (App)} & \mbox{If $((P_1\seq p_1, \dots, P_n\seq p_n)\seq r)\in \baseB$ and} \\
    & \mbox{\quad$S,P_i\deriveBaseIML{\baseB}p_i$ for each $i$, then $S\deriveBaseIML{\baseB}r$}\\[1mm]
    \end{array} 
    \]
    \[
    \begin{array}{r@{\quad}l}
    \mbox{\rm (D)} & \mbox{If $\gamma_D\in\gamma$ and there exists a y such that  $S,xRy\deriveBaseIML{\baseB}p^z$, then $S\deriveBaseIML{\baseB}p^z$} \\[1mm]
    \mbox{\rm (T)} & \mbox{If $\gamma_T\in\gamma$ and $S,xRx\deriveBaseIML{\baseB}p^y$, then $S\deriveBaseIML{\baseB}p^y$}\\[1mm]
    \mbox{\rm (B)} & \mbox{If $\gamma_B\in\gamma$, $S\deriveBaseIML{\baseB}xRy$ and $S,yRx\deriveBaseIML{\baseB}p^z$, then $S\deriveBaseIML{\baseB}p^z$}\\[1mm]
     \end{array} 
    \]
    \[
    \begin{array}{r@{\quad}l}
    \mbox{\rm (4)} & \mbox{If $\gamma_4\in\gamma$, $S\deriveBaseIML{\baseB}xRy$, $S\deriveBaseIML{\baseB}yRz$, and $S,xRz\deriveBaseIML{\baseB}p^w$, then $S\deriveBaseIML{\baseB}p^w$}\\[1mm]
    %
    \mbox{\rm (5)} & \mbox{If $\gamma_5\in\gamma$, $S\deriveBaseIML{\baseB}xRy$, $S\deriveBaseIML{\baseB}xRz$, and $S,yRz\deriveBaseIML{\baseB}p^w$, then $S\deriveBaseIML{\baseB}p^w$}\\[1mm]
    %
    \mbox{\rm (2)} & \mbox{If $\gamma_2\in\gamma$, $S\deriveBaseIML{\baseB}xRy$, $S\deriveBaseIML{\baseB}xRz$, and there exists a $w$ such that}\\
    & \quad\mbox{$S,yRw,zRw\deriveBaseIML{\baseB}p^v$, then $S\deriveBaseIML{\baseB}p^v$}. 
    \end{array} 
    \] 
The last six cases we call the \emph{modal cases} of the derivability relation.
In the case of $\rm (D)$, the label $y$ cannot appear as the label of any $s\in S$ nor be equal to $x$ or $z$. In the case of $(2)$, the label $w$ cannot appear as the label of any $s\in S$ nor be equal to $x,y,z,v$.   \fillBox
\end{definition}



\begin{lemma}\label{lem:basicWeakening}
    If $U\deriveBaseIML{\baseB}u$, then $T,U\deriveBaseIML{\baseB}u$. 
\end{lemma}
\begin{proof}
    We start noting that, in the modal cases, we are immediately done. So now consider when $U\deriveBaseIML{\baseB}u$ holds by (Ref), in which case $u \in U$. Therefore, $u\in T,U$ and thus $T,U\deriveBaseIML{\baseB}u$ holds again by (Ref). Otherwise, consider when $U\deriveBaseIML{\baseB}u^x$ holds by (App). In this case, there must exist a rule $((P_1\seq p_1, \dots, P_n\seq p_n)\seq u)\in \baseB$ such that $U,P_i\deriveBaseIML{\baseB}p_i$ holds for each $i$. By the inductive hypothesis, we therefore obtain that $T,U,P_i\deriveBaseIML{\baseB}p_i$ for each $i$, from which we conclude by (App) that $T,U\deriveBaseIML{\baseB}u$. \fillBox
\end{proof}

\begin{lemma}\label{lem:basicInf}
    $T\deriveBaseIML{\baseB}u$ if and only if, for all $\baseC\baseGeq\baseB$ such that if, for all $t\in T$, we have $\deriveBaseIML{\baseC}t$, then $\deriveBaseIML{\baseC}u$.
\end{lemma}

\begin{proof}
Going left to right, we suppose the hypothesis and consider how $T\deriveBaseIML{\baseB}u$ holds. We consider just the non-modal cases as the modal cases are immediate. If it holds by (Ref), then $u\in T$ and thus we are immediately done. Else, it must hold by (App) in which case we have that there exists a rule $((P_1\seq p_1, \dots, P_n\seq p_n)\seq u)\in \baseB$ and $T,P_i\deriveBaseIML{\baseB}p_i$ for each $i$. By the inductive hypothesis, we therefore have that $P_i\deriveBaseIML{\baseC}p_i$ for each $i$, from which it follows by (App) that $\deriveBaseIML{\baseC}u$.

Going right to left, we consider whether $u\in T$ or not. If it is, then we immediately have by (Ref) that $T\deriveBaseIML{\baseB}u$ and we are done. So suppose not. We begin this case by making the observation that if for any base $\baseX$ we have that $Q\deriveBaseIML{\baseX}q$ holds by (Ref) then it must be the case that $Q\deriveBaseIML{\baseB}q$ and by Lemma~\ref{lem:basicWeakening} we have that $T,Q\deriveBaseIML{\baseB}q$. 

Now consider the base $\base{S} = \baseB \cup \{\seq t \,|\, t \in T\} \baseGeq \baseB$. We deduce that $\deriveBaseIML{\base{S}}u$ holds and that it must hold by (App) or if $u$ is a labelled formula it can hold by a modal case. Starting with (App), since $u \notin T$, there must be a rule concluding $u$ in $\baseB$. Let this rule be $(P_1\seq p_1, \dots, P_n\seq p_n)\seq u$. Thus, we have by (App) that $P_i\deriveBaseIML{\base{S}}p_i$ for all $i$. Thus, by the inductive hypothesis, taking our initial observation as our base case, we have that $T,P_i\deriveBaseIML{\baseB}p_i$ from which, by (App), we conclude $T\deriveBaseIML{\baseB}u$, as required. 

We now show just one of the modal cases --- all the others go similarly. Suppose $u=p^x$ and that we have that $\deriveBaseIML{\base{S}}p^x$ holds by ${\rm (D)}$. Thus, we have that $\gamma_D\in\gamma$ and that there exists a $y$ such that $xRy\deriveBaseIML{\base{S}}p^x$. By the inductive hypothesis, possibly by renaming the variable $y$, we therefore have that there exists a $y$ such that $T,xRy\deriveBaseIML{\baseB}p^x$, and by ${\rm (D)}$ we obtain $T\deriveBaseIML{\baseB}p^x$, as required. \fillBox
\end{proof}

\begin{lemma}[Monotonicity]
    If $S\deriveBaseIML{\baseB}p$, then, for all $\baseC\baseGeq\baseB$, %we have that 
    $S\deriveBaseIML{\baseC}p$. \fillBox
\end{lemma}
To prove this, it suffices to consider how $S\deriveBaseIML{\baseB}p$ holds. Intuitively, we understand that by extending our base, the original atomic derivation still remains a valid argument for $p$ from $S$.

With these preliminary notions established, we can extend the notion of basic derivability to give a support relation, in the sense of Sandqvist \cite{Tor2015}. First, must extend the notion of sequent to allow for relational assumptions or, in the presence of no assumptions, concluding a relation.

\begin{definition}[Extended sequent]
    An extended sequent is a pair $(\Gamma,\varphi)$ that we write $(\Gamma:\varphi)$ where $\Gamma$ is a set of intuitionistic modal formulae and relational assumptions and $\varphi$ is an intuitionistic modal formula or, if $\Gamma$ is empty, also possibly a relational assumption. \fillBox
\end{definition}

The support relation, Definition~\ref{def:support} is core to the base-extension semantics. 

\begin{definition}[Support] \label{def:support}
    Given a set of frame conditions $\gamma$ and a base $\baseB$, we can inductively define a relation of support on extended sequents as follows:
\[
\begin{array}{lrcl}
\mbox{\rm (At)} & \mbox{$\suppIML{\baseB}p^x$} & \;\mbox{iff}\; & 
\mbox{$\deriveBaseIML{\baseB}p^x$} \\ 
\mbox{\rm (Rel)} & \mbox{$\suppIML{\baseB}xRy$} & \;\mbox{iff}\; & \mbox{$\deriveBaseIML{\baseB}xRy$} \\ 
\mbox{$(\land)$} & \mbox{$\suppIML{\baseB}(\varphi\land\psi)^x$} & \;\mbox{iff}\; & \mbox{$\suppIML{\baseB}\varphi^x$ and $\suppIML{\baseB}\psi^x$} \\ 
\mbox{$(\lor)$} & \mbox{$\suppIML{\baseB}(\varphi\lor\psi)^x$} & \;\mbox{iff}\; & \mbox{for all $\baseC\baseGeq\baseB$ and $p^z$,} \\ 
& & & \mbox{if $\varphi^x\suppIML{\baseC}p^z$ and $\psi^x\suppIML{\baseC}p^z$, then $\suppIML{\baseC}p^z$} 
\end{array}
\]
\[
\begin{array}{lrcl}
\mbox{$(\to)$} & \mbox{$\suppIML{\baseB}(\varphi\to\psi)^x$} & \;\mbox{iff}\; & \mbox{$\varphi^x\suppIML{\baseB}\psi^x$} \\ 
\mbox{$(\Box)$} & \mbox{$\suppIML{\baseB}(\Box\varphi)^x$} & \;\mbox{iff}\; & \mbox{$xRy\suppIML{\baseB}\varphi^y$, for all labels $y$} \\ 
\mbox{$(\Diamond)$} & \mbox{$\suppIML{\baseB}(\Diamond\varphi)^x$} & \;\mbox{iff}\; & \mbox{for all $\baseC\baseGeq\baseB$ and $p^z$,} \\ 
& & & \mbox{if $xRy,\varphi^y\suppIML{\baseC}p^z$ for all labels $y$, then $\suppIML{\baseC}p^z$} 
\end{array}
\]
\[
\begin{array}{lrcl} 
\mbox{$(\bot)$} & \mbox{$\suppIML{\baseB}\bot^x$} & \;\mbox{iff}\; & \mbox{$\suppIML{\baseB}p^z$, for all $p^z$}\\
\mbox{$(\top)$} & \mbox{$\suppIML{\baseB}\top^x$} &  & \mbox{always}\\
\mbox{\rm (Inf)} & \mbox{$\Gamma\suppIML{\baseB}\varphi$} & \;\mbox{iff}\; & \mbox{for all $\baseC\baseGeq\baseB$ such that $\suppIML{\baseC}\psi$, for each $\psi\in\Gamma$,} \\  & & & \mbox{implies $\suppIML{\baseC}\varphi$}
\end{array} \vspace{-5mm}
\]
\fillBox
\end{definition}

\begin{definition}[Validity]
    The sequent $(\Gamma:\varphi^x)$ is said to be valid if and only if for all bases $\baseB$, it is the case that $\Gamma\suppIML{\baseB}\varphi^x$ holds. \fillBox
\end{definition}
We start with an ostensibly useful observation.
\begin{lemma}
    The sequent $(\Gamma:\varphi^x)$ is valid if and only if $\Gamma\suppIML{\emptyset}\varphi^x$
\end{lemma}
\begin{proof}
    Going left to right, we have that for all bases $\baseB$, it is the case that $\Gamma\suppIML{\baseB}\varphi^x$. Thus, we can pick $\baseB=\emptyset$. Going right to left, we obtain the result by monotonicity as the empty base is the smallest subset of every base. \fillBox
\end{proof}

So, we are justified in writing a valid sequent as $\Gamma\suppM{}{\,\gamma}\varphi^x$. Before moving on, a brief discussion of the clause for $\Diamond$ is in order. One would perhaps wish to see a clause for $\Diamond$ that says something along the lines of $\suppIML{\baseB}(\Diamond\varphi)^x$ iff $\exists y (\suppIML{\baseB}xRy$ and $\suppIML{\baseB}\varphi^y)$. Doing so, however, quickly presents problems in proving both soundness and completeness. If we understand the presence of the existential as an infinite, meta-level disjunction, then we can understand this problem as being of the same kind faced by Sandqvist \cite{Tor2015} in trying to define disjunction. In fact, the clause for $\Diamond$ amounts to an infinitary version of Sandqvist's clause for disjunction. 

More specifically, suppose one gives a na\"{\i}ve Kripke-like definition for intuitionistic disjunction; that is,  $\Vdash_{\baseB}\varphi\lor\psi\text{ iff }\Vdash_{\baseB}\varphi\text{ or }\Vdash_{\baseB}\psi$. One could instead write this definition as $\exists\chi\in\Delta$ s.t. $\Vdash_{\baseB}\chi$, where $\Delta=\{\varphi,\psi\}$. This definition, as shown by de Campos Sanz and Piecha in~\cite{CamposSanz2014-CAMACR-5}, doesn't work. 

Instead, the clause $\forall \baseC\baseGeq\baseB,\forall p,\forall\chi\in\Delta$, $\chi\Vdash_{\baseC}p$ implies $ \Vdash_{\baseC}p$ --- corresponding to the second-order definition of $\vee$ or to the elimination rule in NJ --- does (again, see \cite{GP2025} for more discussion). Something similar follows for $\Diamond$. If one attempts to give $\Diamond$ a Kripke-like definition, that is, $\suppIML{\baseB}(\Diamond\varphi)^x$ iff $\exists y$ s.t.  $(\suppIML{\baseB}xRy$ and $\suppIML{\baseB}\varphi^y)$, then, similarly to before, this definition fails to be sound and complete. Instead, as demonstrated below, the clause $\forall \baseC\baseGeq\baseB,\forall p^z,\forall y\in\Worlds(\varphi^y,xRy\Vdash_{\baseC}p^z)$ implies $ \Vdash_{\baseC}p^z$, again based on the elimination rule, is sound and complete. We note that, in both cases, we have taken definitions that are meta-level disjunctive in the Kripke semantics, and turned them around into meta-level conjunctive in their proof-theoretic semantics. 


\section{Soundness} \label{sec:soundness}

The soundness of the base-extension semantics we have given with respect to natural deduction system $\rm N_{\Box\Diamond}(\gamma)$ is stated
as follows:
\[
 \mbox{if $\Gamma\vdash^{\,\gamma}\varphi^x$, then $\Gamma\suppM{}{\,\gamma}\varphi^x$.}
\]
By the inductive definition of derivability in $\rm N_{\Box\Diamond}(\gamma)$, it suffices to show the following:
    \begin{itemize}
        \item[$(\text{R})$] $\Gamma,\varphi^x\suppM{}{\gamma}\varphi^x$
        %
        \item[$(\land\text{I})$] If $\Gamma\suppM{}{\gamma}\varphi^x$ and $\Gamma\suppM{}{\gamma}\psi^x$, then $\Gamma\suppM{}{\gamma}(\varphi\land\psi)^x$
        %
        \item[$(\land\text{E})$] If $\Gamma\suppM{}{\gamma}(\varphi\land\psi)^x$, then $\Gamma\suppM{}{\gamma}\varphi^x$ and $\Gamma\suppM{}{\gamma}\psi^x$
        %
        \item[$(\lor\text{I})$] If $\Gamma\suppM{}{\gamma}\varphi^x$ or $\Gamma\suppM{}{\gamma}\psi^x$, then $\Gamma\suppM{}{\gamma}(\varphi\lor\psi)^x$
        %
        \item[$(\lor\text{E})$] If $\Gamma\suppM{}{\gamma}(\varphi\lor\psi)^x$ and $\Gamma,\varphi^x\suppM{}{\gamma}\chi^y$ and $\Gamma,\psi^x\suppM{}{\gamma}\chi^y$, then $\Gamma\suppM{}{\gamma}\chi^y$
        %
        \item[$(\to\text{I})$] If $\Gamma,\varphi^x\suppM{}{\gamma}\psi^x$, then $\Gamma\suppM{}{\gamma}(\varphi\to\psi)^x$
        %
        \item[$(\to\text{E})$] If $\Gamma\suppM{}{\gamma}(\varphi\to\psi)^x$ and $\Gamma\suppM{}{\gamma}\varphi^x$, then $\Gamma\suppM{}{\gamma}\psi^x$
        %
        \item[$(\bot\text{E})$] If $\Gamma\suppM{}{\gamma}\bot^x$, then $\Gamma\suppM{}{\gamma}\chi^y$
        %
        \item[$(\Box\,\text{I})$] If $\Gamma,xRy\suppM{}{\gamma}\varphi^y$ for $y$ different to $x$ and not a label of any element of $\Gamma$, then $\Gamma\suppM{}{\gamma}(\Box\varphi)^x$.
        %
        \item[$(\Box\,\text{E})$] If $\Gamma\suppM{}{\gamma}(\Box\varphi)^x$ and $\Gamma\suppM{}{\gamma}xRy$, then $\Gamma\suppM{}{\gamma}\varphi^y$ 
        %
        \item[$(\Diamond\text{I})$] If $\Gamma\suppM{}{\gamma}\varphi^v$ and $\Gamma\suppM{}{\gamma}xRv$, then $\Gamma\suppM{}{\gamma}(\Diamond \varphi)^x$
        %
        \item[$(\Diamond\text{E})$] If $\Gamma\suppM{}{\gamma}(\Diamond\varphi)^x$ and $\Gamma,\varphi^a,xRa\suppM{}{\gamma}\psi^z$ for $a$ different to $x$ and $z$ and not a label of any element of $\Gamma$, then $\Gamma\suppM{}{\gamma}\psi^z$.
    \end{itemize}
    Additionally, if $\gamma\neq\emptyset$ we must show the following:
    \begin{itemize}
        \item[$(R_D)$] If $\gamma_D\in\gamma$ and $\Gamma,xRa\suppM{}{\gamma}\varphi^z$, for $a$ different to $x$ and $z$ and not a label of any element of $\Gamma$, then $\Gamma\suppM{}{\gamma}\varphi^z$
        %
        \item[$(R_T)$] If $\gamma_T\in\gamma$ and $\Gamma,xRx\suppM{}{\gamma}\varphi^y$ then $\Gamma\suppM{}{\gamma}\varphi^y$
        %
        \item[$(R_B)$] If $\gamma_B\in\gamma$ and $\Gamma\suppM{}{\gamma}xRy$ and $\Gamma,yRx\suppM{}{\gamma}\varphi^z$ then $\Gamma\suppM{}{\gamma}\varphi^z$
        %
        \item[$(R_4)$] If $\gamma_4\in\gamma$ and $\Gamma \suppM{}{\gamma} xRy$ and $\Gamma\suppM{}{\gamma}yRz$ and $\Gamma,xRz\suppM{}{\gamma}\varphi^w$ then $\Gamma\suppM{}{\gamma}\varphi^w$
        %
        \item[$(R_5)$] If $\gamma_5\in\gamma$ and $\Gamma \suppM{}{\gamma} xRy$ and $\Gamma\suppM{}{\gamma}xRz$ and $\Gamma,yRz\suppM{}{\gamma}\varphi^w$ then $\Gamma\suppM{}{\gamma}\varphi^w$
        %
        \item[$(R_2)$] If $\gamma_2\in\gamma$ and $\Gamma \suppM{}{\gamma} xRy$ and $\Gamma\suppM{}{\gamma}xRz$ and $\Gamma,yRw,zRw\suppM{}{\gamma}\varphi^v$, for $w$ different to $x,y,z,v$ and not a label of any element of $\Gamma$, then $\Gamma\suppM{}{\gamma}\varphi^v$.
    \end{itemize}

\begin{theorem}[Soundness]
    If $\Gamma\vdash^{\gamma}\varphi^x$, then $\Gamma\suppM{}{\,\gamma}\varphi^x$.
\end{theorem}

\begin{proof}

    We proceed by proving each of the cases listed above, under the additional hypothesis that we are in an arbitrary base $\baseB$ such that for all $\theta\in\Gamma$ we have that $\suppIML{\baseB}\theta$.
    \begin{itemize}
        \item[$(\text{R})$] $\varphi^x\suppIML{\baseB}\varphi^x$. This case is immediate by (Inf).
        %
        \item[$(\land\text{I})$] If $\suppIML{\baseB}\varphi^x$ and $\suppIML{\baseB}\psi^x$, then $\suppIML{\baseB}(\varphi\land\psi)^x$. This case follows immediately by the definition of $(\land)$.
        %
        \item[$(\land\text{E})$] If $\suppIML{\baseB}(\varphi\land\psi)^x$, then $\suppIML{\baseB}\varphi^x$ and $\suppIML{\baseB}\psi^x$. This case also follows immediately by the definition of $(\land)$.
        %
        \item[$(\lor\text{I})$] If $\suppIML{\baseB}\varphi^x$ or $\suppIML{\baseB}\psi^x$, then $\suppIML{\baseB}(\varphi\lor\psi)^x$. To show this case we suppose we have, for all $\baseC\baseGeq\baseB$ and basic sentences $p^y$, that $\varphi^x\suppIML{\baseC}p^y$ and $\psi^x\suppIML{\baseC}p^y$. We must show that $\suppIML{\baseC}p$. From the hypothesis, we have that $\suppIML{\baseB}\varphi^x$ or $\suppIML{\baseB}\psi^x$, which, by monotonicity, gives that $\suppIML{\baseC}\varphi^x$ or $\suppIML{\baseC}\psi^x$. In either case, by (Inf), we therefore obtain that $\suppIML{\baseC}p^y$, as required.
        %
        \item[$(\lor\text{E})$] If $\suppIML{\baseB}(\varphi\lor\psi)^x$ and $\varphi^x\suppIML{\baseB}\chi^y$ and $\psi^x\suppIML{\baseB}\chi^y$, then $\suppIML{\baseB}\chi^y$. We proceed by an inductive argument over the structure of the labelled formula $\chi^y$.
            \begin{itemize}[leftmargin=*]
                \item[-]$\chi = p$. In this case, we have sufficient hypotheses by the definition of $(\lor)$ to conclude $\suppIML{\baseB}p^y$, as required.
                %
                \item[-]$\chi = \alpha\land\beta$. In this case, by the definition of $(\land)$, we have that $\varphi^x\suppIML{\baseB}\alpha^y$ and $\varphi^x\suppIML{\baseB}\beta^y$, and similarly for  $\psi^x$. Thus, by the inductive hypothesis, we have that $\suppIML{\baseB}\alpha^y$ and $\suppIML{\baseB}\beta^y$, and so we are done.
                %
                \item[-]$\chi = \alpha\lor\beta$. In this case, we start by further supposing that we are in a base $\baseC\baseGeq\baseB$ and that we have, for all atoms $p^z$, that $\alpha^y\suppIML{\baseC}p^z$ and $\beta^y\suppIML{\baseC}p^z$. Our goal will be to show that $\suppIML{\baseC}p^z$. We want to show that $\varphi^x\suppIML{\baseC}p$ and $\psi^x\suppIML{\baseC}p^z$, which will give us sufficient grounds to then use our first hypothesis to give us our conclusion. We will only show $\varphi^x\suppIML{\baseC}p^z$ as the argument is similar for the other case. We start by observing that we have, by hypothesis, $\varphi^x\suppIML{\baseB}(\alpha\lor\beta)^y$. By monotonicity, this is $\varphi^x\suppIML{\baseC}(\alpha\lor\beta)^y$. By (Inf), this gives that, for all $\baseD\baseGeq\baseC$, $\suppIML{\baseD}\varphi^x$ implies $\suppIML{\baseD}(\alpha\lor\beta)^y$. Since we have that $\alpha^y\suppIML{\baseC}p^z$ and $\beta^y\suppIML{\baseC}p^z$, by hypothesis, then we  conclude that we have, for all $\baseD\baseGeq\baseC$, if $\suppIML{\baseD}\varphi^x$, then $\suppIML{\baseD}p^z$. By (Inf), this gives $\varphi^x\suppIML{\baseC}p^z$, as required. 
                %
                \item[-]$\chi = \alpha\to\beta$. In this case, we further suppose we are in a base $\baseC\baseGeq\baseB$ such that $\suppIML{\baseC}\alpha^y$. Our goal will be to show that $\suppIML{\baseC}\beta^y$. We start by considering the hypothesis $\varphi^x\suppIML{\baseB}(\alpha\to\beta)^y$. By monotonicity, we have that $\varphi^x\suppIML{\baseB}(\alpha\to\beta)^y$ and that, by (Inf), for all $\baseD\baseGeq\baseC$, if $\suppIML{\baseD}\varphi^x$, then $\suppIML{\baseD}(\alpha\to\beta)^y$. Since we have that $\suppIML{\baseC}\alpha^y$ by hypothesis, then, by monotonicity and (Inf), we conclude that we have for all $\baseD\baseGeq\baseC$, if $\suppIML{\baseD}\varphi^x$, then $\suppIML{\baseD}\beta^y$, which gives us $\varphi^x\suppIML{\baseC}\beta^y$. Similarly for $\psi^x$, at which point, by the inductive hypothesis, we can conclude that $\suppIML{\baseC}\beta^y$, as required.
                %
                \item[-]$\chi = \bot$. This case is immediate by the definition of $\bot^x$.
                %
                \item[-]$\chi=\Box \alpha$. Our goal will be to show that, $yRa\suppIML{\baseB}\alpha^a$ holds, for all labels $a$. With this in mind, we fix an arbitrary label $a$ and consider all bases $\baseC\baseGeq\baseB$, where $\suppIML{\baseC}yRa$ holds. We are left with showing $\suppIML{\baseC}\alpha^a$.
                To this end, consider the hypothesis $\varphi^x\suppIML{\baseB}(\Box\alpha)^y$. We immediately have that $\varphi^x\suppIML{\baseC}(\Box\alpha)^y$ by monotonicity. This is equivalent to considering all bases $\baseD\baseGeq\baseC$ for which $\suppIML{\baseD}\varphi^x$ implies $\suppIML{\baseD}(\Box\alpha)^y$. 
                The consequent of the previous implication is equivalent to considering all labels $b$ such that $yRb\suppIML{\baseD}\alpha^b$ which implies that in particular $yRa\suppIML{\baseD}\alpha^a$. Since, by hypothesis, we have that $\suppIML{\baseC}yRa$ and $\baseD\baseGeq\baseC$, then it is the case that $\suppIML{\baseD}\alpha^a$. It thus follows that $\varphi^x\suppIML{\baseC}\alpha^a$. The same argument gives that $\psi^x\suppIML{\baseC}\alpha^a$, so, by the inductive hypothesis, we can therefore obtain $\suppIML{\baseC}\alpha^a$, as required.
                %
                \item[-]$\chi=\Diamond \alpha$. We start by fixing a base $\baseC\baseGeq\baseB$ and an atom $p^w$, where $yRz,\alpha^z\suppIML{\baseC}p^w$, for all $z$. We must show that $\suppIML{\baseC}p^w$. The second hypothesis, by monotonicity, gives $\varphi^x\suppIML{\baseC}(\Diamond\alpha)^y$. 
                This equivalently gives us that, for all bases $\baseD\baseGeq\baseC$, $\suppIML{\baseD}\varphi^x$ implies that, for all bases $\baseE\baseGeq\baseD$ and atoms $p^a$, if $yRz,\alpha^z\suppIML{\baseE}p^a$, for all $z$, then $\suppIML{\baseE}p^a$. Thus, we can conclude that $\suppIML{\baseD}p^w$ and therefore $\varphi^x\suppIML{\baseC}p^w$. Similarly, we obtain $\psi^x\suppIML{\baseC}p^w$, and so, by the first hypothesis, we conclude $\suppIML{\baseC}p^w$, as required.
            \end{itemize}
        %
        \item[$(\to\text{I})$] If $\varphi^x\suppIML{\baseB}\psi^x$, then $\suppIML{\baseB}(\varphi\to\psi)^x$. This case follows immediately by the definition of $(\to)$.
        %
        \item[$(\to\text{E})$] If $\suppIML{\baseB}(\varphi\to\psi)^x$ and $\suppIML{\baseB}\varphi^x$ then $\suppIML{\baseB}\psi^x$. In this case, the first hypothesis, by (Inf), is equivalent to saying that for all bases $\baseC\baseGeq\baseB$, if $\suppIML{\baseC}\varphi^x$ then $\suppIML{\baseC}\psi^x$. By hypothesis, we have that $\suppIML{\baseB}\varphi^x$ and thus it follows that $\suppIML{\baseB}\psi^x$, as required.
        %
        \item[$(\bot\text{E})$] If $\suppIML{\baseB}\bot^x$, then $\suppIML{\baseB}\chi^y$. Since we have $\suppIML{\baseB}p^z$, for all atoms $p^z$, then by a simple inductive argument over the structure of $\chi^y$, we obtain $\suppIML{\baseB}\chi^y$, as required.
        %
        \item[$(\Box\,\text{I})$] If $xRy\suppIML{\baseB}\varphi^y$ for $y$ different to $x$, then $\suppIML{\baseB}(\Box\varphi)^x$. To show the conclusion, it suffices, by the definition of $(\Box)$, to show that, for all $z$, we have $xRz\suppIML{\baseB}\varphi^z$. Thus, it is required to show that $xRv\suppIML{\baseB}\varphi^v$, for some $v$ not equal to $x$, which we have, by hypothesis, by setting $v=y$. 
        %
        \item[$(\Box\,\text{E})$] If $\suppIML{\baseB}(\Box\varphi)^x$ and $\suppIML{\baseB}xRy$, then $\suppIML{\baseB}\varphi^y$. This case is immediate, since we consider the definition of $\suppIML{\baseB}(\Box\varphi)^x$ at the label $y$ to obtain the result.
        %
        \item[$(\Diamond\text{I})$] If $\suppIML{\baseB}\varphi^v$ and $\suppIML{\baseB}xRv$, then $\suppIML{\baseB}(\Diamond \varphi)^x$. To show $\suppIML{\baseB}(\Diamond \varphi)^x$, we start by additionally fixing a $\baseC\baseGeq\baseB$ and a $p^w$ such that $xRy,\varphi^y\suppIML{\baseC}p^w$ holds for all $y$ and show that $\suppIML{\baseC}p^w$. We have, by monotonicity, that both $\suppIML{\baseC}\varphi^v$ and $\suppIML{\baseC}xRv$ hold. Furthermore, since $xRy,\varphi^y\suppIML{\baseC}p^w$ holds for all $y$, then in particular, we have that $xRv,\varphi^v\suppIML{\baseC}p^w$. Therefore, we conclude $\suppIML{\baseC}p^w$, as required.
        %
        \item[$(\Diamond\text{E})$] If $\suppIML{\baseB}(\Diamond\varphi)^x$ and $\varphi^a,xRa\suppIML{\baseB}\psi^z$ for $a$ different to $x$ and $z$, then $\suppIML{\baseB}\psi^z$. We break the proof into a case analysis over the structure of $\psi^z$.
            \begin{itemize}[leftmargin=*]
                \item[-]$\psi = p$. We start by considering the second hypothesis. Since $a$ is a label different to $x$ and $z$ and didn't appear in any open assumptions, we conclude that $xRy,\varphi^y\suppIML{\baseB}p^z$ for all labels $y$. We thus have sufficient grounds to conclude, by the first hypothesis, that $\suppIML{\baseB}p^z$, as required.
                %
                \item[-]$\psi = \alpha\to\beta$. In this case, we start by fixing a $\baseC\baseGeq\baseB$ such that $\suppIML{\baseC}\alpha^z$. We want to show that $\suppIML{\baseC}\beta^z$. By monotonicity, the second hypothesis therefore gives that $\varphi^a,xRa\suppIML{\baseC}\beta^z$ from which it follows that $\varphi^y,xRy\suppIML{\baseC}\beta^z$ for all labels $y$. Since, by monotonicity, we have that $\suppIML{\baseC}(\Diamond\varphi)^x$, by applying the inductive hypothesis, we therefore obtain that $\suppIML{\baseC}\beta^z$, as required.
                %
                \item[-]$\psi = \alpha\land\beta$. In this case, the second hypothesis gives that $\varphi^a,xRa\suppIML{\baseB}(\alpha\land\beta)^z$, which equivalently gives $\varphi^a,xRa\suppIML{\baseB}\alpha^z$ and $\varphi^a,xRa\suppIML{\baseB}\beta^z$, and therefore, by the arbitrariness of $a$, that $\varphi^y,xRy\suppIML{\baseB}\alpha^z$ and $\varphi^y,xRy\suppIML{\baseB}\beta^z$, for all $y$. Thus, by the inductive hypothesis, we obtain that $\suppIML{\baseB}\alpha^z$ and $\suppIML{\baseB}\beta^z$, which gives $\suppIML{\baseB}(\alpha\land\beta)^z$, as required.
                %
                \item[-]$\psi = \alpha\lor\beta$. In this case, further fix a base $\baseC\baseGeq\baseB$ and an atom $p^w$ such that $\alpha^z\suppIML{\baseC}p^w$ and $\beta^z\suppIML{\baseC}p^w$. We want to show that $\suppIML{\baseC}p^w$. By monotonicity, taking the second hypothesis is equivalent to considering all $\baseD\baseGeq\baseC$ such that $\suppIML{\baseD}\varphi^a$ and $\suppIML{\baseD}xRa$ implies $\suppIML{\baseD}(\alpha\lor\beta)^z$. By definition, this is equivalent to considering all bases $\baseE\baseGeq\baseD$ and atoms $p^w$ such that $\alpha^z\suppIML{\baseE}p^w$ and $\beta^z\suppIML{\baseE}p^w$ implies $\suppIML{\baseE}p^w$. Since we have that $\alpha^z\suppIML{\baseC}p^w$ and $\beta^z\suppIML{\baseC}p^w$, then we can conclude that we have $\suppIML{\baseD}p^w$. Thus we have that $xRa,\varphi^a\suppIML{\baseC}p^w$, which implies that $xRy,\varphi^y\suppIML{\baseC}p^w$, for all $y$. Hence, by the first hypothesis, we get $\suppIML{\baseC}p^w$, as required.
                %
                \item[-]$\psi = \bot$. In this case, it suffices to show that $\suppIML{\baseB}p^b$, for an arbitrary atoms $p^b$. We note that the second hypothesis implies that $xRa,\varphi^a\suppIML{\baseC}p^b$ from which we conclude, by the arbitrariness of $a$, that $xRy,\varphi^y\suppIML{\baseB}p^w$, for all $y$. Hence, by the first hypothesis, we conclude $\suppIML{\baseB}p^b$, as required.
                %
                \item[-]$\psi = \Box\alpha$. In this case, further fix a label $v$ and a base $\baseC\baseGeq\baseB$, such that $\suppIML{\baseC}zRv$. We are left to show that $\suppIML{\baseC}\alpha^v$. By monotonicity, the second hypothesis gives, for all $\baseD\baseGeq\baseC$, that $\suppIML{\baseD}xRa$ and $\suppIML{\baseD}\varphi^a$ implies that, for all $y$, we have $zRy\suppIML{\baseD}\alpha^y$. Therefore, in particular, we have that $zRv\suppIML{\baseD}\alpha^v$. Since $\suppIML{\baseC}zRv$, we therefore conclude that $xRa,\varphi^a\suppIML{\baseC}\alpha^v$. By the arbitrariness of $a$, we therefore have that $xRa,\varphi^a\suppIML{\baseC}\alpha^v$, for all $y$. Since, by monotonicity, we have that $\suppIML{\baseC}(\Diamond\varphi)^x$, by applying the inductive hypothesis, we therefore obtain $\suppIML{\baseC}\alpha^v$, as required.
                %
                \item[-]$\psi = \Diamond\alpha$. In this case, further fix a base $\baseC\baseGeq\baseB$ and an atom $p^w$ for which $zRv, \varphi^v\suppIML{\baseC}p^w$ holds for all $v$. We want to show that $\suppIML{\baseC}p^w$. By monotonicity, the second hypothesis gives that, for all $\baseD\baseGeq\baseC$, $\suppIML{\baseD}\varphi^a$ and $\suppIML{\baseD}xRa$ implies $\suppIML{\baseD}(\Diamond\alpha)^z$. The conclusion of the previous implication is equivalent to considering all bases $\baseE\baseGeq\baseD$ and atoms $p^b$ such that if $zRv, \varphi^v\suppIML{\baseE}p^b$ for all $v$, then $\suppIML{\baseE}p^b$. Thus we conclude that $\suppIML{\baseD}p^w$ and so that $xRa,\varphi^a\suppIML{\baseC}p^w$. Therefore, we have that $xRy,\varphi^y\suppIML{\baseC}p^w$ for all $y$ from which, by the first hypothesis, we conclude that $\suppIML{\baseC}p^w$, as required.
            \end{itemize}
    \end{itemize}
    Now we consider the cases where $\gamma\neq\emptyset$. In each case, we assume that $\gamma$ contains that particular condition. We leave the proofs of all cases except for one as an exercise as they all follow exactly the same pattern. 
    \begin{itemize}[leftmargin=*]
        \item[$(R_D)$] If $xRa\suppIML{\baseB}\varphi^z$, for $a$ different to $x$, then $\suppIML{\baseB}\varphi^z$. We proceed by induction on the structure of $\varphi^z$.
        \begin{itemize}[leftmargin=*]
            \item[-] If $\varphi=p$, then we start by observing that there exists a $y$ such that $xRy\suppIML{\baseB}\varphi^z$. Thus, we are immediately done by the definition of $\deriveBaseIML{\baseB}$.
            %
            \item[-] If $\varphi=\alpha\land\beta$, then we have that $xRa\suppIML{\baseB}\alpha^z$ and $xRa\suppIML{\baseB}\beta^z$. By the inductive hypothesis, it follows that $\suppIML{\baseB}\alpha^z$ and $\suppIML{\baseB}\beta^z$, and so we can conclude $\suppIML{\baseB}(\alpha\land\beta)^z$, as required.
            %
            \item[-] If $\varphi= \alpha\to\beta$, then we have that $xRa\suppIML{\baseB}(\alpha\to\beta)^z$. We must show that  
            $\suppIML{\baseB}(\alpha\to\beta)^z$. With this in mind, we fix a base $\baseC\baseGeq\baseB$, where $\suppIML{\baseC}\alpha^z$, and show that $\suppIML{\baseC}\beta^z$ holds. 
            By monotonicity, we have that $xRa\suppIML{\baseC}(\alpha\to\beta)^z$, which is equivalent to having, for all $\baseD\baseGeq\baseC$ with $\suppIML{\baseD}xRa$, that $\alpha^z\suppIML{\baseD}\beta^z$. But since $\baseD\baseGeq\baseC$, where $\suppIML{\baseC}\alpha^z$, we therefore have that $\suppIML{\baseD}\beta^z$, and thus $xRa\suppIML{\baseC}\beta^z$, from which we conclude that there exists a $y$ such that $xRy\suppIML{\baseC}\beta^z$. By the inductive hypothesis, we therefore have that $\suppIML{\baseC}\beta^z$, as required. 
            %
            \item[-] If $\varphi = \alpha\lor\beta$, then we have that $xRa\suppIML{\baseB}(\alpha\lor\beta)^z$. Given a base $\baseC\baseGeq\baseB$ and an atom $p^w$ such that $\varphi^z\suppIML{\baseC}p^w$ and $\psi^z\suppIML{\baseC}p^w$, we want to show that $\suppIML{\baseC}p^w$. 
            We start by considering that, by monotonicity, we have $xRa\suppIML{\baseC}(\alpha\lor\beta)^z$, which is equivalent to considering all bases $\baseD\baseGeq\baseC$ for which $\suppIML{\baseD}xRa$ implies $\suppIML{\baseD}(\alpha\lor\beta)^z$. The conclusion of the previous implication is equivalent to considering all bases $\baseE\baseGeq\baseD$ and atoms $q^v$, where $\varphi^z\suppIML{\baseE}q^v$ and $\psi^z\suppIML{\baseE}q^v$ implies $\suppIML{\baseE}q^v$. 
            Since we have by hypothesis that $\varphi^z\suppIML{\baseC}p^w$,  $\psi^z\suppIML{\baseC}p^w$, and $\baseE\baseGeq\baseC$, we therefore conclude that $xRa\suppIML{\baseC}p^v$, and thus that there exists a $y$ such that $xRa\suppIML{\baseC}p^v$. Then, by the definition of $\deriveBaseIML{\baseC}$, we obtain $\suppIML{\baseC}p^v$, as desired.
            %
            \item[-] If $\varphi = \bot$, then we have that $xRa\suppIML{\baseB}\bot^z$ and we must show that $\suppIML{\baseB}\bot^z$. By definition, for each $p^w$, there exists a $y$ such that $xRy\suppIML{\baseB}p^w$ for any $p^w$, and so, by the definition of $\deriveBaseIML{\baseB}$, we obtain $\suppIML{\baseB}p^w$, for all $p^w$. Therefore $\suppIML{\baseB}\bot^z$.
            %
            \item[-] If $\varphi = \Box\alpha$, then we have that $xRa\suppIML{\baseB}(\Box\alpha)^z$ and we must show, given a base $\baseC\baseGeq\baseB$ such that $\suppIML{\baseC}zRw$ for an arbitrary $w$, that $\suppIML{\baseC}\alpha^w$. By monotonicity, we have $xRy\suppIML{\baseC}(\Box\alpha)^z$, which is equivalent to considering all bases $\baseD\baseGeq\baseC$ for which $\suppIML{\baseD}xRy$ implies $\suppIML{\baseD}(\Box\alpha)^z$. The conclusion of the previous implication is equivalent to considering all labels $v$ such that $zRv\suppIML{\baseD}\alpha^v$. Since we have $\suppIML{\baseC}zRw$, then we have, in particular, that $\suppIML{\baseD}\alpha^v$ and thus $xRa\suppIML{\baseC}\alpha^w$. We therefore have that there exists a $y$ such that $xRa\suppIML{\baseC}\alpha^w$ from which, by the inductive hypothesis, we obtain $\suppIML{\baseC}\alpha^w$, as required.
            %
            \item[-] If $\varphi = \Diamond\alpha$, then we have that $xRa\suppIML{\baseB}(\Diamond\alpha)^z$. To show this, we begin by fixing a base $\baseC\baseGeq\baseB$ and an atom $p^w$ such that $zRa,\alpha^a\suppIML{\baseC}p^w$ for all a, with the goal of showing that $\suppIML{\baseC}p^w$. By monotonicity, we have that $xRa\suppIML{\baseC}(\Diamond\alpha)^z$, which gives that, for all $\baseD\baseGeq\baseC$, we have that $\suppIML{\baseD}xRy$ implies, for all $\baseE\baseGeq\baseD$ and all atoms $q^v$, if $zRb,\alpha^b\suppIML{\baseE}q^v$ for all $b$, then $\suppIML{\baseE}q^v$. Since we have $zRa,\alpha^a\suppIML{\baseC}p^w$, we therefore can obtain by monotonicity that $\suppIML{\baseD}p^w$ and therefore $xRa\suppIML{\baseC}p^w$, and thus that there exists a $y$ such that $xRy\suppIML{\baseC}p^w$. Thus, by the definition of $\deriveBaseIML{\baseC}$, we conclude $\suppIML{\baseC}p^w$, as desired.
        \end{itemize}
        %
        \item[$(R_T)$] If $xRx\suppIML{\baseB}\varphi^y$, then $\suppIML{\baseB}\varphi^y$. 
        %
        \item[$(R_B)$] If $\suppIML{\baseB}xRy$ and $yRx\suppIML{\baseB}\varphi^z$, then $\suppIML{\baseB}\varphi^z$. 
        %
        \item[$(R_4)$] If $\suppIML{\baseB}xRy$, $\suppIML{\baseB}yRz$, and $xRz\suppIML{\baseB}\varphi^z$, then $\suppIML{\baseB}\varphi^v$.
        %
        \item[$(R_5)$] If $\suppIML{\baseB}xRy$, $\suppIML{\baseB}xRz$, and $yRz\suppIML{\baseB}\varphi^v$, then $\suppIML{\baseB}\varphi^v$.
        %
        \item[$(R_2)$] If $\suppIML{\baseB}xRy$, $\suppIML{\baseB}yRz$, and $yRw,zRv\suppIML{\baseB}\varphi^w$, then $\suppIML{\baseB}\varphi^w$, for $w$ different to $x,y,z,v$.
    \end{itemize}
    This concludes the proof of soundness. \fillBox
\end{proof}

\section{Completeness} \label{sec:completeness}

We now show that, given an arbitrary valid sequent $(\Gamma:\varphi^x)$, there exists an $\rm N_{\Box\Diamond}(\gamma)$ proof of it. To show this, we will construct a special base, called $\base{N}$, whose rules will mimic the natural deduction rules of $\rm N_{\Box\Diamond}(\gamma)$, with basic sentences playing the role of (or simulating) the subformulae of the arbitrary sequent. Since the base rules can only be in terms of basic sentences and not formulae, we must be careful, as described below, about how we choose the assignment of basic sentences. 

We then show that derivations in $\base{N}$ directly correspond to natural deduction derivations of the formulae being simulated. Thus, in effect, we show that the sequent $(\Gamma:\varphi^x)$ is provable in $\rm N_{\Box\Diamond}(\gamma)$ by constructing the proof. 

To this end, we fix an arbitrary valid sequent $\mathfrak{S}=(\Gamma:\varphi^x)$ and let $\Xi$ be the set of generalized subformulae of the sequent. We define the generalized subformulae of a formula $\varphi$ as follows:
\begin{itemize}
    \item[-]if $\varphi^x$ is an atom $p^x$, then the only generalized subformula of $p^x$ is $p^x$ itself
    \item[-]if $\varphi^x$ is either $\top^x$ or $\bot^x$, then the only generalized subformula of $\varphi^x$ is $\top^x$ or $\bot^x$, respectively
    \item[-]if $\varphi^x$ is $(\alpha\circ\beta)^x$ for $\circ \in \{\land,\lor,\to\}$, then the generalized subformulae of $\varphi^x$ are $\varphi^x$, $\alpha^x$, and $\beta^x$
    \item[-]if $\varphi^x$ is $(\circ\alpha)^x$ for $\circ \in \{\Box,\Diamond\}$, then the generalized subformulae of $\varphi^x$ are $\varphi^x$, $\alpha^z$, and $xRz$, for all $z\in\Worlds$. %\yll{Write something about how this is motivated by the meta-logical reading of these connectives (i.e., $\forall x'(xRx' \supset \varphi^{x'})$ and $\exists x'(xRx' \,\&\,\varphi^{x'})$ where $\forall, \exists, \supset, \&$ are meta-logical connectives.}
\end{itemize}
Define the set $\text{Lab}(\Xi) = \{a\,|\,\xi^a\in \Xi\}\cup\{a , b \,|\,aRb\in\Xi \}$ as the set of labels of each element of $\Xi$. We define an injection $\flatIML{\cdot}:\Xi \rightarrow \Worlds\times\At$, called the flattening map, such that:
\begin{itemize}
    \item[-] It is the identity map on atoms and on $\top^x$ and $\bot^x$. 
    \item[-] For non-atomic formulae, $\alpha^x$, and relational assumptions $vRw$, it picks an $p^x$, where $p^x \notin \Xi$, and, for all $\alpha^x,\beta^y\in \Xi$, if $\alpha^x\neq\beta^y$, then $\flatIML{\alpha^x}\neq\flatIML{\beta^y}$. %That is, it is label-preserving for labelled formulae.
\end{itemize}
$\flatIML{\cdot}$ has a left inverse $\deflatILL{(\cdot)}$, defined by:
\begin{itemize}
    \item[-] The identity map on basic sentences and on $\top^x$ and $\bot^x$.
    \item[-] The original labelled formula otherwise.
\end{itemize}
These functions are defined to be distributing over sets; that is, given a set of labelled formulae $\Gamma$, we define $\Gamma^\flat = \{\flatIML{\gamma^x}\,|\, \gamma^x \in \Gamma \}$ and $\Gamma^\natural = \{\deflatIML{\gamma^x}\,|\, \gamma^x \in \Gamma \}$. 

We can now define the simulation base $\base{N}$ relative to $\Xi$ and $\flatIML{\cdot}$ according to the rules of Figure~\ref{fig:FlatNatDedIML}, where
\begin{itemize}
\item[-] $p^z$ ranges over all atoms, 
\item[-] $\varphi^x$, $\varphi^z$, and $\psi^x$ range over elements of $\Xi$,
\item[-] the formula $\varphi^y$ in the rule $(\irn\Box^\flat)$ ranges over all elements of $\Xi$ such that $y\neq x$ for each $\flatIML{(\Box\varphi)^x}$,
\item[-] the formula $\varphi^y$ in the rule $(\ern\Diamond^\flat)$ ranges over all elements of $\Xi$ such that $y\neq x$, and $y\neq z$, for each  $\flatIML{(\Diamond\varphi)^x}$ and $p^z$. 
\end{itemize}

