% 	\label{eq_DESC}
% 		x_z^{(t)} = \frac{1}{w} \sum_{k=0}^{w-1} \epsilon_{z-k}\lambda\left(1-\frac{1}{w} \sum_{j=0}^{w-1}\rho(1-x_{z+j-k}^{(t-1)})\right)
% 	\end{equation}
% where $\lambda(x) = L^\prime(x)/L^\prime(1)$, $\rho(x) = R^\prime (x) / R^\prime(1)$, $\epsilon_z = \epsilon$ for $z \in [N]$, and zero otherwise. We set $x_z^{(0)}=1$ for $z \in [1,N+w-1]$. For the boundary values, $z \notin [1,N+w-1]$, we set $x_z^{(t)} = 0 $ for all $t$.

	\subsection{Window Decoding}
 WD is a decoding scheme designed based on the structure of spatially coupled LDPC codes, which allows for balancing performance with reduced complexity and decoding latency \cite{iyengar2011windowed}. Assume that the window size is \( W \). The first window consists of the variable nodes and check nodes from positions \( 1 \) to \( W \). The WD performs \( T \) iterations of BP decoding over the subgraph contained in the first window. Then, the window slides one position to the right, meaning the new window consists of the variable nodes and check nodes from positions \( 2 \) to \( W+1 \). Another \( T \) iterations are performed on the subgraph contained in the new window. This procedure proceeds until $T$ iterations have been completed on the subgraph consisting of the final $W$ positions of variable nodes and check nodes. During the decoding process, the window is referred to as the \( c \)th window configuration if it consists of the variable nodes and check nodes at positions \( c, c+1, \ldots, c+W-1 \) with $c \in [N-W+1]$.




Consider the SC-LDPC$(L, R, N, w)$ ensemble, let $x_z^{(c,t)}$ be the average erasure probability of a message incoming to check nodes in position $z \in \mathbb{Z}$ in the $c$th window configuration at iteration $t$. Let $\boldsymbol{x^{(c,t-1)}} = \{x_1^{(c,t-1)},\dots,x_{N+w-1}^{(c,t-1)}\}$, the DE equation \cite{iyengar2012windowed} is
\begin{equation}
\label{WD_DE1}
{x_z^{(c,t)}} =f(z,\boldsymbol{x^{(c,t-1)}};c,w,W,\epsilon),
\end{equation}
\begin{equation}
		\label{WD_DE2}
        \begin{split}
          &x_z^{(c+1,0)} = x_z^{(c,T)}, \\
          &\quad 
        \end{split}
	\end{equation}
 where $f(z,\boldsymbol{x^{(c,t-1)}};c,w,W,\epsilon)$	is defined as
	\begin{equation}
	\label{f_z}
		\begin{cases}
			\frac{1}{w} \sum\limits_{k=0}^{w-1} \epsilon_{z-k} \lambda(1-\frac{1}{w}\sum\limits_{j=0}^{w-1}\rho (1-x_{z+j-k}^{(c,t-1)}))        \\
			{\text{\;\;\;\;\;\;\;\;\;\ if}}\ z \in \{c,c+1,\cdots,c+W-1\} \\ 
			{x_z^{(c,t-1)},}       {\text{\;\;\;\;\;\;\;\;\;\; otherwise,}} 
		\end{cases}
		\end{equation}
\[\lambda(x) = L^\prime(x)/L^\prime(1),\rho(x) = R^\prime (x) / R^\prime(1),\]
for all $z \in [N+w-1]$, $c \in [N-W+1]$ and $t \in [T]$. We set $\epsilon_z=\epsilon$ for $z \in [N]$, and zero otherwise. The initial state of the decoding is set as $x_z^{(1,0)} = 1$ for all $z \in [N+w-1]$. For the boundary values, $z \notin [1,N+w-1]$, we set $x_z^{(c,t)} = 0$ for all $c \in [N-W+1]$ and $t\in \{0,1,\dots,T\}$. 

	\subsection{Potential Function}
The potential function defined on LDPC$(n, L, R)$ ensemble has been introduced and studied in \cite{aref2013convergence} and \cite{yedla2012simple1}. It is formally defined as follows: 
	\begin{equation}
		\label{U_LDPC}
		\begin{split}
			U(x;\epsilon) = \frac{1}{R^\prime(1)}(1-R(1&-x))-x\rho(1-x)\\
			&-\frac{\epsilon}{L^\prime(1)}L(1-\rho(1-x)).
		\end{split}
	\end{equation}


	Now consider the SC-LDPC($L, R, N, w$) ensemble. Similar to \cite{aref2013convergence}, the potential function under the $c$th window configuration is defined as follows:    
    \begin{equation}
	\label{WD_Udef}
	\begin{split}
		\frac{\partial}{\partial x_z} U(\boldsymbol{x};\epsilon,c,w,W) = \rho^\prime(1-x_z)\left(x_z-f(z,\boldsymbol{x};c,w,W,\epsilon)\right),
	\end{split}
	\end{equation}
where $\boldsymbol{x}=\{x_1,
\dots,x_{N+w-1}\}$ for all $z \in [N+w-1]$. It is straightforward to verify that the stationary points of the potential function correspond to the fixed points of the DE equation (\ref{WD_DE1}).

	Combining (\ref{f_z}), we can express the potential function under $c$th window configuration as follows:
    \begin{equation}
	\begin{split}	&U(\boldsymbol{x};\epsilon,c,w,W) =\sum_{z = c-(w-1)}^{c+W-1}  \frac{1}{R^\prime(1)}(1-R(1-x_z))-\\ &x_z\rho(1-x_z)-\frac{\epsilon}{L^\prime(1)}L\left(1-\frac{1}{w}\sum_{j=0}^{w-1}\rho(1-x_{z+j})\right).
	\end{split}
	\end{equation}
where $x_z = 0$ for all $z \notin [N+w-1]$. For notational simplicity, we omit $w$ and $W$ from the expression and write $U(\boldsymbol{x};\epsilon,c)$, with the understanding that $w$ and $W$ are fixed unless otherwise stated.

	Define the vector $\boldsymbol{y}$ as $y_z = x_z^{(c,t)} + h(x_z^{(c,t+1)}-x_z^{(c,t)})$ for $0 \le h \le 1$. Treat $\boldsymbol{x}^{(c,t)}$ as a known vector, we write the Taylor expansion of $U(\boldsymbol{y};\epsilon,c)$ around $U(\boldsymbol{x}^{(c,t)};\epsilon,c)$:
	\begin{equation}
		\begin{split}
			U(\boldsymbol{y};\epsilon,c) = &U(\boldsymbol{x}^{(c,t)};\epsilon,c) + \Delta U_1(\boldsymbol{y},\boldsymbol{x}^{(c,t)};c) \\
            &+ R_1(\boldsymbol{y},\boldsymbol{x}^{(c,t)};c)\\
            &\quad 
		\end{split}
	\end{equation}
	where $\Delta U_1(\boldsymbol{y},\boldsymbol{x}^{(c,t)};c) = \sum_{z=c}^{c+W-1} \frac{\partial U(\boldsymbol{y};\epsilon,c)}{\partial y_z} \Big|_{y_z = x_z^{(c,t)}} (y_z - x_z^{(c,t)})$, $R_1(\boldsymbol{y},\boldsymbol{x}^{(c,t)};c)$ is the remainder term.
	Citing the conclusion from \cite{aref2013convergence}, we have 
	\begin{equation}
	\label{daoshu}
	\alpha (U(\boldsymbol{y};\epsilon,c) - U(\boldsymbol{x}^{(c,t)};\epsilon,c)) \le \Delta U_1(\boldsymbol{y},\boldsymbol{x}^{(c,t)};c)
	\end{equation}
	with $1\le \alpha \le 2$. Although the results in \cite{aref2013convergence} pertain to BP decoding, a similar proof can be applied to reach this conclusion. Following \cite{aref2013convergence}, we set $\alpha =1$ in the subsequent simulation experiments.

