\section{PROOF OF THE THEOREM \ref{th1}}
% {\appendices[PROOF OF THE THEOREM \ref{th1}]
	Recall that $x_z^{(c,t)}$ is an increasing sequence in terms of $z$ and a decreasing sequence in terms of $t$. And \( c^\prime \) be the constant such that 
 \begin{equation}
\label{assume_appe}
 x_z^{(c,0)} = x_{z+1}^{(c+1,0)} = x_{z+1}^{(c,T)}
\end{equation}
holds for all \( c \ge c^\prime\) and $z \in [N+w]$. 
	According to (\ref{daoshu}), 
\begin{equation}
\begin{split}
\label{cw_xianglin}
	&\alpha \left(U(\boldsymbol{x}^{(c,t+1)};\epsilon,c) - U(\boldsymbol{x}^{(c,t)};\epsilon,c) \right)\\
	&\le \sum_{z=c}^{c+W-1}-\rho^\prime(1-x_z^{(c,t)})(x_z^{(c,t+1)}-x_z^{(c,t)})^2\\
    &\quad
\end{split}
\end{equation}
for $t \in \{0,1,\dots,T-1\}$. By summing (\ref{cw_xianglin}) with respect to $t$, we obtain:
\[
\begin{split}
		\label{T}
		&\alpha \left(U(\boldsymbol{x}^{(c,T)};\epsilon,c) - U(\boldsymbol{x}^{(c,0)};\epsilon,c) \right)\\
		&\le \sum_{t=0}^{T-1}\sum_{z=c}^{c+W-1}-\rho^\prime(1-x_z^{(c,t)})(x_z^{(c,t+1)}-x_z^{(c,t)})^2.
	\end{split}
\]
Now, consider the right-hand side of the above inequality and let us exchange the order of the sums. Then for each $z$, we minimize the following summation:
$$
\sum_{t=0}^{T-1} \rho^\prime(1-x_z^{(c,t)})(x_z^{(c,t+1)}-x_z^{(c,t)})^2 = \sum_{t=0}^{T-1} \rho^\prime(1-x_z^{(c,t)})l_t^2,
$$
where $l_t = x_z^{(c,t)}-x_z^{(c,t+1)}$. 

Due to (\ref{assume_appe}) and $x_z^{(c,t)}$ is a decreasing sequence in terms of $t$, $l_t>0$ and
$$
\sum_{t=0}^{T-1}l_t = x_z^{(c,0)} - x_z^{(c,T)} = x_z^{(c,0)} - x_{z-1}^{(c,0)}.
$$

The application of Jensen's inequality leads to 
$$
\frac{1}{T}\sum_{t=0}^{T-1}l_t^2 \ge \left(\frac{1}{T}\sum_{t=0}^{T-1}l_t\right)^2 = \frac{1}{T^2}(x_z^{(c,0)} - x_{z-1}^{(c,0)})^2,
$$
and thus,
\[
\begin{split}
	&\alpha \left(U(\boldsymbol{x}^{(c,0)};\epsilon,c) -U(\boldsymbol{x}^{(c+1,0)};\epsilon,c)\right)\\
	& \ge \sum_{z=c}^{c+W-1} \frac{1}{T} \rho^\prime(1-x_z^{(c,0)}) (x_z^{(c,0)} - x_{z-1}^{(c,0)})^2.
\end{split}
\]


