The famous Curtis-Hedlund-Lyndon theorem established that CCAs are exactly those continuous maps commuting with the shift and
can be formally stated as follows.
\begin{theorem}\cite[Th. 3.4 p. 324]{hedlund69}
    The class of CCAs are exactly the class of continuous mappings $f\colon\setofstates^\lattice\to\setofstates^\lattice$ such that for all $j\in\N$, $f\circ\sigma^j=\sigma^j\circ f$.
\end{theorem}

\section{The Space of Probability Measures}
\label{proba}

In the following let us suppose that the state space $S$ is endowed with a metric $d$ and that $(S,d)$ is a compact metric space. The space $S$ can be discrete as $\{0,1\}$ or continuous as $[0,1]$. Let $\mathcal{B}(S)$ be the Borel sigma-algebra defined on $S$. Let us denote by $\mathcal{M}(S)$ the set of all probability measures defined on $S$. $\mathcal{M}(S)$ can be endowed with the Monge-Kantorovich metric defined as:

\begin{equation}
d_{MK}(\mu,\nu) = \sup_{f\in Lip_1(S)} \int_S f d\mu - \int_S f d\nu     
\end{equation}

where $Lip_1(S)$ is the set of all Lipschitz-1 functions on $S$, that is 

\begin{equation}
Lip_1(S) = \{f:S\to\R\text{ s.\@\,t.\@\;} |f(x)-f(y)|\le d(x,y)\}.   
\end{equation}

{\color{black}
The Monge-Kantorovic metric arose from a classical problem in transportation of mass \cite{Mendivil2015}. 
%is often used for comparing probabilistic approximations \cite{Mendivil2015}. 
Since then it has been employed in many applications areas, several of which are stochastic in nature and require a means to measure the distance between two probability measures. 
%It is one of many different metrics which can be endowed on the set of probability measures in order to yield the topology of weak convergence \cite{Durrett1992}.
Indeed, the set of probability measures can be equipped with the Monge-Kantorovich metric in order to yield the topology of weak convergence \cite{Durrett1992}.
A particularly important feature of the Monge-Kantorovich distance is that it %incorporates 
is tied to the underlying metric $d$ on the space $S$. A simple example illustrating this link is provided below. 
}

\begin{proposition}
Let us suppose that $S$ is a finite and discrete set. Let $d$ the discrete metric defined on $S$, and let us consider the set $D\subseteq \mathcal{M(S)}$ 
composed by all Dirac measures on $S$, that is
\begin{equation}
\mathcal{D} = \{\delta_s, s\in S \}.    
\end{equation}
Then the metric $d_{MK}$ collapses to the discrete metric $d$ on $\mathcal{D}$.
\end{proposition}

\begin{proof}
Let us consider two points $s$ and $t$ in $S$ and the associated Dirac probability measures $x=\delta_s$ and $y=\delta_t$.
Computing $d_{MK}(x,y)$ yields
\begin{equation}
d_{MK}(x,y) = \sup_{f\in Lip_1(S)} f(s) - f(t) = d_D(s,t) ,
\end{equation}

that is, the $d_{MK}$ metric collapses to the discrete metric $d$.
\end{proof}

% maybe this example needs to go later
{\color{black}
%The metric $d_{MK}$ is also easy to compute when $S=[0,1]$.
%Because Bernoulli probability measure can be exactly characterized by the probability $p \in [0,1]$, the set of states $S=[0,1]$ corresponds to the case of (possibly distinct) Bernoulli distributions in each cell of the CA.

The following result shows that the metric $d_{MK}$ may be easily computed for real-valued probability measures. 

%\textcolor{red}{EF:} I think we need to put a reference here for Proposition 2.
\begin{proposition}\cite{vallender1974}
    Let $\mu$ and $\nu$ be two probability measures on $S \subset \mathbb{R}$ and denote their cumulative distribution functions by $F_\mu$ and $F_\nu$, respectively. Then the metric $d_{MK}$ can be expressed as
    \begin{equation}
        d_{MK}(\mu, \nu) = \int_\mathbb{R} \lvert F_\mu - F_\nu \rvert dx.
    \end{equation}
\end{proposition}

Note that $d_{MK}$ simplifies even further in the case of Bernoulli probability measures. Let $\mu$ be a Bernoulli measure with probability $q$ and $\nu$ be a Bernoulli measure with probability $p$. Then,
\begin{equation}
    d_{MK}(\mu, \nu) = \int_\mathbb{R} \lvert F_\mu - F_\nu \rvert dx =  \ \int_0^1 \lvert (1-q) - (1-p) \rvert dx = \lvert p-q\rvert.
    \label{eqn:L1}
\end{equation}
In words, we obtain the desirable property that the Monge-Kantorovich distance simplifies to the $L^1$ distance between the probabilities $p$ and $q$.
}

\begin{remark}
Let us notice that for 
$f\in Lip_1(S)$ and 
$0\in S$ it holds

\begin{equation}
\int_S f d\mu - \int_S f d\nu  \le \int_S f(0)+ d(x,0) d\mu - \int_S f(0)-d(x,0)d\nu \le 2 K  
\end{equation}

where $K=\max_{x\in S} d(x,0)$. In other words, $d_{MK}(\mu,\nu)\le 2K$ for any $\nu,\mu\in \mathcal{M}(S)$, and hence $(d_{MK}, \mathcal{M(S)})$ is a bounded metric space.
\end{remark}


\begin{proposition}
\cite{hutchinson1981fractals}
If $(S,d)$ is a compact metric space then
the metric space $(\mathcal{M}(S),d_{MK})$ is compact and, therefore, complete.
\end{proposition}

%{\color{blue}
Let us notice that the space $\mathcal{M}(S)$ is not a group but it is closed with respect to the convex combination of probability measures (see \cite{barnsley2014fractals, hutchinson1981fractals,kunze2011} for more details).
%}

\begin{proposition}
\cite{barnsley2014fractals} 
Let $\mu_1,\mu_2,...,\mu_n\in \mathcal{M}(S)$ and $\nu_1,\nu_2,...\nu_n\in \mathcal{M}(S)$ be two sets of probability measures and $\lambda_1, \lambda_2, ...,\lambda_n$ a set of weights such that $\sum_{j=1}^n \lambda_j = 1$. Then, the following inequality holds:

\begin{equation}
d_{MK} \left(\sum_{j=1}^n \lambda_j \mu_j,\sum_{j=1}^n \lambda_j \nu_j\right)\le \sum_{j=1}^n \lambda_j d_{MK}(\mu_j,\nu_j)   
\end{equation}

\end{proposition}

\section{Cellular Automata on Probability Measures}

A Cellular Automaton on probability Measures (CAM) is defined on configurations whose elements are probability measures. In other words, in this new setting, the standard state set $S$ is replaced with $\mathcal{M}(S)$. 
Let us notice that this definition collapses to the classical one when the probability measure in the cell $i$ coincides with the Dirac measure on a specific state $s\in S$. In other words, a string of states for a CCA can be embedded into this new stochastic framework by associating with each cell element $s\in S$ the probability mass at $s$.

%It is easy to prove that $\mathcal{M(S)}^L$ is also closed with respect to the convex combination of its elements. 
{\color{black}
In the classical setting where $S$ is a discrete set of states, $S^L$ is not a convex space. A nice property of our framework, as we prove below, is that $\MSL$ is closed with respect to convex combinations of configurations. This fact motivates a particularly interesting choice of local rule which we will define in the next section.  
}

We are now ready to introduce the distance $d_\mathcal{M}$ between two different configurations $x$ and $y$ in $\MSL$, which relies on the Monge-Kantorovich distance $d_{MK}$ between the measures $x_i$ and $y_i$ defined in each cell.

\begin{definition}
For any pair of elements $x,y\in \mathcal{M}(\setofstates)^\lattice$, let us define the function

\begin{equation}
d_{\mathcal{M}}(x,y) = 
\sum_{i\in\lattice} \frac{d_{MK}(x_i,y_i)}{2^{|i|}}    
\end{equation}
where $|\cdot|$ is the norm of $i$.
\end{definition}


%A simple example to illustrate our new framework follows.
We now present a simple example illustrating this new framework.
\begin{example}
 Consider $\setofstates=\set{0,1}$ and the set of all possible discrete probability measures on \setofstates. Any probability can take only two values $p$ and $1-p$, respectively. Let us now consider a set of possible configurations in $\setofstates^\Z$ and, for the sake of simplicity, consider the elements $x_{-1}$, $x_0$ and $x_1$ at the time $t$. We now consider the transition map that associates each triple as above with a new probability measure defined by the convex combinations of $x_{-1}$, $x_0$, and $x_1$ with weights $\lambda_{-1}$, $\lambda_0$, and $\lambda_1$, respectively. An illustration is provided in Fig. \ref{CAbasicgraph} with $\lambda_{-1}=0.2$, $\lambda_0=0.4$, and $\lambda_{1}=0.4$. 
Let us notice, using Eq.~(\ref{eqn:L1}), that in this case the CA $(\setofstates^\Z,d_{\mathcal{M}})$ is 
equivalent to the CA $([0,1]^\Z,d^*_{L^1})$ where $d^*_{L^1}$ is the weighted $L^1$ distance defined as;
$$
d^*_{L^1}(x,y)= \sum_{k=-\infty}^{+\infty} \frac{|x_k-y_k|}{2^{|k|}}
$$\qed
\end{example}

