The following result shows that the shift map is Lipschitz. 

\begin{proposition}
For any $j\in \lattice$, the shift map  $\sigma_j(x)_i=x_{i+j}$ is Lipschitz continuous on 
$(\mathcal{M(S)}^L,d_{\mathcal{M}})$.
\end{proposition}

\begin{proof}
To prove it, let us take two elements $x$ and $y$ in $\mathcal{M(S)}^L$ and calculate the distance between $\sigma_j(x)$ and $\sigma_j(y)$. Computing, we have:
\begin{align}
d_{\mathcal{M}}(\sigma_j(x),\sigma_j(y)) &=
\sum_{i\in\lattice} {d_{MK}((\sigma_j(x))_i,(\sigma_j(y))_i)\over 2^{|i|}} \nonumber\\ 
&=
\sum_{i\in\lattice} {d_{MK}(x_{i+j},y_{i+j})\over 2^{|i|}}
\end{align}
and by doing the substitution $k=i+j$ and remembering that $|j-k|=|k-j|\ge |k| - |j|$ we have that
\begin{align}
d_{\mathcal{M}}(\sigma_j(x),\sigma_j(y)) &=
\sum_{k\in\lattice} {d_{MK}(x_{k},y_{k})\over 2^{|j-k|}} \le 
\sum_{k\in\lattice} {d_{MK}
(x_{k},y_{k})\over 2^{|k|-|j|}} \nonumber\\[2mm] 
&=
2^{|j|} \sum_{k\in\lattice} {d_{MK}(x_{k},y_{k})\over 2^{|k|}} = 2^{|j|} d_{\mathcal{M}}(x,y)
\end{align}
\end{proof}
