%\end{proposition}

It is easy to prove that the shift map $\sigma_j$ has an uncountable set of fixed points, namely all constant sequences taking the form $x_i=\mu$ for any probability measure $\mu\in \mathcal{M}(\setofstates)$.

The following result presents the case of a contraction mapping $f$ on \MSL.

\begin{proposition}
Let $f:\MSL\to\MSL$ be a contraction mapping, that is there exists a constant $c_f\in [0,1)$ such that:
\begin{equation}
d_{\mathcal{M}}(f(x),f(y))\le C d_{\mathcal{M}}(x,y)    
\end{equation}
Then, $f$ has a unique fixed point $\bar x\in \mathcal{M(S)}^\lattice$, and for any configuration $x^0\in \mathcal{M(S)}^\lattice$ the orbit $f^n(x^0)$ converges to $\bar x$ whenever $n\to +\infty$. 
\end{proposition}

\begin{proof}
The proof follows by applying Banach's fixed point theorem \cite{kunze2011} to the complete metric space $\mathcal{M(S)}^\lattice$. 
\end{proof}

\section{A Local Rule: The Convex Combination Map}
\label{sec:convex-combination-map}

In this section we explore the properties of a specific local rule $\delta_C$ which is defined as follows.
For any $i \in \lattice$ and all $j\in N_r(i)$, let $\{\lambda_j\}$ be a set of weights in $[0,1]$ such that $\sum_{j\in N_r(i)} \lambda_j = 1$. 
%\ef{We shall quantify also \wrt to $i$ here otherwise it seems incoherent (no matter if $\lambda_j$ does not depend on $i$)}
Let us notice that the set of weights $\lambda_j$ is only dependent on the position of the element $j\in N_r(i)$ and is not dependent on $i$.  
Let $T: \mathcal{M(S)}\to \mathcal{M(S)}$ be a map defined on the space of probability measures $\mathcal{M(S)}$.
For any $x\in \MSL$ the action of $\delta_C$ on $x$ is defined as 
\begin{equation}
(\delta_C(x))_i = \sum_{j\in N_r(i)} \lambda_j T(x_j)    
\label{eqn:ccrule}
\end{equation}

%\begin{remark}
%Most of the results presented in this section can be extended to the case in which the operator $T$ is also depending on the neighborhood $N_j(r)$.  
%We present one of these extensions at the end of this section. 
%\end{remark}

{\color{black}
Note that the shift map $\sigma_j(x)_i$ is contained in the set of possible convex combination rules expressible in the form of Eq.~(\ref{eqn:ccrule}). To see this, take the identity map $T(x)=x$ with only one non-zero coefficient $\lambda_{i-j}=1$.
}

%The following proposition states an important result in determining the Lipschitz property of the map $\delta_C$.

{\color{black}
As we show below, an interesting consequence of this framework is that the Lipschitz property of the map $\delta_C$ depends entirely on the Lipschitz property of the map $T$. The remainder of this section establishes such Lipschitz properties and provides convergence results in the case of contractivity. 
}

\begin{proposition}
Suppose that the map $T$ satisfies the following average Lipschitz property: There exists a constant $c$ such that for any configurations $x,y \in \MSL$ and any $i\in \lattice$ it holds:

\begin{equation}
\sum_{j\in N_r(i)} \lambda_j d_{MK}(T(x_j),T(y_j))\le c d_{MK}(x_i,y_i)    
\end{equation}
%\ef{there should be a quantification on $x$ and $y$ somewhere here...}
Then the map $\delta_C:\MSL\to\MSL$ is a Lipschitz map with respect to $d_{\mathcal{M}}$ with Lipschitz factor $c$. 
\label{proofbanach1}
\end{proposition}

\begin{proof}
In order to prove this result, let us take two elements $x,y\in\MSL$ and calculate the $d_{\mathcal{M(S)}}$ distance between them. Computing, we get:    

\begin{align}
d_{\mathcal{M}}(\delta_C(x),\delta_C(y)) &=  
\sum_{i\in\lattice} {d_{MK}((\delta_C(x))_i,(\delta_C(y))_i)\over 2^{|i|}} \nonumber\\
&=
\sum_{i\in\lattice} {d_{MK}\left(
\sum_{j\in N_r(i)} \lambda_j T(x_j),\sum_{j\in N_r(i)} \lambda_j T(y_j)
\right)\over 2^{|i|}} \nonumber\\
&\le
\sum_{i\in\lattice} \sum_{j\in N_r(i)} \lambda_j {d_{MK}\left(T(x_j),T(y_j)
\right)\over 2^{|i|}}\nonumber\\[2mm]
&\le c d_{\mathcal{M}}(x,y)
\end{align}
\end{proof}

\begin{remark}
Let us notice that the above average Lipschitz property collapses to the classical notion whenever $r=0$ and $N_r(i)=\set{i}$ for all $i\in L$.     
\end{remark}


%\textcolor{red}{EF:} we should put a sentence or a proof for the following result.
\begin{proposition}
Suppose that the map $T$ satisfies the above average Lipschitz property with Lipschitz factor $c\in [0,1)$. Then the map $\delta_C: \mathcal{M(S)}^L \to \mathcal{M(S)}^\lattice$ is a contraction with contractivity factor $c$. Furthermore, there exists a unique invariant configuration $\bar x$ such that $\delta_C(\bar x)=\bar x$ and, for any configuration $x_0$, the orbit $\delta_c^n (x_0)$ converges to $\bar x$ whenever $n\to +\infty$.   
\end{proposition}

\begin{proof}
The proof follows from first applying Proposition~\ref{proofbanach1} and then Banach's fixed point theorem to the contraction $\delta_c$ in the complete metric space $\MSL$.
\end{proof}

\begin{proposition}
Suppose that the map $T$ satisfies the following cell-dependent Lipschitz property: There exists a constant $c$ such that for any $i\in \lattice$ the following condition holds: 
\begin{equation}
d_{MK}(T(x_i),T(y_i))\le \frac{c}{2^{|i|}} d_{MK}(x_i,y_i)    
\end{equation}
Then, the map $\delta_C: \mathcal{M(S)}^L \to \mathcal{M(S)}^\lattice$ is Lipschitz with respect to $d_{\mathcal{M}}$ with Lipschitz constant $C=\sum_{i\in\lattice} 
\frac{c}{2^{|i|}}$.
\label{proofbanach2}
\end{proposition}

\begin{proof}
In fact, similarly to the proof of the previous proposition, we have:
\begin{align}
d_{\mathcal{M}}(\delta_c(x),\delta_c(y)) &= \sum_{i\in\lattice} {d_{MK}((\delta_C(x))_i,(\delta_C(y))_i)\over 2^{|i|}} \nonumber\\
&= \sum_{i\in\lattice} {d_{MK}\left(
\sum_{j\in N_r(i)} \lambda_j T(x_j),\sum_{j\in N_r(i)} \lambda_j T(y_j)
\right)\over 2^{|i|}} \nonumber\\[1mm]
&\le
\sum_{i\in\lattice} \sum_{j\in N_r(i)} \lambda_j {d_{MK}\left(T(x_j),T(y_j)
\right)\over 2^{|i|}} \nonumber\\[1mm]
&\le
\sum_{i\in\lattice} \sum_{j\in N_r(i)} 
\frac{c \lambda_j}{2^{|i|} 2^{|j|}} 
d_{MK}(x_j,y_j) \nonumber\\[1mm]
&\le  
\sum_{i\in\lattice} 
\frac{c}{2^{|i|}} \left(
\sum_{j\in N_r(i)} 
\frac{\lambda_j}{2^{|j|}} d_{MK}(x_j,y_j) 
\right) \nonumber\\[2mm]
%\end{align}
%\begin{align}
&\le 
\left(\sum_{i\in\lattice} 
\frac{c}{2^{|i|}}\right) d_{\mathcal{M}}(x,y)
\end{align}
\end{proof}

%\textcolor{red}{EF:} we should put a sentence or a proof for the following result.

\begin{proposition}
Suppose that the map $T$ satisfies the above cell-dependent Lipschitz property with constant
$C=\sum_{i\in\lattice} \frac{c}{2^{|i|}}<1$. 
Then, the map $\delta_C:\MSL\to\MSL$ is a contraction with contractivity factor $c$. Furthermore, there exists a unique invariant configuration $\bar x$ such that $\delta_C(\bar x)=\bar x$ and, for any configuration $x_0$, the orbit $\delta_c^n (x_0)$ converges to $\bar x$ whenever $n\to +\infty$ in the $d_{\mathcal{M}}$ metric.   
\end{proposition}

\begin{proof}
The proof follows from first applying Proposition~\ref{proofbanach2} and then Banach's fixed point theorem to the contraction $\delta_c$ in the complete metric space $\MSL$.
\end{proof}

