\vspace{-1em}
\section{Joint distribution of the conditionnal p-values}\label{se:preliminaries}
The present section introduces fundamental mathematical tools that will be required to derive conformal predictors (based on aggregation or on p-values) with the right validity in \Cref{sec:majvote} and \Cref{sec:pvalue_agg}.
We first present 
%in this section 
some key lemma about a uniform distribution over the ranks. We then link this distribution to the joint distribution of conditional p-values associated to each observation $X_{n+i}$. Finally, we derive the distribution of some key statistics.

\paragraph{Key lemma.}
%\subsection{Key lemma}
Let $A_{n,m}$ for $n,m \in \mbn^*$, be the set of ordered discrete p-values:
\begin{equation}\label{eq:def_Anm}
    A_{n,m} := \set[2]{ a \in \set[2]{ \frac{i}{n}: 0\leq i \leq n} ^m : a_1\leq \ldots \leq a_m}\enspace.
\end{equation}
\begin{lemma}\label{lem:keylemma}
    Let $n,m \in \mbn^*$ and $P \sim \cU(A_{n,m})$, where $\cU$ denotes the uniform distribution. Then
    \begin{itemize}
        \item $n \cdot P(j) \sim \BBin(n,j,m-j+1)$ for $j\in\intr{m}$.
      %  \item $\sum_{j=1}^m \bm{1}_{n \cdot P_j \geq \lfloor (n+1)\alpha \rfloor } \sim \BBin(m,\lceil(n+1)(1-\alpha)\rceil, \lfloor (n+1)\alpha \rfloor ) $.
        \item $\sum_{j=1}^m \bm{1}_{\{ n\cdot P(j) \geq \ell\}} \sim \BBin(m,n+1 - \ell, \ell ) $ for $\ell \in \intr{0:n}$.
    \end{itemize}
\end{lemma}

\begin{remark}
The beta-binomial distribution $\BBin(m,a,b)$ is the distribution of a binomial random variable $\cB(m,Q)$ where $Q$ is drawn independently as a beta distribution $B(a,b)$. If $a$ and $b$ are positive integers, then for $k\in \intr{0:m}$, 
\begin{equation*}
    \prob[2]{ \BBin(m,a,b) = k}= \frac{\binom{k+a-1}{k} \binom{m-k+b -1}{m-k}}{\binom{m-1+a+b}{m}}\enspace.
\end{equation*}
In this case, the distribution $\BBin(m,a,b)$ is a negative hypergeometric distribution which can be easily simulated using Polya's urns. For $a=0$ (resp. $b=0$), the distribution is defined as a Dirac in $0$ (resp. in $m$).
\end{remark}

\paragraph{Joint distribution of the conditional p-values.}

We focus here on the joint distribution of the ordered vector of p-values $\sorted{\vp}(y) = (p_{(1)}(y), \ldots, p_{(m)}(y))$, where for $j\in \intr{m}$ and $y\in\intr{K}$
\begin{equation}\label{eq:def:pvalue}
    p_j(y) = \frac{1}{n_y} \sum_{i=1}^{n_y} \bm{1}\set{ s(X_{n+j},y)\leq S_i^y }\enspace.
\end{equation}
The guarantees we obtain on this vector is under the condition that the scores of the new points evaluated in the true label are exchangeable with the scores of the same class: 
\begin{assumption}\label{ass:exchangeability}
For all $y \in \intr{K}$ and conditionally to $Y_{n+1} = y$, the vector of scores $\paren{S_1^y,\ldots, S^y_{n_y}, S_{n+1}(y),\ldots,S_{n+m}(y)}$ is exchangeable.
\end{assumption}
This hypothesis is fundamental to our work. It assumes that the scores of the observed images behave similarly to the calibration scores of the same class. This assumption is more discussed in Section~\ref{sec:exchangebability}. The distribution of the unordered vector of $p$-values has been deeply studied by \citet{Gazin2023TransductiveCI,gazin2024asymptotics} in the general case where the p-values are the marginal ones, the test points do not all share the same class, and the scores have no ties. The following proposition can be seen as an extension of these results conditionally to the class, which includes the possibility of \textit{ties} between scores. To this purpose, we introduce a randomized version $\vprd$ of the vector of conformal p-values~$\vp$.



\begin{theorem}\label{prop:pvalue_distrib}
Under Assumption~\ref{ass:exchangeability}, for $y\in \intr{K}$ and $j\in \intr{m}$, let us introduce
\begin{equation}\label{eq:def_pvalue}
    \prd_j(y) = \frac{1}{n_y} \sum_{i=1}^{n_y} \brac[2]{ \bm{1}\set{ S_{n+j}(y) <S_i^y } + \bm{1}\set{ S_{n+j}(y) =S_i^y }\bm{1}\set{  U_j \leq U_i^y } }\enspace,
\end{equation}
where $(U_i)_{i\in \intr{m}}$ and $\paren{U^y_{i}}_{i\in \intr{n_y}}$ for $y\in \intr{K}$ are i.i.d. uniform random variables on $[0,1]$. Then the ordered vector of randomized p-values $\vprd(y) = \paren{ \prd_{(1)}(y), \ldots, \prd_{(m)}(y)}$,  conditionally to $Y_{n+1}=y$, is uniformly drawn from $A_{n_y,m}$:
\begin{equation}\label{eq:pvalue_distrib}
    \vprd(Y_{n+1}) \,|\, \paren{Y_{n+1} = y }\sim \cU\paren{ A_{n_y,m}} \enspace .
\end{equation}
Moreover, for $j\in \intr{m}$, we have $ n_y \cdot \prd_{(j)}(Y_{n+1}) \,|\, \paren{Y_{n+1} = y }\sim   \BBin(n_y,j,m-j+1)$.
\end{theorem}
The proof is given in Appendix~\ref{sec:app_proofBetaBin}. As a minor remark, notice that when scores have no ties, the original
$\vp$ is preserved. More important, the advantage of the above result is that the knowledge of the exact distribution of the conformal p-values will allow us to estimate more precisely the quantiles of statistics constructed from this vector. As a consequence, the resulting prediction sets will be more informative (smaller sets) than those based on bounds for these quantiles.


\begin{remark}
The definition \eqref{eq:def_pvalue} of the conformal p-values differs a bit from the usual definition (different normalization and no additional $+1$, can be compared with \eqref{eq:def_pvalue_classic}) but provides an equivalent tool. With this definition, the ordered vector of p-values has a symmetric distribution around the diagonal: $1-(p_{(m)}(Y_{n+1}),\ldots,p_{(1)}(Y_{n+1}))$ has the same distribution as $\vprd(Y_{n+1})$. 
\end{remark}




\paragraph{Other important law derivations.}
Combining this first result with Lemma~\ref{lem:keylemma}, we can derive the distribution of critical quantities such as the empirical coverage or the marginal distribution of the ordered vector.

\begin{corollary}\label{prop:betabin_distrib}
Under Assumption~\ref{ass:exchangeability}, let $B_y = \sum_{j=1}^m \bm{1}\set{y \in \cC^{cd}_\alpha(X_{n+j})}$ be the number of class conditional sets containing the label $y$. Then for $y\in \intr{K}$ and $\ell \in \intr{m}$ :
\begin{equation}\label{eq:BBin}
    \prob{ B_{Y_{n+1}} = \ell | Y_{n+1} = y} \geq \prob{ \beta =\ell}\,,
\end{equation}
where $\beta$ follows the distribution $\BBin\paren{m,(n_y+1) - k_{y,\alpha},k_{y,\alpha} }$ with $k_{y,\alpha} = \lfloor (n_y+1)\alpha\rfloor$. Moreover, if the scores have no ties, \Cref{eq:BBin} is an equality.
\end{corollary}

The distribution of empirical coverage for conformal prediction sets has been first studied by \citet{vovk2012conditional} and \citet{angelopoulos2023conformal}. For the exchangeable case with no ties, we will refer to \citet{marquesuniversal} who obtains a similar result. {This result will be used to enhance the aggregation of conformal prediction sets by majority voting in our setting.}



\section{Refinement of majority voting for multiple inputs}\label{sec:majvote}

Thanks to these probabilistic results, we are in position to build new conformal predictors tailored for scenarios where multiple predictive observations of a single instance are available. As this problem can be seen as the aggregation of the prediction set associated to each instance, we focus in this section to the adaptation to our setting of the general majority voting methods proposed by \citet{gasparin2024merging}. They propose to keep the labels appearing in at least one half of the sets, in our setting it consists to consider the \textit{majority voting} set $\cC^{M}_{\alpha,m} = \set[1]{ y :\sum_{j=1}^m \bm{1}\set{y \in \cC^{cd}_\alpha(X_{n+j}} \geq m/2 }$. These authors also propose \textit{exchangeable majority} voting sets defined as $ \cC^{Me} = \cap_{k=1}^m \cC^{M}_{\alpha,k}$ usable in our setting as the sets $\cC^{cd}_\alpha(X_{n+j})$ are exchangeable. Both methods achieve a class-conditional coverage of $1-2\alpha$, replacing $\alpha$ by $\alpha/2$ leads to the correct coverage (see Appendix~\ref{app:majvote}).


If $\cC_j = \cC^{cd}_\alpha(X_{n+j})$, then thanks to Proposition~\ref{prop:betabin_distrib}, the distribution of the number of sets containing the true label $Y_{n+1}$ is known. 
The threshold $m/2$ chosen in the majority vote method can then be improved: we replace it by the quantile of a Beta-Binomial distribution.

\begin{proposition}\label{prop:CBB}
Let $\alpha \in (0,1)$, assume Assumption~\ref{ass:exchangeability}, let
\begin{equation}\label{eq:def_CBB}
    \cC^{BB}_\alpha := \set{ y : \sum_{i=1}^m \bm{1}\set{y \in \cC^{cd}_\alpha(X_{n+i})} \geq q^{BB}_\alpha (y)}\enspace,
\end{equation}
where $q^{BB}_\alpha (y)$ is the $\alpha$-quantile of the distribution $\BBin\paren{m, \lceil(n_y+1)(1-\alpha)\rceil,\lfloor (n_y+1)\alpha\rfloor }$. Then, for all $y\in \intr{K}$:
\begin{equation*}
    \prob{ Y_{n+1} \in \cC^{BB}_\alpha \, \vert \, Y_{n+1} = y } \geq 1 - \alpha\enspace.
\end{equation*}
\end{proposition}

For each class, the set $\cC_\alpha^{BB}$ requires computing or storing quantiles of a Beta-Binomial distributions, which depends on the number of calibration points belonging to that class. To avoid performing this computation for each class individually, one can approximate the Beta-Binomial distribution by a Binomial distribution (see Lemma~\ref{lem:dtv_binbetabin}). This approximation induces a loss in coverage as presented in the following proposition.


\begin{proposition}\label{prop:CBin}
Let $\alpha \in (0,1)$, assume Assumption~\ref{ass:exchangeability} holds, let
	\begin{equation}\label{eq:def_CBin}
		\cC_\alpha^{Bin} := \set[2]{ y : \sum_{j=1}^{m}\bm{1}\set[2]{ y \in \cC^{cd}_\alpha(X_{n+j}) } \geq  q^{Bin}_\alpha}\enspace,
	\end{equation}
	where $q^{Bin}_\alpha$ is the $\alpha$-quantile of the binomial distribution $\cB(m,1-\alpha)$. Then for all $y \in \intr{K}$:
		\begin{equation}
	    \prob{ Y_{n+1} \in \cC_\alpha^{Bin} | Y_{n+1} =y, n_y} \geq 1 - \alpha - \frac{(m-1)\min(1,\alpha m)}{n_y+1}\enspace,\quad a.s.
	\end{equation}
	Moreover, if the labels $Y_1,\dots, Y_{n+1}$ are i.i.d., then
	\begin{equation}
		\prob{ Y_{n+1} \in \cC_\alpha^{Bin}} \geq 1 - \alpha - \frac{K(m-1)\min(1,\alpha m)}{n+1} \enspace.
	\end{equation}

\end{proposition}
The loss of coverage remains negligible when the number of repetitions is small ($m\ll n/K$ for the marginal one). In the setting of Pl@ntNet %\moh{Pl@ntNet?} 
data, the number of repetitions is effectively low, but some classes have also a small numbers of examples in the calibration set which makes this approximation only usable for large classes or when only a marginal coverage is targeted.
\begin{remark}
The possibility to use a binomial distribution quantile has been already proposed by \citet{gasparin2024merging} to merge independent prediction sets. The assumption of independence is a bit restrictive and this result proves that it can effectively be used for prediction sets correlated by the calibration (so not independent) for small enough number of sets $m$.
\end{remark}

\section{p-value aggregation methods}\label{sec:pvalue_agg}

Voting methods presented above aggregate the conformal sets constructed for each observation point by only considering the number of sets that contain a given label. Although this procedure can be interpreted as an aggregation of the conformal p-values and as forming an envelope around them (see Figure~\ref{Fig:env}), we observe, however, that some information is lost in the process. In this section, we exploit the structure of the ordered vector of p-values to aggregate the observations. These methods decisively outperform the previously discussed voting strategies.

\subsection{General method}

The method consists in building a (non-)conformity score function $v:[0,1]^m \times \intr{K} \to \mbr$ directly on the p-values vector. Then, exploiting the result in Theorem~\ref{prop:pvalue_distrib}, we calibrate this new score by simulating samples $P^y_1,\ldots,P^y_T$ of the distribution $\cU(A_{n_y,m})$ for each class, using for example Algorithm~\ref{alg:simPnm}. Here, $T$ can be seen as a budget for approximating the score's distribution by Monte Carlo sampling. The method is summarized in the following result which gives a guarantee on the conditional coverage.

\begin{proposition}
Let $v : [0,1]^m\times \intr{K} \to \mbr$ and $T\in \mbn$, for $y\in \intr{K}$ let $P_t^y \overset{\textit{i.i.d.}}{\sim} \cU(A_{n_y,m})$ and $V_t^y:= v(P_t^y,y)$ for $t\in\intr{T}$. Then, for $\alpha \in (0,1)$, if Assumption~\ref{ass:exchangeability} is satisfied, the set
\begin{equation}\label{eq:def_Cenv}
    \cC_\alpha^{v} = \set{ y : v(\vprd(y),y) \geq V^y_{(\lfloor (T+1)\alpha \rfloor)} } 
\end{equation}
is conditionally valid: $\prob{ y \in \cC_\alpha^{v}  | Y_{n+1} =y } \geq 1 - \alpha$ for all $y\in\intr{K}$.
\end{proposition}

  \begin{wrapfigure}[8]{r}{0.45\textwidth}
  \vspace{-2em}
    \begin{minipage}{0.45\textwidth}
    \begin{algorithm}[H]
    \caption{Simulation of $P \sim \cU(A_{n,m})$}
    \label{alg:simPnm}
    \begin{algorithmic}[1]
    \STATE \textbf{Input:} $n,m$.
    \STATE Draw $R_1,\ldots,R_m$ w./o. replacement from $\intr{n+m}$.
    \STATE $P_i \gets R_{(i)}$ for $1\leq i \leq m$.
    \STATE $P_i \gets P_i -i$ for $1\leq i \leq m$.
    \STATE \textbf{Output:} $(P_1/n,\dots,P_m/n)$.
    \end{algorithmic}
    \end{algorithm}
    \end{minipage}
  \end{wrapfigure}
This result is a direct application of conformal prediction using the score function $v$, and follows as a consequence of Theorem~\ref{prop:pvalue_distrib}. While the choice of the score function $v$ is discussed below, it is worth noting that for a given $v$, we retain the low scores in order to remain within the standard framework of envelope methods: as shown in Table~\ref{tab:envelopes}, the scores associated with envelopes tend to reject p-values corresponding to low scores. 
\begin{remark}

Recall that the guarantees provided by conformal prediction in \eqref{eq:cov_splitCP} and \eqref{eq:covcd_splitCP} hold with high probability, including with respect to the calibration set. Formally, the sample $(P_t^y)_{t,y}$ should be redrawn at each execution. However, it is also possible to fix $T$ sufficiently large and store the value $V^y_{(\lfloor (T+1)\alpha \rfloor)}$ for each class, interpreting it as a quantile estimate of the score distribution.
\end{remark}


\subsection{Construction of score functions $v$}


We propose in the following different envelopes - associated to a score function $v: [0,1]^m \to \mbr$ on the p-values---that can either be used for the vector of p-values $\vp$ or its randomized version $\vprd$ as in the above result.

\paragraph{Quantile envelope.} The first envelope that we consider relies on quantiles of the beta-binomial distribution. For a clear presentation, let us first remark that as presented in Theorem~\ref{prop:pvalue_distrib}, the marginal distributions of the sorted vector of p-values $\vprd(Y_{n+1})$ are known. Indeed, conditionally to $Y_{n+1}=y$ and $n_y$, the random variable $n_y\cdot\prd_j(y)$ follows the distribution $\BBin(n_y,j,n_y-j+1)$. 


To capture the geometry of the trajectory of p-values, we propose to choose an envelope of the trajectories constructed as the vector of quantiles of level $\lambda$ of each marginal (see Figure~\ref{Fig:env}). Consider $\{F_j\}_j$ a general family of cdf and let us remark that
%Let $F_{n,j}$ be the cdf of the distribution $\BBin(n,j,n-j+1)$, then
\begin{equation*}
    \set[1]{ \vp : \forall j :  p_{(j)} \geq F_j^{(-1)}(\lambda)} = \set[1]{ \vp : \min_j F_j(p_{(j)}) \geq \lambda}\enspace.
\end{equation*}
The envelope of quantile of marginal associated to the \textit{quantile} score $v_Q$ is defined as 
\begin{equation}\label{eq:def_score}
    v_Q(\vp,y) := \min_{j\in \intr{m}} F_{j,n_y}(n_y \cdot p_{(j)}(y) )\,, \quad \text{for } \vp\in [0,1]^m, y \in \intr{K}\enspace,
\end{equation} 


\begin{wrapfigure}[18]{r}{0.45\textwidth}  % 'r' pour à droite, 'l' pour à gauche
\vspace{-20pt}
    \centering
    \includegraphics[width=0.45\textwidth]{Envelope_Neurips.pdf}  
\vspace{-20pt}

    \caption{Simulation of 150 samples of $P\sim \cU(A_{n,m})$ for $m=10$ and $n=100$ (black lines). Quantile is the envelope associated to $v_Q$, and Majority to the majority vote.}\label{Fig:env}
\end{wrapfigure}
%
where $F_{j,n}$ is the cdf of the distribution $\BBin(n,j,m-j+1)$. This kind of envelope, constructed as the true quantile of the marginal with a specific level, appears for instance in \citet{genovese2006exceedance,Blanchard2020PostHC} and in \citet{fermanian2025transductive} in an empirical version.


\paragraph{$\ell^q$-Area envelope.} A simple idea to reject the classes whose p-values are too small could be supported by the fact that the area of the trajectory is too small. For $q>0$, we define the \textit{area} score: $v_{q-Area}(\vp,y) := \norm{\vp}_q$,
where $\norm{\cdot}_q$ for $q\geq 1$ is the $\ell_q$-norm in $\mbr^m$.
For $q=1$, the procedure that consists in rejecting a trajectory or not can be viewed as a variant of the Wilcoxon-Mann-Whitney test~\citep{wilcoxon1945individual,mann1947test}.

\paragraph{$\ell^q$-envelope.} As asymptotically, the vector $\vprd(Y_{n+1})$ converges to the identity vector $\texttt{Id} =\paren{{j}/{(m+1)}}_{j=1}^m $, our last score only considers the distance of p-value vector to this vector. In particular, $\e[1]{\prd_{(j)}(Y_{n+1})} = \frac{j}{m+1}$ (\lcf Theorem~\ref{prop:pvalue_distrib}) which motivates the score $v_{\ell^q}$ defined as:
$v_{\ell^q}(\vp,y) :=- \| \vp - \texttt{Id}\|_q$. The resulting set~\eqref{eq:def_Cenv} will then keep p-values close to $\texttt{Id}$.
For $q = \infty$, bounds of the exact quantile and the asymptotic distribution are provided respectively by \citet{Gazin2023TransductiveCI} and \citet{gazin2024asymptotics}.




\section{Experiments}\label{sec:experiments}

A key requirement of a conformal approach is its ability to accurately quantify uncertainty.
For an efficient classifier, this should lead to small prediction sets; for a less accurate one, the conformal set should still contain the correct label, at the cost of a larger set. To this purpose, we compare the methods, by comparing the size of the prediction sets returned for a fixed coverage.

Multiple observations of the same instance are particularly valuable in challenging tasks where a single observation does not permit informative classification. As we will demonstrate, our aggregation techniques lead to a reduction in prediction set size in such cases resulting in a gain of interpretability. Throughout our experiments, we report the accuracy of the base classifiers. The score used for all the following experiments is the \textit{softmax score} which is one minus the softmax output of the class. 

The tested prediction sets are the \textit{Majority} $\cC^M$---\Cref{eq:def_majvote}, \textit{Exchangeable Majority} $\cC^{Me}$---\cref{eq:def_majexchvote}, 
\textit{BetaBinomial} $\cC^{BB}$---\cref{eq:def_CBB}, \textit{Binomial} $\cC^{Bin}$---\cref{eq:def_CBin}, and the set $\cC^v$---\cref{eq:def_Cenv} with the score functions $v_Q$ (\textit{Quantile}), $v_{1-Area}$ (\textit{Wilcoxon}),  $v_{2-Area}$ (\textit{$\ell_2$ Area}) and $v_{\ell_2}$ (\textit{$\ell_2$}).

 Code for reproducing our experiments is available at \url{https://github.com/jeanbaptistefermanian/Class_Conditional_CP_for_Multi_Inputs}.


\subsection{Synthetic data}\label{sec:synthetic}
We choose as distribution of the points, a mixture of Gaussian distributions with randomly drawn centers. Formally, $Y \sim  \sum_{y=1}^K p(y) \delta_y$ and $X|(Y=y) \sim\cN(\mu_y,\sigma^2I_d)$,
where $K=10$, $d=6$, the classes are a bit imbalanced $p(y) \propto \paren{ 1+3(y-1)/K}^{-1}$ and $\sigma^2=3$. The centers of the classes $\mu_y$ are drawn independently as $\cN(0,I_d)$. 
The strength of the noise makes this problem difficult with only one observation as the distance between two centers clusters is relatively close to the distance of a point to its cluster's center : $\e{\norm{ X - \mu_Y}} \simeq \e{\norm{\mu_y-\mu_z}}$.
The model is a ReLu neural network with three hidden layers of width $15$. It is trained with $2000$ observations and achieves a top~1 accuracy of $0.49$. 
We apply our conformal procedure with a calibration set of size $n=1000$ and repeat $5000$ times our procedure for a number of observations $m \in \set{1,\ldots,100}$.

