\section{Proofs}\label{sec:proof}
\subsection{Preliminary results}

This first result is derived from Theorem~A.1 of \citet{Gazin2023TransductiveCI}.
\begin{corollary}\label{cor:unif_pvalue_gen}
Let $S_1,\ldots, S_{n+m}$ exchangeable random variables with no ties ($S\neq S_j$ almost surely). Let $k \in \intr{n}$ and $S_{(1)}< \ldots <S_{(n)}$ the $n$ first random variables ordered, for $j \in \intr{m}$ let
\begin{equation}\label{eq:def_pvalue_app}
    p_j = \frac{1}{n} \sum_{i=1}^n \bm{1} \set{ S_{n+j} \geq S_i},
\end{equation}
and $\sorted{\vp} = \paren{p_{(1)},\ldots, p_{(m)}}$ be the vector of ordered $p$-values. Then
\begin{equation*}
\sorted{\vp} \sim \cU\paren{A_{n,m}}\,,
\end{equation*}
where $A_{n,m}$ is defined in \eqref{eq:def_Anm}.
\end{corollary}
%
\begin{proof}
This result is a direct consequence of Theorem~A.1 of \citet{Gazin2023TransductiveCI}. According to this work, let $\bm{M} \in \intr{0,m}^n $ be the histogram of $\vp$, \emph{i.e.,} for $j\in \intr{0,n}$:
\begin{equation*}
    \bm{M}_j = \abs{\set{ i : p_i = \frac{j}{n} }}\,.
\end{equation*}
Then, $\bm{M} \sim \cU\paren{ H_{n,m}}$ where $H_{n,m}= \set{ h \in \intr{0,m}^n : \sum_{i=1}^n h_i =m  }$ is the set of histogram \citep[Theorem~A.1]{Gazin2023TransductiveCI}. We can now remark that $H_{n,m}$ is in bijection with the set of ordered trajectories $A_{n,m}= \set[2]{ a \in \set[2]{ \frac{i}{n}: 0\leq i \leq n} ^m : a_1\leq \ldots \leq a_m}$. For example $\phi : H_{n,m} \to A_{n,m}$ defined for $h \in H_{n,m}$ by:
\begin{equation*}
    \phi(h) = \frac{1}{n}\paren[3]{ \underbrace{0,\ldots,0}_{ h_0 \text{ times}}, \ldots, \underbrace{n,\ldots,n}_{ h_n \text{ times}}},
\end{equation*}
is such a bijection. Then $\sorted{\vp} = \phi\paren{\bm{M}}$ is uniformly drawn into $A_{n,m}$.
\end{proof}

\subsection{Proof of Lemma~\ref{lem:keylemma}}
\paragraph{Distribution of the marginal.} 
Let $P \sim \cU(A_{n,m})$, $k \in \intr{m}$ and $j\in \intr{0:n}$. The probability of the event $\set{  P(j) = k/n}$ is the probability that the sub-trajectories $P_{1:(j-1)} = (P(1),\ldots,P(j-1))$ belong to $\set{ i/n, i\in \intr{0:k}}^{j-1}$ and the sub-trajectories $P_{(j+1):m} = (P(j+1),\ldots,P(m))$ belong to $\set{ i/n, i\in \intr{k:n}}^{m-j}$. There are respectively $\binom{k+j-1}{j-1}$ and $\binom{n-k+m-j}{m-j}$ of such trajectories which are the numbers of non-decreasing sequences of $j-1$ (resp. $m-j$) elements of $\intr{0:k}$ (resp. $\intr{k:n}$).
Then,
\begin{align*}
    \prob{ P(j) = k/n } &= \frac{\#\set{P \in A_{n,m} : n P_{1:(j-1)} \in \intr{0:k}^{j-1}, nP(j) = k, nP_{(j+1):m} \in \intr{k:n}^{m-j}   }}{\#A_{n,m}} \\
    &= \frac{\#A_{k,j-1}\#A_{n-k,m-j}}{\#A_{n,m}} \\
    &= \frac{\binom{j+k-1}{k}\binom{n+m-j-k}{n-k}}{\binom{n+m}{n}} = \prob[2]{ \BBin(n,j,m-j+1) =k} \,.
\end{align*}
\paragraph{Distribution of the empirical cdf.} The event $\set{\sum_{j=1}^m \bm{1}_{ n\cdot P(j) \geq \ell} = k}$ is satisfied if the first $m-k$ values of $P$ are strictly below $\ell/n$ and the $k$ last ones are above $\ell/n$. That means that the sub-trajectories $P_{1:(m-k)} = (P(1),\ldots,P(m-k))$ belong to $\set{ i/n, i\in \intr{0:\ell-1}}^{m-k}$ and the sub-trajectories $P_{(m-k+1):m} = (P(m-k+1),\ldots,P(m))$ belong to $\set{ i/n, i\in \intr{\ell:n}}^{k}$. There are respectively $\binom{\ell-1+m-k}{m-k}$ and $\binom{n-\ell+k}{k}$ of such trajectories . Then:
\begin{align*}
    \prob{ \sum_{j=1}^m \bm{1}_{ n\cdot P(j) \geq \ell} = k } &= \frac{\#\set{P \in A_{n,m} : n P_{1:(m-k)} \in \intr{0:\ell-1}^{m-k},n P_{(m-k+1):m} \in \intr{\ell:n}^{k}   }}{\#A_{n,m}} \\
    &= \frac{\#A_{\ell-1,m-k}\#A_{n-\ell,k}}{\#A_{n,m}} \\
    &= \frac{\binom{\ell-1+m-k}{m-k}\binom{n-\ell+k}{k}}{\binom{n+m}{m}} = \prob[2]{ \BBin(m,n+1-\ell,\ell) =k} \,.
\end{align*}
\qed
\subsection{Proofs of \Cref{prop:pvalue_distrib} and  Corollary~\ref{prop:betabin_distrib}}\label{sec:app_proofBetaBin}

In this section we prove \Cref{prop:pvalue_distrib} and \Cref{prop:betabin_distrib} simultaneously. Let us first remark that if the scores have no ties, under the Assumption~\ref{ass:exchangeability}, all the results are obtained by applying Corollary~\ref{cor:unif_pvalue_gen} and Lemma~\ref{lem:keylemma} conditionally to $(Y_{n+1} =y)$ to the scores $(S_1^y,\ldots, S_{n_y}^y, S_{n+1}(y),\ldots, S_{n+m}(y) )$. 

Let us now consider the case where there are potentially ties between the scores. The proof uses some common idea with the proof of Proposition~1 of \citet{fermanian2025transductive}. 
Let $\delta$ be the minimum non null distance between the new scores of the true class and those evaluated in the calibration set:
\begin{equation*}
\delta := \min \set{  \abs{s-s'},   s\neq s' \in \set{ S_i}_{i\in \intr{n}} \cup \set{ S_{n+j}(Y_{n+1})}_{j \in \intr{m}}}\,.
\end{equation*}
If all the scores are equal, $\delta$ can be set to any non null value (for example $1$). We now define some proxy scores $\wt{S}$ by:
\begin{equation}\label{eq:proxy_scores}
    \wt{S}_i^y:= S_i^y + U_i^y\delta\,, \quad \text{for } y \in \intr{K}, i \in \intr{n_y}\,, \qquad 
    \wt{S}_{n+j} := S_{n+j} + U_j\delta \,, \quad \text{for } j \in \intr{m}\,,
\end{equation}
where $U_i^y$, $U_{j}$ for $y \in \intr{K}$, $i \in \intr{n_y}$ and $j \in \intr{m}$ are i.i.d. uniform random variables in $[0,1]$. The proxy scores $\wt{S}$ satisfies the Assumption~\ref{ass:exchangeability} and have no ties. We can then apply Corollary~\ref{cor:unif_pvalue_gen} to the proxy scores $(\wt{S}_1^y,\ldots, \wt{S}_{n_y}^y, \wt{S}_{n+1}(y),\ldots, \wt{S}_{n+m}(y) )$ conditionally to $(Y_{n+1} =y)$ to get \eqref{eq:pvalue_distrib}. Indeed, the class conditional p-values $\wt{\vp}$ associated to the proxy scores $\wt{S}$ is equal to $\bm{\prd}$:
\begin{align*} 
\wt{p}_j(y) &:= \frac{1}{n_y} \sum_{i=1}^{n_y} \bm{1}\set{\wt{S}_{n+j}(y) \leq \wt{S}_i^{y}}  \\
&= \frac{1}{n_y} \sum_{i=1}^{n_y} \brac[2]{ \bm{1}\set{S_{n+j}(y) < S_i^{y}} + \bm{1}\set{ S_{n+j}(y) =S_i^y }\bm{1}\set{\delta U_j \leq \delta U_i^y }} \\
       &= \frac{1}{n_y} \sum_{i=1}^{n_y} \brac[2]{ \bm{1}\set{ S_{n+j}(y) <S_i^y } + \bm{1}\set{ S_{n+j}(y) =S_i^y }\bm{1}\set{  U_j \leq U_i^y } } = \prd_j(y)\enspace.
\end{align*}
Then the distribution of the marginal $\prd_{(j)}$ is a consequence of Lemma~\ref{lem:keylemma}.

To get Corollary~\ref{prop:betabin_distrib}, we can remark that the  proxy scores preserve the order as $  S_{n+j}(y) < S_i^y \Longrightarrow \wt{S}_{n+j}(y) < \wt{S}_i^y$. Thus for $j \in \intr{m}$ and $ y\in \intr{K}$:
\begin{align*}
  y \in \cC^{cd}_\alpha(X_{n+j}) & \iff  S_{n+j}(y) \leq S_{(\lfloor (n_y+1)(1-\alpha) \rfloor)}(y) \iff \sum_{i=1}^{n_y} \bm{1} \set{ S_{n+j}(y) \leq S_i^y} \geq \lfloor (n_y+1)\alpha \rfloor \\
  &  \iff \sum_{i=1}^{n_y} \bm{1} \set{ S_{n+j}(y) < S_i^y} + \sum_{i=1}^{n_y} \bm{1} \set{ S_{n+j}(y) = S_i^y} \geq \lfloor (n_y+1)\alpha \rfloor\\ 
  & \impliedby \sum_{i=1}^{n_y} \bm{1} \set{ \wt{S}_{n+j}(y) < \wt{S}_i^y} \geq \lfloor (n_y+1)\alpha \rfloor \\
  & \iff \sum_{i=1}^{n_y} \bm{1} \set{ \wt{S}_{n+j}(y) \leq \wt{S}_i^y} \geq \lfloor (n_y+1)\alpha \rfloor \\
  & \iff y \in \wt{\cC}^{cd}_\alpha(X_{n+j})\enspace ,
\end{align*}
where $\wt{\cC}^{cd}_\alpha$ is the class conditional prediction set \eqref{eq:def_cond_set} constructed with the proxy scores $\wt{S}$. We have therefore shown that $\wt{\cC}^{cd}_\alpha(X_{n+j}) \subset \cC^{cd}_\alpha(X_{n+j}) $, using that the randomization preserves the order and that the scores "tilde" have no ties. This implies that almost surely, the empirical coverage of the true scores is lower bounded by the empirical coverage of conformal sets constructed with the proxy scores, \ie :
\begin{equation*}
    \sum_{j=1}^m \bm{1} \set{ Y_{n+1} \in \cC^{cd}_\alpha(X_{n+j})} \geq \sum_{j=1}^m \bm{1} \set{ Y_{n+1} \in \wt{\cC}^{cd}_\alpha(X_{n+j})}\enspace .
\end{equation*}
We conclude again using Lemma~\ref{lem:keylemma}.

\subsection{Proof of Proposition~\ref{prop:CBB}}
The result is a direct consequence of Corollary~\ref{prop:betabin_distrib}.\qed


\subsection{Proof of Proposition~\ref{prop:CBin}}

Let us denote $B_y =  \sum_{j=1}^{m}\bm{1}\set{ y \in \cC^{cd}_\alpha(X_{n+j} )}$. First observe that:
    \begin{align*}
		\set{Y_{n+1} \notin \cC_\alpha^{Bin} } &= \set{ B_{Y_{n+1}}  <Q_\alpha(\cB(m,1-\alpha))}
		\subset \set{B_{Y_{n+1}}  <Q_\alpha(\cB(m,1-\alpha_{Y_{n+1}}))},
	\end{align*}
	where $\alpha_{Y_{n+1}} = \frac{\lfloor (n_{Y_{n+1}}+1)\alpha \rfloor}{n_{Y_{n+1}}+1} <\alpha$ and $Q_\alpha(\mbq)$ denotes the quantile $\alpha$ of the distribution $\mbq$. Let $Z_y \sim \cB(m,1-\alpha_{y})$ and $\beta_y \sim \BBin(m,n_y+1- k_y, k_y)
	$ where $k_y = \lfloor \alpha(n_y+1)\rfloor$. Then, for $y \in \intr{K}$:
	\begin{align*}
		\prob{Y_{n+1} \notin \cC_\alpha^{Bin} | Y_{n+1} =y } &\leq \prob{ B_y < Q_\alpha(\cB(m,1-\alpha_y)) | Y_{n+1} =y } \\
		&\leq \prob{ \beta_y < Q_\alpha(\cB(m,1-\alpha_y)) },
	\end{align*}
	using Corollary~\ref{prop:betabin_distrib}. It follows that:
	\begin{align}
	\prob{Y_{n+1} \notin \cC_\alpha^{Bin} | Y_{n+1} =y } 
	\leq & \prob{ Z_y < Q_\alpha(\cB(m,1-\alpha_y))} \notag
	\\
	&+d_{TV}\paren[2]{  \cB(m,1-\alpha_{y}), \BBin(m, n_y+1 - k_y, k_y }  \notag\\
			\leq& \alpha +  \frac{(m-1)\min(1,\alpha m )}{n_y+1}\,, \label{al:cond_cov_Bin}
	\end{align}
	where we have used Corollary~\ref{cor:dtv_binbetabin} in the last inequality to bound the total variation distance between the Binomial and the Beta-Binomial distributions. We have then obtained the conditional coverage guarantee. 

	Assume now that the labels $Y_1,\ldots,Y_{n+1}$ are i.i.d.. Then $n_y = \sum_{i=1}^n \bm{1}\set{ Y_i =y}$ is independent of $Y_{n+1}$ and follows a Binomial distribution $\cB(n,q(y))$ for $q(y) := \prob{ Y_1=y}$. Then:
	\begin{equation*}
	    \e{ \frac{1}{n_{Y_{n+1}+1}}} = \e{ \sum_{y=1}^K \frac{q(y)}{n_y+1} } \leq  \e{ \sum_{y=1}^K \frac{q(y)}{q(y)(n+1)} } = \frac{K}{n+1}\,,
	\end{equation*}
	where we have used Lemma~\ref{lem:moment_invbin} for the inequality. That gives the marginal coverage after taking the expectation relatively to $Y_{n+1}$ into \eqref{al:cond_cov_Bin}.\qed


\section{Failure of the naive approaches}\label{app:fail_naive}

We discuss in this section the challenges that naive approaches may face when dealing with the case of aggregated predictions. We consider two naive methods that we view as natural. We illustrate them in the case of mean aggregation and evaluate their performance on the synthetic dataset presented in Section~\ref{sec:synthetic}.

\begin{figure}
    \centering
    \includegraphics[width = 0.5\textwidth]{Distrib_score_avg_neurips2.pdf}
    \caption{Distribution of the averaged softmax scores for synthetic data. $5000$ averaged scores are computed and sorted for $m\in\set{1,3,5,7,9}$. }
    \label{fig:distrib_score}
\end{figure}


\textbf{First method: directly using the calibration set.}
A first naive idea is to construct the prediction set using the original scores and to use it directly with the aggregating scores, \ie when the aggregation is the mean, we are considering the set $\set[2]{ y : S^{agg}_m(y) := m^{-1} \sum_{j=1}^m S_{n+j}(y) \leq S^y_{(\lceil (n_y+1)(1-\alpha) \rceil)}}$. Formally, this set lacks any guarantee since the new (aggregated) score $S^{agg}_m(Y_{n+1})$ follows a different distribution than the calibration scores. In Figure~\ref{fig:distrib_score}, we compare the distribution of this averaged scores for $m=1$ to $9$ observations to the distribution of calibration scores. A clear change in distribution can be observed even for small value of $m$. 
In practice, this method produces conservative prediction sets, whose size increases with the number of repetitions, as it can be seen in Figure~\ref{fig:cov_lgth_naive}.


\begin{figure}
    \centering
    \includegraphics[width = 1\textwidth]{Naive_cov_lgth_neurips.pdf}
    \vspace{-1.2em}
    \caption{Empirical coverage and average lengths for class-conditional approach using two naive calibration sets for synthetic data. The calibration set is of size $5000$, the coverage and the length are evaluated on $300$ multi-inputs repeated $1000$ times. The confidence region is $\pm$ (empirical std)/$\sqrt{5000}$}
    \label{fig:cov_lgth_naive}
\end{figure}

\textbf{Second method: aggregating the calibration scores}
A second idea to obtain a calibration set exchangeable with the new score is, for a given number of observations $m$, to aggregate the calibration scores by class, \ie by averaging them in groups of $m$ points, in order to mimic the distribution of aggregated scores. These new aggregated calibration scores will be exchangeable under Assumption~\ref{ass:exchangeability} with the new aggregated score. However, by doing so, the calibration set is reduced to approximately $n/m$ points (more precisely, $\sum_{y=1}^K \lfloor n_y/m \rfloor$). Recall that the number of points per class must be at least $\alpha^{-1}$ in order to obtain informative class-conditionally valid prediction sets, which no longer holds when $m$ is large. As shown in Figure~\ref{fig:cov_lgth_naive}, this method yields valid prediction sets whose size decreases for small values of $m$, but increases again when the number of observations becomes too large. {This strategy may be sufficient in cases involving a limited number of inputs, or for classes with a sufficient number of points, \textit{i.e.}, when $m\ll n_y$. Note however that the methods based on p-values aggregation outperform this strategy, with an average size quickly below $4$ elements (see Figure~\ref{fig:synthetic}).}


\begin{remark}
Figure~\ref{fig:distrib_score} also highlights the occurrence of tied scores produced by the softmax output of a neural network. When examining the calibration curve, constructed from one minus the softmax outputs corresponding to the true classes, we observe that many of these values are either close or equal to $0$ or $1$ (plateaus at the left or the right). It indicates that the classifier often returns a Dirac, sometimes in the true class (scores of $0$) but also often in a wrong class (scores of $1$). This leads to score ties, therefore caused by a combination of classifier overconfidence and numerical approximation.
\end{remark}



\section{Majority voting.}\label{app:majvote}
We present in this section the majority voting strategies proposed \citet{gasparin2024merging} for aggregating conformal set and the guarantee we get in our setting. The purpose of these methods is to aggregate marginally valid prediction sets $\cC_1, \ldots, \cC_m$ coming from some blackbox method. We have used compared to two of their methods that we consider of interest for our application. The \textit{majority} vote set $\cC^{M}$ contains the classes selected by at least one half of the sets. Formally:
\begin{equation}\label{eq:def_majvote}
  \cC^{M}= \set[3]{ y : \frac{1}{m}\sum_{j=1}^m \bm{1}\set{y \in \cC_j} \geq 1/2 }\,.
\end{equation}
If the sets $\cC_j$ have a coverage of $1-\alpha$, this set has a marginal coverage of at least $1-2\alpha$. To be able to compare this method to our sets of class-conditional coverage $1-\alpha$ we apply this method to the sets $\cC_j = \cC^{cd}_{\alpha/2}(X_{n+j})$ of class-conditional coverage $1-\alpha/2$. Then, we get the resulting majority vote has a class conditional coverage of at least $1-\alpha$, \ie for all $y\in \intr{K}$:
\begin{equation*}
    \prob{ y \in \cC^M | Y_{n+1}=y} = \prob[3]{ y : \frac{1}{m} \sum_{i=1}^m\bm{1}_{y \in  \cC^{cd}_{\alpha/2}(X_{n+i})}  | Y_{n+1}=y} \geq 1 - \alpha.
\end{equation*}
This method can be improved when the sets are exchangeable \citep{gasparin2024merging}: in that situation the intersection $\cC^{Me}$ of the majority vote sets with increasingly more "voters" defined by:
\begin{equation}\label{eq:def_majexchvote}
    \cC^{Me} = \set[3]{ y : \forall k\in \intr{m} : \frac{1}{k}\sum_{j=1}^k \bm{1}\set{y \in \cC^{cd}_{\alpha/2}(X_{n+i})} \geq 1/2 }\,.
\end{equation}
This set also ensures a class conditional coverage of at least $1 - \alpha$. In fact, Assumption~\ref{ass:exchangeability} guarantees that the sets $\mathcal{C}^{cd}_{\alpha/2}(X_{n+i})$ for $i \in \intr{m}$ are exchangeable given $Y_{n+1}$.

