 & +\beta^{2}\epsilon^{i}{}_{jk}\left(\tilde{K}_{a}^{j}-\frac{\kappa}{4}\epsilon^{j}{}_{mn}e_{a}^{m}J^{n}\right)\left(\tilde{K}_{b}^{k}-\frac{\kappa}{4}\epsilon^{k}{}_{pq}e_{b}^{p}J^{q}\right)\sqrt{\text{det}\,h}e_{i}^{b}\Bigr]-\sqrt{\text{det}\,h}\beta\tilde{K}_{a}^{i}J_{i}\nonumber \\
