To motivate the need for this modification, we begin by highlighting a potentially problematic term in the minimally coupled gravity-fermion action:
\begin{equation}
S_{\text{G+F}}=\frac{1}{2\kappa}\int d^{4}x|\text{det}\,e|e_{I}^{a}e_{J}^{b}P_{KL}^{IJ}F_{ab}^{KL}(\omega) + \frac{i}{2}\int d^{4}x|e|\Bigl\{ e_{I}^a\overline{\Psi}\gamma^{I}\mathfrak{D}_a\Psi-e_{I}^a\overline{\mathfrak{D}_a\Psi}\gamma^{I}\Psi\Bigr\}\,.
\end{equation}
As pointed out before, the presence of fermions modifies the compatibility condition. The difference between the full covariant derivative and the torsion-free one can be expressed as
\begin{equation}
    (\mathcal{D}_a - \tilde{\mathcal{D}}_a)X_I = C_{aI}\,^JX_J
\end{equation}
where $C_a^{IJ}$ is the contorsion tensor. The corresponding curvature then becomes
\begin{equation}
    F_{ab}^{IJ} = \tilde{F}_{ab}^{IJ} + 2\partial_{[a}C_{b]}^{IJ} + [C_a, C_b]^{IJ} 
\end{equation}
Substituting this expression into the action $S_{\text{G+F}}$, we obtain
\begin{equation}
\begin{split}
    S_{\text{G+F}}=& \tilde{S}_{\text{G}}+\tilde{S}_{\text{F}} + S_{\text{int}}\\
    =&\frac{1}{2\kappa}\int d^{4}x|\text{det}\,e|e_{I}^{a}e_{J}^{b}P_{KL}^{IJ}\tilde{F}_{ab}^{KL}(\tilde{\omega}) + \frac{i}{2}\int d^{4}x|e|\Bigl\{ e_{I}^a\overline{\Psi}\gamma^{I}\tilde{\mathfrak{D}}_a\Psi-e_{I}^a\overline{\tilde{\mathfrak{D}}_a\Psi}\gamma^{I}\Psi\Bigr\}\\
    &+ \frac{1}{2\kappa}\int d^4x|\text{det}\,e|e_{I}^{a}e_{J}^{b}P_{KL}^{IJ} [C_a, C_b]^{KL} - \frac{1}{4}\int d^4x|\text{det}\,e|\epsilon^I\,_{JKL}e^a_I C_a^{JK}J^L \,.
\end{split}
\end{equation}
Here, $\tilde{S}_{\text{G}}$ and $\tilde{S}_{\text{F}}$ are respectively the gravitational and fermionic actions constructed using the torsion-free spin connection 1-form $\tilde{\omega}_a^{IJ}$ and $S_{\text{int}}$ is the minimal coupling interaction term between gravity and fermions. After performing the contractions in the interaction terms, the full action becomes:
\begin{equation}
    S_{\text{G+F}}= \tilde{S}_{\text{G}}+\tilde{S}_{\text{F}}  - \frac{3\kappa}{16}\frac{\beta^2}{1+\beta^2}\int d^4x |\text{det}\,e| J_IJ^I.
\end{equation}
This coupling term explicitly depends on the Barbero-Immirzi parameter $\beta$, which some authors believe would be problematic \cite{PhysRevD.73.084016}. It is thus suggested that non-minimal couplings could provide a more consistent framework since setting the coupling constant $\alpha=-\frac{1}{\beta}$ yields a $\beta$-independent interaction term. Hence, we present the idea behind this suggestion and the corresponding modifications to the constraints and compatibility conditions when a non-minimal interaction is introduced.

The action incorporating a non-minimal coupling of gravity to Weyl fermions can be written as
\begin{equation}
\begin{split}
    S_{\text{G+F}}=&\frac{1}{2\kappa}\int d^{4}x|\text{det}\,e|e_{I}^{a}e_{J}^{b}P_{KL}^{IJ}F_{ab}^{KL}(\omega) \\
    &+ \frac{i}{2}\int d^{4}x|e|\Bigl\{ e_{I}^a\overline{\Psi}\gamma^{I}(1-i\alpha\gamma_5)\mathfrak{D}_a\Psi-e_{I}^a\overline{\mathfrak{D}_a\Psi}(1-i\bar{\alpha}\gamma_5)\gamma^{I}\Psi\Bigr\}\,,
\end{split}
\end{equation}
where $\alpha\in\mathbb{C}$ parametrizes the non-minimal coupling. Following the same procedure as discussed in detail in previous sections, the constraints become
\begin{align}
\mathcal{G}_{i}^{\text{G+F}}= & \frac{1}{\kappa\beta}\mathcal{D}_{a}^{(A)}E_{i}^{a}+\frac{1}{2}\sqrt{\text{det}\,h}J_{i} + \frac{i}{2}(\alpha-\bar{\alpha})\sqrt{\text{det}\,h}\mathcal{J}_i,\\
\mathcal{S}_{i}^{\text{G+F}}= & -\frac{1+\beta^{2}}{\kappa\beta}\epsilon_{ij}{}^{k}K_{a}^{j}E_{k}^{a}-\frac{1}{2}\beta\sqrt{\text{det}\,h}\,J_{i} - \frac{1}{4}(-\alpha+\bar{\alpha})\sqrt{\text{det}\,h}J_i \nonumber\\
&- \frac{i\beta}{2}(\alpha-\bar{\alpha})\sqrt{\text{det}\,h}\mathcal{J}_i,\\
\mathcal{H}^{\text{G+F}}= & \frac{1}{2\kappa}\frac{E_{i}^{a}E_{j}^{b}}{\sqrt{\text{det}\,h}}\epsilon^{ij}{}_{k}\Bigl\{\mathcal{F}_{ab}^{k}(A)-(1+\beta^{2})\epsilon^{k}{}_{mn}K_{a}^{m}K_{b}^{n}-2\frac{1+\beta^{2}}{\beta}\mathcal{D}_{[a}^{(\Gamma)}K_{b]}^{k}\Bigr\}\nonumber \\
 & -\frac{i}{2}E_{i}^{a}\left(\overline{\Psi}\gamma^{i}(1-i\alpha\gamma_5)\mathfrak{D}_{a}\Psi-\overline{\mathfrak{D}_{a}\Psi}(1-i\bar{\alpha}\gamma_5)\gamma^{i}\Psi\right),\\
\mathcal{H}_{a}^{\text{G+F}}= & \frac{1}{\kappa\beta}\left(E_{j}^{b}\mathcal{F}_{ab}^{j}(A)-(1+\beta^{2})\epsilon^{j}{}_{kl}E_{j}^{b}K_{a}^{k}K_{b}^{l}\right)\nonumber\\
&-\frac{i}{2}\sqrt{\text{det}\,h}\left(\overline{\Psi}\gamma^{0}(1-i\alpha\gamma_5)\mathfrak{D}_{a}\Psi+\overline{\mathfrak{D}_{a}\Psi}(1-i\bar{\alpha}\gamma_5)\gamma^{0}\Psi\right).
\end{align}

