\section*{S2 Text. Equations for Coop, PF, and FA models.}
The Coop and PF models are described in greater detail in Chou et al.~\cite{chou_modeling_2008,chou_noise_2011}. The FA model possesses a first-order filter in front of the PF model.
In all three models, $u$ is the input, $a$ is the polarized species on the surface of the 2D disk ($r=1$ $\mu$m), and $b$ is the negative feedback species that is well-mixed in all of the compartments. $D = 0.001$ $\mu\text{m}^2/s$ is the surface diffusion coefficient.
\subsection*{Cooperative Model (Coop)}

\begin{align*}
\frac{\partial a}{d t} &= D \nabla_s^2 a+\frac{k_0}{1+(\beta u)^{-q}}-k_2 a-k_3 b a \\
\frac{d b}{d t}&=k_4 \hat{a} b 
\end{align*}

\noindent where $\hat{a}=\bar{a}-a_{ss}$ and $\bar{a}=\frac{\int_s a d s}{\int_s d s}$. $k_0=10$, $k_2=k_3=k_4=1$, $\beta=1$, $q=1000$, $a_{ss}=1$.

\subsection*{Positive Feedback Model (PF)}

\begin{align*}
\frac{\partial a}{d t} &= D \nabla_s^2 a+\frac{k_0}{1+(\beta u)^{-q}}+\frac{k_1}{1+(\gamma a)^{-h}}-k_2 a-k_3 b a-k_5 \hat{a} \\
\frac{d b}{d t}&=k_4 \hat{a} b 
\end{align*}

\noindent where $\hat{a}=\overline{a}-a_{ss}$ and $\bar{a}=\frac{\int_s a d s}{\int_s d s}$. $k_0=1$, $k_1=10$, $k_2=k_3=k_4=1, k_5=10$, $\beta=1$, $\gamma=\frac{1}{1+u^{-q}}$, $q=100$, $h=2$, $a_{ss}=1$.

\subsection*{Filter-Amplifier Model (FA)}

 The FA model is composed of three equations in which the first equation is a first-order filter with time constant $\tau$, while the second and third equations are the positive feedback (PF) model.

 \begin{align*}
\frac{\partial f}{\partial t} &= \frac{u-f}{\tau} \\
\frac{\partial a}{d t} &= D \nabla_s^2 a+\frac{k_0}{1+(\beta f)^{-q}}+\frac{k_1}{1+(\gamma a)^{-h}}-k_2 a-k_3 b a-k_5 \hat{a} \\
\frac{d b}{d t}&=k_4 \hat{a} b 
\end{align*}

\noindent where $\tau=10$, and the other parameters are specified above in the PF model.

